/* Независимый сверщик записи доказательства: один файл на C99, из внешнего —
 * только libc.
 *
 *   сверщик [ключи] <исходник.flang> <запись> [ожидаемый sha256 исходника]
 *
 * ИСХОДОВ ТРИ, И ТРЕТИЙ НЕ СЛИВАЕТСЯ НИ С ОДНИМ ИЗ ДВУХ: 0 — ПРОВЕРЕНО (на
 * слово ядра не взято ничего), 1 — НЕ СОШЛОСЬ (противоречие названо), 3 — НЕ
 * ПРОВЕРЕНО (противоречий нет, но проверено не всё, и непроверенное названо
 * числом и словами), 2 — кривой вызов. Слить третий с нулём значит соврать про
 * запись, слить с единицей — оболгать честную.
 *
 * Что именно проверяется, что берётся на слово (закрытый список A1–A10) и
 * почему этот файл не собирается вместе с компилятором —
 * docs/flang/proof/checker/README.md. Здесь — код и доводы к решениям, которых
 * из кода не видно.
 */
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <unistd.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include <dirent.h>


typedef struct Блок { struct Блок *след; size_t взято, вес; char *дно; } Блок;
static Блок *arena;

static void *дай(size_t n) {
  n = (n + 15u) & ~(size_t)15;
  if (!arena || arena->взято + n > arena->вес) {
    size_t вес = n > (1u << 20) ? n : (1u << 20);
    Блок *b = malloc(sizeof *b);
    if (!b) exit(2);
    b->дно = malloc(вес);
    if (!b->дно) exit(2);
    b->след = arena; b->взято = 0; b->вес = вес; arena = b;
  }
  { char *p = arena->дно + arena->взято; arena->взято += n; return p; }
}

static char *копия(const char *s, size_t n) {
  char *p = дай(n + 1); memcpy(p, s, n); p[n] = 0; return p;
}

static char *fmt(const char *f, ...) {
  va_list a; int n; char *p; char проба[1];
  va_start(a, f); n = vsnprintf(проба, sizeof проба, f, a); va_end(a);
  if (n < 0) exit(2);
  p = дай((size_t)n + 1);
  va_start(a, f); vsnprintf(p, (size_t)n + 1, f, a); va_end(a);
  return p;
}

typedef struct { char **e; int n, вес; } Сп;
static const Сп ПУСТО = { NULL, 0, 0 };

static void добавить(Сп *s, char *z) {
  if (s->n == s->вес) {
    int v = s->вес ? s->вес * 2 : 8;
    char **e = дай((size_t)v * sizeof *e);
    if (s->n) memcpy(e, s->e, (size_t)s->n * sizeof *e);
    s->e = e; s->вес = v;
  }
  s->e[s->n++] = z;
}

/* Часть списка по счёту с единицы; нет такой — пустая строка. Выход за край сам
   становится отказом: пустая строка не совпадёт ни с одним ожиданием. */
static char *часть(Сп s, long i) { return (i < 1 || i > s.n) ? (char *)"" : s.e[i - 1]; }

static int начинается(const char *s, const char *p) { return strncmp(s, p, strlen(p)) == 0; }
static int содержит(const char *s, const char *p) { return strstr(s, p) != NULL; }

static Сп разделить(const char *s, const char *sep) {
  Сп v = ПУСТО; size_t k = strlen(sep); const char *p = s, *q;
  if (!k) { добавить(&v, (char *)s); return v; }
  while ((q = strstr(p, sep)) != NULL) { добавить(&v, копия(p, (size_t)(q - p))); p = q + k; }
  добавить(&v, копия(p, strlen(p)));
  return v;
}

static char *соединить(Сп v, const char *sep) {
  size_t k = strlen(sep), дл = 1; int i; char *r, *p;
  for (i = 0; i < v.n; i++) дл += strlen(v.e[i]) + k;
  r = дай(дл); p = r; *p = 0;
  for (i = 0; i < v.n; i++) {
    if (i) { memcpy(p, sep, k); p += k; }
    { size_t d = strlen(v.e[i]); memcpy(p, v.e[i], d); p += d; }
  }
  *p = 0; return r;
}

static char *заменить(const char *s, const char *что, const char *на) {
  return *что ? соединить(разделить(s, что), на) : (char *)s;
}

static char *обрезать(const char *s) {
  size_t a = 0, b = strlen(s);
  while (a < b && (s[a] == ' ' || s[a] == '\t' || s[a] == '\r')) a++;
  while (b > a && (s[b-1] == ' ' || s[b-1] == '\t' || s[b-1] == '\r')) b--;
  return копия(s + a, b - a);
}

static char *слово(const char *s, long n) { return часть(разделить(s, " "), n); }

static char *слова_после(const char *s, long сколько) {
  Сп v = разделить(s, " "), r = ПУСТО; int i;
  for (i = 0; i < v.n; i++) if (i + 1 > сколько) добавить(&r, v.e[i]);
  return соединить(r, " ");
}

static char *в_ёлочках(const char *s, long n) {
  return часть(разделить(часть(разделить(s, "«"), n + 1), "»"), 1);
}
/* Терм в угловых скобках ⟨⟩: ёлочки заняты именами, и терм несёт их сам. */
static char *в_уголках(const char *s, long n) {
  return часть(разделить(часть(разделить(s, "⟨"), n + 1), "⟩"), 1);
}

/* Число из слова; не число — минус один, и это названное значение. */
static double число_из_слова(const char *s) {
  char *конец; double z;
  if (!*s) return -1;
  z = strtod(s, &конец);
  return (*конец || конец == s) ? -1 : z;
}

static char *слово_после(const char *s, const char *метка) {
  return содержит(s, метка) ? слово(часть(разделить(s, метка), 2), 1) : (char *)"";
}
/* ЧИСЛО ЗА МЕТКОЙ ищется по всем вхождениям метки, а не по первому. Довод —
   замер: у записи `утверждение «всякая строка начинается пустым префиксом» …
   строка 30` слово «строка» стоит внутри ИМЕНИ, и счёт по первому вхождению
   давал −1, то есть ЧЕСТНАЯ запись отвергалась. Слово внутри имени числа за
   собой не несёт, и первое вхождение с числом — то самое. */
static double число_после(const char *s, const char *метка) {
  size_t k = strlen(метка); const char *p = s, *q;
  while ((q = strstr(p, метка)) != NULL) {
    double z = число_из_слова(слово(q + k, 1));
    if (z >= 0) return z;
    p = q + k;
  }
  return -1;
}
static long номер_после(const char *s, const char *метка) {
  return (long)число_после(s, метка);
}
static char *хвост_после(const char *s, const char *метка) {
  return содержит(s, метка) ? обрезать(часть(разделить(s, метка), 2)) : (char *)"";
}

/* Строка исходника читается так же, как её читает язык: хвостовое примечание
   снято, табуляции — пробелы, пробельные пробеги сжаты, имена сличаются
   целиком, а не вхождением подстроки. Иначе `принимает первое: нат // первое:
   целое` засчитывается за объявление типа, а `функция «Двойник» // функция
   «Знаки»` подменяет настоящую функцию — и подделка проходит кодом 0. */

/* Строка без хвостового примечания. Двойные кавычки уважаются: «//» внутри
   строкового литерала — знаки литерала, а не начало примечания. */
static char *без_примечания(const char *s) {
  size_t i; int в_кавычках = 0;
  for (i = 0; s[i]; i++) {
    if (s[i] == '"') в_кавычках = !в_кавычках;
    else if (!в_кавычках && s[i] == '/' && s[i + 1] == '/') return копия(s, i);
  }
  return (char *)s;
}

/* Отступ здесь не снимается: заголовок пишется от края, и строка изнутри блока
   иначе сошла бы за объявление. */
static char *имя_функции(const char *сырая) {
  char *b = без_примечания(сырая);
  if (!начинается(b, "функция «") && !начинается(b, "тотальная функция «"))
    return (char *)"";
  return в_ёлочках(b, 1);
}

/* Примечание снимается ЗДЕСЬ, у единственной двери: исходник читают через эту
   функцию два с половиной десятка мест, и правило «читать как язык» обязано
   стоять у двери, а не переписываться в каждом. */
static char *строка_по_номеру(Сп строки, long n) {
  return обрезать(без_примечания(часть(строки, n)));
}

/* Имя, стоящее в записи, обязано стоять и в исходнике. Имя пишется в языке и
   голым словом, и в ёлочках, поэтому ёлочки снимаются с обеих сторон. */
static char *голо(const char *s) {
  char *t = обрезать(s);
  return начинается(t, "«") ? в_ёлочках(t, 1) : t;
}
/* Слово «то» перед обоснованием — грамматика случая, а не часть обоснования. */
static char *без_то(const char *s) {
  return начинается(s, "то ") ? слова_после(s, 1) : (char *)s;
}

static char *первая_с_началом(Сп v, const char *начало) {
  int i;
  for (i = 0; i < v.n; i++) { char *t = обрезать(v.e[i]); if (начинается(t, начало)) return t; }
  return (char *)"";
}
static Сп все_с_началом(Сп v, const char *начало) {
  Сп r = ПУСТО; int i;
  for (i = 0; i < v.n; i++) { char *t = обрезать(v.e[i]); if (начинается(t, начало)) добавить(&r, t); }
  return r;
}
/* Ходы верхнего свода стоят под самим постусловием, а не под посылкой принципа.
   Признак — «ход цель» встречается раньше любой строки «посылка » (или посылок
   нет вовсе); ходы, вписанные ПОД посылки, сюда не относятся. */
static int несёт_верхний_свод(Сп свои) {
  int i;
  for (i = 0; i < свои.n; i++) {
    char *s = обрезать(свои.e[i]);
    if (начинается(s, "посылка ")) return 0;
    if (strcmp(s, "ход цель") == 0) return 1;
  }
  return 0;
}

static char *прочитать_файл(const char *путь) {
  FILE *f = fopen(путь, "rb"); char *b; size_t вес = 0, место = 1 << 16, k;
  if (!f) return NULL;
  b = malloc(место);
  if (!b) exit(2);
  while ((k = fread(b + вес, 1, место - вес - 1, f)) > 0) {
    вес += k;
    if (вес + 1 >= место) { место *= 2; b = realloc(b, место); if (!b) exit(2); }
  }
  fclose(f); b[вес] = 0;
  { char *r = копия(b, вес); free(b); return r; }
}

/* Знаки — кодовые точки, а не байты: так считает и пишущая сторона. */
static long знаков(const char *s) {
  long n = 0; const unsigned char *p = (const unsigned char *)s;
  for (; *p; p++) if ((*p & 0xC0) != 0x80) n++;
  return n;
}
/* Тот же счёт, что у пишущей стороны; написан порознь нарочно. */
static long отпечаток(const char *s, long множ, long модуль) {
  long long h = 7; const unsigned char *p = (const unsigned char *)s;
  while (*p) {
    long long c; int k, i;
    if (*p < 0x80) { c = *p; k = 1; }
    else if ((*p & 0xE0) == 0xC0) { c = *p & 0x1F; k = 2; }
    else if ((*p & 0xF0) == 0xE0) { c = *p & 0x0F; k = 3; }
    else { c = *p & 0x07; k = 4; }
    for (i = 1; i < k && p[i]; i++) c = (c << 6) | (p[i] & 0x3F);
    h = (h * множ + c) % модуль; p += i;
  }
  return (long)h;
}

/* Многочленная свёртка шапки линейна по кодам знаков, модули меньше 2^30, и
   столкновение к ней подбирается приведением решётки за доли секунды. Свёртка
   оставлена (её пишет ядро, расхождение с ней — отказ), но ПРИВЯЗКА стоит на
   SHA-256: строка шапки «отпечаток256» либо отпечаток, поданный третьим доводом. */
static const unsigned long K256[64] = {
  0x428a2f98UL,0x71374491UL,0xb5c0fbcfUL,0xe9b5dba5UL,0x3956c25bUL,0x59f111f1UL,0x923f82a4UL,0xab1c5ed5UL,
  0xd807aa98UL,0x12835b01UL,0x243185beUL,0x550c7dc3UL,0x72be5d74UL,0x80deb1feUL,0x9bdc06a7UL,0xc19bf174UL,
  0xe49b69c1UL,0xefbe4786UL,0x0fc19dc6UL,0x240ca1ccUL,0x2de92c6fUL,0x4a7484aaUL,0x5cb0a9dcUL,0x76f988daUL,
  0x983e5152UL,0xa831c66dUL,0xb00327c8UL,0xbf597fc7UL,0xc6e00bf3UL,0xd5a79147UL,0x06ca6351UL,0x14292967UL,
  0x27b70a85UL,0x2e1b2138UL,0x4d2c6dfcUL,0x53380d13UL,0x650a7354UL,0x766a0abbUL,0x81c2c92eUL,0x92722c85UL,
  0xa2bfe8a1UL,0xa81a664bUL,0xc24b8b70UL,0xc76c51a3UL,0xd192e819UL,0xd6990624UL,0xf40e3585UL,0x106aa070UL,
  0x19a4c116UL,0x1e376c08UL,0x2748774cUL,0x34b0bcb5UL,0x391c0cb3UL,0x4ed8aa4aUL,0x5b9cca4fUL,0x682e6ff3UL,
  0x748f82eeUL,0x78a5636fUL,0x84c87814UL,0x8cc70208UL,0x90befffaUL,0xa4506cebUL,0xbef9a3f7UL,0xc67178f2UL };

static void sha_блок(unsigned long *h, const unsigned char *b) {
  unsigned long w[64], a, c, d, e, f, g, hh, bb, t1, t2; int i;
  for (i = 0; i < 16; i++)
    w[i] = ((unsigned long)b[i*4] << 24 | (unsigned long)b[i*4+1] << 16 |
            (unsigned long)b[i*4+2] << 8 | (unsigned long)b[i*4+3]) & 0xffffffffUL;
  for (i = 16; i < 64; i++) {
    unsigned long s0 = ((w[i-15] >> 7 | w[i-15] << 25) ^ (w[i-15] >> 18 | w[i-15] << 14) ^ (w[i-15] >> 3)) & 0xffffffffUL;
    unsigned long s1 = ((w[i-2] >> 17 | w[i-2] << 15) ^ (w[i-2] >> 19 | w[i-2] << 13) ^ (w[i-2] >> 10)) & 0xffffffffUL;
    w[i] = (w[i-16] + s0 + w[i-7] + s1) & 0xffffffffUL;
  }
  a = h[0]; bb = h[1]; c = h[2]; d = h[3]; e = h[4]; f = h[5]; g = h[6]; hh = h[7];
  for (i = 0; i < 64; i++) {
    unsigned long S1 = ((e >> 6 | e << 26) ^ (e >> 11 | e << 21) ^ (e >> 25 | e << 7)) & 0xffffffffUL;
    unsigned long ч = (e & f) ^ (~e & g);
    unsigned long S0 = ((a >> 2 | a << 30) ^ (a >> 13 | a << 19) ^ (a >> 22 | a << 10)) & 0xffffffffUL;
    unsigned long mj = (a & bb) ^ (a & c) ^ (bb & c);
    t1 = (hh + S1 + ч + K256[i] + w[i]) & 0xffffffffUL;
    t2 = (S0 + mj) & 0xffffffffUL;
    hh = g; g = f; f = e; e = (d + t1) & 0xffffffffUL;
    d = c; c = bb; bb = a; a = (t1 + t2) & 0xffffffffUL;
  }
  h[0] = (h[0]+a)&0xffffffffUL; h[1] = (h[1]+bb)&0xffffffffUL; h[2] = (h[2]+c)&0xffffffffUL;
  h[3] = (h[3]+d)&0xffffffffUL; h[4] = (h[4]+e)&0xffffffffUL; h[5] = (h[5]+f)&0xffffffffUL;
  h[6] = (h[6]+g)&0xffffffffUL; h[7] = (h[7]+hh)&0xffffffffUL;
}
static char *sha256(const char *s) {
  unsigned long h[8] = {0x6a09e667UL,0xbb67ae85UL,0x3c6ef372UL,0xa54ff53aUL,
                        0x510e527fUL,0x9b05688cUL,0x1f83d9abUL,0x5be0cd19UL};
  size_t n = strlen(s), i, вес = ((n + 9 + 63) / 64) * 64;
  unsigned char *b = дай(вес); char *r = дай(65);
  memset(b, 0, вес); memcpy(b, s, n); b[n] = 0x80;
  for (i = 0; i < 8; i++) b[вес-1-i] = (unsigned char)(((unsigned long long)n * 8) >> (8 * i));
  for (i = 0; i < вес; i += 64) sha_блок(h, b + i);
  for (i = 0; i < 8; i++) sprintf(r + i * 8, "%08lx", h[i]);
  return r;
}


static char *сжать_пробелы(const char *t) {
  Сп v = разделить(t, " "), r = ПУСТО; int i;
  for (i = 0; i < v.n; i++) if (*v.e[i]) добавить(&r, v.e[i]);
  return соединить(r, " ");
}
static char *как_читает_язык(const char *s) {
  return сжать_пробелы(заменить(без_примечания(s), "\t", " "));
}

static char *расставить(const char *t) {
  return сжать_пробелы(заменить(заменить(t, "(", " ( "), ")", " ) "));
}
static long сколько_раз(const char *t, const char *ч) {
  long n = 0; const char *p = t, *q;
  while ((q = strstr(p, ч)) != NULL) { n++; p = q + strlen(ч); }
  return n;
}
static int скобки_сошлись(const char *t) { return сколько_раз(t, "(") == сколько_раз(t, ")"); }
static char *без_краёв(const char *t) {
  size_t d = strlen(t); return d < 3 ? (char *)"" : копия(t + 1, d - 2);
}
/* Уходит ли счёт скобок в минус хоть раз: этим «( а ) плюс ( б )» отличается
   от «( ( а ) плюс ( б ) )» — там крайние скобки разные, снимать нельзя. */
static int не_проваливается(const char *t) {
  long сейчас = 0; const char *p;
  for (p = t; *p; p++) {
    if (*p == '(') сейчас++;
    else if (*p == ')') { сейчас--; if (сейчас < 0) return 0; }
  }
  return 1;
}
static int одна_пара(const char *t) {
  size_t d = strlen(t);
  if (d < 3 || t[0] != '(' || t[d-1] != ')') return 0;
  return скобки_сошлись(t) && не_проваливается(без_краёв(t));
}
static char *ужать(const char *t) {
  int i; char *r = обрезать(t);
  for (i = 0; i < 4; i++) { if (!одна_пара(r)) break; r = обрезать(без_краёв(r)); }
  return r;
}
/* Двоеточие разводится пробелами так же, как скобки: у цели «для всех э из Л: У»
   (ADR-0026 §11 п.14) оно стоит вплотную к списку, а `вставить_вместо` ищет
   «результат» по пробельным краям. */
static char *терм(const char *сырой) { return ужать(расставить(заменить(сырой, ":", " : "))); }

/* Ищется и меняется ПО ПРОБЕЛЬНЫМ КРАЯМ: иначе «х» нашлось бы внутри «хвост». */
static int есть_терм(const char *где, const char *что) {
  return содержит(fmt(" %s ", где), fmt(" %s ", что));
}
static char *в_скобки(const char *t) {
  return (!содержит(t, " ") || одна_пара(t)) ? (char *)t : fmt("( %s )", t);
}
/* Два прохода: место, куда подтерм встаёт, БЫВАЕТ УЖЕ В СКОБКАХ, и вторые
   скобки вокруг вставляемого были бы лишними. */
static char *вставить_вместо(const char *где, const char *что, const char *на) {
  /* ОБА прохода оборачивают вставляемое одинаково — через `в_скобки`, а не голой
     парой: `ужать` снимает только ВНЕШНИЕ скобки терма, и лишняя внутренняя пара
     вокруг атома (`длина ( элементы )` против `длина элементы`) расходится при
     сличении знак в знак — честная запись отвергается молча. */
  char *v = заменить(fmt(" %s ", где), fmt(" ( %s ) ", что), fmt(" %s ", в_скобки(на)));
  return обрезать(заменить(v, fmt(" %s ", что), fmt(" %s ", в_скобки(на))));
}

/* Части верхнего уровня: разбить по знаку наивно, а потом склеивать обратно,
   пока скобки не сойдутся. Разборщик языка для этого не нужен. */
static Сп разделить_сверху(const char *t, const char *op) {
  char *sep = fmt(" %s ", op);
  Сп сырые = разделить(t, sep), части = ПУСТО;
  char *тек = (char *)""; int начата = 0, i;
  for (i = 0; i < сырые.n; i++) {
    char *новое = начата ? fmt("%s%s%s", тек, sep, сырые.e[i]) : сырые.e[i];
    if (скобки_сошлись(новое)) { добавить(&части, новое); тек = (char *)""; начата = 0; }
    else { тек = новое; начата = 1; }
  }
  return части;
}

/* Существование со свидетелем `есть такой м, а именно Т, что У`: свидетель
   написан в исходнике, поэтому берётся ровно У[м:=Т], и подстановку сверщик
   строит САМ, а из записи её не берёт — иначе это снимок со снимка. */
static int разобрать_существование(const char *ц, char **м, char **т, char **у) {
  const char *t = обрезать(ц), *а, *ч;
  if (!начинается(t, "есть такой ") || !(а = strstr(t, ", а именно ")) || !(ч = strstr(а, ", что "))) return 0;
  *м = обрезать(копия(t + strlen("есть такой "), (size_t)(а - t) - strlen("есть такой ")));
  *т = обрезать(копия(а + strlen(", а именно "), (size_t)(ч - а) - strlen(", а именно ")));
  *у = обрезать(ч + strlen(", что "));
  return **м && **т && **у;
}
/* Цель, обещанная постусловием: у существования — подставленная (как терм),
   у всего прочего — сама строка, как была (тот же указатель). */
static char *цель_обещанная(const char *ц) {
  char *м, *т, *у;
  return разобрать_существование(ц, &м, &т, &у) ? терм(вставить_вместо(терм(у), м, терм(т))) : (char *)ц;
}

/* У утверждения без функции «место» — его заголовок `утверждение «И»` от края,
   цель — хвост строки `утверждаем`, типы и имена связанных — строки `для всех`
   под ним. Это второй источник того же знания, что даёт постусловие, и читает
   его ОДНА пара функций: разойдись два читателя — разойдутся молча. */
static long строка_высказывания(Сп строки, const char *место) {
  long i;
  if (!начинается(место, "утверждение «")) return 0;
  for (i = 1; i <= строки.n; i++) if (strcmp(как_читает_язык(часть(строки, i)), место) == 0) return i;
  return 0;
}
static char *из_высказывания(Сп строки, long где, const char *имя, Сп *имена) {
  long i; char *итог = (char *)"";
  for (i = где + 1; где && i <= строки.n; i++) {
    char *сырая = часть(строки, i), *l = как_читает_язык(обрезать(без_примечания(сырая)));
    if (*сырая && !начинается(сырая, " ") && !начинается(сырая, "//")) break;
    if (!имя && начинается(l, "утверждаем ")) итог = хвост_после(l, "утверждаем ");
    if (начинается(l, "для всех ")) {
      char *св = l + strlen("для всех "), *огр = strstr(св, " таких что ");
      char *без_огр = огр ? копия(св, (size_t)(огр - св)) : св; Сп связ = разделить_сверху(без_огр, "и"); int j;
      if (!связ.n) добавить(&связ, без_огр);
      for (j = 0; j < связ.n; j++) {
        Сп пара = разделить(обрезать(связ.e[j]), ":");
        if (имена) добавить(имена, голо(часть(пара, 1)));
        if (имя && strcmp(голо(часть(пара, 1)), имя) == 0) итог = обрезать(часть(пара, 2));
      }
    }
  }
  return итог;
}

static Сп ограничения_высказывания(Сп строки, const char *место) {
  Сп итог = ПУСТО; long где = строка_высказывания(строки, место), i;
  for (i = где + 1; где && i <= строки.n; i++) {
    char *сырая = часть(строки, i), *l = как_читает_язык(обрезать(без_примечания(сырая)));
    if (*сырая && !начинается(сырая, " ") && !начинается(сырая, "//")) break;
    if (начинается(l, "для всех ") && содержит(l, " таких что ")) добавить(&итог, терм(хвост_после(l, " таких что ")));
  }
  return итог;
}

typedef struct { int есть; char *лево, *право; } Разрез;

static Разрез разрез_по(const char *t, const char *op) {
  Разрез r; Сп ч = разделить_сверху(ужать(t), op);
  if (ч.n < 2) { r.есть = 0; r.лево = (char *)""; r.право = (char *)""; return r; }
  r.есть = 1; r.лево = обрезать(ч.e[0]);
  { Сп хв = ПУСТО; int i; for (i = 1; i < ч.n; i++) добавить(&хв, ч.e[i]);
    r.право = обрезать(соединить(хв, fmt(" %s ", op))); }
  return r;
}
static char *слева_от(const char *t, const char *op) { return разрез_по(t, op).лево; }
static char *справа_от(const char *t, const char *op) { return разрез_по(t, op).право; }


/* «Простой» — терм без вопроса о старшинстве: одно слово либо одна пара скобок. */
static int простой(const char *t);

typedef struct { int вышло; char *почему; Сп посылки; } Применение;

static Применение не_подошёл(char *почему) {
  Применение p; p.вышло = 0; p.почему = почему; p.посылки = ПУСТО; return p;
}
static Применение закон_суммы(const char *цель) {
  Применение p; Разрез r = разрез_по(цель, "не меньше"), s;
  if (!(r.есть && strcmp(r.право, "0") == 0))
    return не_подошёл((char *)"закон суммы берёт только цель вида «Е не меньше 0»");
  s = разрез_по(r.лево, "плюс");
  if (!(s.есть && разделить_сверху(ужать(r.лево), "плюс").n == 2))
    return не_подошёл((char *)"закон суммы берёт только сумму ровно двух слагаемых");
  p.вышло = 1; p.почему = (char *)""; p.посылки = ПУСТО;
  добавить(&p.посылки, fmt("%s не меньше 0", s.лево));
  добавить(&p.посылки, fmt("%s не меньше 0", s.право));
  return p;
}
/* Литерал не меньше нуля: проверяется счётом, а не списком. */
static Применение закон_литерала(const char *цель) {
  Применение p; Разрез r = разрез_по(цель, "не меньше");
  if (r.есть && strcmp(r.право, "0") == 0 && число_из_слова(ужать(r.лево)) >= 0) {
    p.вышло = 1; p.почему = (char *)""; p.посылки = ПУСТО; return p;
  }
  return не_подошёл((char *)"закон литерала берёт только неотрицательный литерал слева и 0 справа");
}
/* Ровно два куска верхнего уровня по знаку `op`: у терма с одним таким знаком
   разрез однозначен, у терма с двумя — нет, и сверщик тут не берётся. */
static int ровно_надвое(const char *t, const char *op) {
  return разделить_сверху(ужать(t), op).n == 2;
}
static Применение закрыто(void) {
  Применение p; p.вышло = 1; p.почему = (char *)""; p.посылки = ПУСТО; return p;
}

/* Законы разбора цели — ЛОКАЛЬНЫЕ проверки одного шага: сличение литералов и
   тождество знак в знак после `ужать`. Ни один не считает значение и не смотрит
   тело функции: дверь называет ЗАПИСЬ, сверщик сверяет только форму цели. */

/* «мера неотрицательна»: `длина Т не меньше 0` — закрыта. Т обязан быть
   простым (одно слово или одна пара скобок): у `длина а плюс б` старшинства
   сверщик не знает и не гадает. */
static Применение закон_меры(const char *цель) {
  Разрез r = разрез_по(цель, "не меньше"); char *l;
  if (!(r.есть && ровно_надвое(цель, "не меньше") && strcmp(ужать(r.право), "0") == 0))
    return не_подошёл((char *)"закон «мера неотрицательна» берёт только цель вида «длина Т не меньше 0»");
  l = ужать(r.лево);
  if (!начинается(l, "длина ") || !простой(слова_после(l, 1)))
    return не_подошёл((char *)"закон «мера неотрицательна»: слева не мера «длина Т» с простым Т");
  return закрыто();
}

/* «квадрат под оговоркой»: `не ( ( Т минус Т ) равен 0 ) или ( ( Т умножить на Т )
   не меньше 0 )` — закрыта. Четыре вхождения Т обязаны сойтись знак в знак, обе
   правые стороны — литеральный ноль; то же, что стережёт
   `poddelka-ogovorka-o-konechnosti` у двери калькулятора. */
static Применение закон_квадрата(const char *цель) {
  Разрез или = разрез_по(цель, "или"), рав, мин, нм, умн; char *лев, *т;
  if (!(или.есть && ровно_надвое(цель, "или")))
    return не_подошёл((char *)"закон «квадрат под оговоркой» берёт только цель вида «не (…) или (…)»");
  лев = ужать(или.лево);
  if (!начинается(лев, "не "))
    return не_подошёл((char *)"закон «квадрат под оговоркой»: левый дизъюнкт не начат словом «не»");
  рав = разрез_по(ужать(лев + strlen("не ")), "равен");
  if (!(рав.есть && ровно_надвое(лев + strlen("не "), "равен") && strcmp(ужать(рав.право), "0") == 0))
    return не_подошёл((char *)"закон «квадрат под оговоркой»: под «не» не стоит «(Т минус Т) равен 0»");
  мин = разрез_по(рав.лево, "минус");
  if (!(мин.есть && ровно_надвое(рав.лево, "минус") && strcmp(ужать(мин.лево), ужать(мин.право)) == 0))
    return не_подошёл((char *)"закон «квадрат под оговоркой»: оговорка не вида «Т минус Т» с тождественными сторонами");
  т = ужать(мин.лево);
  нм = разрез_по(или.право, "не меньше");
  if (!(нм.есть && ровно_надвое(или.право, "не меньше") && strcmp(ужать(нм.право), "0") == 0))
    return не_подошёл((char *)"закон «квадрат под оговоркой»: правый дизъюнкт не вида «… не меньше 0»");
  умн = разрез_по(нм.лево, "умножить на");
  if (!(умн.есть && ровно_надвое(нм.лево, "умножить на") &&
        strcmp(ужать(умн.лево), т) == 0 && strcmp(ужать(умн.право), т) == 0))
    return не_подошёл(fmt("закон «квадрат под оговоркой»: слева не квадрат «%s умножить на %s» того же терма, что в оговорке", т, т));
  return закрыто();
}

/* «начало склейки»: `( соединить Л с Р ) начинается с П` сводится к
   `Л начинается с П` — Р не смотрится вовсе. Когда Л и П тождественны знак в
   знак, остаток есть «Л начинается с Л», и цель закрыта. Литералы Л ≠ П
   доводятся ходом `вычислить` уже на новой цели. */
static Применение закон_начала_склейки(const char *цель) {
  Применение p; Разрез r = разрез_по(цель, "начинается с"), с; char *лев, *п, *л;
  if (!(r.есть && ровно_надвое(цель, "начинается с")))
    return не_подошёл((char *)"закон «начало склейки» берёт только цель вида «Т начинается с П»");
  лев = ужать(r.лево); п = ужать(r.право);
  if (!начинается(лев, "соединить "))
    return не_подошёл((char *)"закон «начало склейки»: слева не склейка «соединить Л с Р»");
  с = разрез_по(слова_после(лев, 1), "с");
  if (!(с.есть && ровно_надвое(слова_после(лев, 1), "с")))
    return не_подошёл((char *)"закон «начало склейки»: у склейки не ровно два куска по слову «с»");
  л = ужать(с.лево);
  if (strcmp(л, п) == 0) return закрыто();
  p = закрыто(); добавить(&p.посылки, fmt("%s начинается с %s", в_скобки(л), в_скобки(п)));
  return p;
}

/* «пустая приставка»: `Т начинается с ""` — закрыта: сравнивается ноль знаков. */
static Применение закон_пустой_приставки(const char *цель) {
  Разрез r = разрез_по(цель, "начинается с");
  if (r.есть && ровно_надвое(цель, "начинается с") && strcmp(ужать(r.право), "\"\"") == 0) return закрыто();
  return не_подошёл((char *)"закон «пустая приставка» берёт только цель вида «Т начинается с \"\"»");
}

static Применение применить_закон(const char *имя, const char *цель) {
  if (strcmp(имя, "сумма неотрицательных") == 0) return закон_суммы(цель);
  if (strcmp(имя, "литерал неотрицателен") == 0) return закон_литерала(цель);
  if (strcmp(имя, "мера неотрицательна") == 0) return закон_меры(цель);
  if (strcmp(имя, "квадрат под оговоркой") == 0) return закон_квадрата(цель);
  if (strcmp(имя, "начало склейки") == 0) return закон_начала_склейки(цель);
  if (strcmp(имя, "пустая приставка") == 0) return закон_пустой_приставки(цель);
  return не_подошёл(fmt("закона «%s» сверщик не знает: список законов закрыт", имя));
}


static const char *вид_строки_теоремы(const char *s) {
  const char *g = без_то(s);
  if (начинается(g, "по предположению") || начинается(g, "по свойству") ||
      начинается(g, "по примеру") || начинается(g, "по закону") ||
      начинается(g, "затем ")) return "шаг";
  if (начинается(g, "случай ")) return "случай";
  if (начинается(g, "дано ")) return "дано";
  if (начинается(g, "утверждаем")) return "утверждаем";
  if (начинается(g, "индукция по")) return "индукция";
  return strcmp(g, "следовательно доказано") == 0 ? "доказано" : "";
}

static Сп разметка_теоремы(Сп строки, long начало) {
  Сп метки = ПУСТО; long i;
  for (i = начало; i <= строки.n; i++) {
    char *сырая = часть(строки, i), *s = обрезать(без_примечания(сырая));
    const char *вид;
    if (i > начало && *сырая && !начинается(сырая, " ")) break;
    if (начинается(s, "//") || !*s) continue;
    вид = начинается(s, "теорема ") ? "теорема" : вид_строки_теоремы(s);
    if (!*вид) continue;
    /* К5: `дано <утверждение>` — допущение, а не имя; `дано х: T таких что P` —
       имя и допущение на одной строке. Допущение запись печатает своей строкой. */
    if (strcmp(вид, "дано") == 0 && (!содержит(s, ":") || содержит(s, " таких что "))) {
      if (содержит(s, ":")) добавить(&метки, fmt("дано %ld", i));
      добавить(&метки, fmt("допущение %ld", i));
      continue;
    }
    добавить(&метки, strcmp(вид, "доказано") == 0 ? (char *)"доказано" : fmt("%s %ld", вид, i));
  }
  return метки;
}

/* Имя варианта пишется двумя способами — в ёлочках и голым словом; оба в дереве. */
static char *имя_варианта(const char *s) {
  return начинается(s, "вариант «") ? в_ёлочках(s, 1) : слово(s, 2);
}

/* Носитель индукции даёт ОБЪЯВЛЕНИЕ ТИПА довода, прочитанное из исходника, а не
   слово записи: сумма (`тип «Т»` с вариантами; встроенные список и строка) —
   начальная алгебра; запись (`объект «Т»`) — один конструктор; встроенный
   отрезок — дно и точный шаг; псевдоним — то, что даёт его правая часть, по
   цепочке. Всё прочее — принципа нет, и это названо вслух, а не молчание. */

/* Имена встроенного отрезка — ОДИН список, тот же, что у ядра; таблица
   flang/proof/tables/segments.tsv, ядро и этот массив сличаются сторожем в обе стороны.
   Держать два списка нельзя: они расходятся молча, и честный файл с именем из
   одного, но не из другого, уходит на слово ядра. */
static const char *НАТУРАЛЬНОЕ[] = {
  "неотрицательное", "нат", "натуральное", "nat", "naturo", "自然数"
};
static int натуральное_имя(const char *тип) {
  int i;
  for (i = 0; i < (int)(sizeof НАТУРАЛЬНОЕ / sizeof *НАТУРАЛЬНОЕ); i++)
    if (strcmp(тип, НАТУРАЛЬНОЕ[i]) == 0) return 1;
  return 0;
}
/* Имя типа из ОБЪЯВЛЕННОГО текста — так, как его пишет ядро в строке «принцип
   тип «…»» и как его ищет объявление: в ёлочках — целиком («Дерево чисел»),
   голым словом — первое слово (`список «А»` → список; `неотрицательное` — само).
   На имя, уже вынутое из ёлочек записи, НЕ применять: оно и так голое. */
static char *имя_типа(const char *объявлено) {
  char *t = обрезать(объявлено);
  return начинается(t, "«") ? в_ёлочках(t, 1) : слово(t, 1);
}
/* ЕДИНСТВЕННЫЙ ЧИТАТЕЛЬ строки «принимает имя: тип, …»; той же строки держится
   ядро — разойдутся, и терм развёртки не совпадёт с целью. Поля: имена — как
   написаны, по порядку; типы — всё после двоеточия; голые — имена без ёлочек,
   пустые пропущены; хвост — « и б и в», второй довод и дальше. Вызов строится
   ВСЕМИ доводами: на функции с двумя доводами однодоводный вызов расходится с
   телом молча. */
typedef struct { Сп имена, типы, голые; char *хвост; } Доводы;
static Доводы доводы_строки(const char *l) {
  Доводы д; Сп ч; int k; char *t = обрезать(l);
  д.имена = д.типы = д.голые = ПУСТО; д.хвост = (char *)"";
  if (!начинается(t, "принимает ")) return д;
  ч = разделить(хвост_после(t, "принимает "), ",");
  for (k = 0; k < ч.n; k++) {
    Сп пара = разделить(ч.e[k], ":");
    char *имя = обрезать(часть(пара, 1));
    добавить(&д.имена, имя); добавить(&д.типы, обрезать(часть(пара, 2)));
    if (*имя) добавить(&д.голые, голо(имя));
    if (*имя && k) д.хвост = fmt("%s и %s", д.хвост, имя);
  }
  return д;
}
static Доводы доводы_функции(Сп строки, const char *функция) {
  int i, внутри = 0;
  for (i = 0; i < строки.n; i++) {
    char *имя_з = имя_функции(строки.e[i]), *l = обрезать(без_примечания(строки.e[i]));
    if (*имя_з) внутри = (strcmp(имя_з, функция) == 0);
    else if (внутри && начинается(l, "принимает ")) return доводы_строки(l);
  }
  return доводы_строки("");
}
static char *тип_довода_в_строке(const char *l, const char *имя) {
  Доводы д = доводы_строки(l); int k;
  for (k = 0; k < д.имена.n; k++) if (strcmp(голо(д.имена.e[k]), имя) == 0) return д.типы.e[k];
  return (char *)"";
}
/* 6203-Ш2: рекурсивных частей у варианта — полей, чей тип ровно «Т» (как
   «Поле рекурсивно» ядра: поле `список «Т»` не в счёт). */
static int рекурсивных_частей(const char *вариант, const char *тип) {
  Сп ч = разделить(справа_от(вариант, "содержит"), ","); int k, n = 0;
  for (k = 0; k < ч.n; k++) n += strcmp(обрезать(часть(разделить(ч.e[k], ":"), 2)), fmt("«%s»", тип)) == 0;
  return n;
}
typedef struct { const char *вид;  /* "сумма" | "встроенная-сумма" | "запись" | "отрезок" | "" (принципа нет) */
                 Сп варианты;      /* у сумм — имена вариантов; у записи — одно имя типа */
                 char *основа;     /* имя, с которого прочитано: сам тип либо конец цепочки псевдонимов */
                 /* 6203-Ш2: то же объявление словами строки записи `объявление …`.
                    откуда  — «сумма «Т» строка L» | «запись «Т» строка L» | «встроенный «Т»»
                              | «псевдоним «А» строка L → <откуда>» (L — строка объявления);
                    арности — «В» N … в порядке объявления, N — рекурсивных частей. */
                 char *откуда, *арности;
               } Объявление;
/* `имя` — ГОЛОЕ имя типа (как в записи после ёлочек). Псевдонимы разворачиваются
   по цепочке; глубина ограничена — круг псевдонимов даёт «принципа нет». */
static Объявление объявление_типа_(Сп строки, const char *имя, int глубина) {
  Объявление о; char *г = обрезать(имя), *сумма, *объект, *псевдоним; int i, внутри = 0;
  о.вид = ""; о.варианты = ПУСТО; о.основа = г; о.откуда = о.арности = (char *)"";
  if (!*г || глубина > 8) return о;
  if (strcmp(г, "список") == 0 || strcmp(г, "строка") == 0) {
    о.вид = "встроенная-сумма"; о.откуда = fmt("встроенный «%s»", г);
    о.арности = (char *)"«пусто» 0 «голова и хвост» 1";   /* хвост того же типа — одна часть */
    добавить(&о.варианты, (char *)"пусто"); добавить(&о.варианты, (char *)"голова и хвост");
    return о;
  }
  if (натуральное_имя(г)) { о.вид = "отрезок"; о.откуда = fmt("встроенный «%s»", г); return о; }
  сумма = fmt("тип «%s»", г); объект = fmt("объект «%s»", г); псевдоним = fmt("тип «%s» это ", г);
  for (i = 0; i < строки.n; i++) {
    char *s = обрезать(без_примечания(строки.e[i]));
    if (внутри) {
      if (начинается(s, "вариант ")) {
        добавить(&о.варианты, имя_варианта(s));
        о.арности = fmt("%s%s«%s» %d", о.арности, *о.арности ? " " : "", имя_варианта(s), рекурсивных_частей(s, г));
        continue;
      }
      if (!*s) continue;
      break;
    }
    if (strcmp(s, сумма) == 0) { внутри = 1; о.вид = "сумма"; о.откуда = fmt("сумма «%s» строка %d", г, i + 1); continue; }
    if (начинается(s, псевдоним)) {
      Объявление к = объявление_типа_(строки, имя_типа(хвост_после(s, "» это ")), глубина + 1);
      к.откуда = *к.откуда ? fmt("псевдоним «%s» строка %d → %s", г, i + 1, к.откуда) : (char *)"";
      return к;
    }
    if (strcmp(s, объект) == 0) {
      о.вид = "запись"; добавить(&о.варианты, г);
      о.откуда = fmt("запись «%s» строка %d", г, i + 1); о.арности = fmt("«%s» 0", г);
      return о;
    }
  }
  if (о.варианты.n == 0) { о.вид = ""; о.откуда = (char *)""; }   /* `тип «Т»` без единого варианта — не сумма */
  return о;
}
static Объявление объявление_типа(Сп строки, const char *имя) { return объявление_типа_(строки, имя, 0); }
static Сп варианты_типа(Сп строки, const char *имя) {
  Объявление о = объявление_типа(строки, имя);
  if (strcmp(о.вид, "сумма") == 0 || strcmp(о.вид, "встроенная-сумма") == 0) return о.варианты;
  return ПУСТО;
}

static char *строка_варианта_типа(Сп строки, const char *тип, const char *вариант) {
  char *заг = fmt("тип «%s»", объявление_типа(строки, тип).основа), *текст = (char *)""; int i, внутри = 0;
  for (i = 0; i < строки.n; i++) {
    char *s = обрезать(без_примечания(строки.e[i]));
    if (strcmp(s, заг) == 0) { внутри = 1; continue; }
    if (!внутри) continue;
    if (начинается(s, "вариант ")) { if (strcmp(имя_варианта(s), вариант) == 0) текст = s; continue; }
    if (!*s) continue;
    внутри = 0;
  }
  return текст;
}

static char *хозяин_строки(Сп строки, long где) {
  char *текст = (char *)""; long i;
  for (i = 1; i <= строки.n && i <= где; i++) {
    char *имя = имя_функции(часть(строки, i));
    if (*имя) текст = имя;
  }
  return текст;
}


typedef struct { Сп строки, свои; char *цель, *функция, *по, *тип, *хвост;
                 /* 4123, S2: имя доказываемого сейчас постусловия (для сторожа
                    круга — прямой самоссылки по имени) и снимок реестра доказанных
                    РАНЬШЕ постусловий (для сторожа круга через рекурсию). */
                 /* 4416: `объявленные` — имена блоков, чей вердикт ядро напечатало словом
                    «доказано». ПРАВА взять факт не даёт (право даёт только `доказанные`), а
                    отделяет «сверщик сам не переиграл» (место на слове ядра) от «запись
                    доказанным этого не числит» (ложь). */
                 char *обяз; Сп доказанные, объявленные;
                 /* 5144: ограничения «таких что» свободного утверждения, чей блок сейчас
                    переигрывается (термами, по порядку связываний); у постусловий — пусто.
                    Читает их ход «нейтральный ноль»: без посылки о положительности он отказ. */
                 Сп ограничения; } Обст;

/* Инстанция постусловия вызванной строится ДВУМЯ подстановками: параметры
   вызванной → аргументы узла вызова и связка `результат` → сам узел. Все
   читатели берут исходник так, как его читает язык. */

/* ЕДИНСТВЕННЫЙ РАЗРЕЗАТЕЛЬ доводов вызова `«Ф» от А и Б и В`. Хвост за «от»
   читается до конца либо до первой НЕПАРНОЙ закрывающей скобки и режется по
   « и » верхнего уровня: « и » внутри скобок или кавычек — не разрез. Союз
   « и притом » — связка признаков, а не запятая доводов: хвост с ним доводами
   не читается вовсе, и зовущий получает «не берусь», а не угаданный довод. */
static Сп доводы_вызова(const char *хвост) {
  Сп r = ПУСТО; long гл = 0, от = 0, i; int кав = 0; char *последний;
  for (i = 0; хвост[i]; i++) {
    if (кав) { if (хвост[i] == '\\' && хвост[i + 1]) i++; else if (хвост[i] == '"') кав = 0; continue; }
    if (хвост[i] == '"') кав = 1;
    else if (хвост[i] == '(') гл++;
    else if (хвост[i] == ')' && --гл < 0) break;
    else if (гл == 0 && начинается(хвост + i, " и ")) {
      if (начинается(хвост + i, " и притом ")) return ПУСТО;
      добавить(&r, обрезать(копия(хвост + от, (size_t)(i - от))));
      от = i + (long)strlen(" и "); i = от - 1;
    }
  }
  последний = обрезать(копия(хвост + от, (size_t)(i - от)));
  if (*последний) добавить(&r, последний);
  return r;
}

/* Все предусловия функции — строки «требует …» её блока, по порядку (пусто —
   их нет). На них стоит ОПЛАТА (проект §3): постусловие вызванной верно лишь при
   выполненных предусловиях; фактом его берут только там, где КАЖДОЕ `требует`
   вызванной снято в точке вызова. Читаются так же, как язык (без_примечания).
   Все — а не первое: у вызванной с двумя `требует` погашение одного не делает
   постусловие взятым, иначе второе предусловие протекает молча (соундность). */
static Сп все_требования_функции(Сп строки, const char *функция) {
  Сп r = ПУСТО; int i, внутри = 0;
  for (i = 0; i < строки.n; i++) {
    char *сырая = строки.e[i], *l = обрезать(без_примечания(сырая));
    char *имя_з = имя_функции(сырая);
    if (*имя_з) внутри = (strcmp(имя_з, функция) == 0);
    else if (внутри && начинается(l, "требует ")) добавить(&r, l);
  }
  return r;
}
static char *формула_требования(const char *требует_линия) {
  char *имя = в_ёлочках(требует_линия, 1);
  return обрезать(хвост_после(требует_линия, fmt("требует «%s» ", имя)));
}

/* Цели равны, если равны их стороны с точностью до ОБЪЕМЛЮЩЕЙ пары скобок.
   Снимается только пара, обнимающая сторону целиком: она группировки не меняет,
   а `( а плюс б ) плюс в` от `а плюс ( б плюс в )` этим не спутать — там скобки
   стоят вокруг ЧАСТИ, и `ужать` их не трогает. */
static int совпали_цели(const char *a, const char *b) {
  Разрез ра, рб;
  if (strcmp(ужать(a), ужать(b)) == 0) return 1;
  ра = разрез_по(a, "не меньше"); рб = разрез_по(b, "не меньше");
  if (!ра.есть || !рб.есть) return 0;
  return strcmp(ужать(ра.лево), ужать(рб.лево)) == 0 && strcmp(ужать(ра.право), ужать(рб.право)) == 0;
}

/* 4127: неравенства порядка, СИЛЬНОЕ→СЛАБОЕ. Двусловные («не меньше», «не
   больше») стоят ПЕРЕД однословными нарочно: разрез по « меньше » нашёл бы себя
   внутри «не меньше» и порвал бы `X не меньше 0` как `X не`/`0`. Индексы:
   0=не меньше(≥) 1=не больше(≤) 2=больше(>) 3=меньше(<). */
static const char *НЕРАВ_ОПЫ[4] = { "не меньше", "не больше", "больше", "меньше" };
static int нерав_разрез(const char *t, Разрез *out) {
  int i;
  for (i = 0; i < 4; i++) { Разрез r = разрез_по(t, НЕРАВ_ОПЫ[i]); if (r.есть) { *out = r; return i; } }
  return -1;
}

/* Скобки долой: терм, напечатанный ядром, и строка исходника вправе разойтись
   ТОЛЬКО скобками и пробелами — расстановка скобок и есть то, чего в тексте
   строки нет, а в разобранном дереве есть. Разойдутся словами — это уже другой
   терм, и запись краснеет. */
static char *без_скобок(const char *t) {
  return сжать_пробелы(заменить(заменить(расставить(t), "(", " "), ")", " "));
}

static char *случай_варианта(Обст *o, const char *вариант) {
  Сп v = все_с_началом(o->свои, "случай строка"); int i;
  for (i = 0; i < v.n; i++) {
    char *l = строка_по_номеру(o->строки, номер_после(v.e[i], "строка "));
    if (strcmp(имя_варианта(слова_после(l, 1)), вариант) == 0) return l;
  }
  return (char *)"";
}
/* Образец случая становится конструктором: `с голова как г` — `с голова равным г`. */
static char *конструктор_случая(const char *случай) {
  return заменить(слова_после(случай, 1), " как ", " равным ");
}
/* Что стоит на месте поля образца: `с голова как г` при имени «г» — «голова». */
static char *поле_образца(const char *случай, const char *имя) {
  Сп ч = разделить_сверху(справа_от(слова_после(случай, 1), "с"), "и"); int i;
  for (i = 0; i < ч.n; i++)
    if (strcmp(обрезать(справа_от(ч.e[i], "как")), имя) == 0)
      return обрезать(слева_от(ч.e[i], "как"));
  return (char *)"";
}
/* Рекурсивно ли поле — на этом держится законность допущения индукции: часть
   обязана быть того же типа, иначе это не индукция, а круг. */
static int поле_рекурсивно(Обст *o, const char *вариант, const char *поле) {
  char *s = строка_варианта_типа(o->строки, o->тип, вариант);
  Сп ч = разделить(справа_от(s, "содержит"), ","); int i;
  for (i = 0; i < ч.n; i++) {
    Сп p = разделить(ч.e[i], ":");
    if (strcmp(обрезать(часть(p, 1)), поле) == 0)
      return strcmp(обрезать(часть(p, 2)), fmt("«%s»", o->тип)) == 0;
  }
  return 0;
}
/* Цель посылки — утверждение теоремы, где разбираемое имя заменено тем, о чём
   эта посылка, а `результат` — вызовом доказываемой функции на нём. */
static char *цель_при_значении(Обст *o, const char *значение) {
  char *вызов = терм(fmt("«%s» от %s%s", o->функция, в_скобки(значение), o->хвост));
  return терм(вставить_вместо(вставить_вместо(o->цель, "результат", вызов), o->по, значение));
}
/* ВТОРОЙ ИСТОЧНИК КОНСТРУКТОРА — объявление типа: базу, которую ядро закрывает
   сведением, автор вправе не писать случаем вовсе. Берётся ТОЛЬКО у варианта
   БЕЗ ПОЛЕЙ: у варианта с полями конструктор требует имён связывания, а их даёт
   лишь авторский случай — выдумывать их нельзя. Вариант, которого в объявлении
   типа нет вовсе, отвергается. */
static char *начальная_цель(Обст *o, const char *вариант) {
  char *сл = случай_варианта(o, вариант), *v;
  if (*сл) return цель_при_значении(o, терм(конструктор_случая(сл)));
  /* ПОСТУСЛОВИЕ БЕЗ ИНДУКЦИИ: ни случая, ни принципа — цель есть само постусловие,
     где `результат` заменён вызовом функции на её доводах. `цель_при_значении`
     здесь не годится: он подставляет `о->по` значением, а у постусловия значения
     нет, довод свободен. */
  if (!*вариант && !*o->тип) {
    /* Довод в скобках — как его печатает ядро в терме развёртки («Ф» от (н)):
       в_скобки одно слово не оборачивает, а ход оборачивает, и есть_терм (разрез
       по подстроке) их бы не свёл. Скобки ставим прямо. */
    char *вызов = *o->по ? fmt("«%s» от ( %s )%s", o->функция, o->по, o->хвост)
                         : fmt("«%s»%s", o->функция, o->хвост);
    return терм(вставить_вместо(o->цель, "результат", вызов));
  }
  v = строка_варианта_типа(o->строки, o->тип, вариант);
  if (!*v || содержит(v, " содержит ")) return (char *)"";
  return цель_при_значении(o, терм(v));
}

typedef struct { Сп цели, дано, беды, не_взялся; long ходов, проиграно, без_привязки;
                 int идёт, оборван; char *вариант;
                 /* 4123, S2: инстанцированное постусловие вызванной, внесённое
                    ходом `факт по свойству` и потребляемое ходом `закрыть по
                    свойству` (модус-поненс). Пусто — факта нет. */
                 char *посл_факт; } Прогон;

static long номер_свойства(Сп строки, const char *имя);
static int среди(Сп v, const char *имя);

/* 4416: ПЕРВАЯ БЕДА ГАСИТ ПРОГОН — И НА ЭТОМ ЖАЛОБЫ КОНЧАЮТСЯ. Прежде гашение
   `идёт` тянуло за собой две ЛОЖНЫЕ: следующий ход получал «стоит до «ход цель»»,
   а «ход конец» — «стоит без «ход цель»», хотя «ход цель» в записи стоит на своём
   месте. Метка `оборван` отличает «прогон погашен» от «прогон не начинался»: о
   ходах погашенного прогона больше не жалуемся — беда уже названа, и она одна. */
static void беда_прогона(Прогон *p, char *t) { добавить(&p->беды, t); p->идёт = 0; p->оборван = 1; }
/* 4416: МЕСТО, КОТОРОГО ПРОГОН НЕ ВЗЯЛСЯ ПРОВЕРЯТЬ, — НЕ ЛОЖЬ. Прогон гасится так
   же, как бедой (дальше сводить не по чему), но исход у записи третий, а не первый:
   место уходит на слово ядра с названной причиной. Звать это бедой значило бы
   объявлять ложью честную печать ядра — ровно то, на чём задача 4416 поймала
   сверщика силлогизмом (5309). */
static void не_взялся_прогона(Прогон *p, char *t) { добавить(&p->не_взялся, t); p->идёт = 0; p->оборван = 1; }
static char *первая_цель(Прогон *p) { return p->цели.n ? p->цели.e[0] : (char *)""; }

/* Первая цель заменяется тем, во что разошлась: пусто — закрыта, одна —
   переписана, две — поделена. Новые цели встают ПЕРЕД прочими. */
static void вместо_первой(Прогон *p, Сп новые) {
  Сп c = ПУСТО; int i;
  for (i = 0; i < новые.n; i++) добавить(&c, новые.e[i]);
  for (i = 1; i < p->цели.n; i++) добавить(&c, p->цели.e[i]);
  p->цели = c; p->ходов++;
}
static void одна_цель(Прогон *p, char *c) { Сп v = ПУСТО; добавить(&v, c); вместо_первой(p, v); }

static void развернуть_по_телу(Прогон *p, const char *что, const char *образец,
                              char *тело, const char *довод) {
  Сп имена = разделить_сверху(справа_от(слова_после(образец, 1), "с"), "и");
  Сп знач = разделить_сверху(справа_от(довод, "с"), "и");
  int i;
  for (i = 0; i < имена.n; i++) {
    char *имя = обрезать(справа_от(имена.e[i], "как"));
    char *z = обрезать(справа_от(часть(знач, i + 1), "равным"));
    if (*имя && *z) тело = вставить_вместо(тело, имя, z);
  }
  одна_цель(p, терм(вставить_вместо(первая_цель(p), что, тело)));
}

static long блок_функции(Сп строки, const char *функция, long *конец);
static char *собрать_тело_случая(Сп L, long i, long конец, int гл);
static char *тело_со_строки(Сп строки, long где, const char *чья) {
  long b, i; Сп L = ПУСТО;
  if (блок_функции(строки, чья, &b) < 1) return (char *)"";
  for (i = где; i < b; i++) { char *l = как_читает_язык(часть(строки, i)); if (*l) добавить(&L, l); }
  return L.n > 1 ? собрать_тело_случая(L, 0, L.n, 8) : (char *)"";
}

/* РАЗВЁРТКА ОПРЕДЕЛЕНИЯ. Тело берётся из ИСХОДНИКА по номеру строки, и три
   условия проверяются прежде, чем ему поверить: строка стоит внутри названной
   функции, над нею стоит образец названного варианта, и она начата словом «то». */
static void ход_развёртки(Прогон *p, const char *строка, Обст *o) {
  char *что = терм(в_уголках(строка, 1));
  long где = номер_после(строка, "строка ");
  char *имя = в_ёлочках(что, 1);
  /* ДОВОД ОТРЕЗАЕТСЯ ПО ИМЕНИ ФУНКЦИИ, А НЕ ПО ПЕРВОМУ СЛОВУ «от»: у функции,
     чьё имя само несёт «от» («Высота от дна»), разрез по первому «от» идёт
     посередине имени, вариант читается как «от», и честная запись отвергается.
     Прочие доводы отсекаются хвостом подписи: они не часть значения. */
  char *довод = обрезать(хвост_после(что, fmt("«%s» от ", имя)));
  char *вариант;
  { size_t dd = strlen(довод), hh = strlen(o->хвост);
    if (hh && dd >= hh && strcmp(довод + dd - hh, o->хвост) == 0) довод = копия(довод, dd - hh); }
  довод = ужать(обрезать(довод));
  вариант = имя_варианта(довод);
  char *тело, *образец, *хозяин;
  if (!есть_терм(первая_цель(p), что)) {
    беда_прогона(p, fmt("развёртка: в цели «%s» нет терма «%s»", первая_цель(p), что)); return;
  }
  if (где < 1) {   /* будущий вид записи: тело приезжает термом, а не номером */
    char *t = в_уголках(строка, 2);
    if (!*t) { беда_прогона(p, (char *)"развёртка: ни номера строки исходника, ни тела термом"); return; }
    p->без_привязки++;
    развернуть_по_телу(p, что, случай_варианта(o, вариант), терм(t), довод); return;
  }
  тело = строка_по_номеру(o->строки, где);
  образец = строка_по_номеру(o->строки, где - 1);
  хозяин = хозяин_строки(o->строки, где);
  /* ТЕЛО БЕЗ СЛУЧАЯ: довод развёртки — не вариант-конструктор, значит функция
     разбора не несёт, и её тело — одна форма на названной строке. Проверки
     «случай над строкой» и «строка начата «то»» тут не к месту: их несёт только
     разбор. Сверяется общее у обеих форм — строка стоит в названной функции и
     записанное термом тело сходится с исходником знак в знак. */
  if (!*вариант) {
    char *тело_т = терм(обрезать(тело));
    char *написано = в_уголках(строка, 2);
    /* ТЕЛО В НЕСКОЛЬКО СТРОК («если У» / «то А» / «иначе» / «Б»): на строке стоит
       одно условие, сличать с ней термом нечего. Строки до конца блока собираются
       той же дорогой, что тело случая, и сличаются с записанным термом БЕЗ СКОБОК —
       расстановку скобок несёт разобранное дерево, а не текст строк. */
    if (*написано && начинается(тело_т, "если ") && strcmp(без_скобок(написано), без_скобок(тело_т)) != 0) {
      char *целиком = тело_со_строки(o->строки, где, хозяин);
      if (*целиком && strcmp(без_скобок(написано), без_скобок(целиком)) == 0) тело_т = целиком;
    }
    if (*написано && strcmp(без_скобок(написано), без_скобок(тело_т)) != 0) {
      беда_прогона(p, fmt("развёртка «%s»: запись несёт тело ⟨%s⟩, а в строке %ld исходника написано «%s»",
                          имя, написано, где, тело_т)); return;
    }
    if (strcmp(хозяин, имя) != 0)
      беда_прогона(p, fmt("развёртка «%s»: строка %ld исходника стоит в функции «%s»", имя, где, хозяин));
    else развернуть_по_телу(p, что, (char *)"", *написано ? терм(написано) : тело_т, довод);
    return;
  }
  { char *написано = в_уголках(строка, 2);
    if (*написано) {
      char *из_исходника = терм(слова_после(тело, 1));
      if (strcmp(без_скобок(написано), без_скобок(из_исходника)) != 0) {
        беда_прогона(p, fmt("развёртка «%s»: запись несёт тело ⟨%s⟩, а в строке %ld исходника написано «%s»",
                            имя, написано, где, из_исходника)); return;
      }
      тело = fmt("то %s", написано);
    } }
  if (strcmp(хозяин, имя) != 0)
    беда_прогона(p, fmt("развёртка «%s»: строка %ld исходника стоит в функции «%s»", имя, где, хозяин));
  else if (!начинается(тело, "то "))
    беда_прогона(p, fmt("развёртка «%s»: строка %ld исходника не начинается словом «то»", имя, где));
  else if (!(начинается(образец, "случай ") &&
             strcmp(имя_варианта(слова_после(образец, 1)), вариант) == 0))
    беда_прогона(p, fmt("развёртка «%s»: над строкой %ld исходника не стоит случай варианта «%s»", имя, где, вариант));
  else развернуть_по_телу(p, что, образец, терм(слова_после(тело, 1)), довод);
}

/* ПЕРЕПИСКА ДОПУЩЕНИЕМ: допущение обязано быть равенством; переписываются ВСЕ
   вхождения левой стороны, как это делает и ядро. */
static void ход_замены(Прогон *p, const char *строка) {
  long номер = номер_после(строка, "по дано ");
  int наоборот = содержит(строка, " обратно");
  Разрез r = разрез_по(часть(p->дано, номер), "равно");
  char *что = наоборот ? r.право : r.лево, *на = наоборот ? r.лево : r.право;
  if (!r.есть)
    беда_прогона(p, fmt("замена по дано %ld: допущения-равенства под этим номером нет", номер));
  else if (!есть_терм(первая_цель(p), что))
    беда_прогона(p, fmt("замена по дано %ld: в цели «%s» нет терма «%s»", номер, первая_цель(p), что));
  else одна_цель(p, терм(вставить_вместо(первая_цель(p), что, на)));
}

/* ПОРЯДОК СОСЕДЕЙ: переставляются два операнда ОДНОГО узла и только они —
   перестановка через скобки была бы ассоциативностью, а она в IEEE-754 ложна. */
static void ход_соседей(Прогон *p, const char *строка) {
  char *что = терм(в_уголках(строка, 1));
  const char *op = разделить_сверху(что, "плюс").n == 2 ? "плюс" :
                   (разделить_сверху(что, "умножить на").n == 2 ? "умножить на" : "");
  Разрез r = разрез_по(что, op);
  if (!*op)
    беда_прогона(p, fmt("соседи: «%s» не сумма и не произведение ровно двух соседей", что));
  else if (!есть_терм(первая_цель(p), что))
    беда_прогона(p, fmt("соседи: в цели «%s» нет терма «%s»", первая_цель(p), что));
  else одна_цель(p, терм(вставить_вместо(первая_цель(p), что, fmt("%s %s %s", r.право, op, r.лево))));
}

static void ход_выбора(Прогон *p, const char *строка) {
  char *что = терм(в_уголках(строка, 1));
  Разрез по_то = разрез_по(что, "то"), ветви = разрез_по(по_то.право, "иначе");
  char *условие = слова_после(по_то.лево, 1);
  char *взято = strcmp(условие, "да") == 0 ? ветви.лево : ветви.право;
  if (!(по_то.есть && ветви.есть && начинается(по_то.лево, "если ")))
    беда_прогона(p, fmt("выбор: «%s» не вида «если У то А иначе Б»", что));
  else if (!(strcmp(условие, "да") == 0 || strcmp(условие, "нет") == 0))
    беда_прогона(p, fmt("выбор: условие «%s» не вычислено до литерала — ветвь брать не из чего", условие));
  else if (!есть_терм(первая_цель(p), что))
    беда_прогона(p, fmt("выбор: в цели «%s» нет терма «%s»", первая_цель(p), что));
  else одна_цель(p, терм(вставить_вместо(первая_цель(p), что, взято)));
}

/* ДЕЛЕНИЕ ЦЕЛИ ПО УСЛОВИЮ. Берётся ТОЛЬКО выражение, стоящее в цели условием:
   у произвольного подтерма значений больше двух, и замена была бы ложью. */
static void ход_деления(Прогон *p, const char *строка) {
  char *что = терм(в_уголках(строка, 1)), *цель = первая_цель(p); Сп новые = ПУСТО;
  /* Условие, стоящее в цели в скобках — `если ( У ) то` — то же условие: так ядро
     печатает охрану, и обёрнутое вхождение снимается первым же проходом. */
  if (!содержит(цель, fmt("если %s то ", что)) && !содержит(цель, fmt("если ( %s ) то ", что))) {
    беда_прогона(p, fmt("деление: «%s» не стоит в цели условием («если … то»)", что)); return;
  }
  добавить(&новые, терм(вставить_вместо(цель, что, "да")));
  добавить(&новые, терм(вставить_вместо(цель, что, "нет")));
  вместо_первой(p, новые);
}

static void ход_закона(Прогон *p, const char *строка) {
  char *имя = в_ёлочках(строка, 1);
  Применение it = применить_закон(имя, первая_цель(p));
  if (!it.вышло) {
    беда_прогона(p, fmt("закон «%s» к цели «%s» не подошёл: %s", имя, первая_цель(p), it.почему)); return;
  }
  { Сп n = ПУСТО; int i; for (i = 0; i < it.посылки.n; i++) добавить(&n, терм(it.посылки.e[i]));
    вместо_первой(p, n); }
}

/* Равенство язык пишет двумя словами — «равно» и «равен», — и сверщик обязан
   читать оба, иначе он читает не тот язык. Порядок слов ЗНАЧИМ: у терма, несущего
   оба, разрез по первому и по второму — разные разрезы, и каждый зовущий называет
   свой порядок. Разрез идёт по границе слова, поэтому «X не равен Y» режется как
   «X не»/«Y» и тождеством не закрывается — это верно. */
static Разрез разрез_по_слову_равенства(const char *t, const char *первое, const char *второе) {
  Разрез r = разрез_по(t, первое);
  return r.есть ? r : разрез_по(t, второе);
}

static void закрыть_данным(Прогон *p, const char *строка, char *цель) {
  long номер = номер_после(строка, "закрыть дано ");
  char *факт = часть(p->дано, номер);
  if (strcmp(ужать(факт), ужать(цель)) == 0) вместо_первой(p, ПУСТО);
  else беда_прогона(p, fmt("закрыть дано %ld: цель «%s» не совпала с допущением «%s»", номер, цель, факт));
}

static void закрыть_тождеством(Прогон *p, char *цель) {
  Разрез r = разрез_по_слову_равенства(цель, "равно", "равен");
  if (r.есть && strcmp(ужать(r.лево), ужать(r.право)) == 0) вместо_первой(p, ПУСТО);
  else беда_прогона(p, fmt("закрыть тождеством: у цели «%s» стороны равенства разные", цель));
}

static void закрыть_истиной(Прогон *p, char *цель) {
  if (strcmp(цель, "да") == 0) вместо_первой(p, ПУСТО);
  else беда_прогона(p, fmt("закрыть истиной: цель «%s» не литерал «да»", цель));
}

static void закрыть_требованием(Прогон *p, const char *строка, Обст *o, char *цель) {
  char *имя = в_ёлочках(строка, 1);
  long где = номер_после(строка, "строка ");
  char *в_исх = строка_по_номеру(o->строки, где);
  char *факт = хвост_после(в_исх, fmt("требует «%s» ", имя));
  if (!начинается(в_исх, fmt("требует «%s» ", имя)))
    беда_прогона(p, fmt("закрыть требованием «%s»: в строке %ld исходника стоит «%s»", имя, где, в_исх));
  else if (strcmp(хозяин_строки(o->строки, где), o->функция) != 0)
    беда_прогона(p, fmt("закрыть требованием «%s»: строка %ld исходника стоит не в функции «%s»", имя, где, o->функция));
  else if (!совпали_цели(терм(факт), терм(цель)))
    беда_прогона(p, fmt("закрыть требованием «%s»: требование «%s» не совпало с целью «%s»", имя, терм(факт), цель));
  else вместо_первой(p, ПУСТО);
}

/* МОДУС ПОНЕНС над внесённым фактом. Равенством: `L равен R` подставляет R за L
   в да-ветвь цели, и та обязана свестись к тождеству. Неравенством: факт
   замыкает цель ТОЙ ЖЕ формы — тот же оператор порядка, стороны знак в знак;
   чужой знак, чужая правая сторона и цель-равенство (её ни один оператор
   порядка не режет) сюда не проходят. Строгие законы порядка (больше ⟹ не
   меньше) здесь НЕ вводим: закона, доказывающего строгое `больше R`, у сверщика
   нет, и закрывать было бы нечем. */
static void модус_поненс(Прогон *p, char *цель, char *цель_да, char *факт, char *равенство) {
  Разрез фр = разрез_по_слову_равенства(равенство, "равен", "равно");
  /* 4416, ВЫРОЖДЕННЫЙ СЛУЧАЙ. Факт, совпавший с целью ЗНАК В ЗНАК, цель и закрывает:
     выводить нечего — цель И ЕСТЬ внесённый факт. Так закрывается цель-ПРИЗНАК
     («Смертен» от сократ), которую ни равенством, ни неравенством порядка не
     разрезать, а прежде она получала «модус-поненс им цель не замыкает», то есть
     ложь на честном шаге. СТРОГОСТИ НЕ СНИМАЕТ: совпадение полное и после
     нормализации терма, а сам факт внесён ходом «факт по свойству» выше — с
     привязкой, инстанцией, оплатой предусловий и сторожем круга. Частный случай той
     же рефлексивности, что стоит ниже для неравенств (4127). */
  if (strcmp(ужать(терм(цель_да)), ужать(терм(равенство))) == 0) {
    p->посл_факт = (char *)""; вместо_первой(p, ПУСТО); return; }
  if (фр.есть) {
    char *после = терм(вставить_вместо(цель_да, фр.лево, фр.право));
    Разрез g = разрез_по_слову_равенства(после, "равно", "равен");
    if (g.есть && strcmp(ужать(g.лево), ужать(g.право)) == 0) { p->посл_факт = (char *)""; вместо_первой(p, ПУСТО); }
    else беда_прогона(p, fmt("закрыть по свойству: факт «%s» цель «%s» не закрывает", факт, цель));
    return;
  }
  { Разрез фн, цн; int фи = нерав_разрез(равенство, &фн), ци = нерав_разрез(цель_да, &цн);
    if (фи < 0)
      беда_прогона(p, fmt("закрыть по свойству: факт «%s» — ни равенство, ни неравенство порядка, модус-поненс им цель не замыкает", факт));
    else if (ци == фи &&
             strcmp(ужать(фн.лево), ужать(цн.лево)) == 0 &&
             strcmp(ужать(фн.право), ужать(цн.право)) == 0) {
      p->посл_факт = (char *)""; вместо_первой(p, ПУСТО);
    } else
      беда_прогона(p, fmt("закрыть по свойству: факт-неравенство «%s» цель «%s» не замыкает — знак, сторона или форма не те", факт, цель)); }
}

/* ЗАКРЫТЬ ПО СВОЙСТВУ. При охране `по охране ⟨У⟩` и цель, и факт стоят под одной
   охраной: охрана хода обязана БЫТЬ той посылкой, что стоит условием в цели, а
   не приписанной рядом; берётся ветвь `да`, ветвь `иначе да` закрывается истиной.
   Факт БЕЗУСЛОВНЫЙ верен на любой ветви и годится как есть; факт под ЧУЖОЙ
   охраной — отвергается. */
static void закрыть_по_свойству(Прогон *p, const char *строка, char *цель) {
  char *охрана = обрезать(в_уголках(строка, 1));
  char *факт = p->посл_факт ? p->посл_факт : (char *)"";
  char *цель_да = цель, *равенство = факт;
  if (!*факт) {
    беда_прогона(p, (char *)"закрыть по свойству: факта не внесено — нет хода «факт по свойству» перед закрытием"); return;
  }
  if (*охрана) {
    Разрез цель_то = разрез_по(цель, "то"),  цель_в = разрез_по(цель_то.право, "иначе");
    Разрез ф_то  = разрез_по(факт, "то"),  ф_в   = разрез_по(ф_то.право, "иначе");
    char *у_цель  = слова_после(цель_то.лево, 1);
    int факт_под_охраной = ф_то.есть && ф_в.есть && начинается(ф_то.лево, "если ");
    if (!(цель_то.есть && цель_в.есть && начинается(цель_то.лево, "если ") &&
          strcmp(ужать(у_цель), ужать(охрана)) == 0)) {
      беда_прогона(p, fmt("закрыть по свойству по охране ⟨%s⟩: цель «%s» не стоит под этой охраной условием", охрана, цель)); return;
    }
    if (strcmp(ужать(цель_в.право), "да") != 0) {
      беда_прогона(p, fmt("закрыть по свойству: ветвь «иначе» цели «%s» не «да» — истиной не закрыть", цель)); return;
    }
    цель_да = цель_в.лево;
    if (факт_под_охраной) {
      if (strcmp(ужать(слова_после(ф_то.лево, 1)), ужать(охрана)) != 0) {
        беда_прогона(p, fmt("закрыть по свойству по охране ⟨%s⟩: факт «%s» стоит под другой охраной", охрана, факт)); return;
      }
      равенство = ф_в.лево;
    } else равенство = факт;
  }
  модус_поненс(p, цель, цель_да, факт, равенство);
}

static void ход_закрытия(Прогон *p, const char *строка, Обст *o) {
  char *чем = слово(строка, 4), *цель = первая_цель(p);
  if (strcmp(чем, "дано") == 0) закрыть_данным(p, строка, цель);
  else if (strcmp(чем, "тождеством") == 0) закрыть_тождеством(p, цель);
  else if (strcmp(чем, "истиной") == 0) закрыть_истиной(p, цель);
  else if (strcmp(чем, "требованием") == 0) закрыть_требованием(p, строка, o, цель);
  else if (strcmp(чем, "по") == 0) закрыть_по_свойству(p, строка, цель);
  else беда_прогона(p, fmt("закрыть «%s» сверщику неизвестно", чем));
}

/* Инстанция условия СНЯТА в точке хода одним из трёх соундных источников
   (дожатие долга 4126, шапка оплаты ниже): «требует» вызывающей, охрана цели
   `если У то … иначе да`, доказанный факт `дано`. Зовут её оплата предусловий
   вызванной и ограничения `таких что` утверждения (К3c). */
static int снято_в_точке(Прогон *p, Обст *o, const char *инст) {
  Сп треб_ф = все_требования_функции(o->строки, o->функция);
  Разрез цт = разрез_по(первая_цель(p), "то"), цв = разрез_по(цт.право, "иначе");
  char *и = терм(инст); int j;
  for (j = 0; j < треб_ф.n; j++) if (совпали_цели(и, терм(формула_требования(треб_ф.e[j])))) return 1;
  if (цт.есть && цв.есть && начинается(цт.лево, "если ") && strcmp(ужать(цв.право), "да") == 0 &&
      совпали_цели(и, терм(слова_после(цт.лево, 1)))) return 1;
  for (j = 0; j < p->дано.n; j++) if (совпали_цели(и, терм(p->дано.e[j]))) return 1;
  return 0;
}

/* К3c, ПУТЬ ХОДА (контракт stack-B/kontrakt-kvantory.md §К3c):
   `ход K факт по свойству «И» строка M подстановка «л» ⟨Т⟩ [«м» ⟨У⟩ …]` вносит
   фактом ЦЕЛЬ УТВЕРЖДЕНИЯ «И» после подстановки. M — строка заголовка
   `утверждение «И»`, и постусловия с тем же именем нет; пары — ровно по одной
   на связанное имя, в порядке связывания, имя знак в знак; подстановка не
   захватывает имён (как (б′) ниже); ограничение `таких что` после подстановки
   обязано быть снято в точке хода. Цель и ограничения сверщик читает из
   исходника сам, из записи берутся только термы. Сторож круга (оба уровня) уже
   пройден в `ход_факта_свойством`: реестр держит и утверждения. */
static void факт_утверждения(Прогон *p, const char *строка, Обст *o, const char *имя_п, long где) {
  Сп имена = ПУСТО, пн = ПУСТО, пт = ПУСТО, огр = ПУСТО; int i, j; long k;
  char *инст = терм(из_высказывания(o->строки, где, NULL, &имена));
  const char *q = strstr(строка, " подстановка ") + strlen(" подстановка "), *e;
  if (строка_высказывания(o->строки, fmt("утверждение «%s»", имя_п)) != где) {
    беда_прогона(p, fmt("факт по свойству «%s»: строка %ld исходника — не заголовок «утверждение «%s»»", имя_п, где, имя_п)); return; }
  if (номер_свойства(o->строки, имя_п)) {
    беда_прогона(p, fmt("факт по свойству: имя «%s» носят и постусловие, и утверждение — назовите одно", имя_п)); return; }
  while (*q == ' ') q++;
  while (начинается(q, "«") && (e = strstr(q, "» ⟨")) != NULL && strstr(e, "⟩")) {
    const char *т = e + strlen("» ⟨"), *кон = strstr(т, "⟩");
    добавить(&пн, копия(q + strlen("«"), (size_t)(e - q) - strlen("«")));
    добавить(&пт, копия(т, (size_t)(кон - т)));
    for (q = кон + strlen("⟩"); *q == ' '; q++) ;
  }
  if (*q || пн.n != имена.n) {
    беда_прогона(p, fmt("факт по свойству «%s»: подстановка «%s» — не пары «имя» ⟨терм⟩ по одной на каждое из %d связанных имён",
                        имя_п, хвост_после(строка, " подстановка "), имена.n)); return; }
  for (i = 0; i < имена.n; i++) {
    if (strcmp(пн.e[i], имена.e[i]) != 0) {
      беда_прогона(p, fmt("факт по свойству «%s»: чужая подстановка — на месте связанного «%s» стоит «%s»", имя_п, имена.e[i], пн.e[i])); return; }
    for (j = i + 1; j < имена.n; j++)
      if (есть_терм(терм(пт.e[i]), имена.e[j])) {
        беда_прогона(p, fmt("факт по свойству «%s»: подстановка захватила бы имя «%s» — инстанции нет", имя_п, имена.e[j])); return; }
  }
  for (k = где + 1; k <= o->строки.n && начинается(часть(o->строки, k), " "); k++)
    if (содержит(часть(o->строки, k), " таких что "))
      добавить(&огр, хвост_после(как_читает_язык(обрезать(часть(o->строки, k))), " таких что "));
  for (i = 0; i < имена.n; i++) инст = вставить_вместо(инст, имена.e[i], терм(пт.e[i]));
  for (j = 0; j < огр.n; j++) {
    char *ог = терм(огр.e[j]);
    for (i = 0; i < имена.n; i++) ог = вставить_вместо(ог, имена.e[i], терм(пт.e[i]));
    if (!снято_в_точке(p, o, ог)) {
      беда_прогона(p, fmt("факт по свойству «%s»: ограничение утверждения «%s» в точке хода не снято (инстанция «%s»)", имя_п, огр.e[j], терм(ог))); return; }
  }
  p->посл_факт = терм(инст);
  p->ходов++;
}

/* 4123, ХОД S2 «факт по свойству» — перепроверки (а), (б), сторож круга, оплата.
   `ход K факт по свойству «имя-П» строка N вызов ⟨«Г» от а₁ … аₙ⟩` вносит
   ИНСТАНЦИРОВАННОЕ постусловие вызванной функции как ФАКТ. Инстанцию чекер строит
   САМ (двумя подстановками), не берёт из записи — иначе снимок-со-снимком. Факт не
   закрывает цель, а лишь ложится в `посл_факт`; замыкает его следующий ход
   `закрыть по свойству`. */
static void ход_факта_свойством(Прогон *p, const char *строка, Обст *o) {
  char *имя_п = в_ёлочках(строка, 1);
  long где = номер_после(строка, "строка ");
  char *вызов = терм(в_уголках(строка, 1));
  char *имя_г = в_ёлочках(вызов, 1);
  char *в_исх, *тело_п; Сп param, арги, треб_г; int i, j, раньше = 0, подст = содержит(строка, " подстановка ");
  if (!*имя_п || где < 1 || (!*имя_г && !подст)) {
    беда_прогона(p, fmt("факт по свойству: ход «%s» неполон — нужны «имя-П», «строка N» и «вызов ⟨«Г» от …⟩»", строка)); return;
  }
  /* СТОРОЖ КРУГА, УРОВЕНЬ 1 — прямая самоссылка по имени: функция не вправе
     обосновать себя своим же ещё-не-доказанным постусловием (ядро proofterm.flang
     1110). Повторяем ровно это над обязательством записи. */
  if (*o->обяз && strcmp(имя_п, o->обяз) == 0) {
    беда_прогона(p, fmt("факт по свойству «%s»: это круг — постусловие ссылается на само себя", имя_п)); return;
  }
  /* СТОРОЖ КРУГА, УРОВЕНЬ 2 — через рекурсию/взаимную рекурсию, ПОСТРОЕНИЕМ:
     фактом вправе стать лишь постусловие, ДОКАЗАННОЕ РАНЬШЕ этой цели. Реестр
     `o->доказанные` держит имена постусловий, проверенных до текущего (порядок
     записи линеен). Нет в реестре — рекурсия начаться не может (проект §3). */
  for (i = 0; i < o->доказанные.n; i++) if (strcmp(o->доказанные.e[i], имя_п) == 0) { раньше = 1; break; }
  if (!раньше) {
    /* 4416: ДВА СЛУЧАЯ, И ОНИ РАЗНЫЕ. Имени нет в реестре проверенного ПО СУЩЕСТВУ
       по двум несхожим причинам. Либо запись вовсе не числит его доказанным (нет
       вердикта, вердикт другой, блока нет) — тогда фактом его брать нельзя, и это
       ложь, код 1. Либо ядро объявило вердикт «доказано», а сверщик сам этого не
       переиграл, — тогда по собственной доктрине трёх исходов сверщику положено
       сказать «не взялся»: место на слове ядра, код 3. */
    if (среди(o->объявленные, имя_п)) не_взялся_прогона(p, fmt("факт по свойству «%s»: утверждение, но оно не проверено по существу раньше этой цели", имя_п));
    else беда_прогона(p, fmt("факт по свойству «%s»: постусловие не доказано РАНЬШЕ этой цели — фактом брать нельзя (круг или обратный порядок)", имя_п));
    return;
  }
  if (подст) { факт_утверждения(p, строка, o, имя_п, где); return; }     /* К3c: «И» — утверждение */
  /* (а) АТРИБУЦИЯ ПО РЕБРУ: строка N исходника несёт «обеспечивает «имя-П»», лежит
     в блоке ИМЕННО той «Г», что вызвана в узле (не первой одноимённой у чужой
     функции), и N — первое по файлу объявление (как ищет само правило, 3455). */
  в_исх = строка_по_номеру(o->строки, где);
  if (!начинается(в_исх, fmt("обеспечивает «%s» ", имя_п))) {
    беда_прогона(p, fmt("факт по свойству «%s»: строка %ld исходника не несёт «обеспечивает «%s»» (стоит «%s»)", имя_п, где, имя_п, в_исх)); return;
  }
  if (strcmp(хозяин_строки(o->строки, где), имя_г) != 0) {
    беда_прогона(p, fmt("факт по свойству «%s»: строка %ld стоит в функции «%s», а вызвана «%s» — привязка НЕ ПО РЕБРУ",
                        имя_п, где, хозяин_строки(o->строки, где), имя_г)); return;
  }
  if (номер_свойства(o->строки, имя_п) != где) {
    беда_прогона(p, fmt("факт по свойству «%s»: строка %ld — не первое объявление постусловия (первое — %ld)",
                        имя_п, где, номер_свойства(o->строки, имя_п))); return;
  }
  тело_п = цель_обещанная(обрезать(хвост_после(в_исх, fmt("обеспечивает «%s» ", имя_п))));   /* К7: У[м:=Т] */
  param = доводы_функции(o->строки, имя_г).голые;
  арги = доводы_вызова(хвост_после(вызов, fmt("«%s» от ", имя_г)));
  if (param.n != арги.n) {
    беда_прогона(p, fmt("факт по свойству «%s»: у «%s» параметров %d, а в вызове аргументов %d — арность не совпала",
                        имя_п, имя_г, param.n, арги.n)); return;
  }
  /* (б′) ЗАХВАТ ИМЕНИ. Подстановка `вставить_вместо` идёт ПОСЛЕДОВАТЕЛЬНО, и при
     перестановке имён параметров она алиасит: имя аргумента, свободно совпавшее с
     параметром, который ещё подставится, было бы переписано второй подстановкой
     (`«Г» от б и а` при параметрах а,б: а→б делает б, следом б→а рушит оба в а).
     Ядро в таком месте инстанцию НЕ строит, а отказывает (proofterm.flang 1174:
     «подстановка ЗАХВАТИЛА БЫ имя»). Повторяем ровно это: аргумент арги[i] несёт
     свободным именем параметр param[j] с j>i — захват, инстанции нет. */
  for (i = 0; i < param.n; i++)
    for (j = i + 1; j < param.n; j++)
      if (есть_терм(арги.e[i], param.e[j])) {
        беда_прогона(p, fmt("факт по свойству «%s»: подстановка захватила бы имя — в аргументе «%s» свободно имя «%s», а оно ещё подставится параметром (перестановка имён); инстанции нет",
                            имя_п, терм(арги.e[i]), param.e[j])); return;
      }
  /* ОПЛАТА `требует`: постусловие вызванной верно лишь при выполненных её
     предусловиях, потому КАЖДОЕ инстанцируется по вызову и обязано быть СНЯТО в
     точке вызова одним из трёх источников:
       (1) `требует` ВЫЗЫВАЮЩЕЙ — её предусловия суть законные допущения тела;
       (2) ОХРАНА ЦЕЛИ `если У то … иначе да` — цель доказывается под допущением У,
           и факт ляжет под ту же охрану; цель БЕЗ охраны не снимает ничего;
       (3) ДОКАЗАННЫЙ ФАКТ `дано` — посчитанный самим сверщиком, не взятый из записи.
     Не снято ничем — факт НЕ берётся: соундность прежде полноты. */
  треб_г = все_требования_функции(o->строки, имя_г);
  for (i = 0; i < треб_г.n; i++) {
    char *п_инст = формула_требования(треб_г.e[i]);
    for (j = 0; j < param.n; j++) п_инст = вставить_вместо(п_инст, param.e[j], терм(арги.e[j]));
    if (!снято_в_точке(p, o, п_инст)) {
      беда_прогона(p, fmt("факт по свойству «%s»: предусловие «%s» вызванной «%s» в точке вызова не снято — инстанция «%s» не снята ни «требует» вызывающей «%s», ни охраной цели, ни доказанным фактом; постусловие фактом не берётся",
                          имя_п, формула_требования(треб_г.e[i]), имя_г, терм(п_инст), o->функция)); return;
    }
  }
  { char *инст = тело_п;
    for (i = 0; i < param.n; i++) инст = вставить_вместо(инст, param.e[i], терм(арги.e[i]));
    инст = вставить_вместо(инст, "результат", в_скобки(вызов));
    p->посл_факт = терм(инст);
    p->ходов++;    /* факт цель не меняет — счётчик хода двигаем сами */
  }
}

static void ход_цели(Прогон *p, Обст *o) {
  char *начало = начальная_цель(o, p->вариант);
  if (!*начало) {
    беда_прогона(p, fmt("ход цель: случая варианта «%s» в теореме нет", p->вариант)); return;
  }
  p->цели = ПУСТО; добавить(&p->цели, начало);
  p->дано = ПУСТО; p->ходов = 0; p->идёт = 1; p->оборван = 0; p->посл_факт = (char *)"";
}

/* ДОПУЩЕНИЕ ИНДУКЦИИ не читается из записи: чекер считает его сам — то же
   утверждение теоремы, но о названной части значения. */
static void ход_допущения(Прогон *p, const char *строка, Обст *o) {
  char *имя = в_ёлочках(строка, 1);
  char *случай = случай_варианта(o, p->вариант);
  char *поле = поле_образца(случай, имя);
  if (!содержит(строка, " предположение по "))
    беда_прогона(p, (char *)"ход дано: сверщик знает один источник допущения — «предположение по «имя»»");
  else if (!*поле)
    беда_прогона(p, fmt("допущение по «%s»: такого имени образец случая «%s» не связывает", имя, p->вариант));
  else if (!поле_рекурсивно(o, p->вариант, поле))
    беда_прогона(p, fmt("допущение по «%s»: поле «%s» варианта «%s» не того же типа «%s» — это не индукция, а круг",
                        имя, поле, p->вариант, o->тип));
  else добавить(&p->дано, цель_при_значении(o, имя));
}

static void ход_конца(Прогон *p) {
  if (!p->идёт) { if (!p->оборван) беда_прогона(p, (char *)"ход конец стоит без «ход цель»"); }
  else if (p->цели.n)
    беда_прогона(p, fmt("сведение посылки «%s» не доведено: незакрытых целей %d — первая «%s»",
                        p->вариант, p->цели.n, первая_цель(p)));
  else { p->проиграно++; p->идёт = 0; }
}

static void новая_посылка(Прогон *p, const char *строка) {
  if (p->идёт) беда_прогона(p, fmt("сведение посылки «%s» оборвано: «ход конец» не стоит", p->вариант));
  p->цели = ПУСТО; p->дано = ПУСТО; p->ходов = 0; p->идёт = 0; p->оборван = 0;
  p->вариант = в_ёлочках(строка, 1); p->посл_факт = (char *)"";
}

static void ход_вычисления(Прогон *p, const char *строка, Обст *o);

static void ход_переписки_формой(Прогон *p, const char *строка);
static void ход_переписки_свойством(Прогон *p, const char *строка, Обст *o);

/* СВЯЗКА ЦЕЛИ (задача 6127). `связка ⟨и притом⟩` — цель `Л и притом П` даёт ДВЕ
   цели, обе обязаны закрыться; `связка ⟨или⟩ левая|правая` — цель `Л или П`
   даёт ОДНУ, названную половину (доказать её и значит доказать дизъюнкцию).
   Половины обязаны быть простыми (обняты скобками либо одно слово): у голого
   `а не меньше 0 и притом б` старшинства сверщик не знает. Ход ничего не
   считает — он читает написанную связку. */
static void ход_связки(Прогон *p, const char *строка) {
  char *связка = обрезать(в_уголках(строка, 1)), *цель = первая_цель(p);
  char *какая = слово(обрезать(хвост_после(строка, "⟩")), 1);
  Разрез r;
  if (strcmp(связка, "и притом") != 0 && strcmp(связка, "или") != 0) {
    беда_прогона(p, fmt("связка ⟨%s⟩: сверщик знает две связки — «и притом» и «или»", связка)); return; }
  r = разрез_по(цель, связка);
  if (!r.есть || разделить_сверху(ужать(цель), связка).n != 2) {
    беда_прогона(p, fmt("связка ⟨%s⟩: цель «%s» не связка ровно двух половин этим словом", связка, цель)); return; }
  if (!простой(r.лево) || !простой(r.право)) {
    беда_прогона(p, fmt("связка ⟨%s⟩: половины цели «%s» не обняты скобками — старшинства сверщик не знает", связка, цель)); return; }
  if (strcmp(связка, "и притом") == 0) {
    Сп новые = ПУСТО;
    if (*какая) { беда_прогона(p, (char *)"связка ⟨и притом⟩ половину не выбирает: обе идут целями"); return; }
    добавить(&новые, терм(r.лево)); добавить(&новые, терм(r.право));
    вместо_первой(p, новые); return;
  }
  if (strcmp(какая, "левая") == 0) одна_цель(p, терм(r.лево));
  else if (strcmp(какая, "правая") == 0) одна_цель(p, терм(r.право));
  else беда_прогона(p, (char *)"связка ⟨или⟩: надо назвать половину — «левая» или «правая»");
}

/* Язык чист и тотален, и `пусть имя равно значение` есть ровно подстановка
   значения вместо имени. Имя берётся из ИСХОДНИКА по номеру строки и не вправе
   быть доводом функции (заслонить довод подстановкой нельзя) и звать себя в
   своём же значении. `пусть`, которого в цели нет, — отказ, а не пустая работа. */
static void ход_подстановки_пусть(Прогон *p, const char *строка, Обст *o) {
  long где = номер_после(строка, "строка ");
  char *l = как_читает_язык(строка_по_номеру(o->строки, где)), *имя, *знач;
  if (strcmp(слово(строка, 4), "пусть") != 0) {
    беда_прогона(p, fmt("ход «подставить %s» неизвестен: есть «подставить пусть строка N»", слово(строка, 4))); return; }
  if (где < 1) { беда_прогона(p, (char *)"подставить пусть: номер строки исходника не назван"); return; }
  if (!начинается(l, "пусть ") || strcmp(слово(l, 3), "равно") != 0) {
    беда_прогона(p, fmt("подставить пусть: строка %ld исходника не вида «пусть имя равно значение», а «%s»", где, l)); return; }
  имя = слово(l, 2); знач = терм(слова_после(l, 3));
  if (!*имя || содержит(имя, "(") || содержит(имя, "«") || !*знач) {
    беда_прогона(p, fmt("подставить пусть: в строке %ld имя не одно слово либо значение пусто", где)); return; }
  if (strcmp(хозяин_строки(o->строки, где), o->функция) != 0) {
    беда_прогона(p, fmt("подставить пусть: строка %ld исходника стоит в функции «%s», а не в «%s»", где, хозяин_строки(o->строки, где), o->функция)); return; }
  if (strcmp(имя, часть(доводы_функции(o->строки, o->функция).имена, 1)) == 0 ||
      есть_терм(доводы_функции(o->строки, o->функция).хвост, имя)) {
    беда_прогона(p, fmt("подставить пусть: имя «%s» — довод функции «%s», подстановкой его не заслонить", имя, o->функция)); return; }
  if (есть_терм(знач, имя)) {
    беда_прогона(p, fmt("подставить пусть: значение «%s» зовёт своё же имя «%s»", знач, имя)); return; }
  if (!есть_терм(первая_цель(p), имя)) {
    беда_прогона(p, fmt("подставить пусть: в цели «%s» нет имени «%s»", первая_цель(p), имя)); return; }
  одна_цель(p, терм(вставить_вместо(первая_цель(p), имя, знач)));
}

/* НЕЙТРАЛЬНЫЙ НОЛЬ (задача 5144, ведомость Тожд2): `Т плюс 0` и `0 плюс Т` — это Т,
   когда Т строго положительно ПОСЫЛКОЙ утверждения: строка исходника
   `для всех … таких что Т больше К` (или `К меньше Т`), К — литерал не меньше нуля.
   Без посылки ход — отказ, и это не осторожность: `неотрицательное` при работе
   принимает минус ноль, `−0 плюс 0` есть `+0`, а `равен` языка (Object.is) их
   различает — «н плюс 0 равен н» на −0 ЛОЖНО. Литерал нуля — ровно «0», не «-0».
   Форма строки: `ход N нейтральный ноль ⟨Т плюс 0⟩`. */
static void ход_нейтрального_нуля(Прогон *p, const char *строка, Обст *o) {
  char *что = терм(в_уголках(строка, 1)), *т; Разрез r; int k, есть = 0;
  if (strcmp(слово(строка, 4), "ноль") != 0) {
    беда_прогона(p, fmt("ход «нейтральный %s» неизвестен: есть «нейтральный ноль ⟨Т плюс 0⟩»", слово(строка, 4))); return; }
  r = разрез_по(что, "плюс");
  if (!r.есть || разделить_сверху(ужать(что), "плюс").n != 2) {
    беда_прогона(p, fmt("нейтральный ноль: «%s» не сумма ровно двух слагаемых", что)); return; }
  if (strcmp(ужать(r.право), "0") == 0) т = ужать(r.лево);
  else if (strcmp(ужать(r.лево), "0") == 0) т = ужать(r.право);
  else { беда_прогона(p, fmt("нейтральный ноль: в «%s» ни одно слагаемое не литерал 0", что)); return; }
  for (k = 0; k < o->ограничения.n && !есть; k++) {
    Разрез б = разрез_по(o->ограничения.e[k], "больше"), м = разрез_по(o->ограничения.e[k], "меньше");
    if (б.есть && strcmp(ужать(б.лево), т) == 0 && число_из_слова(ужать(б.право)) >= 0) есть = 1;
    if (м.есть && strcmp(ужать(м.право), т) == 0 && число_из_слова(ужать(м.лево)) >= 0) есть = 1;
  }
  if (!есть) {
    беда_прогона(p, fmt("нейтральный ноль: посылки «%s больше К» (К не меньше 0) среди «таких что» утверждения нет — на минус нуле «%s плюс 0 равен %s» ложно", т, т, т)); return; }
  if (!есть_терм(первая_цель(p), что)) {
    беда_прогона(p, fmt("нейтральный ноль: в цели «%s» нет терма «%s»", первая_цель(p), что)); return; }
  одна_цель(p, терм(вставить_вместо(первая_цель(p), что, т)));
}

/* НОМЕР ХОДА СЧИТАЕТСЯ, а не украшает: пропавший посередине ход виден и по
   номеру, и по несошедшейся цели, и первое сообщение понятнее второго. */
static void ход_шага(Прогон *p, const char *строка, Обст *o) {
  char *род = слово(строка, 3);
  long номер = (long)число_из_слова(слово(строка, 2));
  if (!p->идёт) { if (!p->оборван) беда_прогона(p, fmt("ход «%s» стоит до «ход цель»", строка)); return; }
  if (номер != p->ходов + 1) {
    беда_прогона(p, fmt("ход %ld стоит %ld-м: ход пропущен или переставлен", номер, p->ходов + 1)); return;
  }
  if (!p->цели.n) { беда_прогона(p, fmt("ход %ld: незакрытых целей не осталось, ход лишний", номер)); return; }
  if (strcmp(род, "развернуть") == 0) ход_развёртки(p, строка, o);
  else if (strcmp(род, "замена") == 0) ход_замены(p, строка);
  else if (strcmp(род, "соседи") == 0) ход_соседей(p, строка);
  else if (strcmp(род, "выбор") == 0) ход_выбора(p, строка);
  else if (strcmp(род, "деление") == 0) ход_деления(p, строка);
  else if (strcmp(род, "закон") == 0) ход_закона(p, строка);
  else if (strcmp(род, "закрыть") == 0) ход_закрытия(p, строка, o);
  else if (strcmp(род, "вычислить") == 0) ход_вычисления(p, строка, o);
  else if (strcmp(род, "переписать") == 0) {
    if (strcmp(слово(строка, 4), "по") == 0) ход_переписки_свойством(p, строка, o);
    else ход_переписки_формой(p, строка); }
  else if (strcmp(род, "факт") == 0) ход_факта_свойством(p, строка, o);
  else if (strcmp(род, "связка") == 0) ход_связки(p, строка);
  else if (strcmp(род, "подставить") == 0) ход_подстановки_пусть(p, строка, o);
  else if (strcmp(род, "нейтральный") == 0) ход_нейтрального_нуля(p, строка, o);
  else беда_прогона(p, fmt("ход «%s» сверщику неизвестен: первичных ходов тринадцать, и список закрыт", род));
}

static Прогон проиграть_блок(Обст *o) {
  Прогон p; int i;
  memset(&p, 0, sizeof p); p.вариант = (char *)""; p.посл_факт = (char *)"";
  for (i = 0; i < o->свои.n; i++) {
    char *s = обрезать(o->свои.e[i]);
    if (начинается(s, "посылка ")) { новая_посылка(&p, s); continue; }
    if (!начинается(s, "ход ")) continue;
    { char *второе = слово(s, 2);
      if (strcmp(второе, "цель") == 0) ход_цели(&p, o);
      else if (strcmp(второе, "дано") == 0) ход_допущения(&p, s, o);
      else if (strcmp(второе, "конец") == 0) ход_конца(&p);
      else ход_шага(&p, s, o); }
  }
  if (p.идёт) беда_прогона(&p, fmt("сведение посылки «%s» оборвано на конце блока: «ход конец» не стоит", p.вариант));
  return p;
}


/* `крипто` — привязка к программе стоит на SHA-256 и сошлась. Ноль значит не
   «подделка», а «проверить нечем»: исход 3. `приметы` — то, что человеку знать
   полезно, а на исход не влияет. */
typedef struct { Сп беды, приметы; long на_слово, шагов, утверждений, сведений, ходов,
                 узлов, узлов_мест, узлов_мимо,
                 /* 6127: сколько из `узлов_мест` снято БУЛЕВОЙ веткой узла algebra
                    (замыкание `половина_закрыта` — вычислитель, а не структурный
                    переигрыш); линейка вычитает это из структурного. `узел_булев` —
                    флаг последнего проигранного узла, ставит `проиграть_узел_algebra`. */
                 узлов_булево_мест, узел_булев,
                 /* СТОРОЖ ЛОЖНОЙ ПЕРЕПИСКИ: оба числа — про ПОИМКУ, а не про снятие. Мест со
                    слова ядра этот сторож не снимает, и счётчика снятого у него нет. */
                 переписок_поймано, переписок_мимо,
                 разбор, разбор_мест, разбор_мимо, разбор_не_закрылась,
                 /* Приём «вывод»: блоков проиграно и мест этим снято со слова ядра. Второе
                    печатается общей меткой «снято со слова ядра мест» — линейка складывает
                    снятое по всем приёмам, и слагаемое без общей метки тихо выпало бы из
                    тождества. */
                 выводов, выводов_мест,
                 /* 3464: шаги теоремы, обоснованные правилом ведомости («по закону
                    «О10» из 1 и 2»). Считаются порознь затем, что блок `вывод`,
                    проигранный заново, эти самые места УЖЕ проверил по существу:
                    взять за них плату вторым счётом значило бы уронить долю ложью. */
                 шагов_законом,
                 без_привязки, шагов_на_слово, шагов_примером, шагов_свойством, доказанных,
                 /* Места и шаги, проигранные ПО ТЕЛУ ФУНКЦИИ без записанных ходов. Оба числа
                    печатаются одной меткой «проверено по телу функции»: линейка складывает их в
                    тождество двух приборов, и слагаемое без метки тихо выпало бы из него. */
                 шагов_по_телу, мест_по_телу,
                 /* Ч7104: из `шагов_на_слово` — те шаги, которых сверщик не
                    проигрывает вовсе (сегодня это «по предположению»). Число
                    нужно затем, что узел вердикта, проигранный заново, эти
                    самые шаги УЖЕ проверил: он прочёл тело функции и сверил
                    дно со спуском. Брать за них плату второй раз значило бы
                    ронять долю ложью, а не поднимать честностью. */
                 шагов_не_проигрываемых,
                 сверено_обоими,
                 снятий, снятий_проиграно, снятий_на_слово,
                 /* Мест вызова под `требует` у записи без единого блока снятия: они не
                    проиграны, и доля кладёт их в знаменатель, а не молчит о них. */
                 снятий_без_блока; char *sha; int крипто;
                 /* Ч56: вердикт по каждому утверждению порознь (ключ
                    `--по-утверждениям`), а не один на весь файл. */
                 Сп по_утверждениям;
                 /* Ч76: почему сверщик НЕ ВЗЯЛСЯ за шаг вне случая. Молча не
                    брать нельзя — это и есть правило Ч27 о закрытых списках:
                    сломайся приём, и он обязан назвать причину поимённо, а не
                    просто «проверить меньше». */
                 Сп не_взялся;
                 Сп шаги_отложенные;
                 /* 4123, S2 «постусловие вызванной»: реестр постусловий, уже
                    ДОКАЗАННЫХ РАНЬШЕ по порядку записи. Ход `факт по свойству`
                    вправе внести фактом лишь то, что стоит в этом реестре, —
                    сторож круга через рекурсию/взаимную рекурсию (проект §3:
                    неподвижная точка «Закрыть без теорем», ядро proofterm.flang
                    2490). Пополняется в главном цикле ПОСЛЕ каждого утверждения;
                    там, где в записи есть «по свойству», его собирает раньше
                    предпроход `реестр_доказанного` — до неподвижной точки, и тогда
                    порядок печати блоков на вердикт не влияет (4416). */
                 /* 4416: `объявленные_доказанными` — имена всех блоков, чей вердикт ядро
                    напечатало словом «доказано»; собираются одним проходом, потому порядка
                    печати не знают. Смотри `Обст.объявленные`: права взять факт не дают. */
                 Сп доказанные_свойства, объявленные_доказанными; } Сверка;

static void если_не(Сверка *s, int условие, char *текст) { if (!условие) добавить(&s->беды, текст); }

/* Правила сведения названы списком, и список закрыт: правила, которого здесь
   нет, сверщик не принимает. Список обязан совпадать с тем, что ядро способно
   поставить в поле правила: недостающее в нём имя отвергает честную запись как
   подделку. Что список ПОЛОН, стережёт отдельный прогон дерева, а не этот файл. */
static const char *ПРАВИЛА[] = {
  "", "неотрицательность по построению", "ограниченность точным потолком по построению",
  "тождество после переписки допущением", "порядок по построению", "строгий порядок по построению",
  "порядок соседних по построению", "вхождение по построению", "цель есть допущение",
  "несовместимые допущения", "вычисление замкнутой цели", "разбор цели по условию",
  "цель-выбор с истинной ветвью", "разбор случаев по дизъюнкции в допущении",
  "разбор случаев по внутреннему условию цели", "равенство, решённое счётом замкнутых частей",
  "начало по построению", "все элементы по построению"
};

/* ГРАНИЦА ДОВЕРИЯ: примитивы языка тотальны по определению — над IEEE-754 и
   встроенными обходами доказывать нечего, строки объявления у них нет. Это
   единственное, что сертификат тотальности-композиции берёт на слово. Имя вне
   списка отвергается ВСЛУХ, а не пропускается: граница названа, а не растворена
   молчанием. */
static const char *ПРИМИТИВЫ[] = {
  "плюс", "минус", "умножить", "делить", "остаток",
  "длина", "соединить", "подстрока", "содержит", "начинается",
  "если", "разбор", "свёртка", "отобразить", "отфильтровать"
};
static int примитив_языка(const char *имя) {
  int i;
  for (i = 0; i < (int)(sizeof ПРИМИТИВЫ / sizeof *ПРИМИТИВЫ); i++)
    if (strcmp(имя, ПРИМИТИВЫ[i]) == 0) return 1;
  return 0;
}

static void сверить_шапку(Сверка *s, Сп шапка, const char *исходник) {
  long строк = номер_после(часть(шапка, 3), "строк ");
  long знаков_в = номер_после(часть(шапка, 4), "знаков ");
  long первый = (long)число_из_слова(слово(часть(шапка, 5), 2));
  long второй = (long)число_из_слова(слово(часть(шапка, 5), 3));
  long строка_в_исх = разделить(исходник, "\n").n, знак_в_исх = знаков(исходник);
  если_не(s, strcmp(часть(шапка, 1), "запись доказательства 1") == 0,
          (char *)"шапка не та: первой строкой обязано стоять «запись доказательства 1»");
  если_не(s, строк == строка_в_исх,
          fmt("в записи строк %ld, а в исходнике %ld — запись не от этой программы", строк, строка_в_исх));
  если_не(s, знаков_в == знак_в_исх,
          fmt("в записи знаков %ld, а в исходнике %ld — запись не от этой программы", знаков_в, знак_в_исх));
  если_не(s, первый == отпечаток(исходник, 131, 1000000007),
          (char *)"первый отпечаток не сошёлся — запись не от этой программы");
  если_не(s, второй == отпечаток(исходник, 137, 998244353),
          (char *)"второй отпечаток не сошёлся — запись не от этой программы");
  { char *сильный = первая_с_началом(шапка, "отпечаток256 ");
    if (*сильный) {
      if (strcmp(слово(сильный, 2), s->sha) == 0) s->крипто = 1;
      else добавить(&s->беды, fmt("отпечаток256 записи «%s» не сошёлся с исходником «%s»",
                                 слово(сильный, 2), s->sha));
    } }
}

static const char *вид_строки_записи(const char *s) {
  if (strcmp(s, "следовательно доказано да") == 0) return "доказано";
  if (начинается(s, "дано «")) return "дано";
  if (начинается(s, "допущение ⟨")) return "допущение";
  if (начинается(s, "цель строка") || начинается(s, "цель ⟨")) return "утверждаем";
  if (начинается(s, "индукция по ")) return "индукция";
  if (начинается(s, "случай строка")) return "случай";
  return начинается(s, "шаг ") ? "шаг" : "";
}

/* Список меток, как их обещает ЗАПИСЬ: тот же порядок и тот же вид, что даёт
   чтение исходника. Сойтись обязаны знак в знак. Строка записи без номера —
   будущий вид: тогда номера снимаются с ОБЕИХ сторон, и это считается. */
static Сп разметка_записи(Сп свои, long начало, int *без_номеров) {
  Сп метки = ПУСТО; int i;
  добавить(&метки, fmt("теорема %ld", начало));
  for (i = 0; i < свои.n; i++) {
    char *s = обрезать(свои.e[i]);
    const char *вид = вид_строки_записи(s);
    long где;
    if (!*вид) continue;
    if (strcmp(вид, "доказано") == 0) { добавить(&метки, (char *)"доказано"); continue; }
    где = номер_после(s, "строка ");
    if (где < 1) *без_номеров = 1;
    добавить(&метки, fmt("%s %ld", вид, где));
  }
  return метки;
}
static char *без_номеров_в(Сп v) {
  Сп r = ПУСТО; int i;
  for (i = 0; i < v.n; i++) добавить(&r, слово(v.e[i], 1));
  return соединить(r, ", ");
}

/* ТЕРМИН И НОМЕР СТРОКИ — ДВА СВИДЕТЕЛЯ ОБ ОДНОМ МЕСТЕ. Веток три: один номер —
   читается исходник; номер И термин — сверяются друг против друга; термин без
   номера — обязан сойтись с обоснованием той же строки. Запись, несущая термин
   вместо номера, не вправе проверяться МЕНЬШЕ, чем несущая номер. */
static int есть_уголки(const char *s) {
  const char *a = strstr(s, "⟨");
  return a != NULL && strstr(a + strlen("⟨"), "⟩") != NULL;
}
/* Строка записи без терма в уголках: термин несёт пробелы и ёлочки внутри
   себя, и без выреза они съезжали бы в пословный разбор (слово номер N,
   N-е ёлочки) — та самая беда, что делает вид «термин вместо номера»
   нерабочим сегодня. */
static char *без_уголков(const char *s) {
  const char *a = strstr(s, "⟨"), *b;
  if (!a) return (char *)s;
  b = strstr(a + strlen("⟨"), "⟩");
  if (!b) return (char *)s;
  return сжать_пробелы(fmt("%s %s", копия(s, (size_t)(a - s)), b + strlen("⟩")));
}
static char *шаг_словами(const char *ш) { return есть_уголки(ш) ? без_уголков(ш) : (char *)ш; }

/* Термин при номере обязан повторить написанное в исходнике на названной
   строке: у цели — хвост после «утверждаем», у шага — строку без «то»/«затем». */
static void сверить_терм_и_номер(Сверка *s, const char *строка_записи,
                                const char *в_исходнике, long где,
                                const char *имя_т, const char *что) {
  char *в_записи, *в_исх;
  if (где < 1 || !есть_уголки(строка_записи)) return;
  в_записи = терм(в_уголках(строка_записи, 1));
  в_исх = терм(в_исходнике);
  if (strcmp(в_записи, в_исх) == 0) { s->сверено_обоими++; return; }
  добавить(&s->беды,
          fmt("теорема «%s», %s, строка %ld: термин записи и исходник говорят о разном — "
              "в записи ⟨%s⟩, а на строке %ld исходника написано «%s»",
              имя_т, что, где, в_записи, где, в_исх));
}
/* Термин БЕЗ номера: источника, с которым его сверить, нет — единственный
   независимый свидетель тут обоснование той же строки записи. «Достаточен сам
   по себе» значит: термин обязан СОЙТИСЬ с обоснованием, а не просто лечь в
   вердикт процитированным и забытым. Пуст либо расходится — беда прогона. */
static void сверить_терм_без_номера(Сверка *s, const char *строка_записи,
                                   const char *обоснование, const char *имя_т,
                                   const char *что) {
  char *в_записи;
  if (!есть_уголки(строка_записи)) {
    добавить(&s->беды, fmt("теорема «%s», %s: ни номера строки, ни термина в уголках — заменить привязку нечем",
                          имя_т, что));
    return;
  }
  в_записи = терм(в_уголках(строка_записи, 1));
  if (!*в_записи) {
    добавить(&s->беды, fmt("теорема «%s», %s: термин в уголках пуст — заменить недостающий номер ему нечем",
                          имя_т, что));
    return;
  }
  если_не(s, strcmp(в_записи, терм(обоснование)) == 0,
          fmt("теорема «%s», %s: термин в уголках говорит «%s», а обоснование той же строки записи — «%s» — расходятся между собой, а термина без номера сверить больше не с чем",
              имя_т, что, в_записи, обоснование));
}

/* Термин цели БЕЗ номера сверяется тем же сличением двух хвостов исходника: он
   и есть «утверждено» и обязан сойтись с обещанным — сам по себе, а не цитатой. */
static void сверить_цель(Сверка *s, Сп свои, Сп строки, const char *место,
                       const char *имя, const char *имя_т) {
  /* Строка приводится к тому виду, в каком её читает язык, до поиска метки:
     иначе хвостовое примечание подменяет и обещанное, и утверждённое. */
  long гв = строка_высказывания(строки, место);   /* К3b: утверждение без функции */
  char *сырое = гв ? из_высказывания(строки, гв, NULL, NULL)
                   : хвост_после(как_читает_язык(место), fmt("обеспечивает «%s» ", имя));
  char *обещано = гв ? терм(цель_обещанная(сырое))
                     : цель_обещанная(сырое);     /* К7: у существования — У[м:=Т], как терм */
  char *строка_цели = первая_с_началом(свои, "цель ");
  long где = номер_после(строка_цели, "строка ");
  char *утверждено;
  if (где < 1) { утверждено = в_уголках(строка_цели, 1); s->без_привязки++; }
  else {
    утверждено = хвост_после(как_читает_язык(строка_по_номеру(строки, где)), "утверждаем ");
    сверить_терм_и_номер(s, строка_цели, утверждено, где, имя_т, "цель");
  }
  если_не(s, strcmp(обещано, обещано == сырое ? утверждено : терм(утверждено)) == 0,
          fmt("теорема «%s» утверждает «%s», а %s обещает «%s» — доказывается не то, что обещано",
              имя_т, утверждено, гв ? "утверждение" : "постусловие", обещано));
}

/* ШАГ АВТОРА `по примеру` ПРИВЯЗАН К ПРИМЕРУ. Ядро дописывает в конец строки
   шага `пример строка N`, и дальше сверщик шесть раз читает ИСХОДНИК: на строке
   N стоит ровно этот пример; строка лежит в блоке той функции, за которой
   записано утверждение; у примера есть `ожидается`; значение довода в примере —
   то самое, что разбирает случай; цель на нём держится счётом; ветвь тела для
   того же образца даёт то же значение. Прошли все шесть — шаг снят со слова
   ядра. Не прошла первая или вторая, разошлось в четвёртой–шестой — код 1.
   Образец или отношение, которых сверщик не знает, — не «сошлось», а «не
   берусь» с названной причиной. */
#define МЕТКА_ПРИМЕРА " пример строка "
/* Задача 3455: та же привязка, тем же приёмом, для шага `по свойству» —
   номер строки, где ВПЕРВЫЕ ПО ВСЕМУ ФАЙЛУ объявлено постусловие с этим
   именем (см. «Номер свойства записи» в запись.flang; проверка — ниже,
   сверить_шаг_свойством). */
#define МЕТКА_СВОЙСТВА " свойство строка "

/* Обоснование шага без дописанной привязки: сверять с исходником надо ровно то,
   что в исходнике написано, а привязки там нет. */
/* Привязка стоит В САМОМ КОНЦЕ строки и кончается цифрами — только такое
   вхождение метки и отрезается. Иначе имя примера (или свойства), в которое
   вписаны слова метки, прятало бы за собой настоящую привязку. Метка одна из
   двух за раз — `по примеру` и `по свойству» в одном шаге не встречаются. */
static char *без_привязки_меткой(const char *ш, const char *метка) {
  const char *p = ш, *q, *нашли = NULL; size_t d = strlen(метка);
  while ((q = strstr(p, метка)) != NULL) {
    const char *c = q + d;
    if (*c >= '0' && *c <= '9') {
      const char *k = c;
      while (*k >= '0' && *k <= '9') k++;
      if (!*k) нашли = q;
    }
    p = q + 1;
  }
  return нашли ? копия(ш, (size_t)(нашли - ш)) : (char *)ш;
}
static char *без_привязки_примера(const char *ш) { return без_привязки_меткой(ш, МЕТКА_ПРИМЕРА); }
static char *без_привязки_свойства(const char *ш) { return без_привязки_меткой(ш, МЕТКА_СВОЙСТВА); }

/* «Вид» (закрывающий/промежуточный) и обоснование шага, ПОСЛОВНО, независимо
   от того, чем шаг привязан — номером, термином или обоими: «шаг K строка N»
   даёт четыре слова до вида, один «шаг K» — два. Термин вырезается ПЕРЕД
   счётом слов (`шаг_словами`), иначе он сдвигал бы счёт своими пробелами и
   ёлочками — та самая беда, что делает вид «термин вместо номера» нерабочим. */
static char *шаг_вид(const char *ш) {
  return слово(шаг_словами(ш), номер_после(ш, "строка ") >= 1 ? 5 : 3);
}
static char *шаг_обоснование(const char *ш) {
  char *без = без_привязки_свойства(без_привязки_примера(шаг_словами(ш)));
  return слова_после(без, номер_после(ш, "строка ") >= 1 ? 5 : 3);
}

/* Блок функции: строка её заголовка и первая строка ЗА блоком.
   КОНЕЦ БЛОКА — ПЕРВОЕ ЖЕ ОБЪЯВЛЕНИЕ ОТ КРАЯ, а не следующая «функция».
   Довод — замер: теорема пишется от края между функциями, и счёт «до следующей
   функции» затягивал её в блок. Тогда ветвью тела становилась строка теоремы
   `то по примеру «Пустой список»`, и ТРИ честных шага записи
   `svyortka-prefiks-chestnaya` получали «расхождение ветви и ожидания» —
   ложный отказ на честной записи. Внутри функции всё написано с отступом,
   поэтому строка без отступа и есть конец. */
static long блок_функции(Сп строки, const char *функция, long *конец) {
  long i, начало = 0; *конец = строки.n + 1;
  for (i = 1; i <= строки.n; i++) {
    char *z = часть(строки, i);
    if (начало) {
      if (*z && z[0] != ' ' && z[0] != '\t' && z[0] != '\r' && !начинается(z, "//")) { *конец = i; break; }
      continue;
    }
    if (strcmp(имя_функции(z), функция) == 0) начало = i;
  }
  return начало;
}

/* Строка `ожидается …` примера, объявленного на строке p. Пример кончается
   первым же `ожидается` — так его читает и разбор языка. */
static char *ожидается_примера(Сп строки, long p, long конец) {
  long i;
  for (i = p + 1; i < конец; i++) {
    char *z = строка_по_номеру(строки, i);
    if (начинается(z, "ожидается ")) return хвост_после(z, "ожидается ");
    if (!начинается(z, "дано ") && *z) return (char *)"";
  }
  return (char *)"";
}

/* Значение, которое пример даёт названному доводу. Пусто — не даёт.
   ДОВОД ПИШЕТСЯ ДВУМЯ ЗАКОННЫМИ СПОСОБАМИ (R6b): голым словом
   («дано свет равно …», traffic-light.flang) и в ёлочках («дано «носитель»
   равно …», corpus-carrier.flang, corpus-json.flang) — второе имя пришло из
   `индукция по «носитель»`, где оно тоже стоит в ёлочках, и запись их не
   снимает. Оба написания — один и тот же язык, и сверщик обязан читать
   исходник обоими, а не одним из них. */
static char *дано_примера(Сп строки, long p, long конец, const char *довод) {
  long i;
  for (i = p + 1; i < конец; i++) {
    char *z = строка_по_номеру(строки, i);
    if (начинается(z, fmt("дано %s равно ", довод)) ||
        начинается(z, fmt("дано «%s» равно ", довод)))
      return хвост_после(z, "равно ");
    if (начинается(z, "ожидается ")) return (char *)"";
    if (!начинается(z, "дано ") && *z) return (char *)"";
  }
  return (char *)"";
}

/* Ветвь тела для образца: `случай <образец>` и стоящее под ней `то <терм>`.
   Ищется ТОЛЬКО в блоке функции — случаи теоремы лежат выше и сюда не попадают. */
static char *ветвь_тела(Сп строки, long a, long b, const char *образец) {
  long i;
  for (i = a; i < b; i++) {
    if (strcmp(строка_по_номеру(строки, i), fmt("случай %s", образец)) != 0) continue;
    if (i + 1 < b && начинается(строка_по_номеру(строки, i + 1), "то "))
      return слова_после(строка_по_номеру(строки, i + 1), 1);
  }
  return (char *)"";
}

static int число_точно(const char *s, double *z) {
  char *конец;
  if (!*s) return 0;
  *z = strtod(s, &конец);
  return *конец == 0 && конец != s;
}

/* Образец случая и значение примера — одно ли это. СПИСОК ЗАКРЫТ: образца,
   которого здесь нет, сверщик не «пропускает», а объявляет незнакомым. */
static int образец_совпал(const char *образец, const char *значение, int *знаком) {
  double a, b;
  *знаком = 1;
  if (начинается(образец, "вариант «")) return strcmp(образец, значение) == 0;
  if (strcmp(образец, "пусто") == 0)
    return strcmp(значение, "пустой список") == 0 || strcmp(значение, "\"\"") == 0;
  /* ДНО ОТРЕЗКА (`случай 0` по `нат`). Совпали числа — случай тот самый;
     не совпали — сверщик НЕ объявляет ложь: ядро на этой дороге проверяет
     попадание значения в дно [0, верх], а не равенство, и отказ здесь был бы
     отказом честной записи. Не совпали — «не берусь». */
  if (число_точно(образец, &a) && число_точно(значение, &b)) {
    if (a == b) return 1;
    *знаком = 0; return 0;
  }
  *знаком = 0; return 0;
}

/* Держится ли цель `результат <отношение> <число>` при данном значении.
   ОТНОШЕНИЙ ПЯТЬ, и список закрыт по тому же доводу. */
static int цель_держится(const char *цель, const char *значение, int *знаком) {
  static const char *отн[] = { "не меньше ", "не больше ", "больше ", "меньше ", "равен " };
  double v, e; int k;
  *знаком = 0;
  if (!начинается(цель, "результат ")) return 0;
  if (!число_точно(значение, &v)) return 0;
  for (k = 0; k < 5; k++) {
    const char *хвост = цель + strlen("результат ");
    if (!начинается(хвост, отн[k])) continue;
    if (!число_точно(хвост + strlen(отн[k]), &e)) return 0;
    *знаком = 1;
    switch (k) {
      case 0: return v >= e; case 1: return v <= e; case 2: return v > e;
      case 3: return v < e;  default: return v == e;
    }
  }
  return 0;
}

/* ШАГ АВТОРА ВНЕ СЛУЧАЯ: вызов функции БЕЗ параметров, тело которой — литерал,
   заменяется значением этого литерала, и замкнутый терм считается по ЗАКРЫТОМУ
   списку отношений и форм. Сошлось — шаг снят со слова ядра; цель не держится —
   код 1; форма незнакома — «не берусь» с названной причиной, а не «сошлось».
   ГРАНИЦА НАРОЧНАЯ: функция с параметрами не берётся (у неё `результат` не одно
   значение), литерал со знаком вне базовой плоскости отвергается (длину такой
   строки язык считает не кодовыми точками), минус ноль не сравнивается ничем.
   Продолжать список значит заводить внутри сверщика второй вычислитель языка —
   тогда сверщик перестаёт быть независимым, и проверить его самого будет нечем. */

/* Значение замкнутого терма. вид: 0 «не берусь», 1 строка, 2 число, 3 признак,
   4 список, 5 запись, 6 строка, которую не держим, но знаем её длину,
   7 тег варианта, 8 вариант с полями. Каждый вид объяснён у своей `как_*`. */
typedef struct { int вид; char *s; double ч; } Знач;
static const Знач НЕ_БЕРУСЬ = { 0, NULL, 0 };
static Знач как_строка(char *s)  { Знач z; z.вид = 1; z.s = s;    z.ч = 0;         return z; }
static Знач как_число(double c) { Знач z; z.вид = 2; z.s = NULL; z.ч = c;         return z; }
static Знач как_признак(int b)   { Знач z; z.вид = 3; z.s = NULL; z.ч = b ? 1 : 0; return z; }
/* Вид 4 — СПИСОК (ячейка Ч87). Несёт и текст литерала без пробелов вне кавычек
   (по нему решается равенство), и число звеньев (по нему — «длина»). Считать
   элементы по отдельности сверщик не берётся: это был бы разбор значений. */
static Знач как_список(char *s, long n) { Знач z; z.вид = 4; z.s = s; z.ч = (double)n; return z; }
/* Вид 5 — ЗАПИСЬ (минимальный вариант свёртки, задача 8690-V4). Несёт сырой,
   ещё не вычисленный текст ОДНОГО звена списка вида
   `(запись «Тип» с «поле» равным ЗНАЧ и «поле2» равным ЗНАЧ2)`. Поле берёт
   `поле_записи` по требованию проекции `X.«поле»` — вычислять все поля звена,
   которое проекция не спросит, сверщик не берётся (то же правило Ч87, что и у
   вида 4: считать больше, чем спросили, — значит гадать за отсутствием спроса). */
static Знач как_запись(char *s) { Знач z; z.вид = 5; z.s = s; z.ч = 0; return z; }
/* Вид 6 — СТРОКА, КОТОРУЮ СВЕРЩИК ДЕРЖАТЬ НЕ БЕРЁТСЯ, А ДЛИНУ ЕЁ ЗНАЕТ (Ч7104).
   Заводится ровно на литерал с нулевым знаком (`"\u0000"`): строки внутри
   сверщика — строки C, и положить в них нуль значило бы молча обрезать
   литерал, а обрезанный литерал соврал бы и о равенстве, и о вхождении.
   Длина же в знаках считается по САМОЙ ЗАПИСИ литерала и от представления не
   зависит — её и несёт `ч`. Всякое отношение на этом виде обязано отвечать
   «не берусь»: единственное, что с ним делают, — форма `длина`. */
static Знач как_длина_без_строки(long n) { Знач z; z.вид = 6; z.s = NULL; z.ч = (double)n; return z; }
/* ВИДЫ, У КОТОРЫХ `ч` — МЕРА ЗНАЧЕНИЯ, А НЕ САМО ЗНАЧЕНИЕ. В сверщике пять мест
   решают равенство так: «строка и список сличаются текстом, всё остальное —
   числом `ч`». Для видов 2 и 3 это верно, для этих — ложь: две разные строки
   одной длины вышли бы «равными», а честное равенство — «НЕ СОШЛОСЬ». Спросить
   обязано КАЖДОЕ такое место, потому вопрос вынесен в имя, а не переписан пять
   раз: без ответа хоть в одном из них подделка проходит кодом 0. */
/* 3449: и вид 8 — вариант с полями; поля его записаны текстом в порядке написания, и
   равенство по тексту разошлось бы с равенством значений при другом порядке полей. */
static int мера_а_не_значение(int вид) { return вид == 6 || вид == 8; }
/* ВИД 7 — ТЕГ ВАРИАНТА СУММЫ (задача 1573). Несёт текст `вариант «Имя»` — ровно
   в том написании, в каком имя варианта стоит и в примере (`дано стопка равно
   вариант «Пусто»`), и в образце случая. ПОЛЕЙ ТЕГ НЕ НЕСЁТ: вариант с полями —
   вид 8 ниже (задача 3449), и равенства у того нет. Равенство тегов решается ТЕКСТОМ. */
static Знач как_тег(char *s) { Знач z; z.вид = 7; z.s = s; z.ч = 0; return z; }
/* ВИД 8 — ВАРИАНТ С ПОЛЯМИ (задача 3449): текст «вариант «В» с «п» равным ЛИТ и …», где
   каждое поле уже посчитано и записано литералом — строкой, числом или признаком.
   Спрашивает его только разбор (`ветвь_разбора`): поле берётся по имени. */
static Знач как_вариант(char *s) { Знач z; z.вид = 8; z.s = s; z.ч = 0; return z; }
/* ВИДЫ, ЧЬЁ РАВЕНСТВО РЕШАЕТСЯ ТЕКСТОМ, А НЕ ЧИСЛОМ `ч`. Заведено затем же,
   зачем `мера_а_не_значение`: мест равенства пять, и шестое написание вопроса
   руками разошлось бы с пятью молча. */
static int равенство_текстом(int вид) { return вид == 1 || вид == 4 || вид == 7; }

/* Строковый литерал исходника → значение. Экранирование — ровно то, что
   принимает лексер языка (`flang/self/lexer.flang`, «Экранированный» и
   «Читать юникод»): `n`, `r`, `t`, escape `u` с четырьмя знаками, всё остальное
   даёт себя же.
   ТРИ ИСХОДА (Ч7104), а не два: 0 — не литерал или литерал, о котором сверщик
   не берётся судить вовсе; 1 — литерал разобран, строка в `*out`; 2 — литерал
   разобран КАК СЧЁТ, но строку сверщик не отдаёт: в нём есть нулевой знак, а
   строки внутри сверщика — строки C. Во втором случае заполняется только
   `*знаков` — длина В ЗНАКАХ, посчитанная по самой записи литерала. Так
   `длина "\u0000"` перестаёт быть «не берусь», не давая при этом ни одному
   сравнению работать с обрезанной строкой. */
static int разобрать_литерал_полно(const char *t, char **out, long *знаков) {
  size_t d = strlen(t), i, k = 0; char *r; long зн = 0; int есть_нуль = 0;
  if (d < 2 || t[0] != '"' || t[d - 1] != '"') return 0;
  r = дай(d + 1);
  for (i = 1; i + 1 < d; i++) {
    unsigned char c = (unsigned char)t[i];
    if (c >= 0xF0) return 0;                      /* знак вне базовой плоскости */
    /* НЕЭКРАНИРОВАННАЯ КАВЫЧКА ВНУТРИ — это не один литерал, а строка с чем-то
       ещё (`"а" равен "б"`), и брать её за литерал значит подставить не то
       значение. Экранированная сюда не доходит: её съедает ветвь ниже. */
    if (c == '"') return 0;
    if (c != '\\') { r[k++] = (char)c; if ((c & 0xC0) != 0x80) зн++; continue; }
    i++;
    if (i + 1 >= d) return 0;
    if (t[i] == 'n') { r[k++] = '\n'; зн++; }
    else if (t[i] == 'r') { r[k++] = '\r'; зн++; }
    else if (t[i] == 't') { r[k++] = '\t'; зн++; }
    else if (t[i] == 'u') {
      unsigned long код = 0; int j;
      if (i + 4 >= d - 1) return 0;
      for (j = 1; j <= 4; j++) {
        char h = t[i + j];
        if (h >= '0' && h <= '9') код = код * 16 + (unsigned long)(h - '0');
        else if (h >= 'a' && h <= 'f') код = код * 16 + (unsigned long)(h - 'a' + 10);
        else if (h >= 'A' && h <= 'F') код = код * 16 + (unsigned long)(h - 'A' + 10);
        else return 0;
      }
      if (код >= 0xD800 && код <= 0xDFFF) return 0;
      /* 3448: нулевой знак — двумя байтами C0 80 («изменённый UTF-8»): строка Си его не
         обрезает, знаком он один — длина, вырезка, равенство и вхождение те же */
      if (код == 0) { r[k++] = (char)0xC0; r[k++] = (char)0x80; зн++; i += 4; continue; }
      зн++;
      if (код < 0x80) r[k++] = (char)код;
      else if (код < 0x800) {
        r[k++] = (char)(0xC0 | (код >> 6)); r[k++] = (char)(0x80 | (код & 0x3F));
      } else {
        r[k++] = (char)(0xE0 | (код >> 12));
        r[k++] = (char)(0x80 | ((код >> 6) & 0x3F));
        r[k++] = (char)(0x80 | (код & 0x3F));
      }
      i += 4;
    } else { r[k++] = t[i]; зн++; }
  }
  r[k] = 0;
  if (есть_нуль) { *знаков = зн; return 2; }
  *out = r; *знаков = зн; return 1;
}
/* Договор «литерал → строка»: трём зовущим из четырёх нужна именно строка, и
   «есть длина, но нет строки» для них — тот же отказ. */
static int разобрать_литерал(const char *t, char **out) {
  long зн;
  return разобрать_литерал_полно(t, out, &зн) == 1;
}

/* Длина строки В ЗНАКАХ — кодовыми точками. Знак вне базовой плоскости сюда не
   доходит: литерал с ним отвергнут разбором выше, и разницы между счётом
   кодовыми точками и счётом языка тут не остаётся. */
static long длина_знаков(const char *s) {
  long n = 0; const unsigned char *p = (const unsigned char *)s;
  for (; *p; p++) if ((*p & 0xC0) != 0x80) n++;
  return n;
}
/* Начало n-го знака (счёт с единицы); n = длина+1 даёт конец строки. */
static const char *начало_знака(const char *s, long n) {
  long i = 0; const unsigned char *p = (const unsigned char *)s;
  while (*p) { if ((*p & 0xC0) != 0x80) { i++; if (i == n) break; } p++; }
  return (const char *)p;
}
static int подстрока_знаков(const char *s, long a, long b, char **out) {
  const char *на, *ко;
  if (a < 1 || a > b || b > длина_знаков(s)) return 0;
  на = начало_знака(s, a); ко = начало_знака(s, b + 1);
  *out = копия(на, (size_t)(ко - на)); return 1;
}

/* СПИСОК ОТНОШЕНИЙ ЗАКРЫТ. Порядок важен: длинное имя стоит раньше короткого,
   чтобы «не равен» не разрезалось как «равен». */
/* «и притом» дописано задачей 8690-V4: связка ДВУХ признаков внутри тела
   свёртки (обе половины уже сведены к да/нет, дальше — не отношение, а союз).
   Числа и строки этот знак не сравнивает — под него заведена своя проверка
   видов, а не общая ветка кода 2/3, чтобы не путать «и притом» с равенством. */
/* «равно» и «равен» — одно равенство, согласованное по роду; язык пишет оба, и
   сверщик обязан читать оба, иначе он читает не тот язык. Место «равно» в
   списке безразлично: порядок значим лишь для знаков, начинающихся одинаково,
   а эти два расходятся на последнем знаке. */
static const char *ОТНОШЕНИЯ[] = {
  " содержит ", " начинается с ", " не равен ", " равен ",
  " не меньше ", " не больше ", " меньше ", " больше ", " плюс ", " минус ",
  " и притом ", " равно "
};
#define ОТНОШЕНИЙ 12
#define ОТН_РАВНО 11

/* Первое вхождение знака операции ВЕРХНЕГО УРОВНЯ: вне скобок и ВНЕ КАВЫЧЕК.
   Наивное деление по пробелам (как в `разделить_сверху`) здесь не годится: в
   строковом литерале бывают и скобки, и пробелы, и сами слова отношений. */
static int найти_сверху(const char *t, const char **список, int сколько,
                        long *где, int *какое) {
  long гл = 0, i; int в_кавычках = 0;
  for (i = 0; t[i]; i++) {
    if (в_кавычках) {
      if (t[i] == '\\' && t[i + 1]) i++;
      else if (t[i] == '"') в_кавычках = 0;
      continue;
    }
    if (t[i] == '"') { в_кавычках = 1; continue; }
    if (t[i] == '(') { гл++; continue; }
    if (t[i] == ')') { гл--; continue; }
    if (гл != 0 || t[i] != ' ') continue;
    { int k; for (k = 0; k < сколько; k++)
        if (начинается(t + i, список[k])) { *где = i; *какое = k; return 1; } }
  }
  return 0;
}

/* Снятие внешней пары скобок, если она обнимает ВЕСЬ терм. Своё, а не `ужать`:
   тот считает скобки по всей строке, не глядя на кавычки. */
static char *без_внешних(const char *сырой) {
  char *t = обрезать(сырой); int раз;
  for (раз = 0; раз < 6; раз++) {
    long гл = 0, i; int в_кавычках = 0, всё = 1; size_t d = strlen(t);
    if (d < 2 || t[0] != '(' || t[d - 1] != ')') break;
    for (i = 0; t[i]; i++) {
      if (в_кавычках) {
        if (t[i] == '\\' && t[i + 1]) i++;
        else if (t[i] == '"') в_кавычках = 0;
        continue;
      }
      if (t[i] == '"') { в_кавычках = 1; continue; }
      if (t[i] == '(') гл++;
      else if (t[i] == ')') { гл--; if (гл == 0 && t[i + 1]) { всё = 0; break; } }
    }
    if (!всё || гл != 0) break;
    t = обрезать(копия(t + 1, d - 2));
  }
  return t;
}

/* ТЕЛО-СПИСОК: ПЕЧАТЬ ТОЛЬКО УКАЗЫВАЕТ, ГДЕ СМОТРЕТЬ. Оглавление записи
   («таблица «Имя» открыта N закрыта M звеньев K») даёт место, и всё названное
   им перечитывается: на строке N стоит «[», на M — «]», обе внутри блока
   названной функции, у функции нет доводов, звенья пересчитываются сами.
   Разошлось хоть в одном — это ЛОЖЬ ЗАПИСИ, а не «не берусь»: код 1. */

/* Пробелы ВНЕ кавычек долой: тот же литерал, писанный по звену на строку и
   писанный в одну строку, обязаны сравниваться как одно. Внутри кавычек не
   трогается ничего — там пробел есть знак значения. Незакрытая кавычка даёт
   пустую строку, и звавший обязан ответить «не берусь». */
static char *без_пробелов_вне_кавычек(const char *s) {
  size_t d = strlen(s), i, k = 0; char *r = дай(d + 1); int в_кав = 0;
  for (i = 0; i < d; i++) {
    char c = s[i];
    if (в_кав) {
      r[k++] = c;
      if (c == '\\' && i + 1 < d) r[k++] = s[++i];
      else if (c == '"') в_кав = 0;
      continue;
    }
    if (c == '"') { в_кав = 1; r[k++] = c; continue; }
    if (c == ' ' || c == '\t' || c == '\r' || c == '\n') continue;
    r[k++] = c;
  }
  r[k] = 0;
  return в_кав ? (char *)"" : r;
}


/* Звенья по ЗАПЯТЫМ ВЕРХНЕГО УРОВНЯ. Ноль — «не берусь», а не «пусто».
   Примечания сюда не доходят: их снимает `без_примечания` построчно, ещё до
   слияния строк, поэтому закомментированное звено не считается — и запись,
   объявившая его, расходится с исходником арифметикой, а не молчанием. */
static long звеньев_по_запятым(const char *t) {
  size_t d = strlen(t), i; long гл = 0, n = 0; int в_кав = 0, есть_буквы = 0;
  for (i = 0; i < d; i++) {
    if (в_кав) {
      if (t[i] == '\\' && i + 1 < d) i++;
      else if (t[i] == '"') в_кав = 0;
      continue;
    }
    if (t[i] == '"') { в_кав = 1; есть_буквы = 1; continue; }
    if (t[i] == '[' || t[i] == '(') { гл++; continue; }
    if (t[i] == ']' || t[i] == ')') { гл--; continue; }
    if (гл == 1 && t[i] == ',') { n++; continue; }
    if (гл >= 1 && t[i] != ' ') есть_буквы = 1;
  }
  if (в_кав || гл != 0) return 0;
  return есть_буквы ? n + 1 : 0;
}

static char *текст_списка(Сп строки, long a, long b) {
  Сп v = ПУСТО; long i;
  for (i = a - 1; i <= b + 1; i++)
    добавить(&v, без_примечания(строка_по_номеру(строки, i)));
  return без_пробелов_вне_кавычек(соединить(v, " "));
}

static Сп ОГЛАВЛЕНИЕ = { NULL, 0, 0 };
/* Ложь оглавления — беда ЗАПИСИ, а не «не берусь»: печать назвала место, и
   место обязано быть тем самым. Копится здесь, вливается в сверку по концу. */
static Сп ОГЛ_БЕДЫ = { NULL, 0, 0 };

static int литерал_списка(Сп строки, const char *имя, long *a, long *b) {
  int i;
  for (i = 0; i < ОГЛАВЛЕНИЕ.n; i++) {
    char *z = ОГЛАВЛЕНИЕ.e[i];
    long a0, b0, n0, n, нач, конец, j;
    if (strcmp(в_ёлочках(z, 1), имя) != 0) continue;
    a0 = номер_после(z, "открыта "); b0 = номер_после(z, "закрыта ");
    n0 = номер_после(z, "звеньев ");
    if (strcmp(строка_по_номеру(строки, a0), "[") != 0 ||
        strcmp(строка_по_номеру(строки, b0), "]") != 0) {
      добавить(&ОГЛ_БЕДЫ, fmt("оглавление зовёт таблицей «%s» строки %ld…%ld, а «[» и «]» там не стоят",
                             имя, a0, b0));
      return 0;
    }
    нач = блок_функции(строки, имя, &конец);
    if (нач < 1 || a0 <= нач || b0 >= конец) {
      добавить(&ОГЛ_БЕДЫ, fmt("оглавление кладёт таблицу «%s» на строки %ld…%ld, а блок этой функции — не там",
                             имя, a0, b0));
      return 0;
    }
    for (j = нач + 1; j < конец; j++)
      if (начинается(строка_по_номеру(строки, j), "принимает ")) {
        добавить(&ОГЛ_БЕДЫ, fmt("оглавление зовёт таблицей «%s», а у этой функции есть доводы", имя));
        return 0;
      }
    /* Число «звеньев» в оглавлении СВЕРЯЕТСЯ С ТЕМ, ЧТО ЕГО ПЕЧАТАЕТ: печать кладёт
       туда `закрыта − открыта − 1`, то есть число СТРОК между скобками, а не число
       звеньев. Сверка со счётом звеньев обвиняет во лжи честную запись, если таблица
       написана плотнее одного звена на строку. */
    n = b0 - a0 - 1;
    if (n != n0) {
      добавить(&ОГЛ_БЕДЫ, fmt("оглавление объявляет у «%s» звеньев %ld, а строк между скобками %ld",
                             имя, n0, n));
      return 0;
    }
    *a = a0 + 1; *b = b0 - 1;
    return 1;
  }
  return 0;
}

/* СПИСОК В ОДНУ СТРОКУ оглавления не получает вовсе — печать даёт указатель
   только многострочным таблицам, — и потому место здесь ищется прямым чтением
   исходника (функция без доводов, тело — последняя непустая строка блока), а
   запись не читается вообще. Отличие от `тело_таблицы` только в форме литерала. */
static int тело_списком(Сп строки, const char *имя, long *a, long *b) {
  long нач, конец, i, тело = 0; char *z; size_t d;
  нач = блок_функции(строки, имя, &конец);
  if (нач < 1) return 0;
  for (i = нач + 1; i < конец; i++) {
    char *строка = строка_по_номеру(строки, i);
    if (начинается(строка, "принимает ")) return 0;   /* у функции есть доводы */
    if (*строка && !начинается(строка, "//")) тело = i;
  }
  if (тело < 1) return 0;
  z = строка_по_номеру(строки, тело); d = strlen(z);
  if (d < 2 || z[0] != '[' || z[d - 1] != ']') return 0;
  *a = тело + 1; *b = тело - 1;   /* приём литерал_списка: текст_списка(a,b)
                                      сам достраивает диапазон назад до «тело» */
  return 1;
}

static Знач таблица_списком(Сп строки, const char *имя) {
  long a, b, n;
  if (!литерал_списка(строки, имя, &a, &b) && !тело_списком(строки, имя, &a, &b))
    return НЕ_БЕРУСЬ;
  n = звеньев_по_запятым(текст_списка(строки, a, b));
  if (n < 1) return НЕ_БЕРУСЬ;
  return как_список(текст_списка(строки, a, b), n);
}

/* ТЕЛО ФУНКЦИИ-ТАБЛИЦЫ. Годится только функция БЕЗ параметров, тело которой —
   один строковый литерал: последняя непустая строка блока. Всё прочее — 0,
   и звавший обязан ответить «не берусь», а не «сошлось». */
static char *тело_таблицы_строка(Сп строки, const char *имя) {
  long a, b, i, тело = 0;
  a = блок_функции(строки, имя, &b);
  if (a < 1) return (char *)"";
  for (i = a + 1; i < b; i++) {
    char *z = строка_по_номеру(строки, i);
    if (начинается(z, "принимает ")) return (char *)"";   /* у функции есть параметры */
    if (*z && !начинается(z, "//")) тело = i;
  }
  return тело < 1 ? (char *)"" : строка_по_номеру(строки, тело);
}
static int тело_таблицы(Сп строки, const char *имя, char **значение) {
  char *z = тело_таблицы_строка(строки, имя);
  return *z ? разобрать_литерал(z, значение) : 0;
}

/* СВЁРТКА: стек связываний на 8 кадров. Границы остаются проверяемыми кодом, а
   не обещанием:
     • кадров не больше `СВ_КАДРОВ` — глубже «не берусь», а не «сошлось»;
     • глубина терма ограничена отдельно;
     • имя ищется от ВЕРХНЕГО кадра к нижнему: внутреннее связывание перекрывает
       внешнее, как в самом языке, и слить два кадра в один нельзя.
   Второго вычислителя языка этим не заводится: ни вызова функции с доводами,
   ни отката, ни перебора, ни поиска по ключу здесь нет. */
static Сп члены_списка(const char *t);
static int разрез_выбора(const char *t, char **u, char **a, char **b);
static int кавычки_чисты(const char *t);

/* ВЫЗОВ СОСЕДКИ ПО ТОМУ ЖЕ СЛУЧАЮ — не «вычисление функции», а тот же разбор по
   тому же случаю. Чтобы вызов был взят, обязано сойтись ВСЁ:
     • довод вызова — ровно то имя, которое разбирает индукция теоремы;
     • строка `принимает …` у соседки знак в знак та же, что у функции с примером;
     • тело соседки — `разбор <тот же довод>` и ничего кроме;
     • у соседки есть ветвь на ТОТ ЖЕ образец, и её терм считается обычным счётом.
   Всё прочее — «не берусь», а не «сошлось»: ни подстановки произвольного довода
   в параметр, ни отката, ни перебора здесь нет. */
static const char *РЗ_ДОВОД = NULL;      /* имя довода, разбираемого случаем */
static const char *РЗ_ОБРАЗЕЦ = NULL;    /* образец текущего случая, как в теореме */
static const char *РЗ_ПРИНИМАЕТ = NULL;  /* строка `принимает …` функции с примером */

/* ═══ ДВА СТЕКА СВЯЗЫВАНИЙ И ОДИН СЧЁТ ПОРЯДКА — задача 1573 ════════════════
   Связывания в сверщике теперь двух родов: имена свёртки (аккумулятор и
   элемент) и ИМЕНА ДОВОДОВ развёрнутой функции. Внутри одного рода порядок
   даёт сам стек — верхний кадр перекрывает нижний. МЕЖДУ родами его не даёт
   никто: свёртка бывает внутри тела функции (и тогда её имена главнее имён
   доводов), а вызов функции бывает внутри свёртки (и тогда наоборот).
   Разрешить это «сначала один стек, потом другой» нельзя: половину случаев
   такой порядок решил бы неверно, а неверно разрешённое имя — не «не берусь»,
   а ЧУЖОЕ ЗНАЧЕНИЕ, то есть ровно та беда, которой сверщик быть не должен.
   Потому у каждого кадра есть НОМЕР ПОСТАНОВКИ из общего счёта, и имя ищется
   по наибольшему номеру среди совпавших — это и есть «внутреннее перекрывает
   внешнее», сказанное один раз для обоих родов. */
static long СВЯЗЬ_СЧЁТ = 0;

/* Кадр свёртки: два связывания, аккумулятор и элемент. Больше в кадре не
   бывает — форма языка их и заводит ровно два. */
#define СВ_КАДРОВ 8
static struct { const char *акк_имя, *элем_имя; Знач акк, элем; long порядок; } СВ_СТЕК[СВ_КАДРОВ];
static int СВ_ВЕРХ = 0;   /* занятых кадров; 0 — свёртки нет вовсе */

#define ДВ_КАДРОВ 16
static struct { const char *имя; Знач з; long порядок; } ДВ_СТЕК[ДВ_КАДРОВ];
static int ДВ_ВЕРХ = 0;

/* Значение связанного имени. Ищется по НАИБОЛЬШЕМУ номеру постановки среди
   совпавших — по обоим стекам сразу (см. шапку выше).
   Вернуть «нашлось» и «не нашлось» разными путями обязательно — вид 0
   («не берусь») законно бывает и у НАЙДЕННОГО связывания. */
static int связывание(const char *t, Знач *out) {
  int k; long лучший = -1; Знач найдено = НЕ_БЕРУСЬ; int есть = 0;
  for (k = СВ_ВЕРХ - 1; k >= 0; k--) {
    if (СВ_СТЕК[k].акк_имя && strcmp(t, СВ_СТЕК[k].акк_имя) == 0 && СВ_СТЕК[k].порядок > лучший)
      { лучший = СВ_СТЕК[k].порядок; найдено = СВ_СТЕК[k].акк; есть = 1; }
    if (СВ_СТЕК[k].элем_имя && strcmp(t, СВ_СТЕК[k].элем_имя) == 0 && СВ_СТЕК[k].порядок > лучший)
      { лучший = СВ_СТЕК[k].порядок; найдено = СВ_СТЕК[k].элем; есть = 1; }
  }
  for (k = ДВ_ВЕРХ - 1; k >= 0; k--)
    if (ДВ_СТЕК[k].имя && strcmp(t, ДВ_СТЕК[k].имя) == 0 && ДВ_СТЕК[k].порядок > лучший)
      { лучший = ДВ_СТЕК[k].порядок; найдено = ДВ_СТЕК[k].з; есть = 1; }
  if (есть) *out = найдено;
  return есть;
}

/* Связать имя довода значением; снимается `развязать_доводы`. Не влезло в стек
   — 0, и звавший обязан ответить «не берусь», а не считать без связывания. */
static int связать_довод(const char *имя, Знач з) {
  if (ДВ_ВЕРХ >= ДВ_КАДРОВ || !имя || !*имя) return 0;
  ДВ_СТЕК[ДВ_ВЕРХ].имя = имя; ДВ_СТЕК[ДВ_ВЕРХ].з = з;
  ДВ_СТЕК[ДВ_ВЕРХ].порядок = ++СВЯЗЬ_СЧЁТ; ДВ_ВЕРХ++;
  return 1;
}
static void развязать_доводы(int сколько) {
  while (сколько-- > 0 && ДВ_ВЕРХ > 0) { ДВ_ВЕРХ--; ДВ_СТЕК[ДВ_ВЕРХ].имя = NULL; }
}

/* ПРЕДЕЛ СЧЁТА ОБЯЗАТЕЛЕН: тело зовёт тело, и на злом входе (взаимная рекурсия,
   тело, зовущее себя) спуск сам не кончится. Пределов два, и оба названы в
   отчёте: ГЛУБИНА терма (цепочка «свёртка → тело → свёртка → тело» ест по
   четыре-пять уровней на вызов) и ЧИСЛО ОЦЕНОК одного верхнего терма, счётчик
   обнуляется на входе с глубиной 0. Исчерпан любой — «не берусь»; догадок по
   исчерпании здесь нет и быть не может. */
#define ГЛУБИНА_ПРЕДЕЛ 32
#define ОЦЕНОК_ПРЕДЕЛ 200000L
static long ОЦЕНОК = 0;
/* НАЗВАННАЯ ПРИЧИНА «не берусь»: место, где вычислитель сдаётся, остаётся на
   слове ядра, но не безымянно. Держится ПЕРВАЯ поставленная; сброс — вместе с
   ОЦЕНОК, на глубине 0; в сообщение она попадает только через «вид цели …
   незнаком». */
static const char *ПРИЧИНА_СЧЁТА = NULL;
#define ПР_ОТБОР "в счёте встретился отбор «отфильтровать … где …»: сверщик его не вычисляет — это был бы второй вычислитель языка"
#define ПР_НУЛЕВОЙ_ЗНАК "в счёте встретилась строка с нулевым знаком: строки сверщика (строки Си) его не держат, знаков такой строки не перебрать"
#define ПР_РАЗБОР_ЗВЕНА "в счёте встретился разбор, чьи ветви сверщик не читает парами «случай …» / «то …» — многострочная ветвь или вложенный разбор (задача 3449)"
static Знач не_берусь_потому(const char *почему) {
  if (!ПРИЧИНА_СЧЁТА) ПРИЧИНА_СЧЁТА = почему;
  return НЕ_БЕРУСЬ;
}

/* Поле именованного звена `(запись «Тип» с «поле» равным ЗНАЧ и «поле2» равным
   ЗНАЧ2)`. Звено приходит БЕЗ пробелов вне кавычек (Ч87, `текст_списка`), и
   метка ищется слитно; значение тянется до следующего «и«» ВЕРХНЕГО уровня
   или до закрывающей скобки звена — кавычки и скобки внутри значения не в
   счёт. Не запись целиком или поля нет — NULL, а не пустая строка: молчания
   о звене, которое чекер не понял, здесь не бывает, есть только «не берусь»
   выше по стеку. */
static char *поле_записи(const char *rec, const char *поле) {
  char *метка = fmt("«%s»равным", поле);
  const char *p, *q; int v = 0; long гл = 0;
  if (!начинается(rec, "(запись«") || !(p = strstr(rec, метка))) return NULL;
  p += strlen(метка);
  for (q = p; *q; q++) {
    if (v) { if (*q == '\\' && q[1]) { q++; continue; } if (*q == '"') v = 0; continue; }
    if (*q == '"') { v = 1; continue; }
    if (*q == '(') { гл++; continue; }
    if (*q == ')') { if (гл == 0) break; гл--; continue; }
    if (гл == 0 && начинается(q, "и«")) break;
  }
  return копия(p, (size_t)(q - p));
}

/* Тело соседки — это `разбор <довод>` и ничего кроме? Возвращает номер строки
   разбора или 0. Строгость нарочная: увидев в блоке `случай` от чужого разбора
   (вложенного, или второго подряд), приём обязан отказаться, а не выбрать. */
static long тело_одним_разбором(Сп строки, long a, long b, const char *довод) {
  static const char *ЗАГОЛОВКИ[] = { "принимает ", "возвращает ", "для всех ",
                                     "обеспечивает ", "пример ", "дано ", "ожидается " };
  long i, где = 0; int k, свой;
  for (i = a + 1; i < b; i++) {
    char *z = строка_по_номеру(строки, i);
    if (!*z || начинается(z, "//")) continue;
    if (!где) {
      if (strcmp(z, fmt("разбор «%s»", довод)) == 0 || strcmp(z, fmt("разбор %s", довод)) == 0) { где = i; continue; }
      for (k = 0, свой = 0; k < 7; k++) if (начинается(z, ЗАГОЛОВКИ[k])) свой = 1;
      if (!свой) return 0;            /* до разбора стоит что-то ещё — не берусь */
    } else if (!начинается(z, "случай ") && !начинается(z, "то ")) {
      return 0;                       /* после разбора стоит что-то ещё */
    }
  }
  return где;
}

/* ИМЕНА ДОВОДОВ по строке `принимает …`. Имя пишется так же, как на него потом
   ссылается тело — голым словом (`ряд: список числа`) или в ёлочках
   (`«текст»: строка`), — и потому берётся ТЕМ ЖЕ ТЕКСТОМ, без снятия ёлочек:
   связывание сличает написание, а не «смысл имени». Довод без двоеточия —
   пустой перечень, то есть «не берусь» у звавшего. */
static Сп имена_доводов(const char *принимает) {
  Сп r = ПУСТО, ч; int i;
  if (!начинается(принимает, "принимает ")) return r;
  ч = разделить(хвост_после(принимает, "принимает "), ", ");
  for (i = 0; i < ч.n; i++) {
    char *д = обрезать(ч.e[i]), *дв = strchr(д, ':');
    if (!дв || дв == д) { Сп пусто = ПУСТО; return пусто; }
    добавить(&r, обрезать(копия(д, (size_t)(дв - д))));
  }
  return r;
}

static char *строка_принимает(Сп строки, long a, long b) {
  long i;
  for (i = a + 1; i < b; i++) {
    char *z = строка_по_номеру(строки, i);
    if (начинается(z, "принимает ")) return z;
  }
  return (char *)"";
}

/* РАЗВЁРТКА ТЕЛА ОБЪЯВЛЕННОЙ ТОТАЛЬНОЙ ФУНКЦИИ. Тело читается из ИСХОДНИКА:
     • заголовок обязан быть `тотальная функция «F»` — на нетотальной не
       разворачиваем ничего. Сторож не ради завершаемости (её держат пределы), а
       ради того, чтобы разворачиваемое было объявленным всюду завершающимся;
     • доводы считаются ДО связывания и в среде ЗОВУЩЕГО, иначе имя довода
       затенило бы само себя;
     • имена доводов берутся из строки `принимает …` тем же написанием;
     • `результат` внутри чужого тела НЕ ВИДЕН: он значит «то, что вернёт
       функция, за которой стоит теорема», и подставить его туда — соврать. */
static Знач оценить_терм(const char *сырой, Сп строки, Знач результат, int глубина);
static int разрез_выбора_цепочкой(const char *t, char **u, char **a, char **b);

/* ТЕЛО ФУНКЦИИ ОДНИМ ТЕРМОМ. Строки-объявления названы поимённо, всё прочее —
   тело; многострочное склеивается пробелом. ОДНА склейка достраивается, и
   только одна: у свёртки, записанной заголовком на своей строке, стрелки `→` в
   исходнике нет вовсе — её ставит отступ («свёртка ряд начиная с 0 как сколько
   и э» и телом ниже). Стрелка вписывается на границе первой строки и остатка и
   только тогда, когда во всём теле её нет. Тело с `разбор`, `пусть` или
   `случай` сюда не отдаётся: первое читает `ветвь_по_значению`, второе и
   третье сверщик не берёт. */
static char *тело_функции_текст(Сп строки, long a, long b) {
  static const char *ОБЪЯВЛЕНИЯ[11] = {
    "принимает ", "возвращает ", "обеспечивает ", "требует ", "для всех ",
    "пример «", "дано ", "ожидается ", "теорема «", "использует ", "//"
  };
  Сп v = ПУСТО, ост = ПУСТО; long i; int k, объявление;
  for (i = a + 1; i < b; i++) {
    char *l = обрезать(как_читает_язык(часть(строки, i)));
    if (!*l) continue;
    for (k = 0, объявление = 0; k < 11; k++) if (начинается(l, ОБЪЯВЛЕНИЯ[k])) объявление = 1;
    if (объявление) continue;
    if (начинается(l, "разбор ") || начинается(l, "пусть ") || начинается(l, "случай ") ||
        начинается(l, "то ") || начинается(l, "иначе ") || начинается(l, "если "))
      { if (!v.n) return (char *)""; }
    добавить(&v, l);
  }
  if (!v.n) return (char *)"";
  if (v.n == 1) return v.e[0];
  for (i = 1; i < v.n; i++) добавить(&ост, v.e[i]);
  { char *первая = v.e[0], *хв = соединить(ост, " ");
    if (начинается(первая, "свёртка ") && !содержит(первая, " → ") && !содержит(хв, " → "))
      return fmt("%s → %s", первая, хв);
    return fmt("%s %s", первая, хв); }
}

static long строка_разбора(Сп строки, long a, long b, char **что) {
  static const char *ЗАГОЛОВКИ[10] = { "принимает ", "возвращает ", "для всех ",
                                       "обеспечивает ", "требует ", "пример ", "дано ",
                                       "ожидается ", "использует ", "//" };
  long i; int k, свой;
  for (i = a + 1; i < b; i++) {
    char *z = строка_по_номеру(строки, i);
    if (!*z) continue;
    if (начинается(z, "разбор ")) { *что = хвост_после(z, "разбор "); return i; }
    for (k = 0, свой = 0; k < 10; k++) if (начинается(z, ЗАГОЛОВКИ[k])) свой = 1;
    if (!свой) return 0;
  }
  return 0;
}

/* Образцы читаются закрытым списком: тег варианта — и со словом «вариант»
   впереди, и без него, потому что язык пишет оба. Ветвь берётся только
   однострочная: склейка многострочной была бы догадкой об отступе. */
static char *ветвь_по_значению(Сп строки, long a, long b, Знач з) {
  long i;
  for (i = a + 1; i < b; i++) {
    char *z = строка_по_номеру(строки, i), *обр; int совпал = 0; double ч;
    if (!начинается(z, "случай ")) continue;
    обр = хвост_после(z, "случай ");
    if (з.вид == 7)
      совпал = strcmp(обр, з.s) == 0 ||
               (начинается(з.s, "вариант «") && strcmp(обр, з.s + strlen("вариант ")) == 0);
    else if (з.вид == 2 && число_точно(обр, &ч)) совпал = (ч == з.ч);
    if (!совпал) continue;
    if (i + 1 < b && начинается(строка_по_номеру(строки, i + 1), "то "))
      return слова_после(строка_по_номеру(строки, i + 1), 1);
    return (char *)"";
  }
  return (char *)"";
}

/* Ветви читаются только парами «случай …» / «то …» до конца блока: у
   многострочной ветви или вложенного разбора («то разбор …») нашлись бы
   чужие «случай», и разбор стал бы «не берусь» с названной причиной. */
static int поля(const char *t, const char *связка, Сп *имена, Сп *термы) {
  static const char *И_[] = { " и " };
  const char *свз[1], *h = strstr(t, "» с "); long p; int nn;
  свз[0] = связка; *имена = ПУСТО; *термы = ПУСТО;
  if (!h) return 0;
  for (h += strlen("» с "); *h; ) {
    char *кус = (char *)h, *имя;
    if (найти_сверху(h, И_, 1, &p, &nn)) { кус = копия(h, (size_t)p); h += p + strlen(И_[0]); } else h += strlen(h);
    if (!найти_сверху(кус, свз, 1, &p, &nn)) return 0;
    имя = обрезать(копия(кус, (size_t)p));
    if (*в_ёлочках(имя, 1)) имя = в_ёлочках(имя, 1); else if (!*имя || содержит(имя, " ")) return 0;
    добавить(имена, имя); добавить(термы, обрезать(кус + p + strlen(связка)));
  }
  return имена->n > 0;
}
/* Имя ветви связывается обоими написаниями — голым и в ёлочках: язык читает их одним. */
static int связать_оба(const char *имя, Знач з) {
  const char *голое = *в_ёлочках(имя, 1) ? в_ёлочках(имя, 1) : имя;
  return связать_довод(голое, з) + связать_довод(fmt("«%s»", голое), з);
}
static int ветви_парами(Сп строки, long где, long b) {
  long i;
  for (i = где + 1; i < b; i++) {
    char *z = строка_по_номеру(строки, i), *то = i + 1 < b ? строка_по_номеру(строки, i + 1) : (char *)"";
    if (!*z || начинается(z, "//")) continue;
    if (!начинается(z, "случай ") || !начинается(то, "то ") || начинается(то, "то разбор ")) return 0;
    i++;
  }
  return 1;
}
static Знач ветвь_разбора(Сп строки, long где, long b, Знач с, int глубина) {
  Сп чл = с.вид == 4 ? члены_списка(с.s) : ПУСТО, ост = ПУСТО, им, тр, зим, зтр;
  long i; int j, k, связано = 0, нужно = 0; Знач итог = НЕ_БЕРУСЬ;
  if (!ветви_парами(строки, где, b) || (с.вид == 4 && !чл.n && с.ч != 0)) return не_берусь_потому(ПР_РАЗБОР_ЗВЕНА);
  for (i = где + 1; i + 1 < b; i++) {
    char *обр = слова_после(строка_по_номеру(строки, i), 1), *то = слова_после(строка_по_номеру(строки, i + 1), 1);
    Сп сл = разделить(обр, " ");
    if (!начинается(строка_по_номеру(строки, i), "случай ")) continue;
    if (с.вид == 4 && !чл.n) { if (strcmp(обр, "пусто") == 0) return оценить_терм(то, строки, НЕ_БЕРУСЬ, глубина + 1); continue; }
    if (с.вид == 4) {
      if (strcmp(обр, "голова и хвост") != 0 &&
          !(сл.n == 5 && !strcmp(сл.e[0], "голова") && !strcmp(сл.e[2], "и") && !strcmp(сл.e[3], "хвост"))) continue;
      for (j = 1; j < чл.n; j++) добавить(&ост, чл.e[j]);
      связано = связать_оба(сл.n == 5 ? сл.e[1] : "голова", начинается(чл.e[0], "(запись«") ? как_запись(чл.e[0])
                            : оценить_терм(чл.e[0], строки, НЕ_БЕРУСЬ, глубина + 1));
      связано += связать_оба(сл.n == 5 ? сл.e[4] : "хвост", как_список(fmt("[%s]", соединить(ост, ",")), ост.n));
      нужно = 4;
    } else {
      if (начинается(обр, "вариант ")) обр += strlen("вариант ");
      if (strcmp(в_ёлочках(обр, 1), в_ёлочках(с.s, 1)) != 0) continue;
      if (strstr(обр, "» с ") && (!поля(обр, " как ", &им, &тр) || !поля(с.s, " равным ", &зим, &зтр))) return НЕ_БЕРУСЬ;
      for (j = 0; strstr(обр, "» с ") && j < им.n; j++, нужно += 2) {
        for (k = 0; k < зим.n && strcmp(зим.e[k], им.e[j]) != 0; k++) ;
        if (k < зим.n) связано += связать_оба(тр.e[j], оценить_терм(зтр.e[k], строки, НЕ_БЕРУСЬ, глубина + 1));
      }
    }
    if (связано == нужно) итог = оценить_терм(то, строки, НЕ_БЕРУСЬ, глубина + 1);
    развязать_доводы(связано);
    return итог;
  }
  return НЕ_БЕРУСЬ;
}

/* Доводы должны быть УЖЕ СВЯЗАНЫ вызывающим — сама эта ячейка их не связывает. */
static Знач вычислить_тело(Сп строки, long a, long b, int глубина) {
  char *что = (char *)"", *ветвь, *тело;
  long где = строка_разбора(строки, a, b, &что);
  if (где > 0) {
    Знач с = оценить_терм(что, строки, НЕ_БЕРУСЬ, глубина + 1);
    if (!с.вид) return НЕ_БЕРУСЬ;
    if (с.вид == 4 || с.вид == 8) return ветвь_разбора(строки, где, b, с, глубина);
    ветвь = ветвь_по_значению(строки, a, b, с);
    return *ветвь ? оценить_терм(ветвь, строки, НЕ_БЕРУСЬ, глубина + 1) : НЕ_БЕРУСЬ;
  }
  тело = тело_функции_текст(строки, a, b);
  return *тело ? оценить_терм(тело, строки, НЕ_БЕРУСЬ, глубина + 1) : НЕ_БЕРУСЬ;
}

#define ДОВОДОВ_ПРЕДЕЛ 4
static Знач применить_функцию(Сп строки, const char *имя_ф, Сп доводы,
                              Знач результат, int глубина) {
  long a, b; Сп имена; int i, связано = 0; Знач знач[ДОВОДОВ_ПРЕДЕЛ], итог;
  if (доводы.n < 1 || доводы.n > ДОВОДОВ_ПРЕДЕЛ) return НЕ_БЕРУСЬ;
  a = блок_функции(строки, имя_ф, &b);
  if (a < 1) return НЕ_БЕРУСЬ;
  if (!начинается(строка_по_номеру(строки, a), "тотальная функция «")) return НЕ_БЕРУСЬ;
  имена = имена_доводов(строка_принимает(строки, a, b));
  if (имена.n != доводы.n) return НЕ_БЕРУСЬ;
  for (i = 0; i < доводы.n; i++) {
    знач[i] = оценить_терм(доводы.e[i], строки, результат, глубина + 1);
    if (!знач[i].вид) return НЕ_БЕРУСЬ;
  }
  for (i = 0; i < имена.n; i++) if (связать_довод(имена.e[i], знач[i])) связано++;
  if (связано != имена.n) { развязать_доводы(связано); return НЕ_БЕРУСЬ; }
  итог = вычислить_тело(строки, a, b, глубина);
  развязать_доводы(связано);
  return итог;
}

/* СТРОКОВЫЙ ЛИТЕРАЛ ИЗ ЗНАЧЕНИЯ — обратная сторона `разобрать_литерал_полно`.
   Нужен ровно одному месту: `разделить` отдаёт СПИСОК, а список внутри
   сверщика — это ТЕКСТ литерала (вид 4), и куски приходится записать так,
   чтобы тот же разбор прочёл их обратно знак в знак. Экранируются те же
   четыре знака, что понимает разбор, управляющие — через `\u`; всё прочее (в
   том числе не-ASCII в UTF-8) отдаёт себя же, как и читает разбор. */
static char *в_литерал(const char *s) {
  size_t d = strlen(s), i, k = 0; char *r = дай(d * 6 + 3);
  r[k++] = '"';
  for (i = 0; i < d; i++) {
    unsigned char c = (unsigned char)s[i];
    if (c == '"' || c == '\\') { r[k++] = '\\'; r[k++] = (char)c; }
    else if (c == '\n') { r[k++] = '\\'; r[k++] = 'n'; }
    else if (c == '\r') { r[k++] = '\\'; r[k++] = 'r'; }
    else if (c == '\t') { r[k++] = '\\'; r[k++] = 't'; }
    else if (c < 0x20 || c == 0x7f) { sprintf(r + k, "\\u%04x", (unsigned)c); k += 6; }
    else r[k++] = (char)c;
  }
  r[k++] = '"'; r[k] = 0;
  return r;
}

/* `результат` — тело функции, за которой стоит теорема: им и замыкается слово
   `результат` в цели. Глубина ограничена, бесконечного спуска тут быть не должно. */
static Знач отношение_термов(char *t, long где, int какое, Сп строки, Знач результат, int глубина) {
  Знач a = оценить_терм(копия(t, (size_t)где), строки, результат, глубина + 1);
  Знач b = оценить_терм(t + где + strlen(ОТНОШЕНИЯ[какое]), строки, результат, глубина + 1);
  if (!a.вид || !b.вид) return НЕ_БЕРУСЬ;
  if (какое == 0 || какое == 1) {
    if (a.вид != 1 || b.вид != 1) return НЕ_БЕРУСЬ;
    return как_признак(какое == 0 ? содержит(a.s, b.s) : начинается(a.s, b.s));
  }
  if (какое == 2 || какое == 3 || какое == ОТН_РАВНО) {
    int равны;
    if (a.вид != b.вид) return НЕ_БЕРУСЬ;
    if (мера_а_не_значение(a.вид)) return НЕ_БЕРУСЬ;
    равны = равенство_текстом(a.вид) ? (strcmp(a.s, b.s) == 0) : (a.ч == b.ч);
    return как_признак(какое == 2 ? !равны : равны);
  }
  if (какое == 10) {
    if (a.вид != 3 || b.вид != 3) return НЕ_БЕРУСЬ;
    return как_признак(a.ч != 0 && b.ч != 0);
  }
  if (a.вид != 2 || b.вид != 2) return НЕ_БЕРУСЬ;
  switch (какое) {
    case 4: return как_признак(a.ч >= b.ч);
    case 5: return как_признак(a.ч <= b.ч);
    case 6: return как_признак(a.ч <  b.ч);
    case 7: return как_признак(a.ч >  b.ч);
    case 8: return как_число(a.ч + b.ч);
    default: return как_число(a.ч - b.ч);
  }
}

static Знач значение_варианта(char *t, Сп строки, Знач результат, int глубина) {
  Сп им, тр, куски = ПУСТО; int j;
  if (!поля(t, " равным ", &им, &тр)) return НЕ_БЕРУСЬ;
  for (j = 0; j < им.n; j++) {
    Знач з = оценить_терм(тр.e[j], строки, результат, глубина + 1);
    if (з.вид < 1 || з.вид > 3 || (з.вид == 2 && з.ч == 0 && 1 / з.ч < 0)) return НЕ_БЕРУСЬ;
    добавить(&куски, fmt("«%s» равным %s", им.e[j], з.вид == 1 ? в_литерал(з.s)
                          : з.вид == 3 ? (з.ч != 0 ? "да" : "нет") : fmt("%.17g", з.ч)));
  }
  return как_вариант(fmt("вариант «%s» с %s", в_ёлочках(t, 1), соединить(куски, " и ")));
}

static const char *ПО_[] = { " по " }, *ОТ_[] = { " от " };

/* Тело ветви СОСЕДКИ ПО ТОМУ ЖЕ СЛУЧАЮ (`«F» от «довод»`) либо NULL. Соседкой
   зовётся функция, которую разбирает тот же случай: довод вызова — то самое имя,
   строка `принимает` знак в знак та же, тело — разбор по тому же доводу. Не
   сошлось хоть одно — NULL, и зовущий идёт дальше к общему «не берусь». */
static char *ветвь_соседки(char *t, Сп строки, const char *довод_сл,
                           const char *образец, const char *принимает) {
  long где2; int какое2;
  if (!(довод_сл && образец && принимает)) return NULL;
  if (!найти_сверху(t, ОТ_, 1, &где2, &какое2)) return NULL;
  { char *имя_ф = обрезать(копия(t, (size_t)где2));
    char *довод = без_внешних(t + где2 + strlen(ОТ_[0]));
    char *f = в_ёлочках(имя_ф, 1);
    long a2, b2 = 0;
    if (!(*f && strcmp(fmt("«%s»", f), имя_ф) == 0 &&
          (strcmp(довод, fmt("«%s»", довод_сл)) == 0 || strcmp(довод, довод_сл) == 0)))
      return NULL;
    a2 = блок_функции(строки, f, &b2);
    if (!(a2 > 0 && strcmp(строка_принимает(строки, a2, b2), принимает) == 0 &&
          тело_одним_разбором(строки, a2, b2, довод_сл) > 0)) return NULL;
    { char *v = ветвь_тела(строки, a2, b2, образец);
      if (!*v && начинается(образец, "вариант «"))
        v = ветвь_тела(строки, a2, b2, образец + strlen("вариант "));
      return *v ? v : NULL; } }
}

/* Общий вызов `«F» от А [и Б …]` — развёртка тела. Левая часть обязана быть
   РОВНО одной парой ёлочек: этим вызов отделён от свёртки, у которой ` от `
   тоже стоит на верхнем уровне. Не вызов либо тело не посчиталось — НЕ_БЕРУСЬ,
   и зовущий пробует следующие формы. */
static Знач значение_вызова(char *t, Сп строки, Знач результат, int глубина) {
  long где4; int какое4;
  if (!найти_сверху(t, ОТ_, 1, &где4, &какое4)) return НЕ_БЕРУСЬ;
  { char *левое = обрезать(копия(t, (size_t)где4));
    char *f = в_ёлочках(левое, 1);
    if (!(*f && strcmp(fmt("«%s»", f), левое) == 0)) return НЕ_БЕРУСЬ;
    return применить_функцию(строки, f, доводы_вызова(t + где4 + strlen(ОТ_[0])),
                             результат, глубина); }
}

/* Склейка списка строк разделителем. Звено не строка — «не берусь». */
static Знач склейка_списка(char *h, long i1, Сп строки, Знач результат, int глубина) {
  Знач сп = оценить_терм(копия(h, (size_t)i1), строки, результат, глубина + 1);
  Знач раз = оценить_терм(h + i1 + strlen(ПО_[0]), строки, результат, глубина + 1);
  Сп чл, куски = ПУСТО; int j;
  if (сп.вид != 4 || раз.вид != 1) return НЕ_БЕРУСЬ;
  чл = члены_списка(сп.s);
  for (j = 0; j < чл.n; j++) {
    Знач э = оценить_терм(чл.e[j], строки, результат, глубина + 1);
    if (э.вид != 1) return НЕ_БЕРУСЬ;
    добавить(&куски, э.s);
  }
  return как_строка(куски.n ? соединить(куски, раз.s) : (char *)"");
}

/* Разрез строки разделителем. Отдаёт СПИСОК, записанный литералами, — в том же
   виде, в каком список живёт в сверщике везде. Пустой разделитель — «не берусь». */
static Знач разрез_строки(char *h, long i1, Сп строки, Знач результат, int глубина) {
  Знач стр = оценить_терм(копия(h, (size_t)i1), строки, результат, глубина + 1);
  Знач раз = оценить_терм(h + i1 + strlen(ПО_[0]), строки, результат, глубина + 1);
  Сп части, лит = ПУСТО; int j;
  if (стр.вид != 1 || раз.вид != 1 || !*раз.s) return НЕ_БЕРУСЬ;
  части = разделить(стр.s, раз.s);
  for (j = 0; j < части.n; j++) добавить(&лит, в_литерал(части.e[j]));
  return как_список(fmt("[%s]", соединить(лит, ",")), части.n);
}

static Знач мера_терма(char *t, Сп строки, Знач результат, int глубина) {
  Знач a = оценить_терм(t + strlen("длина "), строки, результат, глубина + 1);
  if (a.вид == 4) return как_число(a.ч);
  if (a.вид == 6) return как_число(a.ч);
  return a.вид == 1 ? как_число((double)длина_знаков(a.s)) : НЕ_БЕРУСЬ;
}

static Знач подстрока_терма(char *t, Сп строки, Знач результат, int глубина) {
  static const char *С_[] = { " с " };
  char *h = t + strlen("подстрока "), *рез; long i1, i2, a1, b1; int nn;
  size_t дс = strlen(С_[0]), дпо = strlen(ПО_[0]);
  Знач x, p, q;
  if (!найти_сверху(h, С_, 1, &i1, &nn)) return НЕ_БЕРУСЬ;
  /* Скачок за маркером — длина маркера в БАЙТАХ: «с» и «по» кириллические, по два
     байта на знак, и скачок числом знаков рвёт UTF-8 — довод тихо станет «не берусь». */
  if (!найти_сверху(h + i1 + дс, ПО_, 1, &i2, &nn)) return НЕ_БЕРУСЬ;
  x = оценить_терм(копия(h, (size_t)i1), строки, результат, глубина + 1);
  p = оценить_терм(копия(h + i1 + дс, (size_t)i2), строки, результат, глубина + 1);
  q = оценить_терм(h + i1 + дс + i2 + дпо, строки, результат, глубина + 1);
  if (x.вид != 1 || p.вид != 2 || q.вид != 2) return НЕ_БЕРУСЬ;
  a1 = (long)p.ч; b1 = (long)q.ч;
  if ((double)a1 != p.ч || (double)b1 != q.ч) return НЕ_БЕРУСЬ;
  if (!подстрока_знаков(x.s, a1, b1, &рез)) return НЕ_БЕРУСЬ;
  return как_строка(рез);
}

static Знач значение_головы(char *t, Сп строки, Знач результат, int глубина) {
  Знач a = оценить_терм(t + strlen("голова "), строки, результат, глубина + 1);
  Сп чл;
  if (a.вид != 4) return НЕ_БЕРУСЬ;
  чл = члены_списка(a.s);
  if (!чл.n) return НЕ_БЕРУСЬ;
  return начинается(чл.e[0], "(запись«") ? как_запись(чл.e[0])
       : оценить_терм(чл.e[0], строки, результат, глубина + 1);
}

static Знач значение_свёртки(char *t, Сп строки, Знач результат, int глубина) {
  static const char *НАЧ_[] = { " начиная с " }, *КАК_[] = { " как " },
                     *И_[] = { " и " }, *СТР_[] = { " → " };
  char *h = t + strlen("свёртка "), *список_т, *нач_т, *акк_имя, *элем_слово, *тело_т, *элем_имя;
  long i1, i2, i3, i4; int nn, j, из_разложения = 0;
  Сп члены = ПУСТО;
  Знач акк;
  if (!найти_сверху(h, НАЧ_, 1, &i1, &nn)) return НЕ_БЕРУСЬ;
  список_т = обрезать(копия(h, (size_t)i1));
  h += i1 + strlen(НАЧ_[0]);
  if (!найти_сверху(h, КАК_, 1, &i2, &nn)) return НЕ_БЕРУСЬ;
  нач_т = обрезать(копия(h, (size_t)i2));
  h += i2 + strlen(КАК_[0]);
  if (!найти_сверху(h, И_, 1, &i3, &nn)) return НЕ_БЕРУСЬ;
  акк_имя = обрезать(копия(h, (size_t)i3));
  h += i3 + strlen(И_[0]);
  if (!найти_сверху(h, СТР_, 1, &i4, &nn)) return НЕ_БЕРУСЬ;
  элем_слово = обрезать(копия(h, (size_t)i4));
  тело_т = обрезать(h + i4 + strlen(СТР_[0]));
  /* Имя элемента язык пишет двумя законными способами — в ёлочках (так пишут цели)
     и голым словом (так пишут тела функций); голым считается слово БЕЗ пробелов,
     иначе именем оказался бы кусок разбора. Связывание сличает написание целиком. */
  элем_имя = в_ёлочках(элем_слово, 1);
  if (*элем_имя) { if (strcmp(fmt("«%s»", элем_имя), элем_слово) != 0) return НЕ_БЕРУСЬ; }
  else if (содержит(элем_слово, " ") || !*элем_слово) return НЕ_БЕРУСЬ;
  if (!*акк_имя || содержит(акк_имя, " ")) return НЕ_БЕРУСЬ;
  { char *сп_бв = без_внешних(список_т);
    static const char *НА_СИМВОЛЫ = " на символы";
    size_t дл = strlen(сп_бв), сл = strlen(НА_СИМВОЛЫ), pref = strlen("разложить ");
    if (начинается(сп_бв, "разложить ") && дл > pref + сл &&
        strcmp(сп_бв + дл - сл, НА_СИМВОЛЫ) == 0) {
      Знач осн = оценить_терм(копия(сп_бв + pref, дл - pref - сл), строки, результат, глубина + 1);
      long n, k; char *зн;
      if (осн.вид != 1) return осн.вид == 6 ? не_берусь_потому(ПР_НУЛЕВОЙ_ЗНАК) : НЕ_БЕРУСЬ;
      из_разложения = 1;
      n = длина_знаков(осн.s);
      for (k = 1; k <= n; k++) {
        if (!подстрока_знаков(осн.s, k, k, &зн)) return НЕ_БЕРУСЬ;
        добавить(&члены, зн);
      }
    } else {
      Знач список_з = оценить_терм(сп_бв, строки, результат, глубина + 1);
      if (список_з.вид != 4) return НЕ_БЕРУСЬ;
      члены = члены_списка(список_з.s);
      /* ПУСТОЙ СПИСОК — законный вход свёртки, а не отказ: витков ноль, ответ
         есть начальное значение. Отличается от «звеньев не разобрал» тем, что
         сам список объявил длину ноль (`ч`), — а разошедшийся счёт по-прежнему
         «не берусь». */
      if (!члены.n && список_з.ч != 0) return НЕ_БЕРУСЬ;
    }
  }
  акк = оценить_терм(нач_т, строки, результат, глубина + 1);
  if (!акк.вид) return НЕ_БЕРУСЬ;
  СВ_СТЕК[СВ_ВЕРХ].акк_имя = акк_имя; СВ_СТЕК[СВ_ВЕРХ].элем_имя = элем_слово;
  СВ_СТЕК[СВ_ВЕРХ].акк = НЕ_БЕРУСЬ; СВ_СТЕК[СВ_ВЕРХ].элем = НЕ_БЕРУСЬ;
  СВ_СТЕК[СВ_ВЕРХ].порядок = ++СВЯЗЬ_СЧЁТ;
  СВ_ВЕРХ++;
  for (j = 0; j < члены.n; j++) {
    char *эл = члены.e[j];
    /* Звено «разложить … на символы» — уже готовый знак (взят вырезкой, не
       переписан синтаксисом строки), и второй раз его через `оценить_терм`
       не читают: там, где сам знак — кавычка или экранирующий обратный
       слеш, разбор синтаксиса солгал бы о значении. Звено выписанного
       списка — наоборот, ЕЩЁ строка исходника, и его читает ровно тот же
       разбор, что и любой терм (запись — своим видом 5, прочее — тем же
       `оценить_терм`, что и раньше). */
    Знач элем_з = из_разложения ? как_строка(эл)
                 : начинается(эл, "(запись«") ? как_запись(эл)
                 : оценить_терм(эл, строки, результат, глубина + 1);
    if (!элем_з.вид) { акк = НЕ_БЕРУСЬ; break; }
    СВ_СТЕК[СВ_ВЕРХ - 1].акк = акк; СВ_СТЕК[СВ_ВЕРХ - 1].элем = элем_з;
    акк = оценить_терм(тело_т, строки, результат, глубина + 1);
    if (!акк.вид) break;
  }
  СВ_ВЕРХ--;
  СВ_СТЕК[СВ_ВЕРХ].акк_имя = NULL; СВ_СТЕК[СВ_ВЕРХ].элем_имя = NULL;
  return акк;
}

  /* Звенья не переписываются: итог несёт те же тексты звеньев, вид 4. */
static Знач значение_отбора(char *t, Сп строки, Знач результат, int глубина) {
  static const char *ГДЕ_[] = { " где " }, *В_[] = { " → " };
  char *h = t + strlen("отфильтровать "), *х, *у; long i1, i2; int nn, j; Сп чл, ост = ПУСТО; Знач сп;
  if (!найти_сверху(h, ГДЕ_, 1, &i1, &nn) || !найти_сверху(h + i1 + strlen(ГДЕ_[0]), В_, 1, &i2, &nn))
    return не_берусь_потому(ПР_ОТБОР);
  сп = оценить_терм(копия(h, (size_t)i1), строки, результат, глубина + 1);
  х = обрезать(копия(h + i1 + strlen(ГДЕ_[0]), (size_t)i2));
  у = h + i1 + strlen(ГДЕ_[0]) + i2 + strlen(В_[0]);
  чл = сп.вид == 4 ? члены_списка(сп.s) : ПУСТО;
  if (сп.вид != 4 || (!чл.n && сп.ч != 0)) return НЕ_БЕРУСЬ;
  for (j = 0; j < чл.n; j++) {
    Знач э = начинается(чл.e[j], "(запись«") ? как_запись(чл.e[j]) : оценить_терм(чл.e[j], строки, результат, глубина + 1), уз;
    if (!э.вид || !связать_довод(х, э)) return НЕ_БЕРУСЬ;
    уз = оценить_терм(у, строки, результат, глубина + 1); развязать_доводы(1);
    if (уз.вид != 3) return НЕ_БЕРУСЬ;
    if (уз.ч != 0) добавить(&ост, чл.e[j]);
  }
  return как_список(fmt("[%s]", соединить(ост, ",")), ост.n);
}

static Знач оценить_терм(const char *сырой, Сп строки, Знач результат, int глубина) {
  char *t, *лит, *им; long где; int какое; double ч;
  if (глубина == 0) { ОЦЕНОК = 0; ПРИЧИНА_СЧЁТА = NULL; }
  if (глубина > ГЛУБИНА_ПРЕДЕЛ || ++ОЦЕНОК > ОЦЕНОК_ПРЕДЕЛ) return НЕ_БЕРУСЬ;
  t = без_внешних(сырой);
  if (!*t) return НЕ_БЕРУСЬ;
  /* У `свёртка … → ТЕЛО`, `если … иначе ВЕТВЬ` и `отфильтровать … → У` последняя
     часть тянется до конца терма и правой границы не имеет. Отношения ищутся
     только там, где терм ни одной из этих форм не начинается: иначе ` плюс `
     или ` равен ` внутри хвоста режет терм пополам, и ЧЕСТНАЯ запись отвергается. */
  if (!начинается(t, "свёртка ") && !начинается(t, "если ") && !начинается(t, "отфильтровать ") &&
      найти_сверху(t, ОТНОШЕНИЯ, ОТНОШЕНИЙ, &где, &какое))
    return отношение_термов(t, где, какое, строки, результат, глубина);
  if (strcmp(t, "результат") == 0) return результат;
  if (strcmp(t, "да") == 0) return как_признак(1);
  if (strcmp(t, "нет") == 0) return как_признак(0);
  /* Пустой список — ЗНАЧЕНИЕ (вид 4 длины ноль), а не «не берусь»: без этого
     слова ветвь `случай пусто` не считается вовсе — ни тело, ни цель. */
  if (strcmp(t, "пустой список") == 0) return как_список((char *)"[]", 0);
  { char *тег = в_ёлочках(t, 1);
    if (*тег && strcmp(fmt("вариант «%s»", тег), t) == 0) return как_тег(t); }
  /* Поле иного вида (список, запись, вариант) и минус ноль — «не берусь»:
     литерал их не несёт. */
  if (начинается(t, "вариант «") && strstr(t, "» с "))
    return значение_варианта(t, строки, результат, глубина);
  { Знач св; if (связывание(t, &св)) return св; }
  { long зн; int иск = разобрать_литерал_полно(t, &лит, &зн);
    if (иск == 1) return как_строка(лит);
    if (иск == 2) return как_длина_без_строки(зн); }
  if (число_точно(t, &ч)) {
    /* МИНУС НОЛЬ СЮДА НЕ ПУСКАЕТСЯ: ядро считает `0` и минус ноль одним термом,
       язык — разными. Считать здесь значило бы гадать. */
    if (t[0] == '-' && ч == 0) return НЕ_БЕРУСЬ;
    return как_число(ч);
  }
  им = в_ёлочках(t, 1);
  if (*им && strcmp(fmt("«%s»", им), t) == 0) {
    char *v, *сыр; long зн6;
    if (тело_таблицы(строки, им, &v)) return как_строка(v);
    /* Тело — литерал С НУЛЕВЫМ ЗНАКОМ (`corpus-bytes`, «Однобайтовые»). Строку
       сверщик держать не берётся (вид 6), а ДЛИНУ её знает по самой записи
       литерала — этого хватает цели «(длина результат) равен 128». */
    сыр = тело_таблицы_строка(строки, им);
    if (*сыр && разобрать_литерал_полно(сыр, &v, &зн6) == 2) return как_длина_без_строки(зн6);
    return таблица_списком(строки, им);
  }
  { char *бп = без_пробелов_вне_кавычек(t); size_t бд = strlen(бп);
    if (бд >= 2 && бп[0] == '[' && бп[бд - 1] == ']' && кавычки_чисты(t)) {
      Сп ч2 = члены_списка(бп);
      if (ч2.n) return как_список(бп, ч2.n);
      if (бд == 2) return как_список(бп, 0);
    }
  }
  if (начинается(t, "длина ")) return мера_терма(t, строки, результат, глубина);
  /* Список `ПРИМИТИВЫ` этими формами не пополняется: там имена языка, а здесь —
     то, что вычислитель умеет посчитать сам. `разделить` отдаёт список литералами. */
  if (начинается(t, "соединить ")) {
    char *h = t + strlen("соединить "); long i1; int nn;
    if (найти_сверху(h, ПО_, 1, &i1, &nn)) return склейка_списка(h, i1, строки, результат, глубина);
  }
  if (начинается(t, "разделить ")) {
    char *h = t + strlen("разделить "); long i1; int nn;
    if (найти_сверху(h, ПО_, 1, &i1, &nn)) return разрез_строки(h, i1, строки, результат, глубина);
  }
  if (начинается(t, "подстрока ")) return подстрока_терма(t, строки, результат, глубина);
  { char *u, *ветвь_а, *ветвь_б;
    if (разрез_выбора_цепочкой(t, &u, &ветвь_а, &ветвь_б)) {
      Знач усл = оценить_терм(u, строки, результат, глубина + 1);
      if (усл.вид != 3) return НЕ_БЕРУСЬ;
      return оценить_терм(усл.ч != 0 ? ветвь_а : ветвь_б, строки, результат, глубина + 1);
    }
  }
  { char *v = ветвь_соседки(t, строки, РЗ_ДОВОД, РЗ_ОБРАЗЕЦ, РЗ_ПРИНИМАЕТ);
    if (v) return оценить_терм(v, строки, НЕ_БЕРУСЬ, глубина + 1); }
  { Знач z = значение_вызова(t, строки, результат, глубина); if (z.вид) return z; }
  if (начинается(t, "голова ")) return значение_головы(t, строки, результат, глубина);
  { char *точка = strrchr(t, '.');
    if (точка && точка != t) {
      char *поле = в_ёлочках(точка + 1, 1);
      if (*поле && strcmp(fmt("«%s»", поле), точка + 1) == 0) {
        Знач база = оценить_терм(копия(t, (size_t)(точка - t)), строки, результат, глубина + 1);
        char *зн = база.вид == 5 ? поле_записи(база.s, поле) : NULL;
        return зн ? оценить_терм(зн, строки, результат, глубина + 1) : НЕ_БЕРУСЬ;
      }
    }
  }
  if (начинается(t, "свёртка ") && СВ_ВЕРХ < СВ_КАДРОВ)
    return значение_свёртки(t, строки, результат, глубина);
  if (начинается(t, "отфильтровать ")) return значение_отбора(t, строки, результат, глубина);
  return НЕ_БЕРУСЬ;
}

/* Значение — в строку РАДИ СООБЩЕНИЯ, а не ради сверки: сверка идёт значением
   (ниже), а человеку в беде нужно видеть, ЧТО именно посчитал сверщик. */
static char *знач_в_строку(Знач z) {
  if (равенство_текстом(z.вид) || z.вид == 8) return z.s;
  if (z.вид == 3) return (char *)(z.ч != 0 ? "да" : "нет");
  if (z.вид == 2) { long n = (long)z.ч; return (double)n == z.ч ? fmt("%ld", n) : fmt("%.17g", z.ч); }
  return (char *)"не берусь";
}

/* Считается ТОЛЬКО замкнутый наземный терм. `результат` в счёт НЕ передаётся
   (третий довод — НЕ_БЕРУСЬ): встретив его или иное свободное имя, счёт вернёт
   «не берусь», и ход ОТКАЖЕТ, а не посчитает вслепую. Посчитанное сверяется
   с ⟨V⟩ ЗНАЧЕНИЕМ, и лишь тогда заменяется. */
static void ход_вычисления(Прогон *p, const char *строка, Обст *o) {
  char *что = терм(в_уголках(строка, 1)), *зап = терм(в_уголках(строка, 2));
  Знач т_зн, сверка;
  if (!*зап) { беда_прогона(p, fmt("вычислить «%s»: вторым уголком не стоит значение ⟨V⟩", что)); return; }
  if (!есть_терм(первая_цель(p), что)) {
    беда_прогона(p, fmt("вычислить: в цели «%s» нет терма «%s»", первая_цель(p), что)); return; }
  т_зн = оценить_терм(что, o->строки, НЕ_БЕРУСЬ, 0);
  if (!т_зн.вид) {
    беда_прогона(p, fmt("вычислить «%s»: терм не замкнут (свободное имя или неарифметический конструктор) — считать нечего", что)); return; }
  сверка = оценить_терм(fmt("( %s ) равен ( %s )", что, зап), o->строки, НЕ_БЕРУСЬ, 0);
  if (сверка.вид != 3 || сверка.ч == 0) {
    беда_прогона(p, fmt("вычислить «%s»: терм посчитан = %s, а запись несёт ⟨%s⟩", что, знач_в_строку(т_зн), зап)); return; }
  одна_цель(p, терм(вставить_вместо(первая_цель(p), что, зап)));
}

static int не_взялся(Сверка *s, const char *имя_т, const char *почему) {
  добавить(&s->не_взялся, fmt("теорема «%s»: шаг «по примеру» не проверен по существу — %s", имя_т, почему));
  return 0;
}
static char *цель_незнакома(const char *цель) {
  return fmt("вид цели «%s» сверщику незнаком%s%s", цель,
             ПРИЧИНА_СЧЁТА ? " — " : "", ПРИЧИНА_СЧЁТА ? ПРИЧИНА_СЧЁТА : "");
}
static int сверить_шаг_вне_случая(Сверка *s, Сп строки, const char *имя_т,
                                    const char *имя_п, const char *чья,
                                    const char *ож, const char *цель,
                                    int есть_свободные) {
  char *тело, *ож_з; Знач z;
  if (есть_свободные) return не_взялся(s, имя_т, "в цели остаётся свободное имя");
  if (!тело_таблицы(строки, чья, &тело)) {
    /* ТЕЛО — ЛИТЕРАЛ С НУЛЕВЫМ ЗНАКОМ (задача 1573, `corpus-bytes`). Строку
       такого литерала сверщик не держит (вид 6), а значит и сличать её с
       `ожидается` ЗНАЧЕНИЕМ нечем. Сличается САМА ЗАПИСЬ литерала, знак в знак:
       это проверка более строгая, чем по значению, — два разных литерала с
       одним значением она разведёт, а одинаковые сведёт. */
    { char *сыр = тело_таблицы_строка(строки, чья); char *лит6; long зн6;
      if (*сыр && разобрать_литерал_полно(сыр, &лит6, &зн6) == 2) {
        если_не(s, strcmp(сыр, ож) == 0,
                fmt("теорема «%s»: пример «%s» ждёт «%s», а тело функции «%s» записано иначе",
                    имя_т, имя_п, ож, чья));
        if (strcmp(сыр, ож) != 0) return 0;
        z = оценить_терм(цель, строки, как_длина_без_строки(зн6), 0);
        if (z.вид != 3) return не_взялся(s, имя_т, цель_незнакома(цель));
        если_не(s, z.ч != 0,
                fmt("теорема «%s»: цель «%s» при теле функции «%s» НЕ держится", имя_т, цель, чья));
        return z.ч != 0;
      } }
    Знач сп = таблица_списком(строки, чья);
    char *ож_н = без_пробелов_вне_кавычек(ож);
    if (!сп.вид) return не_взялся(s, имя_т, fmt("тело функции «%s» — не литерал без параметров", чья));
    if (!*ож_н) return не_взялся(s, имя_т, fmt("«ожидается» примера «%s» не разбирается", имя_п));
    если_не(s, strcmp(сп.s, ож_н) == 0,
            fmt("теорема «%s»: пример «%s» ждёт другой список, чем тело функции «%s»",
                имя_т, имя_п, чья));
    if (strcmp(сп.s, ож_н) != 0) return 0;
    z = оценить_терм(цель, строки, сп, 0);
    if (z.вид != 3) return не_взялся(s, имя_т, цель_незнакома(цель));
    если_не(s, z.ч != 0,
            fmt("теорема «%s»: цель «%s» при теле функции «%s» НЕ держится", имя_т, цель, чья));
    return z.ч != 0;
  }
  if (!разобрать_литерал(ож, &ож_з))
    return не_взялся(s, имя_т, fmt("«ожидается» примера «%s» — не строковый литерал", имя_п));
  если_не(s, strcmp(тело, ож_з) == 0,
          fmt("теорема «%s»: пример «%s» ждёт «%s», а тело функции «%s» даёт другое значение",
              имя_т, имя_п, ож, чья));
  if (strcmp(тело, ож_з) != 0) return 0;
  z = оценить_терм(цель, строки, как_строка(тело), 0);
  if (z.вид != 3) return не_взялся(s, имя_т, цель_незнакома(цель));
  если_не(s, z.ч != 0,
          fmt("теорема «%s»: цель «%s» при теле функции «%s» НЕ держится",
              имя_т, цель, чья));
  return z.ч != 0;
}

/* ЗАПАСНОЙ ХОД ДЛЯ ФУНКЦИЙ-ОТРЕЗКОВ: тела `разбор/случай` у них не бывает —
   язык отвергает разбор по числу, и такой разбор пишется одним `если`. Берётся
   только при полном совпадении формы; ветвь выбирается по СЧИТАННОМУ условию,
   не посчиталось — «не берусь»: ветвь наугад была бы верой. */
static int ветвь_если_по_доводу(Сп строки, long a, long b, const char *по,
                               const char *дано, char **ветвь) {
  long i, еслей = 0, н_то = 0, н_иначе = 0;
  char *усл = (char *)"", *в_то = (char *)"", *в_иначе = (char *)"";
  Знач z;
  if (!*по || !*дано) return 0;
  for (i = a; i < b; i++) {
    char *z2 = как_читает_язык(часть(строки, i));
    if (начинается(z2, "если ")) { еслей++; усл = хвост_после(z2, "если "); }
    else if (начинается(z2, "то ")) { н_то++; в_то = хвост_после(z2, "то "); }
    else if (начинается(z2, "иначе ")) { н_иначе++; в_иначе = хвост_после(z2, "иначе "); }
  }
  if (еслей != 1 || н_то != 1 || н_иначе != 1) return 0;
  z = оценить_терм(вставить_вместо(усл, по, дано), строки, НЕ_БЕРУСЬ, 0);
  if (z.вид != 3) return 0;
  *ветвь = терм(z.ч != 0 ? в_то : в_иначе);
  return **ветвь != 0;
}

static int сверить_шаг_примером(Сверка *s, const char *ш, Сп строки, const char *имя_т,
                                const char *чья, const char *по, long случай_где,
                                const char *цель, int есть_свободные) {
  /* Имя примера ищется БЕЗ терма в уголках: термин может нести своё «в
     ёлочках», и без выреза оно перехватило бы первое место у имени примера. */
  char *имя_п = в_ёлочках(шаг_словами(ш), 1);
  long p = номер_после(ш, МЕТКА_ПРИМЕРА), a, b;
  char *ож, *дано, *образец, *образец_сверки, *образец_голый, *ветвь; int знаком = 0;
  if (p < 1) { s->без_привязки++; return не_взялся(s, имя_т, "шаг «по примеру» без привязки к строке примера"); }
  a = блок_функции(строки, чья, &b);
  если_не(s, a > 0, fmt("теорема «%s»: функции «%s» в исходнике нет, а пример «%s» записан за ней",
                        имя_т, чья, имя_п));
  if (a < 1) return 0;
  если_не(s, strcmp(строка_по_номеру(строки, p), fmt("пример «%s»", имя_п)) == 0,
          fmt("теорема «%s»: запись привязывает пример «%s» к строке %ld, а там написано «%s»",
              имя_т, имя_п, p, строка_по_номеру(строки, p)));
  если_не(s, p >= a && p < b,
          fmt("теорема «%s»: пример «%s» записан на строке %ld, а блок функции «%s» — строки %ld…%ld: пример чужой",
              имя_т, имя_п, p, чья, a, b - 1));
  if (strcmp(строка_по_номеру(строки, p), fmt("пример «%s»", имя_п)) != 0 || p < a || p >= b) return 0;
  ож = ожидается_примера(строки, p, b);
  if (!*ож) return не_взялся(s, имя_т, fmt("у примера «%s» нет доступного «ожидается»", имя_п));
  if (случай_где < 1)
    return сверить_шаг_вне_случая(s, строки, имя_т, имя_п, чья, ож, цель, есть_свободные);
  образец = хвост_после(строка_по_номеру(строки, случай_где), "случай ");
  дано = дано_примера(строки, p, b, по);
  if (!*дано || !*образец) return 0;
  /* Нульарный вариант в `случай` вправе писаться и голым тегом «X», и тем же тегом
     со словом «вариант» впереди; ПРИМЕР же называет его всегда со словом «вариант».
     Поэтому для сверки достраивается копия образца до вида, каким его называет
     пример. Голый образец сверщик не узнаёт вовсе, и достройка не портит ничего. */
  образец_сверки = (начинается(образец, "«") && !начинается(образец, "вариант «"))
                     ? fmt("вариант %s", образец) : образец;
  if (!образец_совпал(образец_сверки, дано, &знаком)) {
    if (!знаком)
      return не_взялся(s, имя_т,
                         fmt("образец случая «%s» или значение примера «%s» (%s) сверщику незнакомы",
                             образец, по, дано));
    если_не(s, !знаком,
            fmt("теорема «%s»: случай разбирает «%s», а пример «%s» задаёт «%s» как «%s» — это о другом значении",
                имя_т, образец, имя_п, по, дано));
    return 0;
  }
  ветвь = ветвь_тела(строки, a, b, образец);
  if (!*ветвь && начинается(образец, "вариант «")) {
    /* Индукция теоремы вправе писать образец словом «вариант», а `разбор` тела
       нульарного варианта — тем же тегом БЕЗ этого слова. Один тег, два места, два
       законных написания: вторая попытка ищет ветвь именем без слова спереди. */
    образец_голый = образец + strlen("вариант ");
    ветвь = ветвь_тела(строки, a, b, образец_голый);
  }
  /* Ветвь берётся по СЧИТАННОМУ условию `если`. Значение довода уже сверено с
     образцом случая выше — подставляется именно оно. */
  if (!*ветвь) { char *v2; if (ветвь_если_по_доводу(строки, a, b, по, дано, &v2)) ветвь = v2; }
  /* СЧЁТНОЕ ТЕЛО: когда тело функции не разбор, а свёртка, ветви-литерала у случая
     нет — значение тело не называет, а СЧИТАЕТ. Сличается с «ожидается» ЗНАЧЕНИЕМ,
     не текстом: `[5, 6]` и `[5,6]` — одно значение и разный текст. Разошлось — это
     ЛОЖЬ ЗАПИСИ, а не «не берусь»: обе стороны прочитаны из исходника. */
  if (!*ветвь) {
    Знач д_з = оценить_терм(дано, строки, НЕ_БЕРУСЬ, 0);
    if (д_з.вид) {
      int св = связать_довод(по, д_з) + связать_довод(fmt("«%s»", по), д_з);
      Знач тз = вычислить_тело(строки, a, b, 0);
      Знач ож_з = оценить_терм(ож, строки, НЕ_БЕРУСЬ, 0);
      if (тз.вид && ож_з.вид && тз.вид == ож_з.вид && !мера_а_не_значение(тз.вид)) {
        int сошлось = равенство_текстом(тз.вид) ? (strcmp(тз.s, ож_з.s) == 0) : (тз.ч == ож_з.ч);
        если_не(s, сошлось,
                fmt("теорема «%s»: пример «%s» ждёт «%s», а тело функции «%s» на этом доводе даёт «%s»",
                    имя_т, имя_п, ож, чья, знач_в_строку(тз)));
        if (!сошлось) { развязать_доводы(св); return 0; }
        { Знач z2 = оценить_терм(цель, строки, тз, 0);
          развязать_доводы(св);
          if (z2.вид != 3) return не_взялся(s, имя_т, цель_незнакома(цель));
          если_не(s, z2.ч != 0,
                  fmt("теорема «%s»: цель «%s» на значении примера «%s» (%s) НЕ держится",
                      имя_т, цель, имя_п, ож));
          return z2.ч != 0; }
      }
      развязать_доводы(св);
    }
  }
  if (!*ветвь) return не_взялся(s, имя_т, fmt("ветвь тела на образец «%s» не литерал — прогон не повторить", образец));
  если_не(s, strcmp(ветвь, ож) == 0,
          fmt("теорема «%s»: пример «%s» ждёт «%s», а ветвь тела на «%s» даёт «%s»",
              имя_т, имя_п, ож, образец, ветвь));
  if (strcmp(ветвь, ож) != 0) return 0;
  /* Цель считается `оценить_терм`, а не `цель_держится`: та читает только
     «результат <отношение> ЧИСЛО», а здешние цели иного вида. Подставляется
     значение, ПРОВЕРЕННОЕ дважды: строка ветви тела совпала со строкой
     «ожидается» знак в знак. */
  {
    Знач рез = оценить_терм(ож, строки, НЕ_БЕРУСЬ, 0);
    Знач z;
    if (!рез.вид) return не_взялся(s, имя_т, fmt("значение примера «%s» (%s) сверщику незнакомо", имя_п, ож));
    /* ПРИМЕТЫ СЛУЧАЯ НА ВРЕМЯ СЧЁТА ЦЕЛИ (Ч7104). Ставятся ровно вокруг одного
       вызова и снимаются сразу: цель СЛЕДУЮЩЕГО шага не вправе увидеть образец
       предыдущего. Всё, что они открывают, — вызов соседки, разбирающей тот же
       довод тем же случаем; условия перечислены у RZ_*. */
    /* Довод индукции связывается на время счёта цели: значение его в этом случае
       известно точно и уже сверено с образцом. Имя пишется двумя законными способами
       (голым и в ёлочках) — связываются оба, одним и тем же значением. */
    Знач д_з = оценить_терм(дано, строки, НЕ_БЕРУСЬ, 0);
    int св = д_з.вид ? связать_довод(по, д_з) + связать_довод(fmt("«%s»", по), д_з) : 0;
    РЗ_ДОВОД = по; РЗ_ОБРАЗЕЦ = образец_сверки; РЗ_ПРИНИМАЕТ = строка_принимает(строки, a, b);
    z = оценить_терм(цель, строки, рез, 0);
    РЗ_ДОВОД = NULL; РЗ_ОБРАЗЕЦ = NULL; РЗ_ПРИНИМАЕТ = NULL;
    развязать_доводы(св);
    if (z.вид != 3) return не_взялся(s, имя_т, цель_незнакома(цель));
    если_не(s, z.ч != 0,
            fmt("теорема «%s»: цель «%s» на значении примера «%s» (%s) НЕ держится",
                имя_т, цель, имя_п, ож));
    return z.ч != 0;
  }
}

/* Привязка `свойство строка N` у шага `по свойству`: N — строка, на которой
   постусловие с этим именем объявлено ВПЕРВЫЕ ПО ВСЕМУ ФАЙЛУ, а не в блоке одной
   функции, — так его ищет само правило. Сам вывод не переигрывается: проверено
   лишь, что имя не выдумано и привязка указывает на то самое объявление. */
static long номер_свойства(Сп строки, const char *имя) {
  char *метка = fmt("обеспечивает «%s»", имя); long i;
  for (i = 1; i <= строки.n; i++) {
    char *z = строка_по_номеру(строки, i);
    if (!начинается(z, "обеспечивает «") && !начинается(z, "для всех ")) continue;
    if (содержит(z, метка)) return i;
  }
  return 0;
}
/* Шаг `по свойству «И»`, где «И» — утверждение: снимается со слова ядра, только
   если утверждение проверено по существу раньше. Подстановку шаг не несёт —
   она ищется среди доводов функции ТОГО ЖЕ типа, знак в знак, а довод, чьё имя
   совпало с ещё не подставленным связанным, отбрасывается (захват). */
static int есть_связыватель(const char *t);
static int шаг_утверждением(Сверка *s, Сп строки, const char *имя_т, const char *имя_п,
                            long p, long ут, const char *чья, const char *цель) {
  Сп имена = ПУСТО; Доводы д = доводы_функции(строки, чья);
  char *ц_у = терм(из_высказывания(строки, ут, NULL, &имена)), *ц_ш, *тело = (char *)"";
  const char *почему;
  long a, b, k, всего = 1, c; int i, j, раньше = 0, огр = 0, читается;
  если_не(s, p == ут, fmt("теорема «%s»: свойство «%s» привязано к строке %ld, а заголовок утверждения «%s» — строка %ld",
                          имя_т, имя_п, p, имя_п, ут));
  if (p != ут) return 0;
  for (i = 0; i < s->доказанные_свойства.n; i++) раньше |= strcmp(s->доказанные_свойства.e[i], имя_п) == 0;
  for (k = ут + 1; k <= строки.n && начинается(часть(строки, k), " "); k++) огр |= содержит(часть(строки, k), " таких что ");
  a = блок_функции(строки, чья, &b);
  if (a > 0) тело = тело_функции_текст(строки, a, b);
  ц_ш = терм(вставить_вместо(терм(цель), "результат", тело));
  читается = *тело && !есть_связыватель(ц_ш) && имена.n <= 3;
  for (i = 0; i < имена.n && читается; i++) всего *= д.имена.n;
  for (c = 0; раньше && !огр && читается && c < всего; c++) {
    char *инст = ц_у; long r = c; int годен = 1;
    for (i = 0; i < имена.n; i++, r /= д.имена.n) {
      char *довод = голо(д.имена.e[r % д.имена.n]);
      годен &= *довод && strcmp(обрезать(из_высказывания(строки, ут, имена.e[i], NULL)),
                                обрезать(д.типы.e[r % д.имена.n])) == 0;
      for (j = i + 1; j < имена.n; j++) годен &= strcmp(довод, имена.e[j]) != 0;
      инст = вставить_вместо(инст, имена.e[i], довод);
    }
    if (годен && strcmp(терм(инст), ц_ш) == 0) return 1;
  }
  почему = !раньше ? "оно не проверено по существу раньше этой теоремы"
         : огр ? "у него ограничение «таких что», а снятия его шаг не показывает"
         : !читается ? "цель шага с развёрнутым телом функции сверщику не прочесть"
         : "его цель ни при какой подстановке доводов функции того же типа не совпала с целью шага";
  добавить(&s->не_взялся, fmt("теорема «%s»: шаг «по свойству «%s»» — утверждение, но %s; место на слове ядра",
                              имя_т, имя_п, почему));
  return 0;
}
static int сверить_шаг_свойством(Сверка *s, const char *ш, Сп строки, const char *имя_т,
                                 const char *чья, const char *цель) {
  char *имя_п = в_ёлочках(шаг_словами(ш), 1);
  long p = номер_после(ш, МЕТКА_СВОЙСТВА), настоящий;
  /* Своё `добавить`, а не `не_взялся`: тот зашивает в текст слова «шаг „по примеру“»,
     а шаг здесь другой. */
  if (p < 1) { s->без_привязки++;
    добавить(&s->не_взялся,
            fmt("теорема «%s»: шаг «по свойству «%s»» не проверен по существу — ядро не выписало привязку «свойство строка N»",
                имя_т, имя_п));
    return 0; }
  настоящий = номер_свойства(строки, имя_п);
  { long ут = строка_высказывания(строки, fmt("утверждение «%s»", имя_п));
    если_не(s, !(ут && настоящий),
            fmt("теорема «%s»: имя «%s» носят и постусловие, и утверждение — назовите одно", имя_т, имя_п));
    if (ут) return настоящий ? 0 : шаг_утверждением(s, строки, имя_т, имя_п, p, ут, чья, цель); }
  если_не(s, настоящий >= 1,
          fmt("теорема «%s»: свойство «%s» привязано к строке %ld, а объявления «обеспечивает «%s»»"
              " в исходнике нет вовсе",
              имя_т, имя_п, p, имя_п));
  if (настоящий < 1) return 0;
  если_не(s, p == настоящий,
          fmt("теорема «%s»: свойство «%s» привязано к строке %ld, а первое (и единственно"
              " законное — как ищет само правило) его объявление в модуле — строка %ld",
              имя_т, имя_п, p, настоящий));
  return p == настоящий;
}

static int неотрицательно_algebra(const char *т_сырой, const char *чья, Сп bound,
                                 Сп строки, int глубина, char **почему);
static int прямая_по_предположению(Сп строки, const char *чья) {
  long a, b; char *тело, *почему = (char *)"";
  a = блок_функции(строки, чья, &b);
  if (a < 1) return 0;
  тело = тело_функции_текст(строки, a, b);
  return *тело && неотрицательно_algebra(тело, чья, ПУСТО, строки, 0, &почему);
}

static void сверить_шаги(Сверка *s, Сп свои, Сп строки, const char *имя_т,
                         const char *чья, const char *цель) {
  char *по = в_ёлочках(первая_с_началом(свои, "индукция по "), 1);
  /* Свободное имя в цели: `дано «х»` или индукция. Тогда `результат` не одно
     значение, и подстановка тела (дорога Ч76) не годится — «не берусь». */
  int свободные = (*первая_с_началом(свои, "дано «") != 0) || (*по != 0);
  long случай_где = 0; int i;
  for (i = 0; i < свои.n; i++) {
    char *ш = обрезать(свои.e[i]);
    long где; char *вид, *обоснование, *в_исх;
    if (начинается(ш, "случай строка")) { случай_где = номер_после(ш, "строка "); continue; }
    if (!начинается(ш, "шаг ")) continue;
    где = номер_после(ш, "строка ");
    вид = шаг_вид(ш); обоснование = шаг_обоснование(ш);
    /* «по предположению допущение J»: J обязано быть среди допущений записи, сам вывод —
       на слове ядра. В исходнике шаг написан без номера, потому обоснование и урезается. */
    if (начинается(обоснование, "по предположению допущение ")) {
      long J = номер_после(обоснование, "допущение "), всего = все_с_началом(свои, "допущение ").n;
      если_не(s, J >= 1 && J <= всего,
              fmt("теорема «%s»: шаг %s закрыт допущением %ld, а допущений в записи %ld",
                  имя_т, слово(ш, 2), J, всего));
      обоснование = (char *)"по предположению";
    }
    s->шагов++;
    if (начинается(обоснование, "по примеру")) {
      if (сверить_шаг_примером(s, ш, строки, имя_т, чья, по, случай_где, цель, свободные)) s->шагов_примером++;
      else s->шагов_на_слово++;
    } else if (начинается(обоснование, "по свойству")) {
      if (сверить_шаг_свойством(s, ш, строки, имя_т, чья, цель)) s->шагов_свойством++;
      else s->шагов_на_слово++;
    } else if (начинается(обоснование, "по закону")) {
      /* Закон сверщик не переигрывает; ветка стоит затем, чтобы такой шаг был НАЗВАН,
         а не сосчитан молча. */
      добавить(&s->шаги_отложенные,
              fmt("теорема «%s»: шаг «%s» обоснован законом — сверщик закон не переигрывает, место на слове ядра",
                  имя_т, обоснование));
      s->шагов_на_слово++;
      s->шагов_законом++;
    } else if (strcmp(обоснование, "по предположению") == 0 && !*по &&
               strcmp(ужать(терм(цель)), "результат не меньше 0") == 0 &&
               прямая_по_предположению(строки, чья)) {
      /* Прямая теорема с единственной целью «результат не меньше 0» и шагом «по
         предположению»: допущение у неё одно — предусловие функции, и шаг верен ровно
         тогда, когда тело неотрицательно по построению при этом допущении. */
      s->сведений++; s->шагов_по_телу++;
    } else {
      /* Ветвь ловит ЛЮБОЕ обоснование, а не список имён: имя, не попавшее ни в одну
         ветвь, не было бы ни проверено, ни положено в долг — и пять дописанных строк
         переводили бы запись в «проверено», не проиграв ничего. */
      добавить(&s->шаги_отложенные,
              fmt("теорема «%s»: шаг «%s» сверщик по существу не проигрывает, место на слове ядра",
                  имя_т, *обоснование ? обоснование : слово(ш, 2)));
      s->шагов_на_слово++;
      s->шагов_не_проигрываемых++;
    }
    if (где < 1) {
      сверить_терм_без_номера(s, ш, обоснование, имя_т, fmt("шаг %s", слово(ш, 2)));
      s->без_привязки++; continue;
    }
    /* Строка исходника читается ТАК ЖЕ, КАК ЕЁ ЧИТАЕТ ЯЗЫК, прежде чем искать в ней
       обоснование: иначе обоснование нашлось бы внутри хвостового примечания. */
    в_исх = без_то(как_читает_язык(строка_по_номеру(строки, где)));
    сверить_терм_и_номер(s, ш, начинается(в_исх, "затем ") ? слова_после(в_исх, 1) : в_исх,
                        где, имя_т, fmt("шаг %s", слово(ш, 2)));
    if (strcmp(вид, "промежуточный") == 0)
      если_не(s, начинается(в_исх, "затем ") && содержит(в_исх, обоснование),
              fmt("теорема «%s», строка %ld: запись зовёт шаг промежуточным и обоснованным «%s», а в исходнике стоит «%s» — промежуточный шаг пишется словом «затем»",
                  имя_т, где, обоснование, в_исх));
    else
      если_не(s, strcmp(в_исх, обоснование) == 0,
              fmt("теорема «%s», строка %ld: запись говорит «%s», а в исходнике написано «%s»",
                  имя_т, где, обоснование, в_исх));
  }
}

static long незакрытые_случаи(Сп свои) {
  int i, в_случае = 0, закрыт = 0; long долг = 0;
  for (i = 0; i < свои.n; i++) {
    char *s = обрезать(свои.e[i]);
    if (начинается(s, "случай строка")) {
      if (в_случае && !закрыт) долг++;
      в_случае = 1; закрыт = 0;
    } else if (начинается(s, "шаг ") && strcmp(шаг_вид(s), "закрывающий") == 0) закрыт = 1;
  }
  return (в_случае && !закрыт) ? долг + 1 : долг;
}

static void сверить_закрытие(Сверка *s, Сп свои, const char *имя_т, const char *вердикт) {
  Сп шаги = все_с_началом(свои, "шаг ");
  long закрыв = 0, случаев = все_с_началом(свои, "случай строка").n, нужно, незакр;
  char *qed = слово_после(первая_с_началом(свои, "следовательно доказано "), "доказано ");
  int i, доказано = strcmp(вердикт, "доказано") == 0;
  for (i = 0; i < шаги.n; i++) if (strcmp(шаг_вид(шаги.e[i]), "закрывающий") == 0) закрыв++;
  нужно = случаев > 0 ? случаев : 1;
  незакр = незакрытые_случаи(свои);
  если_не(s, !доказано || strcmp(qed, "да") == 0,
          fmt("теорема «%s»: вердикт «доказано», а «следовательно доказано» не стоит", имя_т));
  если_не(s, !доказано || закрыв >= нужно,
          fmt("теорема «%s»: закрывающих шагов %ld на %ld случаев — цель закрыта не везде, доказательство обрублено",
              имя_т, закрыв, случаев));
  если_не(s, !доказано || незакр == 0,
          fmt("теорема «%s»: случаев без закрывающего шага %ld — цель в них только обставлена промежуточными фактами, а не выведена",
              имя_т, незакр));
}

/* Список стережётся у ВСЯКОГО утверждения, а не только у того, при котором
   написана теорема: посылки с названным правилом ядро ставит и без теоремы. */
static void сверить_правила(Сверка *s, Сп свои, const char *о_чём) {
  Сп посылки = все_с_началом(свои, "посылка "), чужие = ПУСТО;
  int i, j, n = (int)(sizeof ПРАВИЛА / sizeof *ПРАВИЛА);
  for (i = 0; i < посылки.n; i++) {
    char *r = в_ёлочках(посылки.e[i], 3);
    for (j = 0; j < n; j++) if (strcmp(ПРАВИЛА[j], r) == 0) break;
    if (j == n) добавить(&чужие, r);
  }
  если_не(s, чужие.n == 0,
          fmt("%s: запись ссылается на правило сведения, которого сверщик не знает: %s",
              о_чём, соединить(чужие, ", ")));
}

/* Это УЧЁТ, а не ДОВОД: ни одна проверка ниже не выводит цель утверждения и
   потому не снимает его со слова ядра. Поверить ИМЕНИ правила значило бы
   поверить ядру на слово. Само место считается в `без_теоремы`, после всех
   приёмов: здесь ещё неизвестно, не снял ли его кто-то из них, а платить
   дважды нельзя. */
static void сверить_объявление(Сверка *s, Сп свои, const char *о_чём) {
  char *пр = первая_с_началом(свои, "правило «");
  char *по = первая_с_началом(свои, "по объявлению ");
  int i, n = (int)(sizeof ПРАВИЛА / sizeof *ПРАВИЛА);
  if (!*пр && !*по) return;
  если_не(s, *пр && *по,
          fmt("%s: «правило» и «по объявлению» печатаются парой, а здесь одна без другой",
              о_чём));
  if (*пр) {
    char *имя = в_ёлочках(пр, 1);
    for (i = 0; i < n; i++) if (strcmp(ПРАВИЛА[i], имя) == 0) break;
    если_не(s, i < n,
            fmt("%s: правило «%s» ядру неизвестно — такого имени оно в поле правила не ставит",
                о_чём, имя));
  }
  если_не(s, все_с_началом(свои, "посылка ").n == 0,
          fmt("%s: вердикт по объявлению стоит рядом с посылками, а этот маршрут их не даёт",
              о_чём));
  если_не(s, !*первая_с_началом(свои, "принцип тип "),
          fmt("%s: вердикт по объявлению стоит рядом с принципом, а этот маршрут его не даёт",
              о_чём));
}

/* Посылка в долге, если её правило названо, а ходов под нею нет ни одного.
   `ход конец` ходом НЕ считается: иначе подделка дописывает эту строку под каждую
   посылку и выходит по долгу лучше честной записи. */
/* Имя-приёмник необязателен: NULL значит «сосчитай, но молчи». Зовущих двое —
   один кладёт долг на слово ядра и обязан его назвать, другой тем же счётом
   считает места, УЖЕ СНЯТЫЕ узлом, и называть их значило бы соврать наоборот. */
static void назвать_посылку(Сверка *св, const char *имя, const char *строка) {
  if (!св) return;
  добавить(&св->не_взялся,
          fmt("утверждение «%s»: посылка «%s» сведена правилом «%s» и ни одного хода не записано — место на слове ядра",
              имя, в_ёлочках(строка, 1), в_ёлочках(строка, 3)));
}
static long посылки_на_слово_(Сп свои, Сверка *св, const char *имя) {
  int i, правило = 0, ходы = 0; long долг = 0; char *пред = (char *)"";
  /* ХОД СНИМАЕТ ДОЛГ ТОЛЬКО ТАМ, ГДЕ ХОД ПРОИГРЫВАЮТ. Движок ходов зовётся лишь из
     `сверить_теорему`; на дороге без теоремы «ход N …» не проверяет никто, и долг
     снимался бы за одно наличие строки — две дописанные строки с заведомо ложным
     ходом роняли бы число мест. У честных записей на этой дороге ходов нет ни одного. */
  int ходы_считаются = *первая_с_началом(свои, "теорема «") != 0;
  for (i = 0; i < свои.n; i++) {
    char *s = обрезать(свои.e[i]);
    if (начинается(s, "посылка ")) {
      if (правило && !ходы) { долг++; назвать_посылку(св, имя, пред); }
      /* ПУСТОЕ ПРАВИЛО У ПОСЫЛКИ, ЗАКРЫТОЙ СВЕДЕНИЕМ, — ТОЖЕ ДОЛГ. Пустое правило
         законно ровно у посылки, закрытой ШАГАМИ АВТОРА: за нею стоят шаги исходника,
         и их сверяют порознь. У `закрыта reduction` шагов автора нет по определению —
         стирание имени правила иначе снимало бы долг молча. */
      правило = *в_ёлочках(s, 3) != 0 ||
                strcmp(слово_после(s, "закрыта "), "reduction") == 0;
      ходы = 0; пред = s;
    } else if (ходы_считаются && начинается(s, "ход ") && strcmp(s, "ход конец") != 0) ходы = 1;
  }
  if (правило && !ходы) { назвать_посылку(св, имя, пред); return долг + 1; }
  return долг;
}
static long посылки_на_слово(Сп свои) { return посылки_на_слово_(свои, NULL, NULL); }

/* Нужно там, где имя переменной индукции сверить больше не с чем: у утверждения
   без теоремы строки «индукция по» в записи нет. */
/* Имя ДОВОДА стоит ДО двоеточия, имя ТИПА — после. Поиск слова по всей строке
   отдавал бы доводом и «н», и «нат», и запись могла бы объявить индукцию по имени
   ТИПА, которого переменной не существует. Строка читается так, как её читает язык. */
static int довод_функции(Сп строки, const char *место, const char *имя) {
  int i, внутри = 0;
  for (i = 0; i < строки.n; i++) {
    char *сырая = строки.e[i], *l = обрезать(сырая);
    if (начинается(сырая, "функция «") || начинается(сырая, "тотальная функция «")) внутри = 1;
    else if (внутри && начинается(l, "принимает ")) {
      Сп доводы = разделить(слова_после(как_читает_язык(l), 1), ",");
      int k;
      for (k = 0; k < доводы.n; k++) {
        const char *двоеточие = strstr(доводы.e[k], ":");
        char *названо = двоеточие ? копия(доводы.e[k], (size_t)(двоеточие - доводы.e[k]))
                                   : доводы.e[k];
        if (strcmp(голо(названо), имя) == 0) return 1;
      }
    }
    if (strcmp(l, место) == 0) return 0;
  }
  return 0;
}
static char *тип_довода_у_места(Сп строки, const char *место, const char *имя) {
  int i, внутри = 0; char *т = (char *)"";
  if (строка_высказывания(строки, место))     /* К3b: тип — из связывания утверждения */
    return из_высказывания(строки, строка_высказывания(строки, место), имя, NULL);
  for (i = 0; i < строки.n; i++) {
    char *сырая = строки.e[i], *l = обрезать(без_примечания(сырая));
    if (начинается(сырая, "функция «") || начинается(сырая, "тотальная функция «")) { внутри = 1; т = (char *)""; }
    else if (внутри && начинается(l, "принимает ")) т = тип_довода_в_строке(l, имя);
    if (strcmp(l, место) == 0) return т;
  }
  return (char *)"";
}
/* «Не берусь» здесь ДВУХ РАЗНЫХ ПОРОД, и это не одно и то же. Узел ВНЕ ПРИЁМА
   (другой носитель, другое правило, другая цель) считается ЧИСЛОМ: приём за него
   не брался. Узел, за который приём ВЗЯЛСЯ и не смог, называется ПОИМЁННО.
   А расхождение прочитанного с записанным — «НЕ СОШЛОСЬ». */

static int неотрицателен(const char *t, const char *по, int по_нат) {
  double v;
  if (число_точно(t, &v)) return v >= 0;
  return по_нат && strcmp(t, по) == 0;
}

/* Тип довода читается ИЗ ИСХОДНИКА, а не берётся из записи: на этом объявлении
   и стоит неотрицательность самого довода. */
static int довод_с_дном(Сп строки, long a, long b, const char *имя) {
  long i;
  for (i = a; i < b; i++) {
    char *т = тип_довода_в_строке(как_читает_язык(часть(строки, i)), имя);
    if (*т) return strcmp(объявление_типа(строки, имя_типа(т)).вид, "отрезок") == 0;
  }
  return 0;
}

static const char *ветвь_дна(const char *условие, const char *по) {
  static const char *отн[] = { "не больше ", "не меньше ", "больше ", "меньше ", "равно " };
  static const char *где[] = { "то",         "иначе",      "иначе",   "то",      "то" };
  char *хвост; double v; int k;
  if (strcmp(слово(условие, 1), по) != 0) return "";
  хвост = слова_после(условие, 1);
  for (k = 0; k < 5; k++)
    if (начинается(хвост, отн[k]) && число_точно(хвост + strlen(отн[k]), &v)) return где[k];
  return "";
}

/* Довод индукции в ветви СПУСКА строго положителен: в неё вычисление попадает
   ровно тогда, когда условие дна ЛОЖНО, и это вторая половина той же формы, с
   которой прочитано дно. Форм из пяти годятся две, список закрыт:
     `по не больше К` — дно «то», спуск при `по больше К`, строго при К ≥ 0;
     `по меньше К`    — дно «то», спуск при `по не меньше К`, строго при К > 0.
   Прочие три (`не меньше`, `больше`, `равно`) нижней границы в спуске не дают
   вовсе. КОНЕЧНОСТЬ этим не даётся — её даёт объявленный тип-отрезок, и
   спрашивает её вызывающий отдельно. (Замер и довод — работник 7107.) */
static int по_строго_положителен(const char *условие, const char *по) {
  char *хвост; double v;
  if (strcmp(слово(условие, 1), по) != 0) return 0;
  хвост = слова_после(условие, 1);
  if (начинается(хвост, "не больше ") && число_точно(хвост + strlen("не больше "), &v))
    return v >= 0;
  if (начинается(хвост, "меньше ") && число_точно(хвост + strlen("меньше "), &v))
    return v > 0;
  return 0;
}

static int не_проигран(Сверка *s, const char *имя, char *почему) {
  добавить(&s->не_взялся, fmt("утверждение «%s»: узел вердикта не проигран — %s", имя, почему));
  return 0;
}

/* Тело функции читается ИЗ ИСХОДНИКА, записи тут не верят. Допущением индукции
   считается вызов «чья» ТОЛЬКО на имени, связанном этим же случаем: вызов с
   любыми доводами был бы верой в круг. Развёртка чужой плоской функции — ровно
   один шаг, глубже был бы второй вычислитель языка. Форма вне списка —
   «не взялся» с именем. */

static int неотрицательно_algebra(const char *т_сырой, const char *чья, Сп bound,
                                 Сп строки, int глубина, char **почему);
static char *тело_без_пуст(Сп строки, long a, long b);
static int разрез_выбора(const char *t, char **u, char **a, char **b);
static char *вариант_случая(const char *хвост);
static int половина_закрыта(const char *сырой, Сп строки, int делений, const char *конечен);
static int есть_связыватель(const char *t);
static int разрез_словом(const char *t, const char *чем, char **лево, char **право);
static int разрез_равенства(const char *t, char **лево, char **право);
static int тождество_случая(Сп строки, const char *чья, const char *цель,
                           const char *тип, const char *по, const char *тело,
                           const char *образец, Сп связанные, char **почему);
static int охраной_случая(Сп строки, const char *чья, const char *цель,
                         const char *по, const char *тело, const char *образец,
                         char **почему);
static int порядок_случая(Сп строки, const char *чья, const char *цель,
                         const char *тип, const char *по, const char *тело,
                         const char *образец, const char *хвост_образца,
                         Сп связанные, char **почему);
static int тождество_свёртки(Сп строки, const char *чья, const char *цель,
                            const char *тип, const char *по, const char *начало,
                            const char *накопитель, const char *элемент,
                            const char *виток, int это_шаг, char **почему);

/* Плоское тело: ни одного вызова внутри — вызов значил бы догонять ядро вглубь.
   Вторая форма — многострочное «если/то/иначе» без «пусть»: перенос строки
   значения не несёт, и склейка пробелом даёт тот же терм, каким его прочтёт язык.
   Принимается, только если склейка целиком читается как выбор. */
static char *плоское_тело(Сп строки, const char *функция) {
  static const char *ОБЪЯВЛЕНИЯ[10] = {
    "принимает ", "возвращает ", "обеспечивает ", "требует ", "для всех ",
    "пример «", "дано ", "ожидается ", "теорема «", "использует "
  };
  long a, b, i; char *тело, *склейка; Сп строки_тела = ПУСТО;
  a = блок_функции(строки, функция, &b);
  if (a < 1) return (char *)"";
  тело = тело_без_пуст(строки, a, b);
  if (*тело) return содержит(тело, "» от ") ? (char *)"" : тело;
  { int k; char *u, *aa, *bb;
    for (i = a + 1; i < b; i++) {
      char *l = как_читает_язык(часть(строки, i)); int объявление = 0;
      if (!*l) continue;
      for (k = 0; k < 10; k++) if (начинается(l, ОБЪЯВЛЕНИЯ[k])) объявление = 1;
      if (!объявление) добавить(&строки_тела, l);
    }
    склейка = соединить(строки_тела, " ");
    if (!*склейка) return (char *)"";
    тело = терм(склейка);
    if (!разрез_выбора(тело, &u, &aa, &bb)) return (char *)"";
  }
  return содержит(тело, "» от ") ? (char *)"" : тело;
}

static Сп имена_доводов_функции(Сп строки, const char *функция) {
  long a, b, i; Сп r = ПУСТО;
  a = блок_функции(строки, функция, &b);
  if (a < 1) return r;
  for (i = a; i < b; i++) {
    char *l = как_читает_язык(часть(строки, i));
    if (!начинается(l, "принимает ")) continue;
    { Сп доводы = разделить(слова_после(l, 1), ","); int k;
      for (k = 0; k < доводы.n; k++) {
        const char *дв = strstr(доводы.e[k], ":");
        char *названо = дв ? копия(доводы.e[k], (size_t)(дв - доводы.e[k])) : доводы.e[k];
        добавить(&r, голо(обрезать(названо)));
      } }
    return r;
  }
  return r;
}

/* Допущением считается вызов, о котором и говорит принцип: на месте ПЕРЕМЕННОЙ
   ИНДУКЦИИ — имя, связанное разбираемым случаем, прочие доводы — своими
   объявленными именами знак в знак; вызов с любыми доводами был бы верой в круг.
   «хвоста» выписано особо: это единственное встроенное имя со своим родительным. */
static Сп допущения_индукции(Сп строки, const char *чья, const char *по, Сп связанные) {
  Сп имена = имена_доводов_функции(строки, чья), r = ПУСТО;
  int i, k;
  for (i = 0; i < связанные.n; i++) {
    добавить(&r, ужать(терм(fmt("«%s» от %s", чья, связанные.e[i]))));
    if (strcmp(связанные.e[i], "хвост") == 0)
      добавить(&r, ужать(терм(fmt("«%s» от хвоста", чья))));
    if (имена.n < 2 || !*по) continue;
    { Сп доводы = ПУСТО; int нашлась = 0;
      for (k = 0; k < имена.n; k++)
        if (strcmp(имена.e[k], по) == 0) { добавить(&доводы, связанные.e[i]); нашлась = 1; }
        else добавить(&доводы, имена.e[k]);
      if (нашлась)
        добавить(&r, ужать(терм(fmt("«%s» от %s", чья, соединить(доводы, " и "))))); }
  }
  return r;
}

/* Развёртка ОДНОГО вызова чужой плоской функции: не своя (это было бы допущение
   индукции, а не развёртка), и число доводов обязано сойтись. `*взялся` — пробовал
   ли шаг вообще, отдельно от «сошлось»: по нему зовущий не затирает названную причину. */
static int развернуть_вызов(const char *t, const char *чья, Сп bound, Сп строки,
                           int глубина, char **почему, int *взялся) {
  char *имя_ф = в_ёлочках(t, 1), *хвост, *тело_х, *результат; Сп доводы, args; int i;
  *взялся = 0;
  if (!*имя_ф || !начинается(t, fmt("«%s» от ", имя_ф))) return 0;
  if (strcmp(имя_ф, чья) == 0) return 0;
  хвост = обрезать(хвост_после(t, fmt("«%s» от ", имя_ф)));
  тело_х = плоское_тело(строки, имя_ф);
  if (!*тело_х) return 0;
  доводы = имена_доводов_функции(строки, имя_ф);
  args = разделить_сверху(хвост, "и");
  if (доводы.n == 0 || доводы.n != args.n) return 0;
  *взялся = 1;
  результат = тело_х;
  for (i = 0; i < доводы.n; i++)
    результат = вставить_вместо(результат, доводы.e[i], терм(обрезать(args.e[i])));
  return неотрицательно_algebra(результат, чья, bound, строки, глубина + 1, почему);
}

static int шаг_счёта(const char *ш, const char *акк);
/* `глубина` — не от бесконечной рекурсии (терм строго мельчает, кроме одной
   развёртки, а её берут лишь у плоского тела), а порукой на всякий случай. */
static int неотрицательно_algebra(const char *т_сырой, const char *чья, Сп bound,
                                 Сп строки, int глубина, char **почему) {
  char *t = ужать(т_сырой); double v; Разрез sum; char *u, *a, *b; int i, взялся;
  if (глубина > 12) { *почему = fmt("глубина разбора терма «%s» больше 12 — не берусь", t); return 0; }
  if (число_точно(t, &v)) {
    if (v >= 0) return 1;
    *почему = fmt("лист «%s» — отрицательное число", t); return 0;
  }
  /* Допущение индукции: список выписан ЦЕЛИКОМ вызывающим
     (`допущения_индукции`) и сличается знак в знак. Форма, которой в списке
     нет, допущением не считается — вера в круг тут стоила бы соундности. */
  for (i = 0; i < bound.n; i++) if (strcmp(t, bound.e[i]) == 0) return 1;
  /* ДОПУЩЕНИЕ ФУНКЦИИ — правило ядра Н2: в списке известного стоит «Т не меньше
     0», сличаемое знак в знак. Список этот у функции написан своей строкой
     `требует`, и язык её ПРИНУЖДАЕТ: вычислитель проверяет предусловие до
     входа и нарушенное прекращает вычисление отказом. Значит внутри тела
     допущение истинно, и читается оно из исходника, а не берётся на веру.
     Формы две и список закрыт: «Т не меньше К» и «Т больше К» при выписанном
     К не меньше нуля. */
  { long fa, fb, j;
    fa = блок_функции(строки, чья, &fb);
    if (fa >= 1)
      for (j = fa; j < fb; j++) {
        char *l = как_читает_язык(часть(строки, j)), *усл, *лев, *пр; double k;
        if (!начинается(l, "требует ")) continue;
        усл = обрезать(хвост_после(l, fmt("«%s» ", в_ёлочках(l, 1))));
        if (!*усл) continue;
        if (разрез_словом(усл, " не меньше ", &лев, &пр) &&
            число_точно(обрезать(пр), &k) && k >= 0 &&
            strcmp(ужать(терм(лев)), t) == 0) return 1;
        if (разрез_словом(усл, " больше ", &лев, &пр) &&
            число_точно(обрезать(пр), &k) && k >= 0 &&
            strcmp(ужать(терм(лев)), t) == 0) return 1;
      }
  }
  /* ВСТРОЕННАЯ МЕРА — правило ядра Н4 («Неотрицательная форма»,
     `flang/self/proof-kernel.flang`): длина чего бы то ни было есть число
     ячеек либо знаков, а их не бывает меньше нуля. Имя закрыто одним словом:
     `длина`. Это не вычисление — терм под мерой не считается и даже не
     читается, отвечает САМА ФОРМА. */
  if (начинается(t, "длина ")) return 1;
  /* СВЁРТКА-СЧЁТ — правило Н7 (страховка №2–5): «свёртка Л начиная с Н как А и Э →
     Ш» неотрицательна, если Н неотрицательно этой же грамматикой, А и Э — различные
     имена, а Ш — шаг счёта по форме (`шаг_счёта`: А, А плюс неотрицательный литерал
     или выбор из двух таких; условие не читается). Шаг не читает известного вовсе —
     значит и знание о пересвязанных именах в него не едет. Стоит РАНЬШЕ «если» и
     «плюс»: хвост свёртки тянется до конца терма, и «то А плюс 1 иначе А» внутри шага
     иначе раскололо бы саму свёртку. */
  if (начинается(t, "свёртка ")) {
    Разрез до_шага = разрез_по(t, "→"), до_имён = разрез_по(до_шага.лево, "как");
    Разрез нач = разрез_по(до_имён.лево, "начиная с"), имена = разрез_по(до_имён.право, "и");
    char *акк = ужать(имена.лево), *эл = ужать(имена.право);
    if (до_шага.есть && до_имён.есть && нач.есть && имена.есть && *акк && *эл && !содержит(акк, " ") &&
        !содержит(эл, " ") && strcmp(акк, эл) != 0 && шаг_счёта(до_шага.право, акк))
      return неотрицательно_algebra(нач.право, чья, bound, строки, глубина + 1, почему);
    *почему = fmt("свёртка «%s»: шаг не счёт по форме (Н7) — знак не держится", t);
    return 0;
  }
  /* «если» — ПЕРВОЙ, раньше «плюс»: скобки у обеих ветвей «если» держат
     баланс уже ДО собственного «плюс» внутри ветви (Ч369 не оборачивает
     ветви в скобки, только вызовы), и `разрез_по` считает исключительно
     скобки — она бы честно нашла «плюс» ветви и расколола терм НЕ по границе
     «если», а посередине одной из ветвей. Проверено прогоном: без этой
     очерёдности `corpus-tree-depth`/`corpus-tree-height` (обе — «Глубже» от
     двух вызовов внутри «если … то 1 плюс …» ) раскалывались посередине
     первой же ветви и не проигрывались вовсе. */
  if (разрез_выбора(t, &u, &a, &b))
    return неотрицательно_algebra(a, чья, bound, строки, глубина + 1, почему)
        && неотрицательно_algebra(b, чья, bound, строки, глубина + 1, почему);
  sum = разрез_по(t, "плюс");
  if (sum.есть)
    return неотрицательно_algebra(sum.лево, чья, bound, строки, глубина + 1, почему)
        && неотрицательно_algebra(sum.право, чья, bound, строки, глубина + 1, почему);
  /* ПРОИЗВЕДЕНИЕ НА ПОЛОЖИТЕЛЬНЫЙ ЛИТЕРАЛ — правило Н8, второй способ (замер
     запаса Lead-A, №1): один сомножитель — выписанное число в (0, 2⁵³−1], то
     есть не ноль и конечное (граница — К_ПРЕДСТ_ЧИСЛО ниже по файлу), другой
     неотрицателен этой же грамматикой. «0 умножить на +∞» так исключено: ноль
     сомножителем не берётся. Разрез — ПОСЛЕ «плюс»: произведение связывает
     теснее, и «А плюс Б умножить на 2» делится сперва по «плюс». */
  { Разрез пр = разрез_по(t, "умножить на"); char *другой = NULL;
    if (пр.есть) {
      if (число_точно(ужать(пр.право), &v) && v > 0 && v <= 9007199254740991.0) другой = пр.лево;
      else if (число_точно(ужать(пр.лево), &v) && v > 0 && v <= 9007199254740991.0) другой = пр.право;
      if (другой) return неотрицательно_algebra(другой, чья, bound, строки, глубина + 1, почему);
      *почему = fmt("произведение «%s»: ни один сомножитель не выписанное число больше нуля — «0 умножить на +∞» не исключено", t);
      return 0;
    } }
  if (развернуть_вызов(t, чья, bound, строки, глубина, почему, &взялся)) return 1;
  if (взялся) return 0;                /* причина уже названа внутри развёртки */
  *почему = fmt("форма «%s» сверщику незнакома", t);
  return 0;
}

static Сп bound_имена_случая(const char *хвост) {
  Сп r = ПУСТО;
  if (начинается(хвост, "голова")) {
    Сп ч = разделить_сверху(хвост, "и"); char *g, *x;
    if (ч.n != 2) return r;
    g = strcmp(обрезать(ч.e[0]), "голова") == 0
          ? (char *)"голова" : обрезать(хвост_после(обрезать(ч.e[0]), "голова "));
    x = strcmp(обрезать(ч.e[1]), "хвост") == 0
          ? (char *)"хвост" : обрезать(хвост_после(обрезать(ч.e[1]), "хвост "));
    if (*g) добавить(&r, g);
    if (*x) добавить(&r, x);
    return r;
  }
  if (strcmp(хвост, "пусто") == 0) return r;
  { char *после_с = справа_от(хвост, "с"); Сп части; int i;
    if (!*после_с) return r;
    части = разделить_сверху(после_с, "и");
    for (i = 0; i < части.n; i++) {
      char *им = обрезать(справа_от(части.e[i], "как"));
      if (*им) добавить(&r, им);
    } }
  return r;
}

/* В ветви разбора известно не только имя разбираемого, но и его СТРОЕНИЕ, и
   подставить конструктор образца в цель — ЧТЕНИЕ образца, а не догадка.
   Носитель, которого в закрытом списке нет, отдаёт пустую строку — «не берусь». */
static char *образец_как_терм(const char *хвост, const char *тип) {
  int строка = strcmp(тип, "строка") == 0;
  if (strcmp(хвост, "пусто") == 0) return строка ? (char *)"\"\"" : (char *)"пустой список";
  if (начинается(хвост, "голова")) {
    Сп ч = разделить_сверху(хвост, "и"); char *g, *x;
    if (ч.n != 2) return (char *)"";
    g = strcmp(обрезать(ч.e[0]), "голова") == 0
          ? (char *)"голова" : обрезать(хвост_после(обрезать(ч.e[0]), "голова "));
    x = strcmp(обрезать(ч.e[1]), "хвост") == 0
          ? (char *)"хвост" : обрезать(хвост_после(обрезать(ч.e[1]), "хвост "));
    if (!*g || !*x) return (char *)"";
    return строка ? fmt("соединить %s с %s", g, x) : fmt("приписать %s к %s", g, x);
  }
  if (начинается(хвост, "вариант «")) {
    char *им = в_ёлочках(хвост, 1), *после;
    if (!*им) return (char *)"";
    после = справа_от(хвост, "с");
    if (!*после) return fmt("вариант «%s»", им);
    { Сп части = разделить_сверху(после, "и"), поля = ПУСТО; int i;
      for (i = 0; i < части.n; i++) {
        char *поле = обрезать(копия(части.e[i], (size_t)(strstr(части.e[i], " как ")
                       ? (size_t)(strstr(части.e[i], " как ") - части.e[i]) : 0)));
        char *имя = обрезать(справа_от(части.e[i], "как"));
        if (!*поле || !*имя) return (char *)"";
        добавить(&поля, fmt("%s равным %s", поле, имя));
      }
      return fmt("вариант «%s» с %s", им, соединить(поля, " и ")); }
  }
  return (char *)"";
}

/* Случай ищется В ТЕЛЕ ФУНКЦИИ [a,b), не в теореме: слово `случай` стоит и там и там. */
static long найти_случай(Сп строки, long a, long b, const char *вариант) {
  long i;
  for (i = a; i < b; i++) {
    char *l = как_читает_язык(часть(строки, i));
    if (начинается(l, "случай ") && strcmp(вариант_случая(слова_после(l, 1)), вариант) == 0)
      return i;
  }
  return -1;
}

/* Скобки вокруг условия и ветвей ставятся ВСЕГДА: граница куска — перенос строки
   исходника, и без скобок соседний знак читался бы поперёк неё. Ни одна ветвь тут
   не выбирается и ни одно условие не считается — собирается ТЕРМ целиком, со всеми
   ветвями. Форма вне закрытого списка — пустая строка, то есть «не берусь». */
static char *собрать_тело_случая(Сп L, long i, long конец, int гл) {
  char *l, *имя, *знач, *ост, *у, *в_то, *в_иначе, *u, *a, *b;
  long j, k;
  if (гл <= 0 || i >= конец) return (char *)"";
  l = часть(L, i + 1);
  if (strcmp(l, "то") == 0 || strcmp(l, "иначе") == 0)
    return собрать_тело_случая(L, i + 1, конец, гл - 1);
  if (начинается(l, "то ")) l = обрезать(l + strlen("то "));
  else if (начинается(l, "иначе ")) l = обрезать(l + strlen("иначе "));
  if (начинается(l, "пусть ")) {
    имя = слово(l, 2); знач = слова_после(l, 3);
    if (strcmp(слово(l, 3), "равно") != 0) return (char *)"";
    if (!*имя || !*знач || содержит(имя, "(")) return (char *)"";
    ост = собрать_тело_случая(L, i + 1, конец, гл - 1);
    return *ост ? терм(вставить_вместо(ост, имя, терм(знач))) : (char *)"";
  }
  if (i + 1 == конец) return терм(l);
  if (!начинается(l, "если ")) return (char *)"";
  /* Пара `то`/`иначе` УЖЕ на этой строке, а строки ниже ещё есть — двух чтений
     у такого блока нет, и сверщик не выбирает между ними наугад. */
  if (разрез_выбора_цепочкой(терм(l), &u, &a, &b)) return (char *)"";
  у = обрезать(l + strlen("если "));
  for (j = i + 1; j < конец; j++) {
    char *z = часть(L, j + 1);
    if (strcmp(z, "то") == 0 || начинается(z, "то ")) break;
  }
  if (j >= конец) return (char *)"";
  for (k = j + 1; k < конец; k++) {
    char *z = часть(L, k + 1);
    if (strcmp(z, "иначе") == 0 || начинается(z, "иначе ")) break;
  }
  if (k >= конец) return (char *)"";
  в_то = собрать_тело_случая(L, j, k, гл - 1);
  в_иначе = собрать_тело_случая(L, k, конец, гл - 1);
  if (!*в_то || !*в_иначе || !*у) return (char *)"";
  return терм(fmt("если ( %s ) то ( %s ) иначе ( %s )", у, в_то, в_иначе));
}

/* Пустые строки не считаются: иначе однострочный случай с пустой строкой ПОСЛЕ
   читался бы как двухстрочный. */
static char *тело_случая(Сп строки, long ци, long конец_блока) {
  long i, край = конец_блока; Сп непраздные = ПУСТО;
  for (i = ци + 1; i < конец_блока; i++)
    if (начинается(как_читает_язык(часть(строки, i)), "случай ")) { край = i; break; }
  for (i = ци + 1; i < край; i++) {
    char *l = как_читает_язык(часть(строки, i));
    if (*l) добавить(&непраздные, l);
  }
  if (непраздные.n == 0 || непраздные.n > 5) return (char *)"";
  return собрать_тело_случая(непраздные, 0, непраздные.n, 8);
}

/* Правила, какими ядро сводит БУЛЕВУ цель случая (не `результат не меньше 0`).
   Список — подмножество закрытого `ПРАВИЛА`: ровно те, что суть булево замыкание,
   а его умеет `половина_закрыта`. Правило — фильтр «о том ли запись», а не довод:
   ложное правило лишь заведёт не ту ветку, а замыкание всё равно СОУНДНО (само
   ложную цель не закроет). Пустое правило сюда не входит — его посылка пропускается
   (сведена в другом месте), как и в ветке неотрицательности. */
static int булево_правило(const char *пр) {
  static const char *B[] = {
    "вычисление замкнутой цели", "разбор случаев по внутреннему условию цели",
    "цель-выбор с истинной ветвью", "равенство, решённое счётом замкнутых частей"
  };
  int k;
  for (k = 0; k < (int)(sizeof B / sizeof *B); k++) if (strcmp(пр, B[k]) == 0) return 1;
  return 0;
}

/* ДОМЕН ЦЕЛИ УЗЛА algebra — по какому из пяти доводов узел будет проигран.
   Тождество, порядок и охрана решаются ДО булева и ВМЕСТО него: булево замыкание
   зовёт вычислитель, а эти три переписываются законами и сличаются знак в знак. */
typedef struct { int неотр, тожд, пор, охр; } Домен;

/* У КАЖДОЙ названной посылки правило обязано быть одним из двух названных (второе
   имя необязательно). Посылка с ПУСТЫМ правилом не в счёт: она закрыта шагами
   автора и сведена в другом месте, а заваливать из-за неё узел значило бы
   отнимать снятое у соседней посылки, которая честно должна была закрыться. */
static int все_посылки_правилом(Сп посылки, const char *а, const char *б) {
  int i;
  for (i = 0; i < посылки.n; i++) {
    char *пр = в_ёлочках(посылки.e[i], 3);
    if (*пр && strcmp(пр, а) != 0 && (!б || strcmp(пр, б) != 0)) return 0;
  }
  return 1;
}

/* «Разбор цели по условию» стоит рядом с тождеством не по родству имён, а по делу:
   у ветви, чьё тело есть выбор, ядро делит цель на две половины и КАЖДУЮ закрывает
   тем же тождеством. */
static Домен домен_цели(const char *цель, Сп посылки) {
  Домен д; char *l0, *p0, *у0, *т0, *и0;
  д.тожд = д.пор = д.охр = 0;
  д.неотр = strcmp(цель, "результат не меньше 0") == 0;
  if (д.неотр) return д;
  д.тожд = разрез_равенства(терм(цель), &l0, &p0)
           && все_посылки_правилом(посылки, "тождество после переписки допущением", "разбор цели по условию");
  if (д.тожд) return д;
  д.пор = разрез_словом(терм(цель), " не больше ", &l0, &p0)
          && все_посылки_правилом(посылки, "ограниченность точным потолком по построению", "порядок по построению");
  if (д.пор) return д;
  д.охр = разрез_выбора_цепочкой(терм(цель), &у0, &т0, &и0) && strcmp(ужать(и0), "да") == 0
          && все_посылки_правилом(посылки, "разбор цели по условию", NULL);
  return д;
}

/* «Цель есть допущение» стоит рядом с неотрицательностью по той же причине, по
   какой «разбор цели по условию» стоит рядом с тождеством: ядро сводит им ту же
   цель ветви, только читает её из строки `требует`. */
static int правило_вне_домена(Домен д, const char *пр) {
  if (!*пр) return 0;
  if (д.неотр) return strcmp(пр, "неотрицательность по построению") != 0 &&
                      strcmp(пр, "цель есть допущение") != 0;
  if (д.тожд) return strcmp(пр, "тождество после переписки допущением") != 0 &&
                     strcmp(пр, "разбор цели по условию") != 0;
  if (д.пор) return strcmp(пр, "ограниченность точным потолком по построению") != 0 &&
                    strcmp(пр, "порядок по построению") != 0;
  if (д.охр) return strcmp(пр, "разбор цели по условию") != 0;
  return !булево_правило(пр);
}

static int проиграть_узел_algebra(Сверка *s, Сп строки, const char *имя,
                                 const char *чья, const char *цель, const char *принцип,
                                 Сп посылки) {
  char *тип = в_ёлочках(принцип, 1);
  Сп варианты_т = варианты_типа(строки, тип);
  Домен д;
  long a, b, i, проверено = 0;
  if (варианты_т.n == 0 || посылки.n != варианты_т.n) { s->узлов_мимо++; return 0; }
  д = домен_цели(цель, посылки);
  for (i = 0; i < посылки.n; i++)
    if (правило_вне_домена(д, в_ёлочках(посылки.e[i], 3))) { s->узлов_мимо++; return 0; }
  a = блок_функции(строки, чья, &b);
  if (a < 1) return 0;                   /* функции в исходнике нет — об этом скажет сверка имён */
  for (i = 0; i < посылки.n; i++) {
    char *rule = в_ёлочках(посылки.e[i], 3), *вариант, *тело, *почему = (char *)""; Сп bound; long ци;
    if (!*rule) continue;
    проверено++;
    вариант = в_ёлочках(посылки.e[i], 2);
    ци = найти_случай(строки, a, b, вариант);
    if (ци < 0)
      return не_проигран(s, имя, fmt("случай варианта «%s» не найден в теле функции «%s»", вариант, чья));
    тело = тело_случая(строки, ци, b);
    if (!*тело)
      return не_проигран(s, имя, fmt("тело случая «%s» не читается одним термом", вариант));
    if (д.неотр) {
      bound = допущения_индукции(строки, чья, в_ёлочках(принцип, 2),
                  bound_имена_случая(слова_после(как_читает_язык(часть(строки, ци)), 1)));
      if (!неотрицательно_algebra(тело, чья, bound, строки, 0, &почему))
        return не_проигран(s, имя, fmt("случай «%s»: %s", вариант, почему));
    } else if (д.тожд) {
      char *хв_сл = слова_после(как_читает_язык(часть(строки, ци)), 1);
      char *образец = образец_как_терм(хв_сл, тип);
      if (!*образец)
        return не_проигран(s, имя, fmt("образец случая «%s» сверщику незнаком", вариант));
      if (!тождество_случая(строки, чья, цель, тип, в_ёлочках(принцип, 2), тело,
                            образец, bound_имена_случая(хв_сл), &почему))
        return не_проигран(s, имя, fmt("случай «%s»: %s", вариант, почему));
    } else if (д.пор) {
      char *хв_сл = слова_после(как_читает_язык(часть(строки, ци)), 1);
      char *образец = образец_как_терм(хв_сл, тип);
      if (!*образец)
        return не_проигран(s, имя, fmt("образец случая «%s» сверщику незнаком", вариант));
      if (!порядок_случая(строки, чья, цель, тип, в_ёлочках(принцип, 2), тело,
                          образец, хв_сл, bound_имена_случая(хв_сл), &почему))
        return не_проигран(s, имя, fmt("случай «%s»: %s", вариант, почему));
    } else if (д.охр) {
      char *хв_сл = слова_после(как_читает_язык(часть(строки, ци)), 1);
      char *образец = образец_как_терм(хв_сл, тип);
      if (!*образец)
        return не_проигран(s, имя, fmt("образец случая «%s» сверщику незнаком", вариант));
      if (!охраной_случая(строки, чья, цель, в_ёлочках(принцип, 2), тело, образец, &почему))
        return не_проигран(s, имя, fmt("случай «%s»: %s", вариант, почему));
    } else {
      /* БУЛЕВА ЦЕЛЬ СЛУЧАЯ. Подставить тело случая вместо `результат` и замкнуть
         `половина_закрыта` — тем же булевым замыканием (да/нет, связки да/или/не,
         `равен`-тождество, замкнутый счёт), каким `разбором_цели` закрывает половины
         разбора цели по условию. Связыватель в теле (`свёртка`/`разбор`/…) замыканию
         не по зубам — честный отказ, а не догадка. Замыкание СОУНДНО: ложную цель
         оно не закроет, значит место лишь останется на слове ядра, не примется. */
      char *цель_сл = вставить_вместо(терм(цель), "результат", тело);
      if (есть_связыватель(цель_сл) || !половина_закрыта(цель_сл, строки, 0, NULL))
        return не_проигран(s, имя, fmt("случай «%s»: булева цель «%s» не замкнулась", вариант, цель_сл));
    }
  }
  /* ВАКУУМНЫЙ УСПЕХ НЕ ЗАСЧИТЫВАЕТСЯ: когда у ВСЕХ посылок правило пусто, цикл выше
     не прочёл ни одного случая, а «проигран» отпускал бы со слова ядра шаги
     «по предположению» этой теоремы. Нечего проверять — значит узел ВНЕ ПРИЁМА. */
  if (!проверено) { s->узлов_мимо++; return 0; }
  /* Булева ветка — замыкание `половина_закрыта`, то есть вычислитель; узел
     помечается, чтобы зовущий отнёс снятые им места в `узлов_булево_мест`. */
  if (!д.неотр && !д.тожд && !д.пор && !д.охр) s->узел_булев = 1;
  return 1;
}

/* Свёртка в flang ЛЕВАЯ, и принцип идёт по числу витков, а не по списку: допущение
   по списку говорило бы о свёртке хвоста при ТОМ ЖЕ начале, а заключение — при
   другом. Оттого читается ЗАГОЛОВОК свёртки, а не `разбор/случай`. Сворачиваемое
   обязано быть переменной принципа знак в знак; из имён витка доверен лишь накопитель. */
static int проиграть_узел_fold(Сверка *s, Сп строки, const char *имя,
                              const char *чья, const char *цель, const char *принцип,
                              Сп посылки) {
  char *по = в_ёлочках(принцип, 2), *тело, *голова, *что, *ост;
  char *начало, *связки, *накопитель, *элемент, *виток, *почему = (char *)"";
  Сп допущено = ПУСТО;
  long a, b; int i, проверено = 0;
  char *l0, *p0; int nonneg, тожд;
  if (посылки.n != 2 || !*по) { s->узлов_мимо++; return 0; }
  nonneg = strcmp(цель, "результат не меньше 0") == 0;
  тожд = !nonneg && разрез_равенства(терм(цель), &l0, &p0);
  for (i = 0; i < посылки.n; i++) {
    char *пр = в_ёлочках(посылки.e[i], 3);
    if (*пр && (nonneg ? strcmp(пр, "неотрицательность по построению") != 0
                       : тожд ? strcmp(пр, "тождество после переписки допущением") != 0
                              : 1))
      { s->узлов_мимо++; return 0; }
  }
  if (!nonneg && !тожд) { s->узлов_мимо++; return 0; }
  a = блок_функции(строки, чья, &b);
  if (a < 1) return 0;                   /* функции в исходнике нет — об этом скажет сверка имён */
  тело = тело_функции_текст(строки, a, b);
  if (!начинается(тело, "свёртка ")) { s->узлов_мимо++; return 0; }
  if (!разрез_словом(тело, " → ", &голова, &виток) ||
      !разрез_словом(обрезать(голова + strlen("свёртка ")), " начиная с ", &что, &ост) ||
      !разрез_словом(ост, " как ", &начало, &связки) ||
      !разрез_словом(связки, " и ", &накопитель, &элемент))
    return не_проигран(s, имя, (char *)"заголовок свёртки не читается четырьмя кусками");
  if (strcmp(обрезать(что), по) != 0)
    return не_проигран(s, имя, fmt("свёртка идёт по «%s», а принцип — по «%s»", обрезать(что), по));
  if (!*накопитель || !*элемент || strcmp(накопитель, элемент) == 0)
    return не_проигран(s, имя, (char *)"имена витка свёртки не различаются");
  добавить(&допущено, накопитель);
  for (i = 0; i < посылки.n; i++) {
    char *rule = в_ёлочках(посылки.e[i], 3);
    int это_шаг = содержит(посылки.e[i], " вид step ");
    if (!*rule) continue;                /* уже не на слове ядра — проверять здесь нечего */
    проверено++;
    if (nonneg) {
      if (!неотрицательно_algebra(терм(это_шаг ? виток : начало), чья,
                                  это_шаг ? допущено : ПУСТО, строки, 0, &почему))
        return не_проигран(s, имя, fmt("%s свёртки: %s", это_шаг ? "виток" : "начало", почему));
    } else if (!тождество_свёртки(строки, чья, цель, в_ёлочках(принцип, 1), по,
                                  начало, накопитель, элемент, виток, это_шаг, &почему))
      return не_проигран(s, имя, fmt("%s свёртки: %s", это_шаг ? "виток" : "начало", почему));
  }
  /* ВАКУУМНЫЙ УСПЕХ НЕ ЗАСЧИТЫВАЕТСЯ — тот же довод, что у ветки `algebra`:
     нечего проверять значит вне приёма, а не проиграно. */
  if (!проверено) { s->узлов_мимо++; return 0; }
  return 1;
}

/* К3b: заголовок утверждения без функции, чьё доказательство сейчас
   переигрывается (`сверить_высказывание` ставит его на время переигрывания и
   снимает после). У постусловий — всегда NULL. */
static const char *МЕСТО_ВЫСКАЗЫВАНИЯ = NULL;
static int проиграть_узел_высказывания(Сверка *s, Сп строки, const char *имя,
                                       const char *цель, const char *принцип, Сп посылки);

static int проиграть_узел(Сверка *s, Сп свои, Сп строки, const char *имя,
                         const char *чья, const char *цель) {
  char *принцип = первая_с_началом(свои, "принцип тип ");
  Сп посылки = все_с_началом(свои, "посылка ");
  char *по = в_ёлочках(принцип, 2), *носитель = слово_после(принцип, "носитель ");
  char *усл = (char *)"", *в_то = (char *)"", *в_иначе = (char *)"";
  long шаг = номер_после(принцип, "шаг "), a, b, i, еслей = 0, н_то = 0, н_иначе = 0;
  const char *дно; char *т_дно, *т_спуск, *вызов; Разрез sum; int знаком = 0;
  int вне;
  s->узел_булев = 0;
  if (!*принцип) return 0;               /* «по объявленному типу»: узла в записи нет */
  /* К3b: УТВЕРЖДЕНИЕ СВОДИТСЯ К ПОСТУСЛОВИЮ ФУНКЦИИ, КОТОРУЮ ЗОВЁТ. Цель
     «для всех л: T, P(«F» от л)» — это постусловие P(результат) функции «F» над
     её доводом p, если у «F» довод ОДИН, тип его T знак в знак и л стоит в цели
     ТОЛЬКО вызовом «F» от л (иначе после замены л остался бы свободным). Тогда
     узел проигрывается как у постусловия: цель — P(результат), принцип — по «p».
     Не сошлось хоть одно условие — перевода нет, и узел, как прежде, остаётся на
     слове ядра. У постусловий МЕСТО_ВЫСКАЗЫВАНИЯ пусто, и ветка не исполняется. */
  if (МЕСТО_ВЫСКАЗЫВАНИЯ && *чья) {
    Доводы д = доводы_функции(строки, чья);
    char *т = терм(цель), *в1 = fmt("( «%s» от %s )", чья, по), *в2 = fmt("( «%s» от ( %s ) )", чья, по);
    char *ц2 = терм(заменить(заменить(т, в2, "результат"), в1, "результат"));
    char *тип_св = из_высказывания(строки, строка_высказывания(строки, МЕСТО_ВЫСКАЗЫВАНИЯ), по, NULL);
    if (д.голые.n == 1 && strcmp(ц2, т) != 0 && !есть_терм(т, "результат") && !есть_терм(ц2, по) &&
        *тип_св && strcmp(обрезать(д.типы.e[0]), тип_св) == 0) {
      цель = ц2;
      принцип = заменить(принцип, fmt("по «%s»", по), fmt("по «%s»", д.голые.e[0]));
      по = в_ёлочках(принцип, 2);
    }
  }
  /* Утверждение о своём типе, к постусловию НЕ сведённое (связанное имя под
     конструктором либо вызовов на нём несколько) — проигрывается по самому утверждению. */
  if (МЕСТО_ВЫСКАЗЫВАНИЯ && strcmp(носитель, "algebra") == 0 && !есть_терм(терм(цель), "результат"))
    return проиграть_узел_высказывания(s, строки, имя, цель, принцип, посылки);
  if (strcmp(носитель, "algebra") == 0)
    return проиграть_узел_algebra(s, строки, имя, чья, цель, принцип, посылки);
  if (strcmp(носитель, "fold") == 0)
    return проиграть_узел_fold(s, строки, имя, чья, цель, принцип, посылки);
  /* ВНЕ ПРИЁМА — не поломка: узел остаётся на слове ядра и считается числом. */
  вне = strcmp(носитель, "segment") != 0 || посылки.n != 2 || шаг < 1
        || strcmp(цель, "результат не меньше 0") != 0;
  /* ПУСТОЕ ПРАВИЛО ПОСЫЛКИ НЕ РОНЯЕТ УЗЕЛ: пусто оно ровно там, где автор закрыл
     базу СВОИМ шагом, — и ронять узел значило бы наказывать за подробное
     доказательство. Правило посылки — фильтр «понимаю ли, о чём запись», а не довод. */
  for (i = 0; !вне && i < посылки.n; i++) {
    char *пр = в_ёлочках(посылки.e[i], 3);
    if (*пр && strcmp(пр, "неотрицательность по построению") != 0) вне = 1;
  }
  if (вне) { s->узлов_мимо++; return 0; }
  a = блок_функции(строки, чья, &b);
  if (a < 1) return 0;                   /* функции в исходнике нет — об этом скажет сверка имён */
  for (i = a; i < b; i++) {
    char *z = как_читает_язык(часть(строки, i));
    if (начинается(z, "если ")) { еслей++; усл = хвост_после(z, "если "); }
    else if (начинается(z, "то ")) { н_то++; в_то = хвост_после(z, "то "); }
    else if (начинается(z, "иначе ")) { н_иначе++; в_иначе = хвост_после(z, "иначе "); }
  }
  if (еслей != 1 || н_то != 1 || н_иначе != 1)
    return не_проигран(s, имя, (char *)"тело функции — не одно «если» с одной парой ветвей");
  дно = ветвь_дна(усл, по);
  if (!*дно) return не_проигран(s, имя, fmt("форма условия «%s» сверщику незнакома", усл));
  т_дно   = терм(strcmp(дно, "то") == 0 ? в_то : в_иначе);
  т_спуск = терм(strcmp(дно, "то") == 0 ? в_иначе : в_то);
  if (!цель_держится(цель, т_дно, &знаком)) {
    если_не(s, !знаком, fmt("утверждение «%s»: дно даёт «%s», и цель «%s» на нём НЕ держится",
                            имя, т_дно, цель));
    return знаком ? 0 : не_проигран(s, имя, fmt("дно «%s» — не замкнутое число", т_дно));
  }
  вызов = терм(fmt("«%s» от ( %s минус %ld )", чья, по, шаг));
  sum = разрез_по(т_спуск, "плюс");
  { int нат = довод_с_дном(строки, a, b, по);
    Разрез про;
    if (sum.есть && strcmp(ужать(sum.право), вызов) == 0 && неотрицателен(ужать(sum.лево), по, нат)) return 1;
    if (sum.есть && strcmp(ужать(sum.лево), вызов) == 0 && неотрицателен(ужать(sum.право), по, нат)) return 1;
    /* ВТОРОЙ СЛУЧАЙ УМНОЖЕНИЯ, слово в слово тот же, каким его берёт ядро
       (`flang/self/proof-kernel.flang`, «Правило неотрицательности»): ОДИН
       сомножитель лежит в (0, конечное], и тогда второму хватает дна. Пара
       здесь ровно одна и список закрыт: довод индукции `по` — строго
       положителен фактом ветви спуска (выше) и конечен ОБЪЯВЛЕННЫМ отрезком
       `нат`, — и вызов на «по минус шаг», он же допущение индукции.
       Дна одного мало и здесь: `0 умножить на +∞` есть не-число, поэтому
       строгость и конечность спрашиваются ОБЕ, а не одна. */
    про = разрез_по(т_спуск, "умножить на");
    if (про.есть && нат && по_строго_положителен(усл, по)) {
      if (strcmp(ужать(про.право), вызов) == 0 && strcmp(ужать(про.лево), по) == 0) return 1;
      if (strcmp(ужать(про.лево), вызов) == 0 && strcmp(ужать(про.право), по) == 0) return 1; } }
  return не_проигран(s, имя, fmt("спуск «%s» — ни сумма неотрицательного по построению, ни произведение строго положительного довода индукции — с вызовом «%s»",
                                  т_спуск, вызов));
}


/* ТРИ ДВЕРИ СЛИЧЕНИЯ, И ЧЕТВЁРТОЙ НЕТ: знак в знак; перестановка двух операндов
   ОДНОГО узла; счёт замкнутых сторон. АССОЦИАТИВНОСТИ СРЕДИ НИХ НЕТ: в IEEE-754 она
   ложна, и потому перестановка берётся только там, где терм есть ровно один двоичный
   узел. Обе стороны замкнуты, посчитаны и разные — равенство ложно, «НЕ СОШЛОСЬ». */

/* Кавычки в терме чисты: внутри строкового литерала нет ни скобки, ни пробела,
   ни обратной косой. Довод простой: всё дальнейшее (`расставить`, `ужать`,
   `заменить`, счёт скобок) читает терм СТРОКОЙ и в кавычки не заглядывает.
   Литерал со скобкой сбил бы этот счёт МОЛЧА — а молчаливая ошибка тут дороже
   непроверенного места. */
static int кавычки_чисты(const char *t) {
  int v = 0; long i;
  for (i = 0; t[i]; i++) {
    if (t[i] == '"') { v = !v; continue; }
    if (v && (t[i] == '(' || t[i] == ')' || t[i] == ' ' || t[i] == '\\')) return 0;
  }
  return !v;
}

/* Знаки, которые сверщик умеет видеть на верхнем уровне терма. СПИСОК ЗАКРЫТ
   (правило Ч27), и закрыт не из скупости: терм, у которого таких знаков больше
   одного, читается только со СТАРШИНСТВОМ, а старшинства сверщик не знает. */
static const char *ЗНАКИ_ТЕРМА[] = {
  " умножить на ", " делить на ", " остаток от деления на ",
  " плюс ", " минус ", " и притом ", " или ",
  " содержит ", " начинается с ", " кончается на ",
  " не равен ", " равен ", " не меньше ", " не больше ", " меньше ", " больше "
};
#define ЗНАКОВ_ТЕРМА 16

/* Квадратная скобка — сразу «нет»: уровни считаются по круглым, и выписанный
   список сбил бы счёт. */
static int один_узел(const char *t, const char *знак, char **лево, char **право) {
  long где; int какое; char *l, *p;
  if (содержит(t, "[") || содержит(t, "]")) return 0;
  if (!найти_сверху(t, ЗНАКИ_ТЕРМА, ЗНАКОВ_ТЕРМА, &где, &какое)) return 0;
  if (strcmp(ЗНАКИ_ТЕРМА[какое], знак) != 0) return 0;
  l = обрезать(копия(t, (size_t)где));
  p = обрезать(t + где + strlen(знак));
  if (!*l || !*p) return 0;
  if (найти_сверху(l, ЗНАКИ_ТЕРМА, ЗНАКОВ_ТЕРМА, &где, &какое)) return 0;
  if (найти_сверху(p, ЗНАКИ_ТЕРМА, ЗНАКОВ_ТЕРМА, &где, &какое)) return 0;
  *лево = l; *право = p; return 1;
}

/* Разрез по названному слову верхнего уровня и ВНЕ КАВЫЧЕК, ровно надвое.
   Второе такое слово справа — отказ: у формы с двумя «к» одного чтения нет. */
static int разрез_словом(const char *t, const char *чем, char **лево, char **право) {
  const char *сп[1]; long где; int какое;
  сп[0] = чем;
  if (!найти_сверху(t, сп, 1, &где, &какое)) return 0;
  *лево = обрезать(копия(t, (size_t)где));
  *право = обрезать(t + где + strlen(чем));
  if (!**лево || !**право) return 0;
  if (найти_сверху(*право, сп, 1, &где, &какое)) return 0;
  return 1;
}

static Сп члены_списка(const char *t) {
  Сп r = ПУСТО; long i, нач = 1, кр = 0, кв = 0; int v = 0; long d = (long)strlen(t);
  if (d < 3 || t[0] != '[' || t[d - 1] != ']') return r;
  for (i = 1; i < d - 1; i++) {
    char c = t[i];
    /* Знак за «\» пропускается: иначе звено вида "\"" закрыло бы кавычку на своём же
       экранирующем знаке, и счёт запятых верхнего уровня разошёлся бы молча. */
    if (v) { if (c == '\\' && t[i + 1]) { i++; continue; } if (c == '"') v = 0; continue; }
    if (c == '"') v = 1;
    else if (c == '(') кр++;
    else if (c == ')') кр--;
    else if (c == '[') кв++;
    else if (c == ']') кв--;
    else if (c == ',' && кр == 0 && кв == 0) {
      добавить(&r, обрезать(копия(t + нач, (size_t)(i - нач)))); нач = i + 1;
    }
  }
  добавить(&r, обрезать(копия(t + нач, (size_t)(d - 1 - нач))));
  return r;
}

/* Переписка по закрытому списку законов. Терм незнакомой формы остаётся собой —
   и место остаётся на слове ядра; «почти подходит» тут не бывает. */
static char *свести_терм(const char *сырой, Сп строки, int гл) {
  char *t = ужать(обрезать(сырой)), *l, *p, *ном, *спис, *n, *сп2, *хв2;
  double v;
  if (гл <= 0) return t;
  if (начинается(t, "длина ")) {
    char *a = свести_терм(t + strlen("длина "), строки, гл - 1);
    if (разрез_словом(a, " к ", &l, &p) &&
        (начинается(l, "добавить ") || начинается(l, "приписать ")))
      return fmt("%s плюс 1",
                 в_скобки(свести_терм(fmt("длина %s", в_скобки(p)), строки, гл - 1)));
    if (разрез_словом(a, " с ", &l, &p) && начинается(l, "соединить "))
      return fmt("%s плюс %s",
                 в_скобки(свести_терм(fmt("длина %s", в_скобки(слова_после(l, 1))), строки, гл - 1)),
                 в_скобки(свести_терм(fmt("длина %s", в_скобки(p)), строки, гл - 1)));
    if (разрез_словом(a, " на ", &l, &p) && начинается(l, "разложить ") &&
        strcmp(p, "символы") == 0)
      return свести_терм(fmt("длина %s", в_скобки(слова_после(l, 1))), строки, гл - 1);
    if (разрез_словом(a, " как ", &l, &p) && начинается(l, "отобразить "))
      return свести_терм(fmt("длина %s", в_скобки(слова_после(l, 1))), строки, гл - 1);
    return fmt("длина %s", в_скобки(a));
  }
  if (начинается(t, "элемент ") &&
      разрез_словом(обрезать(t + strlen("элемент ")), " в ", &ном, &спис)) {
    Сп члены;
    n = свести_терм(ном, строки, гл - 1);
    сп2 = свести_терм(спис, строки, гл - 1);
    if (разрез_словом(сп2, " к ", &l, &p)) {
      хв2 = свести_терм(p, строки, гл - 1);
      if (начинается(l, "приписать ") && число_точно(n, &v) && v == (double)(long)v) {
        if ((long)v == 1) return свести_терм(слова_после(l, 1), строки, гл - 1);
        if ((long)v >= 2)
          return свести_терм(fmt("элемент %ld в %s", (long)v - 1, в_скобки(хв2)), строки, гл - 1);
      }
      if (начинается(l, "добавить ") &&
          (strcmp(n, fmt("( длина %s ) плюс 1", в_скобки(хв2))) == 0 ||
           strcmp(n, fmt("1 плюс ( длина %s )", в_скобки(хв2))) == 0))
        return свести_терм(слова_после(l, 1), строки, гл - 1);
    }
    члены = члены_списка(сп2);
    if (члены.n && число_точно(n, &v) && v == (double)(long)v &&
        (long)v >= 1 && (long)v <= члены.n)
      return свести_терм(часть(члены, (long)v), строки, гл - 1);
    return fmt("элемент %s в %s", в_скобки(n), в_скобки(сп2));
  }
  return t;
}

static char *развернуть_плоское_тело(const char *t, const char *чья, Сп строки);

/* Правила названы именами ведомости `flang/proof/tables/inference-rules.tsv` (пометы О2…О6,
   П1 ниже по коду). Прибавка у О5 и О6 обязана быть КОНЕЧНОЙ: при бесконечной сумма
   есть не-число и правило выводило бы ложь из истины. Меры читаются, а не считаются;
   ни `оценить_терм`, ни `половина_закрыта` здесь не зовутся — ветвь по условию
   не выбирается. */

typedef struct { Сп строки; const char *чья; const char *голова; } Порядок;

static char *свести_порядком(const char *t, Порядок *o, int гл) {
  char *s = свести_терм(t, o->строки, 8), *a, *b; int k;
  if (начинается(s, "длина ")) {
    char *под = ужать(обрезать(s + strlen("длина ")));
    Сп члены;
    if (strcmp(под, "\"\"") == 0 || strcmp(под, "пустой список") == 0) return (char *)"0";
    члены = члены_списка(под);
    if (члены.n) return fmt("%ld", члены.n);
    if (*o->голова && strcmp(под, o->голова) == 0) return (char *)"1";
    return s;
  }
  if (гл > 0)
    for (k = 0; k < ЗНАКОВ_ТЕРМА; k++)
      if (один_узел(s, ЗНАКИ_ТЕРМА[k], &a, &b)) {
        char *l = свести_порядком(a, o, гл - 1), *p = свести_порядком(b, o, гл - 1);
        double vl, vp;
        /* СЧЁТ ВЫПИСАННЫХ, и он один: сумма ДВУХ выписанных чисел — снова
           выписанное число. Это не запуск программы (ни имени, ни вызова, ни
           ветви под знаком нет), а та же арифметика над написанным, какой
           правило П1 сличает два литерала. Другого знака и другой формы этот
           счёт не берёт. */
        if (strcmp(ЗНАКИ_ТЕРМА[k], " плюс ") == 0 &&
            число_точно(l, &vl) && число_точно(p, &vp) &&
            vl == (double)(long)vl && vp == (double)(long)vp)
          return fmt("%ld", (long)vl + (long)vp);
        return обрезать(fmt("%s%s%s", в_скобки(l), ЗНАКИ_ТЕРМА[k], в_скобки(p)));
      }
  return s;
}

/* Прибавка правила О6: неотрицательна И КОНЕЧНА по одной своей форме. */
static int прибавка_снизу(const char *t) {
  char *u = ужать(t); double v;
  if (число_точно(u, &v)) return v >= 0;
  return начинается(u, "длина ");
}

/* ОБЩАЯ ПРИБАВКА ПРАВИЛА О5 обязана быть КОНЕЧНОЙ, и это не придирка: О5 двигает
   обе стороны разом, так что дна прибавке не нужно, — но при Г = +∞ и Ш = −∞ правая
   сторона есть не-число, и правило вывело бы ложь из истины (встречный пример
   проверен в `flang/proof/lean/Rules.lean`). Спрашивается форма терма, не контекст. */
static int прибавка_конечна(const char *t) {
  char *u = ужать(t); double v;
  return число_точно(u, &v) || начинается(u, "длина ");
}

static int не_больше_правилами(const char *сл, const char *сп, Порядок *o,
                              Сп ихл, Сп ихп, int гл) {
  char *L = свести_порядком(сл, o, 6), *P = свести_порядком(сп, o, 6);
  char *u, *a, *b, *a1, *a2, *b1, *b2, *почему = (char *)"";
  double vl, vp; int i;
  if (гл <= 0) return 0;
  if (strcmp(L, P) == 0) return 1;                          /* О2 «Одинаковы» */
  for (i = 0; i < ихл.n && i < ихп.n; i++)                  /* допущение индукции */
    if (strcmp(L, ихл.e[i]) == 0 && strcmp(P, ихп.e[i]) == 0) return 1;
  if (число_точно(L, &vl)) {
    if (число_точно(P, &vp)) return vl <= vp;               /* П1 */
    if (vl <= 0 && неотрицательно_algebra(P, o->чья, ПУСТО, o->строки, 0, &почему))
      return 1;                                             /* О4 */
  }
  if (разрез_выбора_цепочкой(L, &u, &a, &b))                /* О3 */
    return не_больше_правилами(a, P, o, ихл, ихп, гл - 1) &&
           не_больше_правилами(b, P, o, ихл, ихп, гл - 1);
  if (один_узел(L, " плюс ", &a1, &a2) && один_узел(P, " плюс ", &b1, &b2)) {
    char *ла[4], *ра[4], *лб[4], *рб[4]; int k;            /* О5, четыре сочетания */
    ла[0] = a1; ра[0] = b1; лб[0] = a2; рб[0] = b2;
    ла[1] = a2; ра[1] = b2; лб[1] = a1; рб[1] = b1;
    ла[2] = a1; ра[2] = b2; лб[2] = a2; рб[2] = b1;
    ла[3] = a2; ра[3] = b1; лб[3] = a1; рб[3] = b2;
    for (k = 0; k < 4; k++) {
      char *общая = свести_порядком(лб[k], o, 6);
      /* Совпадения прибавки знак в знак МАЛО: она обязана быть ещё и КОНЕЧНОЙ,
         иначе обе суммы суть не-число и правило ложно. См. «прибавка_конечна». */
      if (strcmp(общая, свести_порядком(рб[k], o, 6)) == 0 && прибавка_конечна(общая) &&
          не_больше_правилами(ла[k], ра[k], o, ихл, ихп, гл - 1)) return 1;
    }
  }
  if (один_узел(P, " плюс ", &b1, &b2)) {                    /* О6 */
    if (strcmp(L, свести_порядком(b1, o, 6)) == 0 && прибавка_снизу(b2)) return 1;
    if (strcmp(L, свести_порядком(b2, o, 6)) == 0 && прибавка_снизу(b1)) return 1;
  }
  return 0;
}

static int порядок_случая(Сп строки, const char *чья, const char *цель,
                         const char *тип, const char *по, const char *тело,
                         const char *образец, const char *хвост_образца,
                         Сп связанные, char **почему) {
  Порядок o; char *ц, *L, *P; Сп ихл = ПУСТО, ихп = ПУСТО; int i, k;
  o.строки = строки; o.чья = чья; o.голова = (char *)"";
  /* Головное имя случая берётся ТОЛЬКО у строки и ТОЛЬКО у образца
     `голова … и хвост …` — там, где ядро и читает свой «Факт длины знака». */
  if (strcmp(тип, "строка") == 0 && начинается(хвост_образца, "голова")) {
    Сп ч = разделить_сверху(хвост_образца, "и");
    if (ч.n == 2)
      o.голова = strcmp(обрезать(ч.e[0]), "голова") == 0
                   ? (char *)"голова" : обрезать(хвост_после(обрезать(ч.e[0]), "голова "));
  }
  ц = вставить_вместо(терм(цель), "результат", развернуть_плоское_тело(терм(тело), чья, строки));
  ц = вставить_вместо(ц, по, образец);
  if (!разрез_словом(ц, " не больше ", &L, &P)) {
    *почему = fmt("цель ветви «%s» — не «не больше»", ц); return 0; }
  for (i = 0; i < связанные.n; i++) {
    Сп один = ПУСТО, вызовы;
    добавить(&один, связанные.e[i]);
    вызовы = допущения_индукции(строки, чья, по, один);
    for (k = 0; k < вызовы.n; k++) {
      char *ih = вставить_вместо(терм(цель), "результат", вызовы.e[k]), *a, *b;
      ih = вставить_вместо(ih, по, связанные.e[i]);
      if (!разрез_словом(ih, " не больше ", &a, &b)) continue;
      добавить(&ихл, свести_порядком(a, &o, 6));
      добавить(&ихп, свести_порядком(b, &o, 6));
    }
  }
  if (не_больше_правилами(L, P, &o, ихл, ихп, 8)) return 1;
  *почему = fmt("«%s» не больше «%s» — правилами ядра не выводится",
                свести_порядком(L, &o, 6), свести_порядком(P, &o, 6));
  return 0;
}

/* Цель ветви собирается ДВУМЯ подстановками: `результат` ← тело ветви, переменная
   индукции ← конструктор образца — в ветви известно строение разбираемого.
   У свёртки образца нет, и инвариант усилен ПРОЙДЕННЫМ КУСКОМ (иначе на пустом
   списке он о начале ложен); имя пройденного занято исходником — сверщик не берётся. */

static int разрез_равенства(const char *t, char **лево, char **право) {
  return разрез_словом(t, " равен ", лево, право) ||
         разрез_словом(t, " равно ", лево, право);
}

/* Тело ветви ЦЕЛИКОМ — вызов чужой ПЛОСКОЙ функции: он разворачивается её
   объявлением, ровно один шаг, фактические доводы встают на места
   объявленных. Не своя функция (это было бы не развёртка, а круг) и не
   вглубь терма: развёртка под знаком означала бы второй вычислитель языка
   внутри сверщика. Развернуть нечем — тело остаётся собой. */
static char *развернуть_плоское_тело(const char *t, const char *чья, Сп строки) {
  char *им = в_ёлочках(t, 1), *хвост, *тело, *итог; Сп доводы, факты; int i;
  if (!*им || strcmp(им, чья) == 0) return (char *)t;
  if (!начинается(t, fmt("«%s» от ", им))) return (char *)t;
  хвост = обрезать(хвост_после(t, fmt("«%s» от ", им)));
  тело = плоское_тело(строки, им);
  if (!*тело) return (char *)t;
  доводы = имена_доводов_функции(строки, им);
  факты = разделить_сверху(хвост, "и");
  if (доводы.n == 0 || доводы.n != факты.n) return (char *)t;
  итог = тело;
  for (i = 0; i < доводы.n; i++)
    итог = вставить_вместо(итог, доводы.e[i], терм(обрезать(факты.e[i])));
  return итог;
}

/* Ветвь выбрана ОБЪЯВЛЕНИЕМ: на месте разбираемого довода стоит выписанный
   конструктор. Вызов с ИМЕНЕМ на месте разбираемого не разворачивается — это
   значило бы считать на неизвестном значении. Подстановка идёт в два прохода через
   метки `%п N %`: значение поля бывает термом с именем другого поля. Знака `%` в именах нет. */
static char *развернуть_вариантом(const char *t, const char *чья, Сп строки) {
  char *им, *довод, *вариант, *тело, *хв_сл; long a, b, i, ци, разборов = 0, k_р = -1;
  Сп доводы, args, поля_к = ПУСТО, имена_к = ПУСТО, поля_в = ПУСТО, знач_в = ПУСТО;
  char *ц = терм(t);
  им = в_ёлочках(ц, 1);
  if (!*им || strcmp(им, чья) == 0) return (char *)t;
  if (!начинается(ц, fmt("«%s» от ", им))) return (char *)t;
  a = блок_функции(строки, им, &b);
  if (a < 1) return (char *)t;
  доводы = имена_доводов_функции(строки, им);
  args = доводы_вызова(обрезать(хвост_после(ц, fmt("«%s» от ", им))));
  if (доводы.n == 0 || доводы.n != args.n) return (char *)t;
  for (i = a; i < b; i++) {
    char *l = как_читает_язык(часть(строки, i)); int k;
    if (!начинается(l, "разбор ")) continue;
    разборов++;
    for (k = 0; k < доводы.n; k++)
      if (strcmp(обрезать(слова_после(l, 1)), доводы.e[k]) == 0) k_р = k;
  }
  if (разборов != 1 || k_р < 0) return (char *)t;
  довод = ужать(обрезать(args.e[k_р]));
  if (!начинается(довод, "вариант «")) return (char *)t;
  вариант = в_ёлочках(довод, 1);
  if (!*вариант) return (char *)t;
  ци = найти_случай(строки, a, b, вариант);
  if (ци < 0) return (char *)t;
  тело = тело_случая(строки, ци, b);
  if (!*тело) return (char *)t;
  хв_сл = слова_после(как_читает_язык(часть(строки, ци)), 1);
  { char *после = справа_от(хв_сл, "с"); int k;
    if (*после) {
      Сп части = разделить_сверху(после, "и");
      for (k = 0; k < части.n; k++) {
        char *поле = обрезать(слева_от(части.e[k], "как"));
        char *имя  = обрезать(справа_от(части.e[k], "как"));
        if (!*поле || !*имя) return (char *)t;
        добавить(&поля_к, поле); добавить(&имена_к, имя);
      } } }
  { char *после = справа_от(довод, "с"); int k;
    if (*после) {
      Сп части = разделить_сверху(после, "и");
      for (k = 0; k < части.n; k++) {
        char *поле = обрезать(слева_от(части.e[k], "равным"));
        char *знач = обрезать(справа_от(части.e[k], "равным"));
        if (!*поле || !*знач) return (char *)t;
        добавить(&поля_в, поле); добавить(&знач_в, знач);
      } } }
  if (поля_к.n != поля_в.n) return (char *)t;
  { int k, j; Сп метки = ПУСТО, значения = ПУСТО;
    for (k = 0; k < поля_к.n; k++) {
      char *знач = NULL;
      for (j = 0; j < поля_в.n; j++)
        if (strcmp(поля_к.e[k], поля_в.e[j]) == 0) { знач = знач_в.e[j]; break; }
      if (!знач) return (char *)t;
      добавить(&метки, fmt("%%п%d%%", k)); добавить(&значения, терм(знач));
    }
    for (k = 0; k < имена_к.n; k++)
      тело = вставить_вместо(тело, имена_к.e[k], метки.e[k]);
    /* Прочие доводы — ПОСЛЕ имён образца (образец затеняет одноимённый довод) и
       тоже через метку: фактический довод сам может нести имя другого довода. */
    for (k = 0; k < доводы.n; k++) {
      if (k == k_р) continue;
      добавить(&метки, fmt("%%д%d%%", k)); добавить(&значения, терм(обрезать(args.e[k])));
      тело = вставить_вместо(тело, доводы.e[k], метки.e[метки.n - 1]);
    }
    for (k = 0; k < метки.n; k++)
      тело = вставить_вместо(тело, метки.e[k], значения.e[k]);
  }
  return терм(тело);
}

/* Развёртка по конструктору ВГЛУБЬ ТЕРМА: переписывается каждая скобочная группа,
   чей разбираемый довод выписан конструктором. Круга тут быть не может — конструктор
   съедается, а вызов с ИМЕНЕМ не разворачивается вовсе; предел шагов — порука. */
static char *развернуть_везде(const char *t, const char *чья, Сп строки) {
  char *r = терм(t); int шаг;
  for (шаг = 0; шаг < 24; шаг++) {
    char *р2 = развернуть_вариантом(r, чья, строки); const char *p; int менялось = 0;
    if (strcmp(р2, r) != 0) { r = терм(р2); continue; }
    for (p = strstr(r, "( «"); p && !менялось; p = strstr(p + 1, "( «")) {
      const char *q; long гл = 0;
      for (q = p; *q; q++) { if (*q == '(') гл++; else if (*q == ')' && --гл == 0) break; }
      if (!*q) break;
      { char *внутр = обрезать(копия(p + 1, (size_t)(q - p - 1)));
        char *н = развернуть_вариантом(внутр, чья, строки);
        if (strcmp(н, внутр) != 0) {
          r = терм(fmt("%s%s%s", копия(r, (size_t)(p - r)), в_скобки(н), q + 1)); менялось = 1; } }
    }
    if (!менялось) break;
  }
  return r;
}

static char *свести_допущением(const char *t, Порядок *o, Сп лево, Сп право) {
  char *r = свести_порядком(развернуть_везде(t, o->чья, o->строки), o, 6); int i;
  for (i = 0; i < лево.n && i < право.n; i++)
    if (*лево.e[i] && strcmp(лево.e[i], право.e[i]) != 0 && есть_терм(r, лево.e[i]))
      r = свести_порядком(вставить_вместо(r, лево.e[i], право.e[i]), o, 6);
  return r;
}

/* Выбор бывает не на верху стороны, а под знаком — `длина (если У то А иначе Б)`.
   Берётся первая скобочная группа, читающаяся как выбор целиком, и зовущий
   подставляет каждую ветвь порознь. Условие не смотрится: обе ветви обязаны сойтись. */
static int выбор_внутри(const char *t, char **цел, char **u, char **a, char **b) {
  const char *p = t;
  while ((p = strstr(p, "( если ")) != NULL) {
    const char *q; long глубина = 0; const char *конец = NULL;
    for (q = p; *q; q++) {
      if (*q == '(') глубина++;
      else if (*q == ')') { глубина--; if (глубина == 0) { конец = q; break; } }
    }
    if (!конец) return 0;
    { char *внутр = обрезать(копия(p + 1, (size_t)(конец - p - 1)));
      if (разрез_выбора_цепочкой(внутр, u, a, b)) { *цел = внутр; return 1; } }
    p++;
  }
  return 0;
}

static int равенство_правилами(const char *сл, const char *сп, Порядок *o,
                              Сп ихл, Сп ихп, int гл) {
  char *L = свести_допущением(сл, o, ихл, ихп), *P = свести_допущением(сп, o, ихл, ихп);
  char *u, *a, *b, *цел;
  if (strcmp(L, P) == 0) return 1;
  if (гл <= 0) return 0;
  if (разрез_выбора_цепочкой(L, &u, &a, &b))
    return равенство_правилами(a, P, o, ихл, ихп, гл - 1) &&
           равенство_правилами(b, P, o, ихл, ихп, гл - 1);
  if (разрез_выбора_цепочкой(P, &u, &a, &b))
    return равенство_правилами(L, a, o, ихл, ихп, гл - 1) &&
           равенство_правилами(L, b, o, ихл, ихп, гл - 1);
  if (выбор_внутри(L, &цел, &u, &a, &b))
    return равенство_правилами(вставить_вместо(L, цел, a), P, o, ихл, ихп, гл - 1) &&
           равенство_правилами(вставить_вместо(L, цел, b), P, o, ихл, ихп, гл - 1);
  if (выбор_внутри(P, &цел, &u, &a, &b))
    return равенство_правилами(L, вставить_вместо(P, цел, a), o, ихл, ихп, гл - 1) &&
           равенство_правилами(L, вставить_вместо(P, цел, b), o, ихл, ихп, гл - 1);
  return 0;
}

static int тождество_случая(Сп строки, const char *чья, const char *цель,
                           const char *тип, const char *по, const char *тело,
                           const char *образец, Сп связанные, char **почему) {
  Порядок o; char *ц, *L, *P; Сп лево = ПУСТО, право = ПУСТО; int i, k;
  (void)тип;
  o.строки = строки; o.чья = чья; o.голова = (char *)"";
  ц = вставить_вместо(терм(цель), "результат",
                      развернуть_плоское_тело(терм(тело), чья, строки));
  ц = вставить_вместо(ц, по, образец);
  if (!разрез_равенства(ц, &L, &P)) {
    *почему = fmt("цель ветви «%s» — не равенство", ц); return 0; }
  for (i = 0; i < связанные.n; i++) {
    Сп один = ПУСТО, вызовы;
    добавить(&один, связанные.e[i]);
    вызовы = допущения_индукции(строки, чья, по, один);
    for (k = 0; k < вызовы.n; k++) {
      char *ih = вставить_вместо(терм(цель), "результат", вызовы.e[k]), *a, *b;
      ih = вставить_вместо(ih, по, связанные.e[i]);
      if (!разрез_равенства(ih, &a, &b)) continue;
      добавить(&лево, свести_порядком(a, &o, 6));
      добавить(&право, свести_порядком(b, &o, 6));
    }
  }
  if (равенство_правилами(L, P, &o, лево, право, 4)) return 1;
  *почему = fmt("стороны «%s» и «%s» не сошлись знак в знак",
                свести_допущением(L, &o, лево, право),
                свести_допущением(P, &o, лево, право));
  return 0;
}

/* Постусловие под охраной обещает Ц, пока держится У, и ничего иначе (`иначе да`).
   В ветви разбора У разворачивается по конструктору образца и оказывается
   КОНЪЮНКЦИЕЙ, среди частей которой стоит сам Ц знак в знак: тогда цель верна при
   любом исходе У. Условие не считается ни разу — разрез конъюнкции и сличение. */
static int охраной_случая(Сп строки, const char *чья, const char *цель,
                         const char *по, const char *тело, const char *образец,
                         char **почему) {
  char *ц, *у, *в_то, *в_иначе, *развёрнуто; Сп части; int i;
  ц = вставить_вместо(терм(цель), "результат", терм(тело));
  ц = терм(вставить_вместо(ц, по, образец));
  if (!разрез_выбора_цепочкой(ц, &у, &в_то, &в_иначе)) {
    *почему = fmt("цель ветви «%s» — не охрана «если У то Ц иначе да»", ц); return 0; }
  if (strcmp(ужать(в_иначе), "да") != 0) {
    *почему = fmt("у охраны «%s» ветвь «иначе» не литерал «да»", ц); return 0; }
  if (strcmp(ужать(в_то), "да") == 0) return 1;
  развёрнуто = терм(развернуть_вариантом(ужать(у), чья, строки));
  части = разделить_сверху(развёрнуто, "и притом");
  for (i = 0; i < части.n; i++)
    if (strcmp(терм(части.e[i]), терм(в_то)) == 0) return 1;
  /* Обещанного среди конъюнктов нет, но Ц сама несёт выбор с ТЕМ ЖЕ условием: под
     охраной У это условие есть «да». Меняется ТОЛЬКО условие выбора знак в знак
     (`если У то`), а не всякое вхождение текста У: замена по пробельным краям нашла бы
     У и там, где оно не подтерм. Связыватель в Ц — отказ: под ним имя из У значит другое. */
  { char *вт = fmt(" %s ", терм(в_то)), *уу = терм(у);
    char *под = обрезать(заменить(заменить(вт, fmt(" если ( %s ) то ", уу), " если да то "),
                                   fmt(" если %s то ", уу), " если да то "));
    if (strcmp(под, обрезать(вт)) != 0 && !есть_связыватель(под) &&
        половина_закрыта(под, строки, 0, NULL)) return 1; }
  *почему = fmt("среди конъюнктов охраны «%s» нет обещанного «%s»", развёрнуто, терм(в_то));
  return 0;
}

static int тождество_свёртки(Сп строки, const char *чья, const char *цель,
                            const char *тип, const char *по, const char *начало,
                            const char *накопитель, const char *элемент,
                            const char *виток, int это_шаг, char **почему) {
  /* Имя пройденного куска — ОДНО СЛОВО нарочно: составное имя пришлось бы
     оборачивать скобками при каждой подстановке, и стороны расходились бы
     скобкой, а не смыслом. */
  static const char *ПРОЙДЕНО = "пройденное";
  Порядок o; char *ц, *L, *P; Сп лево = ПУСТО, право = ПУСТО;
  o.строки = строки; o.чья = чья; o.голова = (char *)"";
  if (strcmp(тип, "список") != 0) {
    *почему = fmt("носитель свёртки «%s» тождеству сверщику незнаком", тип); return 0; }
  if (есть_терм(терм(цель), ПРОЙДЕНО) || есть_терм(терм(виток), ПРОЙДЕНО) ||
      есть_терм(терм(начало), ПРОЙДЕНО)) {
    *почему = (char *)"имя пройденного куска занято исходником"; return 0; }
  if (!это_шаг) {
    ц = вставить_вместо(терм(цель), "результат", терм(начало));
    ц = вставить_вместо(ц, по, (char *)"пустой список");
  } else {
    char *ih, *a, *b;
    ц = вставить_вместо(терм(цель), "результат", терм(виток));
    ц = вставить_вместо(ц, по, fmt("добавить %s к %s", элемент, ПРОЙДЕНО));
    ih = вставить_вместо(терм(цель), "результат", накопитель);
    ih = вставить_вместо(ih, по, ПРОЙДЕНО);
    if (разрез_равенства(ih, &a, &b)) {
      добавить(&лево, свести_порядком(a, &o, 6));
      добавить(&право, свести_порядком(b, &o, 6));
    }
  }
  if (!разрез_равенства(ц, &L, &P)) {
    *почему = fmt("цель половины «%s» — не равенство", ц); return 0; }
  if (равенство_правилами(L, P, &o, лево, право, 4)) return 1;
  *почему = fmt("стороны «%s» и «%s» не сошлись знак в знак",
                свести_допущением(L, &o, лево, право),
                свести_допущением(P, &o, лево, право));
  return 0;
}

/* ПЕРЕПИСАТЬ ФОРМОЙ. Запись несёт ИМЯ закона; переигрыватель проверяет, что
   левая сторона той самой формы, и САМ пересобирает правую по закону — из
   записи её не берёт. Пересобранная разошлась с записанной — отказ. Закон
   применяется РОВНО РАЗ, без сведения подтермов. */
static int закон_формы_есть(const char *z) {
  return strcmp(z, "Мера прибавления") == 0 || strcmp(z, "Мера склейки") == 0 ||
         strcmp(z, "Мера разложения") == 0 || strcmp(z, "Мера построения") == 0 ||
         strcmp(z, "Развернуть элемент по номеру") == 0 ||
         strcmp(z, "Закон признака") == 0 || strcmp(z, "Вхождение в выписанный список") == 0 ||
         strcmp(z, "Склейка разложения") == 0 ||
         strcmp(z, "Склейка ассоциативна") == 0 || strcmp(z, "Пустая склейка слева") == 0 ||
         strcmp(z, "Пустая склейка справа") == 0;
}

/* Три закона склейки взяты аксиомами: определения у встроенной «соединить» в
   языке нет — разворачивать нечего, а индукция по строке без того же равенства
   не докажет. Отказ на стыке половин суррогатной пары у обеих сторон один и тот
   же, поэтому переписка его не создаёт и не прячет. */
static char *форма_склейкой(const char *лево, const char *закон) {
  char *t = терм(лево), *л, *п, *л2, *п2;
  if (!разрез_словом(t, " с ", &л, &п) || !начинается(л, "соединить ")) return 0;
  л = ужать(слова_после(л, 1)); п = ужать(п);
  if (strcmp(закон, "Пустая склейка слева") == 0) return strcmp(л, "\"\"") == 0 ? терм(п) : 0;
  if (strcmp(закон, "Пустая склейка справа") == 0) return strcmp(п, "\"\"") == 0 ? терм(л) : 0;
  if (!разрез_словом(л, " с ", &л2, &п2) || !начинается(л2, "соединить ")) return 0;
  return терм(fmt("соединить %s с ( соединить %s с %s )",
                  в_скобки(ужать(слова_после(л2, 1))), в_скобки(ужать(п2)), в_скобки(п)));
}

static int закон_признака(const char *внутри, char **out);

/* Члены выписанного списка не считаются, а сличаются термами знак в знак.
   Х не из списка — 0 «закон не подошёл», а не «нет»: ненайденный член ложью
   вхождения не является. */
static char *форма_вхождением(const char *лево) {
  char *t = терм(лево), *x; Разрез r = разрез_по(t, "содержит"); Сп члены; int i;
  if (!r.есть || разделить_сверху(t, "содержит").n != 2) return 0;
  члены = члены_списка(ужать(r.лево)); x = ужать(r.право);
  for (i = 0; i < члены.n; i++) if (strcmp(ужать(члены.e[i]), x) == 0) return (char *)"да";
  return 0;
}

/* Правая сторона собирается из левой: подтермы — как записаны, номер и границы
   списка сверщик считает сам, рекурсии по подтермам нет. */
static char *форма_элементом(const char *лево) {
  char *t = терм(лево), *ном, *спис, *l, *p; double v; Сп члены;
  if (!начинается(t, "элемент ")) return 0;
  if (!разрез_словом(ужать(обрезать(t + strlen("элемент "))), " в ", &ном, &спис)) return 0;
  ном = ужать(ном); спис = ужать(спис);   /* номер и список приезжают обёрнутыми в скобки подстановкой — снимаем внешнюю пару, как Д-путь снимает её у аргумента длины */
  if (разрез_словом(спис, " к ", &l, &p)) {
    if (начинается(l, "приписать ") && число_точно(ном, &v) && v == (double)(long)v) {
      if ((long)v == 1) return терм(слова_после(l, 1));
      if ((long)v >= 2) return терм(fmt("элемент %ld в %s", (long)v - 1, в_скобки(p)));
    }
    if (начинается(l, "добавить ") &&
        (strcmp(ном, fmt("( длина %s ) плюс 1", в_скобки(p))) == 0 ||
         strcmp(ном, fmt("1 плюс ( длина %s )", в_скобки(p))) == 0))
      return терм(слова_после(l, 1));
  }
  члены = члены_списка(спис);
  if (члены.n && число_точно(ном, &v) && v == (double)(long)v &&
      (long)v >= 1 && (long)v <= члены.n)
    return терм(часть(члены, (long)v));
  return 0;
}

static char *форма_законом(const char *лево, const char *закон) {
  char *t, *a, *l, *p;
  if (strcmp(закон, "Развернуть элемент по номеру") == 0) return форма_элементом(лево);
  if (strcmp(закон, "Закон признака") == 0)
    return закон_признака(терм(лево), &p) ? терм(p) : 0;
  if (strcmp(закон, "Вхождение в выписанный список") == 0) return форма_вхождением(лево);
  if (strcmp(закон, "Склейка разложения") == 0) {
    t = терм(лево);
    return (начинается(t, "соединить ") && разрез_словом(t + strlen("соединить "), " по ", &l, &p) &&
            strcmp(обрезать(p), "\"\"") == 0 && разрез_словом(ужать(обрезать(l)), " на ", &a, &p) &&
            начинается(a, "разложить ") && strcmp(обрезать(p), "символы") == 0)
           ? терм(слова_после(a, 1)) : 0;
  }
  if (начинается(закон, "Склейка ") || начинается(закон, "Пустая склейка ")) return форма_склейкой(лево, закон);
  t = терм(лево);
  if (!начинается(t, "длина ")) return 0;
  a = ужать(обрезать(t + strlen("длина ")));
  if (strcmp(закон, "Мера прибавления") == 0)
    return (разрез_словом(a, " к ", &l, &p) &&
            (начинается(l, "добавить ") || начинается(l, "приписать ")))
           ? терм(fmt("( длина %s ) плюс 1", в_скобки(p))) : 0;
  if (strcmp(закон, "Мера склейки") == 0)
    return (разрез_словом(a, " с ", &l, &p) && начинается(l, "соединить "))
           ? терм(fmt("( длина %s ) плюс ( длина %s )",
                      в_скобки(слова_после(l, 1)), в_скобки(p))) : 0;
  if (strcmp(закон, "Мера разложения") == 0)
    return (разрез_словом(a, " на ", &l, &p) && начинается(l, "разложить ") &&
            strcmp(p, "символы") == 0)
           ? терм(fmt("длина %s", в_скобки(слова_после(l, 1)))) : 0;
  if (strcmp(закон, "Мера построения") == 0)
    return (разрез_словом(a, " как ", &l, &p) && начинается(l, "отобразить "))
           ? терм(fmt("длина %s", в_скобки(слова_после(l, 1)))) : 0;
  return 0;
}

static void ход_переписки_формой(Прогон *p, const char *строка) {
  char *лево = терм(в_уголках(строка, 1)), *право = терм(в_уголках(строка, 2));
  /* Имя закона — ёлочки ПОСЛЕ слова «законом», а не первые в строке: сам терм
     несёт ёлочки (например `отобразить … как «Ф»`), и `в_ёлочках(строка,1)`
     схватил бы их, а не закон. */
  char *закон = в_ёлочках(хвост_после(строка, "законом "), 1), *собрано;
  if (strcmp(слово(строка, 4), "формой") != 0) {
    беда_прогона(p, fmt("ход «переписать %s» неизвестен: есть «переписать формой» и «переписать по свойству»", слово(строка, 4))); return; }
  if (!*право) {
    беда_прогона(p, fmt("переписать формой «%s»: вторым уголком ⟨…⟩ не стоит правая сторона", лево)); return; }
  if (!закон_формы_есть(закон)) {
    беда_прогона(p, fmt("переписать формой: закон «%s» не из списка Д1–Д5 / Э1–Э4 / признака (Мера прибавления / склейки / разложения / построения / Развернуть элемент по номеру / Закон признака / Вхождение в выписанный список / Склейка разложения / Склейка ассоциативна / Пустая склейка слева / справа)", закон)); return; }
  if (!есть_терм(первая_цель(p), лево)) {
    беда_прогона(p, fmt("переписать формой: в цели «%s» нет терма «%s»", первая_цель(p), лево)); return; }
  собрано = форма_законом(лево, закон);
  if (!собрано) {
    беда_прогона(p, fmt("переписать формой законом «%s»: левая сторона «%s» не той формы, какой закон требует", закон, лево)); return; }
  if (strcmp(собрано, право) != 0) {
    беда_прогона(p, fmt("переписать формой законом «%s»: правая пересобрана как «%s», а запись несёт «%s»", закон, собрано, право)); return; }
  одна_цель(p, терм(вставить_вместо(первая_цель(p), лево, право)));
}

/* Переписка по доказанному утверждению. Законность инстанции проверяет путь
   «факт по свойству»; здесь добавлено своё: у утверждения не должно быть
   «таких что» — ограничение снимается в одной точке, а переписка идёт по всем
   вхождениям; цель утверждения — равенство, ориентация слева направо. */
/* Правилом берётся только ГОЛОЕ равенство «Л равен П»: один узел `равен`/`равно`
   сверху, ни «не», ни связки, ни выбора над ним — иначе разрез по слову прочёл бы
   «А не равен Б» или «(А равен Б) или В» равенством. */
static int голое_равенство(const char *факт, char **л, char **п) {
  static const char *чужие[4] = { " или ", " и притом ", " то ", " иначе " };
  char *t = ужать(факт); long где; int какое, i;
  for (i = 0; i < 4; i++) if (найти_сверху(t, &чужие[i], 1, &где, &какое)) return 0;
  if (начинается(t, "не ") || начинается(t, "если ") || !разрез_равенства(t, л, п)) return 0;
  return !(strlen(*л) >= strlen(" не") && strcmp(*л + strlen(*л) - strlen(" не"), " не") == 0);
}

static void ход_переписки_свойством(Прогон *p, const char *строка, Обст *o) {
  char *имя = в_ёлочках(строка, 1), *лево = терм(в_уголках(строка, 1)), *право = терм(в_уголках(строка, 2)), *л, *п;
  long где = номер_после(строка, "строка "), k, было = p->ходов;
  if (!содержит(строка, " подстановка ") || !*право) {
    беда_прогона(p, fmt("переписать по свойству «%s»: нужны «строка M», ⟨Л⟩ = ⟨П⟩ и «подстановка»", имя)); return; }
  for (k = где + 1; k <= o->строки.n && начинается(часть(o->строки, k), " "); k++)
    if (содержит(часть(o->строки, k), " таких что ")) {
      беда_прогона(p, fmt("переписать по свойству «%s»: у утверждения есть «таких что» — ограничение снимается в точке, а переписка идёт по всем вхождениям; правилом оно не берётся", имя)); return; }
  ход_факта_свойством(p, строка, o);
  if (p->ходов == было) return;
  p->ходов = было;
  if (!голое_равенство(p->посл_факт, &л, &п)) {
    беда_прогона(p, fmt("переписать по свойству «%s»: цель утверждения «%s» — не голое равенство «Л равен П»", имя, p->посл_факт)); return; }
  p->посл_факт = (char *)"";
  if (strcmp(ужать(л), ужать(лево)) != 0 || strcmp(ужать(п), ужать(право)) != 0) {
    беда_прогона(p, fmt("переписать по свойству «%s»: запись несёт ⟨%s⟩ = ⟨%s⟩, а инстанция утверждения — ⟨%s⟩ = ⟨%s⟩",
                        имя, лево, право, ужать(л), ужать(п))); return; }
  if (!есть_терм(первая_цель(p), лево)) {
    беда_прогона(p, fmt("переписать по свойству «%s»: в цели «%s» нет терма «%s»", имя, первая_цель(p), лево)); return; }
  одна_цель(p, терм(вставить_вместо(первая_цель(p), лево, право)));
}

static int тождественны(const char *са, const char *сб, Сп строки, int гл) {
  static const char *СОСЕДИ[2] = { " плюс ", " умножить на " };
  char *a = свести_терм(са, строки, гл), *b = свести_терм(сб, строки, гл);
  char *a1, *a2, *b1, *b2; int k;
  if (strcmp(a, b) == 0) return 1;
  if (гл > 0)
    for (k = 0; k < 2; k++)
      if (один_узел(a, СОСЕДИ[k], &a1, &a2) && один_узел(b, СОСЕДИ[k], &b1, &b2)) {
        if (тождественны(a1, b1, строки, гл - 1) && тождественны(a2, b2, строки, гл - 1)) return 1;
        if (тождественны(a1, b2, строки, гл - 1) && тождественны(a2, b1, строки, гл - 1)) return 1;
      }
  { Знач за = оценить_терм(a, строки, НЕ_БЕРУСЬ, 0), зб = оценить_терм(b, строки, НЕ_БЕРУСЬ, 0);
    if (за.вид && за.вид == зб.вид && !мера_а_не_значение(за.вид))
      return равенство_текстом(за.вид) ? strcmp(за.s, зб.s) == 0 : за.ч == зб.ч; }
  return 0;
}

/* Обе стороны ЗАМКНУТЫ, посчитаны — и это РАЗНЫЕ значения. Тогда равенство
   ложно, а запись числит его доказанным: это противоречие, а не «не берусь».
   «Не число» сюда не пускается: с ним неравенство значений ещё не ложь. */
static int стороны_разошлись(const char *са, const char *сб, Сп строки) {
  Знач за = оценить_терм(свести_терм(са, строки, 8), строки, НЕ_БЕРУСЬ, 0);
  Знач зб = оценить_терм(свести_терм(сб, строки, 8), строки, НЕ_БЕРУСЬ, 0);
  if (!за.вид || за.вид != зб.вид) return 0;
  /* ЕДИНСТВЕННОЕ ИЗ ПЯТИ МЕСТ, ГДЕ `ч` У ВИДА-МЕРЫ ГОДИТСЯ, и потому здесь
     нет `мера_а_не_значение`. Вопрос тут не «равны ли», а «точно ли разные», и
     на него мера отвечает верно в обе стороны: разная длина — это заведомо
     разные строки (разошлись), равная — «не знаю», и функция отвечает 0, то
     есть «не разошлись», что и значит здесь «не берусь». Поставить отказ и
     сюда значило бы ослабить проверку без выигрыша в честности. */
  if (равенство_текстом(за.вид)) return strcmp(за.s, зб.s) != 0;
  if (за.ч != за.ч || зб.ч != зб.ч) return 0;
  return за.ч != зб.ч;
}

/* УЗЕЛ У УТВЕРЖДЕНИЯ О СВОЁМ ТИПЕ-СУММЕ. Тела у такого утверждения нет: цель
   случая и допущение индукции строятся из объявления типа — конструктор
   варианта на месте связанного имени, допущение на каждом рекурсивном поле.
   Домен один, тождество; вычислитель не зовётся, носитель — объявленная сумма. */
static int проиграть_узел_высказывания(Сверка *s, Сп строки, const char *имя,
                                       const char *цель, const char *принцип, Сп посылки) {
  char *тип = в_ёлочках(принцип, 1), *по = в_ёлочках(принцип, 2), *L0, *P0;
  Объявление об = объявление_типа(строки, тип);
  Порядок o; long i, проверено = 0;
  o.строки = строки; o.чья = (char *)""; o.голова = (char *)"";
  if (strcmp(об.вид, "сумма") != 0 || посылки.n != об.варианты.n || !разрез_равенства(терм(цель), &L0, &P0)) {
    s->узлов_мимо++; return 0; }
  for (i = 0; i < посылки.n; i++) {
    char *пр = в_ёлочках(посылки.e[i], 3);
    if (*пр && strcmp(пр, "тождество после переписки допущением") != 0) { s->узлов_мимо++; return 0; }
  }
  for (i = 0; i < посылки.n; i++) {
    char *вариант = в_ёлочках(посылки.e[i], 2), *объявлен, *конструктор, *ц, *L, *P, *почему;
    Сп поля = ПУСТО, лево = ПУСТО, право = ПУСТО; int k, свой = 0;
    if (!*в_ёлочках(посылки.e[i], 3)) continue;   /* закрыта шагами автора — сверена порознь */
    объявлен = строка_варианта_типа(строки, тип, вариант);
    if (!*объявлен) return не_проигран(s, имя, fmt("варианта «%s» у типа «%s» в исходнике нет", вариант, тип));
    проверено++;
    if (содержит(объявлен, "содержит ")) {
      Сп ч = разделить(справа_от(объявлен, "содержит"), ",");
      for (k = 0; k < ч.n; k++) {
        char *поле = обрезать(часть(разделить(ч.e[k], ":"), 1)), *т_поля = обрезать(часть(разделить(ч.e[k], ":"), 2));
        /* Метка поля в конструкторе цели (`с пред равным н`) — не имя; имя — прочие вхождения. */
        if (!*поле || есть_терм(заменить(fmt(" %s ", терм(цель)), fmt(" %s равным ", поле), " ~ "), поле))
          return не_проигран(s, имя, fmt("случай «%s»: имя поля «%s» занято целью утверждения — подставить конструктор нечем", вариант, поле));
        добавить(&поля, fmt("%s равным %s", поле, поле));
        if (strcmp(т_поля, fmt("«%s»", тип)) == 0) {
          char *ih = вставить_вместо(терм(цель), по, поле), *a, *b; свой++;
          if (разрез_равенства(ih, &a, &b)) { добавить(&лево, свести_порядком(a, &o, 6)); добавить(&право, свести_порядком(b, &o, 6)); }
        }
      }
    }
    конструктор = поля.n ? fmt("вариант «%s» с %s", вариант, соединить(поля, " и ")) : fmt("вариант «%s»", вариант);
    ц = вставить_вместо(терм(цель), по, конструктор);
    если_не(s, (свой > 0) == (strcmp(слово_после(посылки.e[i], "вид "), "step") == 0),
            fmt("утверждение «%s», посылка «%s»: у варианта %s поля типа «%s», а записана как «вид %s»",
                имя, вариант, свой ? "есть" : "нет", тип, слово_после(посылки.e[i], "вид ")));
    if (!разрез_равенства(ц, &L, &P)) return не_проигран(s, имя, fmt("случай «%s»: цель «%s» — не равенство", вариант, ц));
    if (равенство_правилами(L, P, &o, лево, право, 4)) continue;
    L = свести_допущением(L, &o, лево, право); P = свести_допущением(P, &o, лево, право);
    if (стороны_разошлись(L, P, строки)) {
      добавить(&s->беды, fmt("утверждение «%s», случай «%s»: обе стороны равенства замкнуты и посчитаны, и это РАЗНЫЕ значения — «%s» против «%s»", имя, вариант, L, P));
      s->переписок_поймано++; return 0; }
    почему = fmt("случай «%s»: стороны «%s» и «%s» не сошлись знак в знак", вариант, L, P);
    return не_проигран(s, имя, почему);
  }
  if (!проверено) { s->узлов_мимо++; return 0; }
  return 1;
}

static int есть_требования(Сп строки, long a, long b) {
  long i;
  for (i = a; i < b; i++)
    if (начинается(как_читает_язык(часть(строки, i)), "требует ")) return 1;
  return 0;
}

/* Список имён объявлений закрыт нарочно: незнакомая строка делает тело
   многострочным, а многострочное тело — отказ, а не догадка. */
static char *тело_одной_строкой(Сп строки, long a, long b) {
  static const char *ОБЪЯВЛЕНИЯ[10] = {
    "принимает ", "возвращает ", "обеспечивает ", "требует ", "для всех ",
    "пример «", "дано ", "ожидается ", "теорема «", "использует "
  };
  long i; int k, нашли = 0; char *тело = (char *)"";
  for (i = a + 1; i < b; i++) {
    char *l = как_читает_язык(часть(строки, i)); int объявление = 0;
    if (!*l) continue;
    for (k = 0; k < 10; k++) if (начинается(l, ОБЪЯВЛЕНИЯ[k])) объявление = 1;
    if (объявление) continue;
    нашли++; тело = l;
  }
  return нашли == 1 ? тело : (char *)"";
}

/* СТОРОЖ ЛОЖНОЙ ПЕРЕПИСКИ. Он ничего не доказывает и ни одного места со слова
   ядра не снимает — только обвиняет: 1, когда запись числит доказанным
   равенство, обе стороны которого замкнуты, посчитаны и РАЗНЫЕ; 0, когда
   сказать нечего. Доказывать цель счётом сторожу не положено. */
static int сторож_ложной_переписки(Сверка *s, Сп свои, Сп строки, const char *имя,
                                   const char *чья, const char *цель_сырая) {
  static const char *РАВНО[2] = { " не равен ", " равен " };
  char *цель, *тело, *лево, *право, *сл, *сп3;
  long a, b, где; int какое;
  /* Узел Ч363 — принцип с посылками — не этот приём. И посылок у ЭТОГО узла
     быть не может: он их не проигрывает, а стало быть и снять их со слова
     ядра не вправе; счёт снятого держится на этой строке. */
  if (*первая_с_началом(свои, "принцип тип ") || все_с_началом(свои, "посылка ").n) return 0;
  if (!*цель_сырая || !кавычки_чисты(цель_сырая)) return 0;
  цель = терм(цель_сырая);
  if (!найти_сверху(цель, РАВНО, 2, &где, &какое) || какое != 1) { s->переписок_мимо++; return 0; }
  лево  = обрезать(копия(цель, (size_t)где));
  право = обрезать(цель + где + strlen(РАВНО[1]));
  if (!*лево || !*право) { s->переписок_мимо++; return 0; }
  if (найти_сверху(право, РАВНО, 2, &где, &какое)) { s->переписок_мимо++; return 0; }
  a = блок_функции(строки, чья, &b);
  if (a < 1) return 0;                 /* функции в исходнике нет — скажет сверка имён */
  тело = тело_одной_строкой(строки, a, b);
  if (!*тело || !кавычки_чисты(тело)) { s->переписок_мимо++; return 0; }
  тело = терм(тело);
  сл  = вставить_вместо(лево,  "результат", тело);
  сп3 = вставить_вместо(право, "результат", тело);
  /* ЛОЖЬЮ «разные значения» становятся ТОЛЬКО у функции без «требует», и это не
     осторожность, а замер. Честная половина `flang/test/fixtures/
     poddelka-protivorechie.flang` требует разом `первое меньше второе` и
     `второе не больше первое`: такого входа нет, функция недостижима, и
     `1 равен 2` о ней ядро доказывает ПО ПРАВУ — истинно пусто. Без этой строки
     приём кричал «НЕ СОШЛОСЬ» на ЧЕСТНОЙ записи корпуса; поймано прогоном, а не
     рассуждением. Снятие места остаётся и под допущением: безусловное
     тождество влечёт условное, обратное неверно. */
  if (!есть_требования(строки, a, b) && стороны_разошлись(сл, сп3, строки)) {
    добавить(&s->беды,
            fmt("утверждение «%s»: обе стороны равенства замкнуты и посчитаны, "
                "и это РАЗНЫЕ значения — «%s» против «%s»", имя, сл, сп3));
    s->переписок_поймано++;
    return 1;
  }
  return 0;
}

/* РАЗБОР ЦЕЛИ ПО УСЛОВИЮ. Ход ничего не выводит: у признака ровно два значения,
   и цель совпадает либо с целью при «да», либо с целью при «нет». Терм со
   связывателем не берётся вовсе; связка и выбор разбираются только там, где
   границы частей названы скобками; незакрытая половина — «не берусь», а не
   «неправда». */

#define ПРЕДЕЛ_ВЕТВЛЕНИЯ 4

/* Связыватели: список закрыт и повторяет закрытый список ядра («Это
   связыватель», `flang/self/proof-kernel.flang`). Под связывателем у выражения
   нет ОДНОГО значения — `эл равно искомое` внутри свёртки означает своё на
   каждом элементе, — и заменять его нельзя. */
static int есть_связыватель(const char *t) {
  static const char *СВЯЗЬ[6] = {
    "пусть ", "разбор ", "свёртка ", "отобразить ", "отфильтровать ", "случай "
  };
  int k;
  for (k = 0; k < 6; k++)
    if (начинается(t, СВЯЗЬ[k]) || содержит(t, fmt(" %s", СВЯЗЬ[k]))) return 1;
  return 0;
}

/* Счёт вхождений на ВЕРХНЕМ уровне отличает один выбор от двух вложенных,
   написанных без скобок: второй читался бы догадкой о старшинстве. */
static long сколько_сверху(const char *t, const char *что) {
  const char *список[1]; const char *p = t; long где, n = 0; int какое;
  список[0] = что;
  while (найти_сверху(p, список, 1, &где, &какое)) { n++; p += где + strlen(что); }
  return n;
}

static int разрез_выбора(const char *t, char **u, char **a, char **b) {
  static const char *ТО_[1] = { " то " }, *ИНАЧЕ_[1] = { " иначе " };
  const char *h; long g1, g2; int k;
  if (!начинается(t, "если ")) return 0;
  h = t + strlen("если ");
  if (сколько_сверху(h, " то ") != 1 || сколько_сверху(h, " иначе ") != 1) return 0;
  if (!найти_сверху(h, ТО_, 1, &g1, &k)) return 0;
  if (!найти_сверху(h + g1 + strlen(" то "), ИНАЧЕ_, 1, &g2, &k)) return 0;
  *u = обрезать(копия(h, (size_t)g1));
  *a = обрезать(копия(h + g1 + strlen(" то "), (size_t)g2));
  *b = обрезать(h + g1 + strlen(" то ") + g2 + strlen(" иначе "));
  return **u && **a && **b;
}

/* ЦЕПОЧКА «иначе если» (задача 1573). `разрез_выбора` считает ` то ` и
   ` иначе ` по всему терму и на второй паре отказывается — нарочно, чтобы не
   выбирать наугад. Здесь пара ищется СЧЁТОМ ВЛОЖЕННОСТИ: закрывающее наш
   `если` — то ` иначе `, перед которым все вложенные `если` уже закрыты. На
   терме с одной парой ответ тот же, что и у `разрез_выбора`, и он спрашивается
   первым: разбор двух видов должен сходиться там, где оба берутся. */
static int разрез_выбора_цепочкой(const char *t, char **u, char **a, char **b) {
  static const char *ТО_[1] = { " то " };
  const char *h, *хв; long g1, i, гл = 0, откр = 0; int k, в_кав = 0;
  if (разрез_выбора(t, u, a, b)) return 1;
  if (!начинается(t, "если ")) return 0;
  h = t + strlen("если ");
  if (!найти_сверху(h, ТО_, 1, &g1, &k)) return 0;
  хв = h + g1 + strlen(ТО_[0]);
  if (начинается(хв, "если ")) откр++;
  for (i = 0; хв[i]; i++) {
    if (в_кав) { if (хв[i] == '\\' && хв[i + 1]) i++; else if (хв[i] == '"') в_кав = 0; continue; }
    if (хв[i] == '"') { в_кав = 1; continue; }
    if (хв[i] == '(') { гл++; continue; }
    if (хв[i] == ')') { гл--; continue; }
    if (гл != 0 || хв[i] != ' ') continue;
    if (начинается(хв + i, " если ")) { откр++; continue; }
    if (начинается(хв + i, " иначе ")) {
      if (откр > 0) { откр--; continue; }
      *u = обрезать(копия(h, (size_t)g1));
      *a = обрезать(копия(хв, (size_t)i));
      *b = обрезать(хв + i + strlen(" иначе "));
      return **u && **a && **b;
    }
  }
  return 0;
}

/* Терм, о старшинстве которого спрашивать не приходится: либо он обнят одной
   парой скобок целиком, либо он одно слово. Только такие части сверщик и
   разбирает по связкам — иначе он читал бы чужой разбор. */
static int простой(const char *t) {
  char *u = обрезать(t);
  return одна_пара(u) || !содержит(u, " ");
}

/* Условие берётся у ПЕРВОГО «если» — по нему делит цель ядро; по другому
   половины были бы не половинами этой цели. */
static int первое_условие(const char *t, char **u) {
  const char *список[1]; long i, где; int в_кав = 0, какое;
  список[0] = " то ";
  for (i = 0; t[i]; i++) {
    if (в_кав) { if (t[i] == '\\' && t[i + 1]) i++; else if (t[i] == '"') в_кав = 0; continue; }
    if (t[i] == '"') { в_кав = 1; continue; }
    if ((i == 0 || t[i - 1] == ' ') && начинается(t + i, "если ")) {
      const char *h = t + i + strlen("если ");
      if (!найти_сверху(h, список, 1, &где, &какое)) return 0;
      *u = без_внешних(копия(h, (size_t)где));
      return **u != 0;
    }
  }
  return 0;
}

/* ГДЕ УСЛОВИЕ МОЖНО ЗАМЕНИТЬ, И СПИСОК СОСЕДЕЙ ЗАКРЫТ. Тот же набор знаков
   бывает частью ДРУГОГО терма: «2 плюс н больше 0» читается как
   «(2 плюс н) больше 0», и заменить в нём «н больше 0» значило бы прочитать
   чужой разбор. Поэтому вхождение признаётся, только когда слева от него стоит
   начало терма, открывающая скобка или одно из пяти слов, а справа — конец
   терма, закрывающая скобка или одно из четырёх. Прочие вхождения того же
   текста пропускаются НЕТРОНУТЫМИ, и половина тогда просто не закроется. */
static int место_замены(const char *t, long i, size_t d) {
  static const char *СЛЕВА[7] = {
    "( ", "если ", " то ", " иначе ", " и притом ", " или ", "не "
  };
  static const char *СПРАВА[5] = { " )", " то ", " иначе ", " и притом ", " или " };
  int k, слева = (i == 0), справа = (t[i + (long)d] == 0);
  for (k = 0; k < 7 && !слева; k++) {
    size_t дл = strlen(СЛЕВА[k]);
    if ((size_t)i >= дл && strncmp(t + i - (long)дл, СЛЕВА[k], дл) == 0) слева = 1;
  }
  for (k = 0; k < 5 && !справа; k++)
    if (начинается(t + i + (long)d, СПРАВА[k])) справа = 1;
  return слева && справа;
}

/* Замена условия литералом признака во ВСЕХ признанных местах. Внутрь кавычек и
   внутрь «ёлочек» замена не заходит: там знаки значат себя, а не терм. */
static char *подставить_условие(const char *t, const char *u, const char *на, long *сколько) {
  size_t d = strlen(u); long i, нач = 0; int в_кав = 0, в_ёл = 0; Сп куски = ПУСТО;
  *сколько = 0;
  if (!d) return (char *)t;
  for (i = 0; t[i]; i++) {
    if (в_кав) { if (t[i] == '\\' && t[i + 1]) i++; else if (t[i] == '"') в_кав = 0; continue; }
    if (t[i] == '"') { в_кав = 1; continue; }
    if (начинается(t + i, "«")) { в_ёл++; i += (long)strlen("«") - 1; continue; }
    if (начинается(t + i, "»")) { if (в_ёл) в_ёл--; i += (long)strlen("»") - 1; continue; }
    if (в_ёл) continue;
    if (strncmp(t + i, u, d) == 0 && место_замены(t, i, d)) {
      добавить(&куски, копия(t + нач, (size_t)(i - нач)));
      добавить(&куски, копия(на, strlen(на)));
      нач = i + (long)d; i = нач - 1; (*сколько)++;
    }
  }
  добавить(&куски, копия(t + нач, strlen(t) - (size_t)нач));
  return соединить(куски, "");
}

/* Законы признака: список закрыт, и ни один из них не про числа и не про
   порядок — это подстановка значения в признак, и ничего сверх. Применяются
   к содержимому скобочной группы и только когда обе части просты: старшинства
   сверщик не знает. */
static int закон_признака(const char *внутри, char **out) {
  static const char *СВЯЗКИ[2] = { " и притом ", " или " };
  char *t = обрезать(внутри), *l, *p; long где; int какое;
  if (начинается(t, "не ") && простой(t + strlen("не "))) {
    char *v = без_внешних(t + strlen("не "));
    if (strcmp(v, "да") == 0)  { *out = (char *)"нет"; return 1; }
    if (strcmp(v, "нет") == 0) { *out = (char *)"да";  return 1; }
    return 0;
  }
  if (!найти_сверху(t, СВЯЗКИ, 2, &где, &какое)) return 0;
  if (сколько_сверху(t, СВЯЗКИ[какое]) != 1) return 0;
  l = копия(t, (size_t)где);
  p = t + где + strlen(СВЯЗКИ[какое]);
  if (!простой(l) || !простой(p)) return 0;
  l = без_внешних(l); p = без_внешних(p);
  if (какое == 0) {                                   /* и притом */
    if (strcmp(l, "да") == 0) { *out = p; return 1; }
    if (strcmp(p, "да") == 0) { *out = l; return 1; }
    if (strcmp(l, "нет") == 0 || strcmp(p, "нет") == 0) { *out = (char *)"нет"; return 1; }
    return 0;
  }
  if (strcmp(l, "нет") == 0) { *out = p; return 1; }   /* или */
  if (strcmp(p, "нет") == 0) { *out = l; return 1; }
  if (strcmp(l, "да") == 0 || strcmp(p, "да") == 0) { *out = (char *)"да"; return 1; }
  return 0;
}

/* Сворачивается только группа, ОБНЯТАЯ СКОБКАМИ ЦЕЛИКОМ: у неё конец ветви
   «иначе» назван закрывающей скобкой, а не старшинством. Выбор на самом верху
   терма разбирает `половина_закрыта` — там конец ветви есть конец строки. */
static char *сжать_выборы(const char *сырой) {
  char *t = обрезать(сырой); int раз;
  for (раз = 0; раз < 16; раз++) {
    long начала[32]; long i; int гл = 0, в_кав = 0, меняли = 0;
    for (i = 0; t[i] && !меняли; i++) {
      char *внутри, *u, *a, *b, *новое = NULL; long нач;
      if (в_кав) { if (t[i] == '\\' && t[i + 1]) i++; else if (t[i] == '"') в_кав = 0; continue; }
      if (t[i] == '"') { в_кав = 1; continue; }
      if (t[i] == '(') { if (гл < 32) начала[гл] = i; гл++; continue; }
      if (t[i] != ')') continue;
      гл--;
      if (гл < 0 || гл >= 32) break;
      нач = начала[гл];
      внутри = обрезать(копия(t + нач + 1, (size_t)(i - нач - 1)));
      if (разрез_выбора(внутри, &u, &a, &b)) {
        char *uu = без_внешних(u);
        if (strcmp(uu, "да") == 0)  новое = a;
        if (strcmp(uu, "нет") == 0) новое = b;
      }
      if (!новое && !закон_признака(внутри, &новое)) continue;
      t = fmt("%s( %s )%s", копия(t, (size_t)нач), новое, t + i + 1);
      меняли = 1;
    }
    if (!меняли) break;
  }
  return t;
}

/* Замкнутое значение с ТРЕМЯ добавками к общему счётчику сверщика: списочный
   литерал, выписанный прямо в терме (общий счётчик берёт списки только из
   оглавления печати), его мера и вхождение в него. Общий счётчик зовётся
   ПЕРВЫМ, и добавки трогаются лишь там, где он сказал «не берусь»: два ответа
   на один вопрос разошлись бы молча. Значений списочный литерал не разбирает —
   звенья сличаются как термы, ровно как в Ч87. */
static Знач знач_моё(const char *сырой, Сп строки, int гл) {
  char *t = без_внешних(сырой), *ls; long где; int какое;
  Знач z = оценить_терм(t, строки, НЕ_БЕРУСЬ, 0);
  if (z.вид || гл > 6) return z;
  { char *бп = без_пробелов_вне_кавычек(t); size_t d = strlen(бп);
    if (d >= 2 && *бп == '[' && бп[d - 1] == ']' && кавычки_чисты(t))
      return как_список(бп, члены_списка(t).n); }
  if (начинается(t, "длина ")) {
    Знач a = знач_моё(t + strlen("длина "), строки, гл + 1);
    return a.вид == 4 ? как_число(a.ч) : НЕ_БЕРУСЬ;
  }
  if (!найти_сверху(t, ОТНОШЕНИЯ, ОТНОШЕНИЙ, &где, &какое)) return НЕ_БЕРУСЬ;
  ls = копия(t, (size_t)где);
  { Знач a = знач_моё(ls, строки, гл + 1);
    Знач b = знач_моё(t + где + strlen(ОТНОШЕНИЯ[какое]), строки, гл + 1);
    if (!a.вид || !b.вид) return НЕ_БЕРУСЬ;
    if (какое == 0 && a.вид == 4) {                    /* вхождение в выписанный список */
      Сп члены = члены_списка(без_внешних(ls)); int i;
      for (i = 0; i < члены.n; i++) {
        Знач c = знач_моё(члены.e[i], строки, гл + 1);
        if (c.вид != b.вид || мера_а_не_значение(c.вид)) continue;
        if (равенство_текстом(c.вид) ? (strcmp(c.s, b.s) == 0) : (c.ч == b.ч))
          return как_признак(1);
      }
      return НЕ_БЕРУСЬ;                                 /* «звена не нашлось» — не ложь */
    }
    if (какое == 2 || какое == 3 || какое == ОТН_РАВНО) {   /* не равен / равен / равно */
      int равны;
      if (a.вид != b.вид || мера_а_не_значение(a.вид)) return НЕ_БЕРУСЬ;
      равны = равенство_текстом(a.вид) ? (strcmp(a.s, b.s) == 0) : (a.ч == b.ч);
      return как_признак(какое == 2 ? !равны : равны);
    }
    if (a.вид != 2 || b.вид != 2) return НЕ_БЕРУСЬ;
    switch (какое) {
      case 4: return как_признак(a.ч >= b.ч);
      case 5: return как_признак(a.ч <= b.ч);
      case 6: return как_признак(a.ч <  b.ч);
      case 7: return как_признак(a.ч >  b.ч);
      default: return НЕ_БЕРУСЬ;
    } }
}

/* «длина Т» неотрицательна ПО ОБЪЯВЛЕНИЮ встроенной формы: мера считает число
   звеньев списка либо число знаков строки, и не-числа среди её значений нет.
   Дверь одна и записана одной формой — «Т не меньше 0»; зеркальной записи
   «0 не больше Т» эта дверь не знает: её знает зеркало порядка, а второй ответ
   на тот же вопрос разошёлся бы с первым молча. */
static int мера_неотрицательна(const char *t, Сп строки) {
  static const char *НМ[1] = { " не меньше " };
  char *l, *p; long где; int какое;
  if (!найти_сверху(t, НМ, 1, &где, &какое)) return 0;
  l = без_внешних(копия(t, (size_t)где));
  p = без_внешних(t + где + strlen(" не меньше "));
  if (strcmp(p, "0") != 0) return 0;
  return начинается(без_внешних(свести_терм(l, строки, 4)), "длина ");
}

/* НАЧАЛО ПО ПОСТРОЕНИЮ. «соединить Л с Р» начинается с П, когда с П начинается
   Л: правый кусок дверь не смотрит и не вправе. Доводов два — тождество термов
   и, при обоих замкнутых, посимвольное сравнение посчитанных значений (П бывает
   лишь ГОЛОВОЙ литерала Л). Приставке ПЕРЕМЕННОЙ строки третьей двери нет. */
static int начало_по_построению(const char *t, Сп строки) {
  static const char *НС[1] = { " начинается с " };
  char *l, *p, *сл, *левый, *правый, *голова; long где; int какое;
  if (!найти_сверху(t, НС, 1, &где, &какое)) return 0;
  l = без_внешних(копия(t, (size_t)где));
  p = без_внешних(t + где + strlen(" начинается с "));
  if (strcmp(p, "\"\"") == 0) return 1;
  сл = без_внешних(l);
  if (!разрез_словом(сл, " с ", &левый, &правый)) return 0;
  if (!начинается(левый, "соединить ")) return 0;
  голова = слова_после(левый, 1);
  if (тождественны(голова, p, строки, 6)) return 1;
  { Знач зг = оценить_терм(голова, строки, НЕ_БЕРУСЬ, 0), зп = оценить_терм(p, строки, НЕ_БЕРУСЬ, 0);
    return зг.вид == 1 && зп.вид == 1 && начинается(зг.s, зп.s); }
}

static int половина_закрыта(const char *сырой, Сп строки, int делений,
                            const char *конечен);

/* Разделить цель по условию и закрыть ОБЕ половины. Замен обязано быть хоть
   одна и ПОРОВНУ в обеих половинах: разное число значило бы, что заменено не
   одно и то же место, а половины тогда — не половины этой цели. */
static int деление(const char *t, const char *u, Сп строки, int делений,
                   const char *конечен) {
  char *да, *нет; long n1, n2;
  if (делений >= ПРЕДЕЛ_ВЕТВЛЕНИЯ || есть_связыватель(t)) return 0;
  да  = подставить_условие(t, u, "да",  &n1);
  нет = подставить_условие(t, u, "нет", &n2);
  if (n1 < 1 || n1 != n2) return 0;
  return половина_закрыта(да, строки, делений + 1, конечен) &&
         половина_закрыта(нет, строки, делений + 1, конечен);
}

/* ОГОВОРКА О КОНЕЧНОСТИ. Цель вида `не ((Т минус Т) равен 0) или Ц` означает
   «Т конечно ⟹ Ц»: у конечного Т разность с собой равна нулю, значит левый
   дизъюнкт ложен и цель сводится к Ц; у «не числа» разность с собой нулю не
   равна, левый дизъюнкт истинен и цель верна сама по себе. Так это читает и
   ядро — правило описано его же словами в шапке
   `flang/test/fixtures/poddelka-ogovorka-o-konechnosti.flang`.

   Снятая оговорка даёт РОВНО ОДИН факт — конечность именно ЭТОГО терма — и
   ничего сверх; закрывать цель она не вправе. Отсюда обе строгости ниже:
   стороны `минус` обязаны быть тождественны (иначе это не «Т минус Т»), а
   правая сторона `равен` обязана быть литеральным нулём. */
static int оговорка_о_конечности(const char *t, Сп строки,
                                  char **терм_конечен, char **под_оговоркой) {
  static const char *ИЛИ[1]   = { " или " };
  static const char *РАВЕН[1] = { " равен " };
  static const char *МИНУС[1] = { " минус " };
  char *левый, *внутри, *слева, *справа, *m1, *m2; long где; int какое;
  if (!найти_сверху(t, ИЛИ, 1, &где, &какое)) return 0;
  левый = без_внешних(копия(t, (size_t)где));
  if (!начинается(левый, "не ")) return 0;
  внутри = без_внешних(левый + strlen("не "));
  if (!найти_сверху(внутри, РАВЕН, 1, &где, &какое)) return 0;
  слева  = без_внешних(копия(внутри, (size_t)где));
  справа = без_внешних(внутри + где + strlen(" равен "));
  if (strcmp(справа, "0") != 0) return 0;
  if (!найти_сверху(слева, МИНУС, 1, &где, &какое)) return 0;
  m1 = без_внешних(копия(слева, (size_t)где));
  m2 = без_внешних(слева + где + strlen(" минус "));
  if (!тождественны(m1, m2, строки, 0)) return 0;
  найти_сверху(t, ИЛИ, 1, &где, &какое);
  *терм_конечен = m1;
  *под_оговоркой = без_внешних(t + где + strlen(" или "));
  return 1;
}

/* КВАДРАТ КОНЕЧНОГО НЕОТРИЦАТЕЛЕН. Единственный факт, который здесь покупает
   снятая оговорка: точное `е·е` при конечном `е` неотрицательно, а округление
   к ближайшему знака не меняет.

   Четыре строгости — и все четыре сторожит подделка
   `poddelka-ogovorka-o-konechnosti`, где каждая пробита отдельной функцией:
     · оговорка обязана БЫТЬ (без неё правило FLANG_BOUND_ON_NAN отвергает
       файл, и закрывать тут нечего) — отсюда проверка `конечен`;
     · оговорка обязана быть О ТОМ ЖЕ терме, что возводится в квадрат:
       конечность «второго» о «х» не говорит ничего;
     · сомножители обязаны быть ТОЖДЕСТВЕННЫ: у произведения разных термов
       знак от конечности одного не зависит, и `1 · (−1)` это показывает;
     · граница обязана быть литеральным НУЛЁМ: `квадрат не меньше самого
       числа` ложно уже на 0,5. */
static int квадрат_под_оговоркой(const char *t, Сп строки, const char *конечен) {
  static const char *НМ[1]  = { " не меньше " };
  static const char *УМН[1] = { " умножить на " };
  char *l, *p, *e1, *e2; long где; int какое;
  if (!конечен) return 0;
  if (!найти_сверху(t, НМ, 1, &где, &какое)) return 0;
  l = без_внешних(копия(t, (size_t)где));
  p = без_внешних(t + где + strlen(" не меньше "));
  if (strcmp(p, "0") != 0) return 0;
  if (!найти_сверху(l, УМН, 1, &где, &какое)) return 0;
  e1 = без_внешних(копия(l, (size_t)где));
  e2 = без_внешних(l + где + strlen(" умножить на "));
  if (!тождественны(e1, e2, строки, 0)) return 0;
  return тождественны(e1, конечен, строки, 0);
}

/* ПОЛОВИНА ЗАКРЫТА? Список способов закрыт, и ни один из них не объявляет
   половину ЛОЖНОЙ: незакрытая половина значит «не берусь».
   Из отношений берётся РАВЕНСТВО и только оно: «равен» языка есть Object.is,
   и «Т равен Т» истинно даже на не-числе, а «Т не больше Т» — ложно; порядка в
   этом списке нет и не будет.
   Отрицание `не Х` закрывает определённая ЛОЖЬ замкнутого счёта, а НЕ то, что
   Х не закрылся: незакрытость и есть «не берусь», из неё не следует ничего. */
static int половина_закрыта(const char *сырой, Сп строки, int делений,
                            const char *конечен) {
  static const char *СВЯЗКИ[2] = { " и притом ", " или " };
  static const char *РАВНО[1] = { " равен " };
  char *t = без_внешних(сжать_выборы(без_внешних(сырой)));
  char *u, *a, *b, *l, *p; long где; int какое;
  Знач z;
  if (strcmp(t, "да") == 0) return 1;
  if (strcmp(t, "нет") == 0) return 0;
  if (разрез_выбора(t, &u, &a, &b)) {
    char *uu = без_внешних(u);
    if (strcmp(uu, "да") == 0)  return половина_закрыта(a, строки, делений, конечен);
    if (strcmp(uu, "нет") == 0) return половина_закрыта(b, строки, делений, конечен);
    return деление(t, uu, строки, делений, конечен);
  }
  z = знач_моё(t, строки, 0);
  if (z.вид == 3) return z.ч != 0;
  if (начинается(t, "не ")) {
    Знач v = знач_моё(t + strlen("не "), строки, 0);
    if (v.вид == 3 && v.ч == 0) return 1;
  }
  /* Оговорка о конечности снимается ДО общей связки: разбирать `не (…) или Ц`
     как обычную дизъюнкцию бесполезно — левая половина не закрыта (она ложна,
     а ложь этот список объявлять не вправе), правая без факта конечности тоже.
     Снятие даёт факт и передаёт его вглубь. */
  {
    char *тк, *под;
    if (оговорка_о_конечности(t, строки, &тк, &под))
      return половина_закрыта(под, строки, делений, тк);
  }
  if (квадрат_под_оговоркой(t, строки, конечен)) return 1;
  if (найти_сверху(t, СВЯЗКИ, 2, &где, &какое)) {
    l = копия(t, (size_t)где);
    p = t + где + strlen(СВЯЗКИ[какое]);
    if (простой(l) && простой(p)) {
      int эл = половина_закрыта(l, строки, делений, конечен);
      int эп = половина_закрыта(p, строки, делений, конечен);
      if (какое == 0 ? (эл && эп) : (эл || эп)) return 1;
    }
  }
  /* 3781: ГЛУБИНА 0, А НЕ 6, И ЭТО ГРАНИЦА, А НЕ НАСТРОЙКА. На глубине 6
     `тождественны` ПЕРЕПИСЫВАЕТ обе стороны законами закрытого списка
     (`свести_терм`) и меняет местами соседей одного узла — то есть ВЫВОДИТ
     равенство, а не считает его. Замерено: этой дверью закрывались цели со
     свободными именами (`(а плюс б) равен (б плюс а)`, `длина (добавить эл к
     элементы) равен ((длина элементы) плюс 1)`), то есть ∀-цели, доказанные
     счётом без единого записанного хода. Это тот же калькулятор Г7, что был в
     `перепиской`, и снимать его надо в обоих местах разом: снимешь в одном —
     работу немедленно подхватит другое (померено опытом expB).
     На глубине 0 остаётся ровно две двери, и обе не выводят: тождество ЗНАК В
     ЗНАК после сжатия пробелов и равенство ДВУХ ЗАМКНУТЫХ значений, которое
     считает `оценить_терм` (та же граница доверия, что у «по примеру»). */
  if (найти_сверху(t, РАВНО, 1, &где, &какое)) {
    l = копия(t, (size_t)где);
    p = t + где + strlen(" равен ");
    if (простой(l) && простой(p) && тождественны(l, p, строки, 0)) return 1;
  }
  if (мера_неотрицательна(t, строки)) return 1;
  if (начало_по_построению(t, строки)) return 1;
  if (первое_условие(t, &u)) return деление(t, u, строки, делений, конечен);
  return 0;
}

/* Тело функции ОДНИМ термом, `пусть` развёрнут подстановкой. Язык чист и
   тотален, поэтому `пусть имя равно значение` есть ровно подстановка значения
   вместо имени, а `пусть`, которым никто не пользуется, исчезает целиком — на
   этом стоит запись `binder-wall-map`: свёртка, в цель не входящая, цель ронять
   не должна. Подстановка идёт С КОНЦА: поздний `пусть` вправе звать раннее имя,
   ранний позднее — нет. Связывателей больше четырёх сверщик не разворачивает,
   имя обязано быть одним словом, и строка не-`пусть` до последней делает тело
   многострочным, то есть отказом, а не догадкой. */
static char *тело_без_пуст(Сп строки, long a, long b) {
  static const char *ОБЪЯВЛЕНИЯ[10] = {
    "принимает ", "возвращает ", "обеспечивает ", "требует ", "для всех ",
    "пример «", "дано ", "ожидается ", "теорема «", "использует "
  };
  Сп пусти = ПУСТО; long i; int k, продолжение = 0; char *тело = (char *)"";
  for (i = a + 1; i < b; i++) {
    char *l = как_читает_язык(часть(строки, i)); int объявление = 0;
    if (!*l) continue;
    /* 6432, Т1: случаи цели-разбора под `обеспечивает` — отступом глубже — часть цели, не тела */
    if (продолжение && начинается(часть(строки, i), "   ")) continue;
    продолжение = начинается(l, "обеспечивает ");
    for (k = 0; k < 10; k++) if (начинается(l, ОБЪЯВЛЕНИЯ[k])) объявление = 1;
    if (объявление) continue;
    if (*тело) добавить(&пусти, тело);
    тело = l;
  }
  if (!*тело || пусти.n > 4) return (char *)"";
  тело = терм(тело);
  for (i = пусти.n; i >= 1; i--) {
    char *l = часть(пусти, i), *имя = слово(l, 2), *знач = слова_после(l, 3);
    if (!начинается(l, "пусть ") || strcmp(слово(l, 3), "равно") != 0) return (char *)"";
    if (!*имя || !*знач || содержит(имя, "(")) return (char *)"";
    тело = вставить_вместо(тело, имя, терм(знач));
  }
  return тело;
}

/* ЦЕЛЬ СЛЕДУЕТ ИЗ ОБЪЯВЛЕННОГО О ДОВОДАХ. Довод берётся ИЗ ИСХОДНИКА — тем же
   `довод_типа`, каким его уже берёт спуск индукции, — и даёт РОВНО то, что
   объявление обещает, ничего сверх. Список закрыт: три случая, каждый сторожит
   своя проба.

   Строгости, и каждая нужна:
     · «плюс» с двумя `нат` даёт неотрицательность, а «минус» НЕ даёт — это
       называет сам корпус (`corpus-natural` против `corpus-natural-ceiling`),
       и сторожит проба `vychitanie-ne-sohranyaet`;
     · потолок даёт ТИП РЕЗУЛЬТАТА, а не тип доводов: замерено прогоном ядра —
       `возвращает число` при той же цели ЛОЖНО (код 1), `целое` и `нат` верны;
     · «не убывает» держится на типе ВТОРОГО слагаемого; первое может быть
       каким угодно `число` (`order`), поэтому требовать `нат` от обоих нельзя. */
static char *тип_возврата(Сп строки, long a, long b) {
  long i;
  for (i = a; i < b; i++) {
    char *l = как_читает_язык(часть(строки, i));
    if (!начинается(l, "возвращает ")) continue;
    return обрезать(хвост_после(l, "возвращает "));
  }
  return (char *)"";
}

static int нат_довод(Сп строки, long a, long b, const char *t) {
  return *t && довод_с_дном(строки, a, b, t);
}

static int из_объявленного(const char *сырой, Сп строки, long a, long b) {
  static const char *НМ[1]  = { " не меньше " };
  static const char *НБ[1]  = { " не больше " };
  static const char *ПЛ[1]  = { " плюс " };
  char *t = без_внешних(сырой), *тк = NULL, *под = NULL;
  char *лево, *право, *p1, *p2; long где; int какое;

  if (оговорка_о_конечности(t, строки, &тк, &под)) t = без_внешних(под);

  if (найти_сверху(t, НМ, 1, &где, &какое)) {
    лево  = без_внешних(копия(t, (size_t)где));
    право = без_внешних(t + где + strlen(" не меньше "));
    if (strcmp(право, "0") == 0 && найти_сверху(лево, ПЛ, 1, &где, &какое)) {
      p1 = без_внешних(копия(лево, (size_t)где));
      p2 = без_внешних(лево + где + strlen(" плюс "));
      if (нат_довод(строки, a, b, p1) && нат_довод(строки, a, b, p2)) return 1;
    }
    return 0;
  }

  if (!найти_сверху(t, НБ, 1, &где, &какое)) return 0;
  лево  = без_внешних(копия(t, (size_t)где));
  право = без_внешних(t + где + strlen(" не больше "));

  if (strcmp(право, "9007199254740991") == 0) {
    char *т = тип_возврата(строки, a, b);
    return strcmp(т, "целое") == 0 || натуральное_имя(т);
  }

  if (!найти_сверху(право, ПЛ, 1, &где, &какое)) return 0;
  p1 = без_внешних(копия(право, (size_t)где));
  p2 = без_внешних(право + где + strlen(" плюс "));
  if (тождественны(лево, p1, строки, 0) && нат_довод(строки, a, b, p2)) return 1;
  if (тождественны(лево, p2, строки, 0) && нат_довод(строки, a, b, p1)) return 1;
  return 0;
}

/* Разбор ОДНОЙ посылки на стороны и оператор. Список короче ОТНОШЕНИЯ —
   только пять сравнений, из которых складывается граница несовместимости
   ниже. Порядок хранит то же правило, что и там: длинное имя раньше
   короткого, чтобы «не меньше»/«не больше» не резались по «меньше»/«больше». */
static int разбор_сравнения(const char *t, char **l, int *op, char **p) {
  static const char *СРАВНЕНИЯ[5] = {
    " не меньше ", " не больше ", " равен ", " меньше ", " больше "
  };
  long где; int какое;
  if (!найти_сверху(t, СРАВНЕНИЯ, 5, &где, &какое)) return 0;
  *l = без_внешних(копия(t, (size_t)где));
  *p = без_внешних(t + где + strlen(СРАВНЕНИЯ[какое]));
  *op = какое;
  return 1;
}

/* НЕСОВМЕСТИМАЯ ПАРА ДОПУЩЕНИЙ. Список пар закрыт, и пара сверх него считается
   СОВМЕСТИМОЙ: молчание тут — верный ответ. Ошибка в другую сторону тиха и
   дорога — несовместимость делает постусловие истинным пусто, и цель снимается
   не глядя. Первое сравнение обязано быть строгим. */
static int несовместима_пара(const char *f1, const char *f2, Сп строки) {
  char *l1, *p1, *l2, *p2; int op1, op2;
  if (!разбор_сравнения(f1, &l1, &op1, &p1)) return 0;
  if (op1 != 3 && op1 != 4) return 0;                  /* первое обязано быть строгим */
  if (!разбор_сравнения(f2, &l2, &op2, &p2)) return 0;
  if (op2 == 2)                                        /* равенство тех же сторон */
    return (тождественны(l2, l1, строки, 0) && тождественны(p2, p1, строки, 0)) ||
           (тождественны(l2, p1, строки, 0) && тождественны(p2, l1, строки, 0));
  if (!тождественны(l2, p1, строки, 0) || !тождественны(p2, l1, строки, 0)) return 0;
  return op1 == 3 ? (op2 == 3 || op2 == 1)             /* меньше: больше́ / не-больше́ */
                  : (op2 == 4 || op2 == 0);            /* больше: меньше́ / не-меньше́ */
}

/* У этого узла посылок в ЗАПИСИ нет и быть не может, поэтому допущения
   читаются из ИСХОДНИКА — оттуда же, откуда берётся тело. */
static Сп требования_функции(Сп строки, long a, long b) {
  Сп r = ПУСТО; long i;
  for (i = a + 1; i < b; i++) {
    char *l = как_читает_язык(часть(строки, i));
    if (начинается(l, "требует ") && содержит(l, "» "))
      добавить(&r, терм(хвост_после(l, "» ")));
  }
  return r;
}

/* НЕВЫПОЛНИМАЯ ПОСЫЛКА. Есть среди объявленных допущений функции несовместимая
   пара — входов, доходящих до тела, нет вовсе, постусловие истинно ПУСТО, и
   цель здесь не смотрится совсем: это смысл приёма, а не пробел в нём. */
static int невыполнимая_посылка(Сп строки, long a, long b) {
  Сп t = требования_функции(строки, a, b); int i, j;
  for (i = 0; i < t.n; i++)
    for (j = 0; j < t.n; j++)
      if (i != j && несовместима_пара(t.e[i], t.e[j], строки)) return 1;
  return 0;
}

static int разбором_цели(Сверка *s, Сп свои, Сп строки,
                         const char *чья, const char *цель_сырая) {
  char *цель, *тело; long a, b;
  /* Узел Ч363 — принцип с посылками — не этот приём. И посылок у ЭТОГО узла
     быть не может: он их не проигрывает, а стало быть и снять их со слова ядра
     не вправе; счёт снятого держится на этой строке. */
  if (*первая_с_началом(свои, "принцип тип ") || все_с_началом(свои, "посылка ").n) return 0;
  if (!*цель_сырая || !кавычки_чисты(цель_сырая)) return 0;
  a = блок_функции(строки, чья, &b);
  if (a < 1) return 0;                 /* функции в исходнике нет — скажет сверка имён */
  тело = тело_без_пуст(строки, a, b);
  if (!*тело || !кавычки_чисты(тело)) { s->разбор_мимо++; return 0; }
  цель = вставить_вместо(терм(цель_сырая), "результат", тело);
  if (есть_связыватель(цель)) { s->разбор_мимо++; return 0; }
  if (половина_закрыта(цель, строки, 0, NULL)) return 1;
  if (из_объявленного(цель, строки, a, b)) return 1;
  if (невыполнимая_посылка(строки, a, b)) return 1;
  /* Незакрытая половина — «не берусь», а НЕ «неправда»: сочетание значений
     условий бывает невыполнимым, и кричать тут было бы ложью. */
  s->разбор_не_закрылась++;
  return 0;
}

/* ═══ ПРИЁМ «ВЫВОД»: ПЕРЕИГРЫВАНИЕ ЗАПИСАННОГО ВЫВОДА ФАКТА О ТИПЕ ═══════════
   Приём ничего не выводит сам и ничего не ищет: он берёт НАПИСАННОЕ и сверяет
   каждый шаг порознь. Ни одно правило не подбирает себе основание, не читает
   тело функции и не считает значений.

       вывод цель ⟨Ц⟩
       вывод 1 ИМЯ ⟨Ф⟩ ОСНОВАНИЕ          ОСНОВАНИЕ = сам | строка N | из N [M]
       …
       вывод конец

   Ц сверяется не с записью, а с ИСХОДНИКОМ (хвост постусловия): без этого блок
   объявлял бы себе цель сам. Ф записано ФОРМУЛОЙ, а не именем свойства, — имя
   пришлось бы брать на веру из словаря, формулу же видно знак в знак. Основание
   «из N» указывает только на прежние шаги того же блока, номером меньше своего;
   последний шаг обязан заключать РОВНО цель.

   ПОТОЛОК — НЕ СВОЙСТВО ТИПА, А ОБЯЗАТЕЛЬСТВО. У П3 стоит посылка Пред1
   «⟨Т помещается⟩», за которую отвечает ЗОВУЩИЙ строкой `обязательство вход`, —
   а не имя типа, за которое не отвечает никто; основание «строка N» у П3 —
   отказ. Число 9007199254740991 — постоянная ПРЕДСТАВЛЕНИЯ, а не типа. */

/* Имена, у которых в ведомости вид «запрет». Список закрыт: запретом ничего не
   выводится, и строка с таким именем — отказ с названной причиной. */
static const char *ЗАПРЕТЫ_ВЫВОДА[] = {
  "Н✗", "П✗", "О✗", "О✗✗", "О✗✗✗", "С✗", "С✗✗", "С✗3", "С✗4", "СС✗", "Ч✗", "Ч✗✗"
};
/* Типы с дном (Н3) и типы точной сетки (П3/Пред1) — по ОБЪЯВЛЕНИЮ довода (6203):
   встроенный отрезок (любое имя из НАТУРАЛЬНОЕ[], в том числе за псевдонимом)
   даёт и дно, и потолок; сверх него «вес» — только дно (потолка нет), «сотых» и
   «тысячных» — только точную сетку. Два списка дополнений закрыты, взяты у
   ведомости построчно. */
static const char *ДНО_СВЕРХ_ОТРЕЗКА[]   = { "вес" };
static const char *СЕТКА_СВЕРХ_ОТРЕЗКА[] = { "сотых", "тысячных" };
/* Постоянная представления (ADR-0025 §4, проект 6202 §2.4): 2⁵³−1. Одна строка
   и одно число — сличение знак в знак и сравнение величин делаются по ним же. */
static const char *К_ПРЕДСТ = "9007199254740991";
#define К_ПРЕДСТ_ЧИСЛО 9007199254740991.0

enum { ОСН_ЛИСТ, ОСН_СТРОКА, ОСН_ИЗ1, ОСН_ИЗ2, ОСН_ИЗ1_СТРОКА, ОСН_ИЗ3 };
/* `откр` — открытые гипотезы шага битами (бит k−1 — шаг k «ГипО»/«ГипД»; шагов
   не больше 64, столько же бит): шаг наследует их от посылок, гипотеза кладёт
   себя, Р1/Р4 снимают. `снята` ставится гипотезе снявшим её правилом. */
typedef struct { long номер; char *правило; char *формула;
                 int вид; long строка, из1, из2, из3;
                 unsigned long long откр; int снята; } ШагВывода;

/* Ровно два куска верхнего уровня по знаку `op`, обе стороны ужаты. У терма с
   двумя такими знаками разрез неоднозначен, и приём тут не берётся. */
static int надвое_вывода(const char *ф, const char *op, char **л, char **п) {
  Разрез r;
  if (разделить_сверху(ужать(ф), op).n != 2) return 0;
  r = разрез_по(ф, op);
  if (!r.есть) return 0;
  *л = ужать(r.лево); *п = ужать(r.право);
  return 1;
}
/* Целый неотрицательный литерал: цифры и только они. Слово с любым иным знаком
   литералом не считается — «−1» и «не число» сюда не попадают. */
static int литерал_вывода(const char *t, double *z) {
  const char *p; char *u = ужать(t);
  if (!*u) return 0;
  for (p = u; *p; p++) if (*p < '0' || *p > '9') return 0;
  *z = число_из_слова(u);
  return *z >= 0;
}
/* Дробный литерал: цифры, точка, цифры, и после точки не одни нули — «2.5», но не
   «2.0». Целым он не бывает никогда; им закрытие целости ловит ложь зовущего. */
static int дробный_литерал(const char *t) {
  const char *u = ужать(t); size_t ц = strspn(u, "0123456789"), д;
  if (!ц || u[ц] != '.') return 0;
  д = strspn(u + ц + 1, "0123456789");
  return д && !u[ц + 1 + д] && strspn(u + ц + 1, "0") < д;
}
static int имя_вывода(const char *t) {
  double z; char *u = ужать(t);
  return *u && !содержит(u, " ") && !содержит(u, "(") && !литерал_вывода(u, &z);
}
static int имя_среди(const char *т, const char **список, int n) {
  int i;
  for (i = 0; i < n; i++) if (strcmp(т, список[i]) == 0) return 1;
  return 0;
}
static int объявлен_с_дном(Сп строки, const char *l, const char *имя) {
  char *т = имя_типа(тип_довода_в_строке(l, имя));
  return *т && (strcmp(объявление_типа(строки, т).вид, "отрезок") == 0 ||
                имя_среди(т, ДНО_СВЕРХ_ОТРЕЗКА, (int)(sizeof ДНО_СВЕРХ_ОТРЕЗКА / sizeof *ДНО_СВЕРХ_ОТРЕЗКА)));
}
static int объявлен_точным(Сп строки, const char *l, const char *имя) {
  char *т = имя_типа(тип_довода_в_строке(l, имя));
  return *т && (strcmp(объявление_типа(строки, т).вид, "отрезок") == 0 ||
                имя_среди(т, СЕТКА_СВЕРХ_ОТРЕЗКА, (int)(sizeof СЕТКА_СВЕРХ_ОТРЕЗКА / sizeof *СЕТКА_СВЕРХ_ОТРЕЗКА)));
}
/* Строка исходника по номеру — но только та, что стоит В ТЕЛЕ названной
   функции: иначе шаг опёрся бы на объявление чужого довода. */
static char *строка_функции(Сп строки, long где, const char *чья) {
  if (где < 1 || где > строки.n) return NULL;
  if (strcmp(хозяин_строки(строки, где), чья) != 0) return NULL;
  return как_читает_язык(строка_по_номеру(строки, где));
}
static char *допущение_строки(const char *l) {
  if (!l || !начинается(обрезать(l), "требует ") || !содержит(l, "» ")) return NULL;
  return терм(хвост_после(l, "» "));
}

/* ═══ 6202 (ADR-0025): ПРЕДСТАВИМОСТЬ И ОБЯЗАТЕЛЬСТВО ВХОДА ═════════════════
   Суждение «Т помещается» — значение довода Т лежит в представлении
   [−К_предст, К_предст]. Оно НЕ следует из имени типа: его даёт обязательство
   входа, лежащее на зовущем, и сверщик обязан это обязательство увидеть в
   записи и переиграть его закрытие. Ниже — чтение формы, чтение объявления и
   закрытие; ни одна из функций не ищет себе основания. */

static int помещается_вывода(const char *ф, char **имя) {
  char *u = ужать(ф);
  size_t d = strlen(u), k = strlen(" помещается");
  if (d <= k || strcmp(u + d - k, " помещается") != 0) return 0;
  *имя = ужать(копия(u, d - k));
  return имя_вывода(*имя);
}
static int довод_точного_типа(Сп строки, const char *функция, const char *имя) {
  long a, b, i;
  a = блок_функции(строки, функция, &b);
  if (a < 1) return 0;
  for (i = a; i < b; i++) {
    char *l = как_читает_язык(часть(строки, i));
    if (начинается(l, "принимает "))
      return объявлен_точным(строки, l, имя);
  }
  return 0;
}
/* ЗАКРЫТИЕ ОБЯЗАТЕЛЬСТВА ВХОДА. Причины отказа ДВУХ пород, и смешивать их
   нельзя: литерал выше К_предст (или дробный на месте целого) — ЛОЖЬ записи;
   всё прочее — «закрыть нечем», место уходит на слово ядра поимённо. Ни вызовов,
   ни «дано» — вход внешний, обязательство остаётся на границе программы. */
static char *закрытие_обязательства(Сп строки, const char *чья, const char *имя, int цел, int *ложь) {
  Сп парам = доводы_функции(строки, чья).голые;
  char *метка = fmt("«%s» от ", чья);
  long a, b, i; int k; double z;
  *ложь = 0;
  for (k = 0; k < парам.n; k++) if (strcmp(парам.e[k], имя) == 0) break;
  if (k == парам.n) { *ложь = 1; return fmt("«%s» не довод функции «%s»", имя, чья); }
  for (i = 1; i <= строки.n; i++) {
    char *l = как_читает_язык(часть(строки, i)), *p = l;
    char *зовущий = хозяин_строки(строки, i);
    while ((p = strstr(p, метка)) != NULL) {
      Сп дов = доводы_вызова(p + strlen(метка)); char *д;
      p += strlen(метка);
      if (дов.n <= k)
        return fmt("вызов «%s» на строке %ld подаёт доводов %d, а «%s» стоит %d-м", чья, i, дов.n, имя, k + 1);
      д = ужать(без_внешних(терм(дов.e[k])));
      if (литерал_вывода(д, &z)) {
        if (цел || z <= К_ПРЕДСТ_ЧИСЛО) continue;
        *ложь = 1;
        return fmt("вызов «%s» на строке %ld подставляет на место «%s» литерал «%s» выше К_предст %s",
                   чья, i, имя, д, К_ПРЕДСТ);
      }
      if (цел && дробный_литерал(д)) {
        *ложь = 1;
        return fmt("вызов «%s» на строке %ld подставляет на место «%s» дробный литерал «%s» — не целое", чья, i, имя, д);
      }
      if (имя_вывода(д) && *зовущий && довод_точного_типа(строки, зовущий, д)) continue;
      return fmt("вызов «%s» на строке %ld подставляет на место «%s» «%s» — ни литерал под К_предст, "
                 "ни довод зовущей «%s» под своим обязательством; закрыть нечем",
                 чья, i, имя, д, зовущий);
    }
  }
  a = блок_функции(строки, чья, &b);
  for (i = a; a >= 1 && i < b; i++) {
    char *l = как_читает_язык(часть(строки, i)), *зн;
    if (!начинается(l, "дано ")) continue;
    if (strcmp(голо(слово(l, 2)), имя) != 0 || strcmp(слово(l, 3), "равно") != 0) continue;
    зн = ужать(слова_после(l, 3));
    if (цел && дробный_литерал(зн)) {
      *ложь = 1;
      return fmt("пример на строке %ld даёт «%s» дробное значение «%s» — не целое", i, имя, зн);
    }
    if (!литерал_вывода(зн, &z))
      return fmt("пример на строке %ld даёт «%s» значение «%s» — не литерал; закрыть нечем", i, имя, зн);
    if (!цел && z > К_ПРЕДСТ_ЧИСЛО) {
      *ложь = 1;
      return fmt("пример на строке %ld даёт «%s» значение «%s» выше К_предст %s", i, имя, зн, К_ПРЕДСТ);
    }
  }
  return (char *)"";
}
/* Строки обязательства переигрываются ЦЕЛИКОМ, а не узнаются по виду.
   Обязательство сверяется на КАЖДЫЙ довод точного типа, звал его шаг вывода
   или нет. Возврат — сколько закрыть НЕ СМОГЛИ (не ложь, а «нечем»); при
   ненулевом блок вывода того же утверждения место со слова ядра не снимает. */
static int сверить_обязательства(Сверка *s, Сп свои, Сп строки, const char *имя_т,
                                 const char *чья) {
  Сп все = все_с_началом(свои, "обязательство "); int i, нечем = 0;
  for (i = 0; i < все.n; i++) {
    char *l = все.e[i], *имя = в_ёлочках(l, 1), *ф = терм(в_уголках(l, 1)), *исх, *почему;
    long n = номер_после(хвост_после(l, "⟩"), "строка "); int ложь, цел = strcmp(ф, fmt("%s : цел", имя)) == 0;
    if (!начинается(l, "обязательство вход «")) {
      если_не(s, 0, fmt("утверждение «%s»: «%s» — сверщик знает только обязательство входа", имя_т, l));
      continue;
    }
    если_не(s, имя_вывода(имя),
            fmt("утверждение «%s»: обязательство входа названо над «%s», а это не имя довода", имя_т, имя));
    если_не(s, цел || strcmp(ф, fmt("%s не больше %s", имя, К_ПРЕДСТ)) == 0,
            fmt("утверждение «%s»: обязательство входа «%s» заключает «%s», а обязано «%s не больше %s» либо «%s : цел»",
                имя_т, имя, ф, имя, К_ПРЕДСТ, имя));
    исх = строка_функции(строки, n, чья);
    если_не(s, исх != NULL,
            fmt("утверждение «%s»: обязательство входа «%s» указывает на строку %ld, а в функции «%s» её нет",
                имя_т, имя, n, чья));
    если_не(s, !исх || объявлен_точным(строки, исх, имя),
            fmt("утверждение «%s»: обязательство входа «%s» — строка %ld не объявляет «%s» типом точной сетки",
                имя_т, имя, n, имя));
    почему = закрытие_обязательства(строки, чья, имя, цел, &ложь);
    if (*почему && ложь)
      если_не(s, 0, fmt("утверждение «%s»: обязательство входа «%s» зовущим не закрыто — %s", имя_т, имя, почему));
    else if (*почему) {
      нечем++;
      добавить(&s->не_взялся,
              fmt("утверждение «%s»: обязательство входа «%s» сверщик закрыть не смог — %s; место на слове ядра",
                  имя_т, имя, почему));
    }
  }
  return нечем;
}

/* ═══ ФОРМЫ ЗАКЛЮЧЕНИЙ СЕМЕЙСТВ ОТНОШЕНИЙ ═══════════════════════════════════
   Ниже — чтение формул, и только чтение: ни одна из этих функций не считает
   значений, не подбирает основания и не ходит в исходник. Каждая отвечает на
   один вопрос — «есть ли у написанной формулы такой-то вид», — и отдаёт куски
   этого вида знак в знак. */

/* Порядок: «Е не больше Г». Тот же узел язык пишет и второй стороной —
   «Г не меньше Е», — и это ОДНА форма, а не две: `boundaries` держит обе
   («В4 результат не больше терма» и «В5 результат не меньше терма»). */
static int порядок_вывода(const char *ф, char **е, char **г) {
  char *л, *п;
  if (надвое_вывода(ф, "не больше", &л, &п)) { *е = л; *г = п; return 1; }
  if (надвое_вывода(ф, "не меньше", &л, &п)) { *е = п; *г = л; return 1; }
  return 0;
}
/* Строгий порядок: «Е меньше Г» либо зеркало «Г больше Е». Слова «не меньше» и
   «не больше» ПЕРЕХВАТЫВАЮТСЯ ПЕРВЫМИ: в них тот же знак стоит подстрокой, и
   без этой заставы «а не больше б» прочлось бы строгим «б больше ( а не )». */
static int строгий_вывода(const char *ф, char **е, char **г) {
  char *л, *п, *в = fmt(" %s ", ужать(ф));
  if (содержит(в, " не меньше ") || содержит(в, " не больше ")) return 0;
  if (надвое_вывода(ф, "меньше", &л, &п)) { *е = л; *г = п; return 1; }
  if (надвое_вывода(ф, "больше", &л, &п)) { *е = п; *г = л; return 1; }
  return 0;
}
static int неубыв_вывода(const char *ф, char **л) {
  char *u = ужать(ф);
  size_t d = strlen(u), k = strlen(" не убывает");
  if (d <= k || strcmp(u + d - k, " не убывает") != 0) return 0;
  *л = ужать(копия(u, d - k));
  return **л != 0;
}
/* Выбор «если У то А иначе Б». Две ветви и только две: у вложенного выбора
   кусков верхнего уровня больше двух, и приём за него не берётся. */
static int выбор_вывода(const char *t, char **а, char **б) {
  char *u = ужать(t), *лево;
  if (!начинается(u, "если ")) return 0;
  if (разделить_сверху(u, "иначе").n != 2) return 0;
  лево = ужать(разрез_по(u, "иначе").лево);
  *б = ужать(разрез_по(u, "иначе").право);
  if (разделить_сверху(лево, "то").n != 2) return 0;
  *а = ужать(разрез_по(лево, "то").право);
  return **а != 0 && **б != 0;
}
static char *знаки_списка(const char *t) {
  return сжать_пробелы(заменить(заменить(заменить(t, "[", " [ "), "]", " ] "), ",", " , "));
}
/* Члены ВЫПИСАННОГО списка. `выписан` — у «пустой список» и у «[ … ]»; вложенный
   список не берётся вовсе, и это отказ, а не молчание: границу видно по числу
   членов, которое приём не вернёт. */
static Сп члены_списка_вывода(const char *t, int *выписан) {
  Сп r = ПУСТО; char *u = ужать(t), *в; size_t d;
  *выписан = 0;
  if (strcmp(u, "пустой список") == 0) { *выписан = 1; return r; }
  u = сжать_пробелы(знаки_списка(u));
  d = strlen(u);
  if (d < 2 || u[0] != '[' || u[d - 1] != ']') return r;
  в = обрезать(копия(u + 1, d - 2));
  if (содержит(в, "[") || содержит(в, "]")) return r;
  *выписан = 1;
  if (!*в) return r;
  { Сп ч = разделить_сверху(в, ","); int i;
    for (i = 0; i < ч.n; i++) добавить(&r, ужать(ч.e[i])); }
  return r;
}
static int к_списку_вывода(const char *t, const char *имя_формы, char **э, char **л) {
  char *u = ужать(t);
  if (!начинается(u, fmt("%s ", имя_формы))) return 0;
  if (разделить_сверху(u, "к").n != 2) return 0;
  *э = ужать(слова_после(разрез_по(u, "к").лево, 1));
  *л = ужать(разрез_по(u, "к").право);
  return **э != 0 && **л != 0;
}
static int голова_списка_вывода(const char *t, char **г, int *пуст) {
  int выписан; char *э, *х;
  Сп ч = члены_списка_вывода(t, &выписан);
  *пуст = 0;
  if (выписан) { if (!ч.n) { *пуст = 1; return 1; } *г = ч.e[0]; return 1; }
  if (к_списку_вывода(t, "приписать", &э, &х)) { *г = э; return 1; }
  return 0;
}
/* Двоичная склейка «соединить Л с Р». Списочная «соединить Ч по Р» сюда не
   попадает ни одной строкой — у неё нет знака «с», и это запрет Ч✗. */
static int склейка_вывода(const char *t, char **л, char **р) {
  char *u = ужать(t);
  if (!начинается(u, "соединить ")) return 0;
  if (разделить_сверху(u, "с").n != 2) return 0;
  *л = ужать(слова_после(разрез_по(u, "с").лево, 1));
  *р = ужать(разрез_по(u, "с").право);
  return **л != 0;
}
static int шаг_порядка(const char *о, const char *е, const char *г) {
  char *ое, *ог;
  return порядок_вывода(о, &ое, &ог) && strcmp(ое, е) == 0 && strcmp(ог, г) == 0;
}
static int шаг_дна(const char *о, const char *г, const char *д) {
  char *ол, *оп;
  return надвое_вывода(о, "не меньше", &ол, &оп) && strcmp(ол, г) == 0 && strcmp(оп, д) == 0;
}
/* Лежит ли терм в отрезке (0,кон] по НАЗВАННЫМ допущениям функции: «Т больше К»
   при неотрицательном целом литерале К и «Т не больше ⟨целый литерал⟩». Оба
   допущения читаются из ИСХОДНИКА, а не из записи (Н8, второй способ). */
static int в_строго_положительном_отрезке(Сп строки, const char *чья, const char *т) {
  Сп треб = все_требования_функции(строки, чья); int i, низ = 0, верх = 0; double z; char *ф, *л, *п;
  for (i = 0; i < треб.n; i++)
    if ((ф = допущение_строки(треб.e[i])) != NULL) {
      if (надвое_вывода(ф, "не больше", &л, &п)) верх |= strcmp(л, т) == 0 && литерал_вывода(п, &z);
      else if (надвое_вывода(ф, "больше", &л, &п)) низ |= strcmp(л, т) == 0 && литерал_вывода(п, &z);
    }
  return низ && верх;
}
static int шаг_строгий(const char *о, const char *е, const char *г) {
  char *ое, *ог;
  return строгий_вывода(о, &ое, &ог) && strcmp(ое, е) == 0 && strcmp(ог, г) == 0;
}
static int шаг_неубыв(const char *о, const char *л) {
  char *ол; return неубыв_вывода(о, &ол) && strcmp(ол, л) == 0;
}
static int шаг_вхождения(const char *о, const char *л, const char *э) {
  char *ол, *оэ;
  return надвое_вывода(о, "содержит", &ол, &оэ) && strcmp(ол, л) == 0 && strcmp(оэ, э) == 0;
}
/* «для всех П из Л : У» — имя, список и свойство (семейство Э, ADR-0026 §11
   п.14). Режется по ПЕРВОМУ верхнему « : »: справа может стоять вложенный
   квантор со своим двоеточием, и он целиком уходит в свойство. */
static int все_элементы_вывода(const char *о, char **п, char **л, char **у) {
  Сп ч = разделить_сверху(ужать(о), ":"), хвост = ПУСТО; char *лево; int i;
  if (ч.n < 2) return 0;
  лево = ужать(ч.e[0]);
  for (i = 1; i < ч.n; i++) добавить(&хвост, ч.e[i]);
  *у = ужать(соединить(хвост, " : "));
  if (!начинается(лево, "для всех ")) return 0;
  return надвое_вывода(лево + strlen("для всех "), "из", п, л) &&
         **п && !содержит(*п, " ") && **л && **у;
}
/* Имена, связанные ВНУТРИ свойства кванторами «для всех N из …» и «есть такой
   N, …»: подстановка вместо `п` заперта, если одно из них — сам `п` (тень) или
   стоит словом в подставляемом терме (захват). Прочие связыватели (`пусть`,
   `свёртка`, …) в свойстве — отказ целиком: их имён этот читатель не знает. */
static int захват_в_свойстве(const char *у, const char *п, const char *чем) {
  const char *k; Сп имена = ПУСТО; int i;
  if (есть_связыватель(у)) return 1;
  for (k = у; (k = strstr(k, "для всех ")) != NULL; k += strlen("для всех "))
    добавить(&имена, слово(k, 3));
  for (k = у; (k = strstr(k, "есть такой ")) != NULL; k += strlen("есть такой ")) {
    char *n = слово(k, 3); size_t d = strlen(n);
    if (d && n[d - 1] == ',') n[d - 1] = 0;
    добавить(&имена, n);
  }
  for (i = 0; i < имена.n; i++)
    if (strcmp(имена.e[i], п) == 0 || есть_терм(чем, имена.e[i])) return 1;
  return 0;
}
/* Свободно ли имя `б` в терме `на` (аудит 2844): стоит ли оно словом ВНЕ области
   связывателя того же имени. Область связывателя тянется до конца объемлющей
   пары скобок — она стирается, и что осталось, смотрится словом. Так тело
   «отфильтровать л где э → э больше 0» имени «э» наружу не отдаёт, а
   «длина ( … где э → … ) плюс э» — отдаёт. Lean: «свободныеТело». */
static int свободно_в(const char *на, const char *б) {
  static const char *К[9] = { " для всех %s из ", " есть такой %s,", " как %s →", " как %s и ",
                              " и %s →", " где %s →", " случай %s и ", " и %s то ", " пусть %s " };
  char *t = fmt(" %s ", терм(на)), *k; long гл; int j;
  for (j = 0; j < 9; j++)
    while ((k = strstr(t, fmt(К[j], б))) != NULL)
      for (гл = 0; *k && (*k != ')' || гл > 0); k++) { гл += (*k == '(') - (*k == ')'); *k = ' '; }
  return есть_терм(t, б);
}
/* ЗАХВАТ ПРИ ПОДСТАНОВКЕ `на` вместо `что` в терм `где` (аудит 2844, дыры Разв2
   и Разв3). Захват — одно из двух: `что` само связано в `где` (тень) либо имя,
   связанное в `где`, стоит свободным в `на` — тогда подстановка сказала бы о
   СВЯЗАННОМ имени то, что обещано о свободном. Связыватели `где`: «для всех N
   из», «есть такой N,», «как N →» и «как А и Э →» (отображение, свёртка, поле
   варианта «с п как х»), «где N →», «пусть N». Разбор списка «случай Г и Х» в
   одну строку этот читатель не знает — отказ целиком, как у
   `захват_в_свойстве`. Lean: «захват?» приёмки; у Т2 и Э2 тот же вопрос задаёт
   `захват_в_свойстве`. */
static int захват(const char *где, const char *что, const char *на) {
  static const char *К[6] = { " для всех ", " есть такой ", " как ", " где ", " пусть ", " случай " };
  char *п = fmt(" %s ", терм(где)); const char *k; int j, l;
  for (j = 0; j < 6; j++)
    for (k = п; (k = strstr(k, К[j])) != NULL; k += strlen(К[j]))
      for (l = 1; l <= 3; l += 2) {
        char *n = слово(k + strlen(К[j]), l); size_t d = strlen(n);
        if (d && n[d - 1] == ',') n[d - 1] = 0;
        if (j == 5) { if (strcmp(n, "вариант") != 0) return 1; break; }
        if (l == 3 && strcmp(слово(k + strlen(К[j]), 2), "и") != 0) break;
        if (*n && (strcmp(n, что) == 0 || свободно_в(на, n))) return 1;
      }
  return 0;
}
static int шаг_всех(const char *о, const char *п, const char *л, const char *у) {
  char *оп, *ол, *оу;
  return все_элементы_вывода(о, &оп, &ол, &оу) && strcmp(оп, п) == 0 &&
         strcmp(ол, л) == 0 && strcmp(оу, у) == 0;
}
static int отображение_вывода(const char *л, char **над, char **х, char **ф) {
  char *u = ужать(л), *хвост;
  if (!начинается(u, "отобразить ")) return 0;
  if (!надвое_вывода(u + strlen("отобразить "), "как", над, &хвост)) return 0;
  if (!надвое_вывода(хвост, "→", х, ф)) return 0;
  return **над && **х && !содержит(*х, " ") && **ф;
}
static int отбор_вывода(const char *л, char **над, char **х, char **у) {
  char *u = ужать(л), *хвост;
  if (!начинается(u, "отфильтровать ")) return 0;
  if (!надвое_вывода(u + strlen("отфильтровать "), "где", над, &хвост)) return 0;
  if (!надвое_вывода(хвост, "→", х, у) && !надвое_вывода(хвост, ":", х, у)) return 0;
  return **х && !содержит(*х, " ") && **у;
}
static int шаг_начала(const char *о, const char *т, const char *п) {
  char *от, *оп;
  return надвое_вывода(о, "начинается с", &от, &оп) && strcmp(от, т) == 0 && strcmp(оп, п) == 0;
}
static int дно_шага(const char *о, const char *г, double *д) {
  char *ол, *оп;
  return надвое_вывода(о, "не меньше", &ол, &оп) && strcmp(ол, г) == 0 &&
         литерал_вывода(оп, д);
}
/* Ветвь шага свёртки для Н7: накопитель сам либо накопитель плюс неотрицательный
   целый литерал (в любой позиции) — при неотрицательном накопителе ветвь не меньше
   нуля. Шаг — такая ветвь либо выбор из двух таких; условие выбора не читается. */
static int ветвь_счёта(const char *в, const char *акк) {
  char *л, *п, *у = ужать(в); double z;
  if (strcmp(у, акк) == 0) return 1;
  return надвое_вывода(у, "плюс", &л, &п) &&
         ((strcmp(л, акк) == 0 && литерал_вывода(п, &z)) || (strcmp(п, акк) == 0 && литерал_вывода(л, &z)));
}
static int шаг_счёта(const char *ш, const char *акк) {
  char *а, *б;
  return ветвь_счёта(ш, акк) || (выбор_вывода(ужать(ш), &а, &б) && ветвь_счёта(а, акк) && ветвь_счёта(б, акк));
}
static int целое_неотрицательное(const char *правило1, const char *о1, const char *о2, const char *т) {
  char *е, *к, *г;
  return (strcmp(правило1, "Цел1") == 0 || strcmp(правило1, "Цел2") == 0) && надвое_вывода(о1, ":", &е, &к) &&
         strcmp(к, "цел") == 0 && strcmp(е, т) == 0 && порядок_вывода(о2, &е, &г) && strcmp(е, "0") == 0 &&
         strcmp(г, т) == 0;
}
/* Стоит ли под утверждением `обязательство вход «ИМЯ» ⟨Ф⟩ строка N на зовущем` — имя,
   формула и строка знак в знак. Имени и строки мало: у довода точного типа строк
   обязательства может быть две (потолок и целость), и шаг обязан опереться на свою. */
static int есть_обязательство(Сп обяз, const char *имя, const char *ф, long n) {
  int j;
  for (j = 0; j < обяз.n; j++)
    if (начинается(обяз.e[j], "обязательство вход «") && strcmp(в_ёлочках(обяз.e[j], 1), имя) == 0 &&
        strcmp(терм(в_уголках(обяз.e[j], 1)), ф) == 0 && номер_после(хвост_после(обяз.e[j], "⟩"), "строка ") == n)
      return 1;
  return 0;
}
static int дно_литералом(const char *о, const char *г, double *д) {
  char *е, *в;
  return порядок_вывода(о, &е, &в) && strcmp(в, г) == 0 && литерал_вывода(е, д);
}
static char *список_из_пустоты(const char *о) {
  char *л, *п;
  if (начинается(о, "пусто ")) return ужать(слова_после(о, 1));
  if (!надвое_вывода(о, "равен", &л, &п)) return NULL;
  if (strcmp(п, "пустой список") == 0 || strcmp(п, "\"\"") == 0) return л;
  if (strcmp(п, "0") == 0 && начинается(л, "длина ")) return ужать(слова_после(л, 1));
  return NULL;
}
static long младшая_гипотеза(unsigned long long м) {
  long k = 1; while (м && !(м & 1)) { м >>= 1; k++; } return k;
}

static long случай_звена(Сп строки, long a, long b, char **г, char **х) {
  long i;
  for (i = a; i < b; i++) {
    char *l = как_читает_язык(часть(строки, i)), *обр;
    if (!начинается(l, "случай ")) continue;
    обр = слова_после(l, 1);
    if (разделить(обр, " ").n == 3 && strcmp(слово(обр, 2), "и") == 0 &&
        имя_вывода(слово(обр, 1)) && имя_вывода(слово(обр, 3))) { *г = слово(обр, 1); *х = слово(обр, 3); return i; }
  }
  return -1;
}
/* Список остальных членов выписанного списка — так, как его пишет ядро. */
static char *хвост_списка(Сп члены) {
  Сп ост = ПУСТО; int i;
  for (i = 1; i < члены.n; i++) добавить(&ост, члены.e[i]);
  return ост.n ? fmt("[%s]", соединить(ост, ", ")) : (char *)"пустой список";
}
/* ТОЧНЫЙ ТЕКСТ. Список форм закрыт; 0 — «не берусь», а не ложь. Длина
   строки-литерала точным числом сюда не входит: мера знаков у языка своя, и
   второго счётчика знаков сверщик не заводит. */
static int точный_текст(const char *t, char **куда) {
  char *u = ужать(t), *л, *р, *а, *б, *ч; size_t d = strlen(u); double z; int выписан;
  if (d >= 2 && u[0] == '"' && u[d - 1] == '"' && strchr(u + 1, '"') == u + d - 1 && !strchr(u, '\\')) {
    *куда = копия(u + 1, d - 2); return 1;
  }
  if (склейка_вывода(u, &л, &р)) {
    if (!точный_текст(л, &а) || !точный_текст(р, &б)) return 0;
    *куда = fmt("%s%s", а, б); return 1;
  }
  if (!начинается(u, "к строке ")) return 0;
  ч = ужать(слова_после(u, 2));
  if (литерал_вывода(ч, &z)) { *куда = ч; return 1; }
  if (!начинается(ч, "длина ")) return 0;
  члены_списка_вывода(слова_после(ч, 1), &выписан);
  if (!выписан) return 0;
  *куда = fmt("%d", члены_списка_вывода(слова_после(ч, 1), &выписан).n); return 1;
}

/* ОДИН ШАГ. Возврат — пустая строка, когда шаг сошёлся, иначе названная
   причина отказа. Ни одно правило не ищет себе основания: оно сверяет
   написанное. */
/* Прибавка Т у О5/О6 — ЧИСЛО в отрезке [Д, В]: целым литералом (основание «из N»)
   либо ИМЕНЕМ, зажатым посылками «из N M K»: шаг M заключает «Т не меньше Д», шаг K —
   «Т не больше В», Д и В — неотрицательные целые литералы. Не-число не проходит ни
   одной из двух посылок, минус бесконечность — первой, плюс бесконечность — второй;
   дно Д ≥ 0 даёт и неотрицательность, которую спрашивает О6. Lean: «отрезок-числом». */
static int прибавка_числом(int вид, const char *т, const char *о2, const char *о3) {
  char *дл, *дп, *вл, *вп; double z;
  if (вид != ОСН_ИЗ3) return литерал_вывода(т, &z);
  return надвое_вывода(о2, "не меньше", &дл, &дп) && strcmp(дл, т) == 0 && литерал_вывода(дп, &z) &&
         надвое_вывода(о3, "не больше", &вл, &вп) && strcmp(вл, т) == 0 && литерал_вывода(вп, &z);
}
/* ═══ ADR-0042 §2 (задача 6432): ПЕРЕПИСКА ОДНОЙ СТОРОНЫ ОТНОШЕНИЯ ═══════════
   М1, М2 и К↑ — уравнения вычислителя: сторона посылки заменяется РАВНЫМ ей
   значением, и отношение держится, какое бы из шести ни стояло сверху. Какой
   стала сторона — написано (мера, свёртка, поле конструктора); какой она была —
   пересобирает сверщик из частей написанного и сличает термом. Заставы «не …» —
   первыми: в «не меньше» тот же знак стоит подстрокой. */
static const char *ОТН_ПЕРЕПИСКИ[] = { "не меньше", "не больше", "не равен", "меньше", "больше", "равен" };
#define ОТН ОТН_ПЕРЕПИСКИ
static int сторона_переписана(const char *о, const char *ф, char **было, char **стало) {
  char *ол, *оп, *зл, *зп; int i;
  for (i = 0; i < 6 && !надвое_вывода(о, ОТН[i], &ол, &оп); i++) ;
  if (i == 6 || !надвое_вывода(ф, ОТН[i], &зл, &зп)) return 0;
  if (strcmp(ол, зл) == 0 && strcmp(оп, зп) != 0) { *было = оп; *стало = зп; return 1; }
  if (strcmp(оп, зп) == 0 && strcmp(ол, зл) != 0) { *было = ол; *стало = зл; return 1; }
  return 0;
}
/* Одно отношение с теми же сторонами: внешние скобки стороны смысла не несут. */
static int то_же_отношение(const char *а, const char *б) {
  char *ал, *ап, *бл, *бп; int i;
  for (i = 0; i < 6 && !надвое_вывода(б, ОТН[i], &бл, &бп); i++) ;
  return strcmp(а, б) == 0 || (i < 6 && надвое_вывода(а, ОТН[i], &ал, &ап) && !strcmp(ал, бл) && !strcmp(ап, бп));
}
#undef ОТН
/* Реестр ПРОВЕРЕННЫХ постусловий записи, чей блок проигрывается (`доказанные_свойства`,
   4123): М2 берёт меру шага-вызова только оттуда — постусловие на слове ядра не звено. */
static Сп *ДОКАЗАНО_ДО_ВЫВОДА;
static char *как_слово(const char *w);
static int доказано_раньше(const char *имя) {
  int i;
  for (i = 0; ДОКАЗАНО_ДО_ВЫВОДА && i < ДОКАЗАНО_ДО_ВЫВОДА->n; i++)
    if (strcmp(ДОКАЗАНО_ДО_ВЫВОДА->e[i], имя) == 0) return 1;
  return 0;
}
/* М2: мера свёртки «свёртка Л начиная с Н как а и э → Ш», чей шаг растит накопитель
   РОВНО на один: Ш — «добавить|приписать Х к а» либо «Г» от а, у которой постусловие
   «( длина результат ) равен ( ( длина П ) плюс 1 )» о единственном параметре П
   проверено раньше. Мера — «( длина Н ) плюс ( длина Л )», при Н = «пустой список» —
   «длина Л»: ноль плюс длина есть та же длина. NULL — свёртка не такая. */
static char *мера_свёртки(const char *вн, Сп строки) {
  Разрез как, нач, стр, им; char *а, *ш, *х, *п, *г; long a, b, i; Сп пар;
  if (!начинается(вн, "свёртка ")) return NULL;
  как = разрез_по(слова_после(вн, 1), "как"); нач = разрез_по(как.лево, "начиная с");
  стр = разрез_по(как.право, "→"); им = разрез_по(стр.лево, "и");
  if (!как.есть || !нач.есть || !стр.есть || !им.есть) return NULL;
  а = ужать(им.лево); ш = ужать(стр.право);
  if ((начинается(ш, "добавить ") || начинается(ш, "приписать ")) &&
      надвое_вывода(слова_после(ш, 1), "к", &х, &п) && strcmp(п, а) == 0) ;
  else {
    if (!начинается(ш, "«") || strcmp(ужать(хвост_после(ш, "» от ")), а) != 0) return NULL;
    г = в_ёлочках(ш, 1); a = блок_функции(строки, г, &b); пар = доводы_функции(строки, г).голые;
    if (a < 1 || пар.n != 1) return NULL;
    for (i = a; i < b; i++) {
      char *l = как_читает_язык(обрезать(строка_по_номеру(строки, i)));
      if (начинается(l, "обеспечивает «") && доказано_раньше(в_ёлочках(l, 1)) &&
          strcmp(терм(хвост_после(l, "» ")), терм(fmt("( длина результат ) равен ( ( длина %s ) плюс 1 )", часть(пар, 1)))) == 0) break;
    }
    if (i >= b) return NULL;
  }
  п = ужать(нач.право);
  return strcmp(п, "пустой список") == 0 ? fmt("длина %s", в_скобки(ужать(нач.лево)))
       : fmt("( длина %s ) плюс ( длина %s )", в_скобки(п), в_скобки(ужать(нач.лево)));
}

/* Таблица «правило → какое основание оно берёт». Правил с двумя допустимыми
   основаниями и тех, у кого вид основания спрошен заодно с формой заключения,
   в таблице нет: имени нет — ответ NULL, и правило спрашивает основание само.
   NULL здесь значит «таблица молчит», а не «основание проверено». */
typedef struct { int вид; const char *имена; const char *чем; } Основание;
static const Основание ОСНОВАНИЯ[] = {
  { ОСН_СТРОКА, "Т1 Т2 Н2 Д1 О1 СС2 С1", " опирается на строку допущения — основание обязано быть «строка N»" },
  { ОСН_ИЗ1, "Св1 Кон3 Цел1 Или1 Или2 И1 И2 М1 М2 К↑ О2 В3 Э6 Ч3", " берёт одну посылку — основание обязано быть «из N»" },
  { ОСН_ИЗ2, "Кон2", " берёт гипотезу оговорки и вывод под ней — основание обязано быть «из H M»" },
  { ОСН_СТРОКА, "Цел2 Н3 Пред1", " опирается на объявление довода — основание обязано быть «строка N»" },
  { ОСН_ИЗ1_СТРОКА, "Разв2 Разв3", " берёт посылку и строку тела — основание обязано быть «из N строка M»" },
  { ОСН_СТРОКА, "ГипД", " — половина дизъюнкции допущения, основание обязано быть «строка N»" },
  { ОСН_ЛИСТ, "Выч Н1 Н4 П1 Д6 СС1 В1 В2 Э1 Э2 Ч1 Ч2 Ч5", " — лист, основание обязано быть «сам»" },
  { ОСН_ИЗ2, "Пр1", " берёт пару посылок — основание обязано быть «из N M»" },
  { ОСН_ИЗ2, "Р3 Р2", " берёт две замкнутые половины — основание обязано быть «из M1 M2»" },
  { ОСН_ИЗ2, "Р1", " берёт гипотезу охраны и вывод под ней — основание обязано быть «из H M»" },
  { ОСН_ИЗ2, "Р4", " берёт два случая — основание обязано быть «из M1 M2»" },
  { ОСН_ИЗ1_СТРОКА, "Р5 Р6", " берёт факт пустоты и первую строку тела — основание обязано быть «из H строка N»" },
  { ОСН_ИЗ2, "Н5 П5 Д4 О3 С2 В4 Э3 Э4 Э5 Ч4", " берёт две посылки — основание обязано быть «из N M»" },
  { ОСН_ИЗ2, "Н12", " берёт дно и потолок вычитаемого — основание обязано быть «из N M»" },
  { ОСН_ИЗ2, "Н10 П6", " берёт целость и дно делимого — основание обязано быть «из M1 M2»" },
  { ОСН_ИЗ1, "Н7", " берёт дно начала свёртки — основание обязано быть «из N»" },
  { ОСН_ИЗ1, "Н8", " берёт дно второго сомножителя — основание обязано быть «из N»" },
  { ОСН_ИЗ2, "Д5", " берёт дно каждого сомножителя — основание обязано быть «из M1 M2»" },
  { ОСН_ИЗ2, "Д3", " берёт дно каждого слагаемого — основание обязано быть «из M1 M2»" },
  { ОСН_ИЗ1, "О4 С3", " берёт дно верхней стороны — основание обязано быть «из N»" },
  { ОСН_ИЗ2, "О10 Ч6", " берёт два звена — основание обязано быть «из N M»" },
  { ОСН_ЛИСТ, "ГипО", " — охрана цели, основание обязано быть «сам»; дизъюнкт пишется именем «ГипД»" },
};
/* NULL — основание то самое, какое правило берёт (либо правила в таблице нет). */
static char *не_то_основание(ШагВывода *ш, const char *имя) {
  int i; size_t n = strlen(имя); const char *с, *p;
  for (i = 0; i < (int)(sizeof ОСНОВАНИЯ / sizeof *ОСНОВАНИЯ); i++)
    for (с = ОСНОВАНИЯ[i].имена, p = strstr(с, имя); p; p = strstr(p + 1, имя))
      if ((p == с || p[-1] == ' ') && (p[n] == ' ' || p[n] == '\0'))
        return ш->вид == ОСНОВАНИЯ[i].вид ? NULL
             : fmt("шаг %ld: %s%s", ш->номер, имя, ОСНОВАНИЯ[i].чем);
  return NULL;
}


static char *правило_т1(ШагВывода *ш, char *ф, char *исх) {
  char *доп;
  доп = допущение_строки(исх);
  if (!доп)
    return fmt("шаг %ld: Т1 — строка %ld не есть допущение «требует «имя» формула»", ш->номер, ш->строка);
  if (!содержит(ф, " "))
    return fmt("шаг %ld: Т1 — заключение «%s» скаляр, а скаляром допущение не сличают", ш->номер, ф);
  if (strcmp(доп, ф) != 0)
    return fmt("шаг %ld: Т1 — допущение строки %ld есть «%s», а заключено «%s»",
               ш->номер, ш->строка, доп, ф);
  return (char *)"";
}

static char *правило_т2(ШагВывода *ш, char *ф, char *исх) {
  char *доп, *дп, *дл, *ду, *цп, *цл, *цу;
  if ((доп = допущение_строки(исх)) == NULL || !все_элементы_вывода(доп, &дп, &дл, &ду))
    return fmt("шаг %ld: Т2 — строка %ld не есть допущение-квантор «требует «имя» для всех П из Л : У»", ш->номер, ш->строка);
  if (!все_элементы_вывода(ф, &цп, &цл, &цу))
    return fmt("шаг %ld: Т2 заключает квантор по элементам, а вида «для всех П из Л : У» у «%s» нет", ш->номер, ф);
  if (strcmp(дл, цл) != 0)
    return fmt("шаг %ld: Т2 — допущение строки %ld о списке «%s», а заключено о списке «%s»", ш->номер, ш->строка, дл, цл);
  /* Имя цели не свободно в свойстве допущения (или то же имя): иначе
     переименование его захватывает — «для всех э из Л : э больше м» не есть
     «для всех м из Л : м больше м». Lean: «Т2-терм», ловушка 33. */
  if (strcmp(цп, дп) != 0 && есть_терм(ду, цп))
    return fmt("шаг %ld: Т2 — имя цели «%s» стоит свободным в свойстве допущения строки %ld «%s»: переименование его захватило бы", ш->номер, цп, ш->строка, ду);
  if (захват_в_свойстве(ду, дп, цп) || strcmp(терм(вставить_вместо(ду, дп, цп)), цу) != 0)
    return fmt("шаг %ld: Т2 — свойство допущения строки %ld «%s» при «%s» вместо «%s» не есть свойство цели «%s»", ш->номер, ш->строка, ду, цп, дп, цу);
  return (char *)"";
}

static char *правило_св1(ШагВывода *ш, char *ф, char *о1) {
  char *м, *т, *у, *ждём;
  if (!разобрать_существование(ф, &м, &т, &у))
    return fmt("шаг %ld: Св1 заключает существование, а вида «есть такой м, а именно Т, что У» у «%s» нет", ш->номер, ф);
  if (захват_в_свойстве(у, м, т))
    return fmt("шаг %ld: Св1 — тело «%s» связывает имя, подстановка «%s» вместо «%s» заперта", ш->номер, у, т, м);
  ждём = терм(вставить_вместо(терм(у), м, терм(т)));
  if (strcmp(о1, ждём) != 0)
    return fmt("шаг %ld: Св1 — шаг %ld заключает «%s», а нужно «%s»", ш->номер, ш->из1, о1, ждём);
  return (char *)"";
}

static char *правило_кон1(ШагВывода *ш, char *ф, char *исх) {
  double з1;
  char *т, *к, *дл, *дп, *доп;
  if (ш->вид != ОСН_СТРОКА || !надвое_вывода(ф, ":", &т, &к) || strcmp(к, "кон") != 0)
    return fmt("шаг %ld: Кон1 заключает «Т : кон» строкой допущения — вид «%s», основание обязано быть «строка N»",
               ш->номер, ф);
  if ((доп = допущение_строки(исх)) == NULL || !надвое_вывода(доп, "не больше", &дл, &дп) ||
      strcmp(дл, т) != 0 || !литерал_вывода(дп, &з1))
    return fmt("шаг %ld: Кон1 — строка %ld не есть допущение «%s не больше ⟨целый литерал⟩»", ш->номер, ш->строка, т);
  return (char *)"";
}

static char *правило_кон3(ШагВывода *ш, char *ф, char *о1) {
  char *т, *к, *рл, *рп, *а, *б;
  if (!надвое_вывода(ф, ":", &т, &к) || strcmp(к, "кон") != 0)
    return fmt("шаг %ld: Кон3 заключает «Т : кон», а у «%s» такого вида нет", ш->номер, ф);
  if (!надвое_вывода(о1, "равен", &рл, &рп) || strcmp(рп, "0") != 0 ||
      !надвое_вывода(рл, "минус", &а, &б) || strcmp(а, т) != 0 || strcmp(б, т) != 0)
    return fmt("шаг %ld: Кон3 — шаг %ld заключает «%s», а нужно «( %s минус %s ) равен 0»",
               ш->номер, ш->из1, о1, т, т);
  return (char *)"";
}

static char *правило_кон2(ШагВывода *ш, ШагВывода *преж, char *ф, char *о1, char *о2) {
  char *лев, *ц, *вн, *рл, *рп, *а, *б; ШагВывода *г;
  г = &преж[ш->из1 - 1];
  if (strcmp(г->правило, "ГипО") != 0)
    return fmt("шаг %ld: Кон2 — шаг %ld не гипотеза оговорки «ГипО ⟨( Т минус Т ) равен 0⟩ сам»", ш->номер, ш->из1);
  if (!надвое_вывода(ф, "или", &лев, &ц) || !начинается(лев, "не "))
    return fmt("шаг %ld: Кон2 заключает «не ( ( Т минус Т ) равен 0 ) или Ц», а у «%s» такого вида нет", ш->номер, ф);
  вн = ужать(слова_после(лев, 1));
  if (!надвое_вывода(вн, "равен", &рл, &рп) || strcmp(рп, "0") != 0 ||
      !надвое_вывода(рл, "минус", &а, &б) || strcmp(а, б) != 0)
    return fmt("шаг %ld: Кон2 — «%s» не оговорка о конечности одного терма «( Т минус Т ) равен 0»", ш->номер, вн);
  if (strcmp(вн, о1) != 0)
    return fmt("шаг %ld: Кон2 — гипотеза шага %ld «%s» не есть оговорка цели «%s»", ш->номер, ш->из1, о1, вн);
  if (strcmp(ц, о2) != 0)
    return fmt("шаг %ld: Кон2 — под оговоркой выведено «%s» (шаг %ld), а правый дизъюнкт есть «%s»", ш->номер, о2, ш->из2, ц);
  if (преж[ш->из2 - 1].откр & ~г->откр)
    return fmt("шаг %ld: Кон2 — шаг %ld стоит и на гипотезе шага %ld, а снимается только гипотеза шага %ld",
               ш->номер, ш->из2, младшая_гипотеза(преж[ш->из2 - 1].откр & ~г->откр), ш->из1);
  ш->откр &= ~г->откр; г->снята = 1;
  return (char *)"";
}

static char *правило_цел1(ШагВывода *ш, char *ф, char *о1) {
  char *т, *к, *рл, *рп, *мера = NULL, *а, *б;
  if (!надвое_вывода(ф, ":", &т, &к) || strcmp(к, "цел") != 0)
    return fmt("шаг %ld: Цел1 заключает «Т : цел», а у «%s» такого вида нет", ш->номер, ф);
  if (надвое_вывода(о1, "равен", &рл, &рп)) мера = strcmp(рп, "0") == 0 ? рл : strcmp(рл, "0") == 0 ? рп : NULL;
  if (мера && надвое_вывода(мера, "плюс", &а, &б) && strcmp(б, "0") == 0) мера = а;
  if (!мера || !надвое_вывода(мера, "остаток от", &а, &б) || strcmp(б, "1") != 0 || strcmp(а, т) != 0)
    return fmt("шаг %ld: Цел1 — шаг %ld заключает «%s», а нужно «( %s остаток от 1 ) равен 0»"
               " (с прибавкой «плюс 0» или без, нулём справа или слева)", ш->номер, ш->из1, о1, т);
  return (char *)"";
}

static char *правило_цел2(ШагВывода *ш, Сп строки, Сп обяз, char *ф, char *исх) {
  char *т, *к;
  if (!надвое_вывода(ф, ":", &т, &к) || strcmp(к, "цел") != 0 || !имя_вывода(т))
    return fmt("шаг %ld: Цел2 заключает «ИМЯ : цел», а у «%s» такого вида нет", ш->номер, ф);
  if (!объявлен_точным(строки, исх, т))
    return fmt("шаг %ld: Цел2 — строка %ld не объявляет «%s» типом точной сетки", ш->номер, ш->строка, т);
  if (!есть_обязательство(обяз, т, ф, ш->строка))
    return fmt("шаг %ld: Цел2 — под утверждением нет строки «обязательство вход «%s» ⟨%s⟩ строка %ld»: "
               "целость довода держится на обязательстве зовущего, а оно не названо", ш->номер, т, ф, ш->строка);
  return (char *)"";
}

static char *правило_разв2(ШагВывода *ш, Сп строки, const char *чья, char *ф, char *о1, char *исх) {
  long a, b; char *тело, *подставлено;
  a = блок_функции(строки, чья, &b);
  if (a < 1)
    return fmt("шаг %ld: Разв2 — функции «%s» в исходнике нет", ш->номер, чья);
  тело = тело_без_пуст(строки, a, b);
  if (!*тело)
    return fmt("шаг %ld: Разв2 — тело функции «%s» не читается одним термом", ш->номер, чья);
  /* Ведомость зовёт Разв2 развёрткой ПЛОСКОГО определения: тела с вызовом
     здесь нет, и граница названа вслух, а не оставлена молчанием. */
  if (содержит(тело, "» от "))
    return fmt("шаг %ld: Разв2 берёт плоское тело, а тело функции «%s» зовёт другую", ш->номер, чья);
  if (strcmp(терм(исх), тело) != 0)
    return fmt("шаг %ld: Разв2 — строка %ld не есть тело функции «%s»", ш->номер, ш->строка, чья);
  /* Тело встаёт под связыватели ЦЕЛИ, и имя, связанное в цели, не смеет быть
     свободным в теле: цель «для всех э из [1, 2] : не ( э больше результат )»
     при теле «э» дала бы «не ( э больше э )» о СВЯЗАННОМ э, а обещано о
     доводе — при доводе 0 обещание ложно (аудит 2844, подделка «Себя»).
     Lean: приёмка «Разв2», `захват?`. */
  if (захват(ф, "результат", тело))
    return fmt("шаг %ld: Разв2 — тело «%s» под связывателем цели «%s»: подстановка захватила бы имя",
               ш->номер, тело, ф);
  подставлено = терм(вставить_вместо(ф, "результат", тело));
  if (strcmp(подставлено, о1) != 0)
    return fmt("шаг %ld: Разв2 — заключение по телу есть «%s», а шаг %ld заключает «%s»",
               ш->номер, подставлено, ш->из1, о1);
  return (char *)"";
}

static char *правило_разв1_список(ШагВывода *ш, Сп строки, const char *чья, char *ф, char *о1) {
  long a, b, где, ци; char *что = (char *)"", *тело = (char *)"", *г, *х, *хв; int выписан; Сп члены;
  if (ш->вид != ОСН_ИЗ1_СТРОКА)
    return fmt("шаг %ld: Разв1 берёт посылку и строку разбора — основание обязано быть «из N строка M»", ш->номер);
  a = блок_функции(строки, чья, &b);
  где = a < 1 ? 0 : строка_разбора(строки, a, b, &что);
  if (где < 1 || где != ш->строка)
    return fmt("шаг %ld: Разв1 — строка %ld не есть строка «разбор Л» тела функции «%s»", ш->номер, ш->строка, чья);
  члены = члены_списка_вывода(терм(что), &выписан);
  if (!выписан)
    return fmt("шаг %ld: Разв1 берёт разбор ВЫПИСАННОГО списка, а разбирается «%s»", ш->номер, терм(что));
  if (!члены.n) {
    ци = найти_случай(строки, где, b, "пусто");
    if (ци >= 0) тело = тело_случая(строки, ци, b);
  } else if ((ци = случай_звена(строки, где, b, &г, &х)) >= 0) {
    хв = хвост_списка(члены);
    тело = тело_случая(строки, ци, b);
    /* Члены встают в тело ветви: имя образца среди самих членов — это
       неоднозначность, а связыватель ветви над именем, свободным в члене, —
       захват (аудит 2844, та же порода, что у Разв2 и Разв3). */
    if (есть_терм(члены.e[0], х) || есть_терм(хв, г) ||
        захват(тело, г, члены.e[0]) || захват(тело, х, хв))
      return fmt("шаг %ld: Разв1 — имя образца «%s»/«%s» стоит и среди членов списка либо ветвь связывает имя члена: подстановка неоднозначна", ш->номер, г, х);
    if (*тело) тело = терм(вставить_вместо(вставить_вместо(тело, г, члены.e[0]), х, хв));
  }
  if (!*тело)
    return fmt("шаг %ld: Разв1 — у разбора на строке %ld нет ветви %s либо её тело не читается одним термом",
               ш->номер, где, члены.n ? "звена «случай Г и Х»" : "«случай пусто»");
  if (strcmp(терм(вставить_вместо(ф, "результат", тело)), о1) != 0)
    return fmt("шаг %ld: Разв1 — заключение по ветви есть «%s», а шаг %ld заключает «%s»",
               ш->номер, терм(вставить_вместо(ф, "результат", тело)), ш->из1, о1);
  return (char *)"";
}

static char *правило_гипотезы(ШагВывода *ш, const char *имя, char *ф, char *исх) {
  char *л = (char *)""; char *п = (char *)"";
  if (strcmp(имя, "ГипД") == 0) {
    char *доп;
    доп = допущение_строки(исх);
    if (!доп)
      return fmt("шаг %ld: ГипД — строка %ld не есть допущение «требует «имя» формула»", ш->номер, ш->строка);
    if (!надвое_вывода(доп, "или", &л, &п))
      return fmt("шаг %ld: ГипД — допущение строки %ld «%s» не дизъюнкция двух половин", ш->номер, ш->строка, доп);
    if (strcmp(ф, л) != 0 && strcmp(ф, п) != 0)
      return fmt("шаг %ld: ГипД — «%s» не половина дизъюнкции строки %ld «%s»", ш->номер, ф, ш->строка, доп);
  }
  ш->откр = 1ULL << (ш->номер - 1);
  return (char *)"";
}


static char *правило_или(ШагВывода *ш, const char *имя, char *ф, char *о1) {
  char *л = (char *)""; char *п = (char *)"";
  int левая = strcmp(имя, "Или1") == 0;
  if (!надвое_вывода(ф, "или", &л, &п))
    return fmt("шаг %ld: %s заключает дизъюнкцию «Л или П», а у «%s» такого вида нет", ш->номер, имя, ф);
  if (strcmp(о1, левая ? л : п) != 0)
    return fmt("шаг %ld: %s — посылка шага %ld «%s» не %s половина «%s»",
               ш->номер, имя, ш->из1, о1, левая ? "левая" : "правая", ф);
  return (char *)"";
}


static char *правило_и(ШагВывода *ш, const char *имя, char *ф, char *о1) {
  char *л = (char *)""; char *п = (char *)"";
  int левая = strcmp(имя, "И1") == 0;
  if (!надвое_вывода(о1, "и притом", &л, &п))
    return fmt("шаг %ld: %s — посылка шага %ld «%s» не конъюнкция «Л и притом П»", ш->номер, имя, ш->из1, о1);
  if (strcmp(ф, левая ? л : п) != 0)
    return fmt("шаг %ld: %s — «%s» не %s половина конъюнкции «%s»",
               ш->номер, имя, ф, левая ? "левая" : "правая", о1);
  return (char *)"";
}

static char *правило_выч(ШагВывода *ш, Сп строки, char *ф) {
  if (!половина_закрыта(ф, строки, 0, NULL))
    return fmt("шаг %ld: Выч — половина «%s» замкнутым счётом не закрывается", ш->номер, ф);
  return (char *)"";
}

static char *правило_пр1(ШагВывода *ш, char *о1, char *о2) {
  char *е, *г, *бл, *бп;
  if (!строгий_вывода(о1, &е, &г) || !надвое_вывода(о1, "меньше", &е, &г) ||
      !надвое_вывода(о2, "не больше", &бл, &бп) || strcmp(бл, г) != 0 || strcmp(бп, е) != 0)
    return fmt("шаг %ld: Пр1 — посылки «%s» и «%s» не пара «А меньше Б», «Б не больше А»: они совместны",
               ш->номер, о1, о2);
  return (char *)"";
}

static char *правило_меры(ШагВывода *ш, Сп строки, const char *имя, char *ф, char *о1) {
  char *было, *стало, *вн, *э, *л, *ждём = NULL;
  if (!сторона_переписана(о1, ф, &было, &стало) || !начинается(стало, "длина "))
    return fmt("шаг %ld: %s — «%s» не посылка шага %ld с одной стороной, переписанной мерой", ш->номер, имя, ф, ш->из1);
  вн = ужать(слова_после(стало, 1));
  if (strcmp(имя, "М1") == 0 && (начинается(вн, "добавить ") || начинается(вн, "приписать ")) &&
      надвое_вывода(слова_после(вн, 1), "к", &э, &л))
    ждём = fmt("( длина %s ) плюс 1", в_скобки(л));
  if (strcmp(имя, "М2") == 0) ждём = мера_свёртки(вн, строки);
  if (!ждём || strcmp(терм(ждём), терм(было)) != 0)
    return fmt("шаг %ld: %s — у «%s» мера не та или шаг свёртки растит не ровно на один: стоит «%s»%s",
               ш->номер, имя, стало, было, ждём ? fmt(", а по правилу «%s»", терм(ждём)) : "");
  return (char *)"";
}

static char *правило_поля(ШагВывода *ш, char *ф, char *о1) {
  char *было, *стало, *т, *сл, *кон; Сп поля; int i;
  if (!сторона_переписана(о1, ф, &было, &стало) || !(т = strstr(стало, " .«")))
    return fmt("шаг %ld: К↑ — «%s» не посылка шага %ld со стороной-полем «( … ) .«п»»", ш->номер, ф, ш->из1);
  while ((сл = strstr(т + 1, " .«")) != NULL) т = сл;
  кон = ужать(копия(стало, (size_t)(т - стало)));
  поля = разделить_сверху(справа_от(кон, "с"), "и");
  for (i = 0; начинается(кон, "вариант «") && i < поля.n; i++)
    if (strcmp(как_слово(ужать(слева_от(поля.e[i], "равным"))), т + 2) == 0)
      return strcmp(терм(справа_от(поля.e[i], "равным")), терм(было)) == 0 ? (char *)""
           : fmt("шаг %ld: К↑ — поле %s конструктора равно «%s», а стоит «%s»", ш->номер, т + 2,
                 терм(справа_от(поля.e[i], "равным")), было);
  return fmt("шаг %ld: К↑ — «%s» не выписанный конструктор с полем %s", ш->номер, кон, т + 2);
}

static char *правило_разв3(ШагВывода *ш, Сп строки, const char *чья, char *ф, char *о1) {
  long a, b, i; char *г, *тело, *вх, *хв; Сп пар;
  г = хозяин_строки(строки, ш->строка); a = блок_функции(строки, г, &b);
  тело = a < 1 ? (char *)"" : тело_без_пуст(строки, a, b);
  if (!*тело || strcmp(терм(как_читает_язык(строка_по_номеру(строки, ш->строка))), тело) != 0)
    return fmt("шаг %ld: Разв3 — строка %ld не есть тело функции «%s» одной строкой", ш->номер, ш->строка, г);
  if (strcmp(г, чья) == 0 && !захват(ф, "результат", тело) &&
      strcmp(терм(вставить_вместо(ф, "результат", тело)), о1) == 0) return (char *)"";
  if (strcmp(г, чья) == 0 || содержит(тело, "» от "))
    return fmt("шаг %ld: Разв3 — %s", ш->номер, strcmp(г, чья) == 0 ? "тело на месте «результат» не даёт посылки"
               : "тело вызванной зовёт другую, а разворачивается только плоское");
  пар = доводы_функции(строки, г).голые; вх = fmt("«%s» от ", г);
  for (хв = strstr(ф, вх); хв; хв = strstr(хв + 1, вх)) {
    char *за = хв + strlen(вх), *т = тело, *пре = копия(ф, (size_t)(хв - ф)); long гл = 0, к; Сп дов; int чисто;
    for (к = 0; за[к] && (за[к] != ')' || гл > 0); к++) гл += (за[к] == '(') - (за[к] == ')');
    дов = доводы_вызова(копия(за, (size_t)к)); чисто = 1;
    /* ДОВОДЫ ВСТАЮТ НА МЕСТА ПАРАМЕТРОВ РАЗОМ: сперва каждый параметр
       помечается своим номером, и лишь потом метки меняются на доводы. По
       одному выходила подмена: «Разность» от б и а при теле «а минус б» и
       парах а := б, б := а давала «а минус а» вместо «б минус а» — при а = 0,
       б = 1 это 0 против 1, и ложное обещание проходило (аудит 2844,
       подделка «Разность»). Заодно спрашивается захват: тело не смеет
       связывать имя, свободное в доводе. Lean: «Разв3-терм», ловушка 54. */
    for (i = 0; дов.n == пар.n && i < пар.n; i++) {
      чисто = чисто && !захват(тело, пар.e[i], дов.e[i]);
      т = вставить_вместо(заменить(т, fmt("%s.«", пар.e[i]), fmt("%s .«", пар.e[i])), пар.e[i], fmt("§%ld", i));
    }
    for (i = 0; дов.n == пар.n && i < пар.n; i++) т = вставить_вместо(т, fmt("§%ld", i), дов.e[i]);
    if (дов.n == пар.n && !чисто)
      return fmt("шаг %ld: Разв3 — тело «%s» вызванной «%s» связывает имя, свободное в доводе: подстановка захватила бы имя",
                 ш->номер, тело, г);
    /* вызов, уже стоящий в паре скобок, получает тело без второй пары */
    if (дов.n == пар.n && то_же_отношение(терм(fmt(начинается(за + к, ")") && strlen(пре) > 1 && пре[strlen(пре) - 2] == '('
                                          ? "%s%s %s" : "%s( %s ) %s", пре, т, за + к)), о1))
      return (char *)"";
  }
  return fmt("шаг %ld: Разв3 — ни один вызов «%s» в «%s» не развёртывается в посылку шага %ld «%s»",
             ш->номер, г, ф, ш->из1, о1);
}

static char *правило_разв1_вариант(ШагВывода *ш, char *ф, char *о1) {
  Сп ч = разделить_сверху(ф, "случай"), поля; char *кон, *в; int i, j, k;
  кон = ч.n > 1 ? ужать(слова_после(ужать(ч.e[0]), 1)) : (char *)"";
  if (ч.n < 2 || !начинается(ужать(ч.e[0]), "разбор ") || !начинается(кон, "вариант «"))
    return fmt("шаг %ld: Разв1 «из N» берёт разбор выписанного конструктора, а заключено «%s»", ш->номер, ф);
  в = в_ёлочках(кон, 1); поля = разделить_сверху(справа_от(кон, "с"), "и");
  for (i = 1; i < ч.n; i++) {
    char *обр = слева_от(ч.e[i], "то"), *ц = справа_от(ч.e[i], "то"); Сп св;
    if (!начинается(обр, "вариант «") || strcmp(в_ёлочках(обр, 1), в) != 0) continue;
    св = разделить_сверху(справа_от(обр, "с"), "и");
    for (j = 0; j < св.n && содержит(обр, " с "); j++)
      for (k = 0; k < поля.n; k++)
        if (strcmp(как_слово(ужать(слева_от(поля.e[k], "равным"))), как_слово(ужать(слева_от(св.e[j], "как")))) == 0)
          ц = вставить_вместо(ц, ужать(справа_от(св.e[j], "как")), ужать(справа_от(поля.e[k], "равным")));
    return strcmp(терм(ц), о1) == 0 ? (char *)""
         : fmt("шаг %ld: Разв1 — ветвь «%s» даёт «%s», а шаг %ld заключает «%s»", ш->номер, в, терм(ц), ш->из1, о1);
  }
  return fmt("шаг %ld: Разв1 — у разбора нет ветви варианта «%s»", ш->номер, в);
}

static char *семейство_р(ШагВывода *ш, ШагВывода *преж, Сп строки, const char *чья, const char *имя,
                         char *ф, char *о1, char *о2, char *исх) {
  char *л = (char *)""; char *п = (char *)"";
  /* Р3 (и Р2 — то же сличение, выбор условия — дело ядра): условие В,
     подставленное в Ф литералом «да», даёт половину о1, литералом «нет» —
     половину о2; обе замкнуты (Выч) — значит Ф верна при любом значении В.
     В НЕ ищется спуском: он ВОССТАНАВЛИВАЕТСЯ из первого расхождения Ф и о1
     (сбалансированный кусок Ф, на месте которого в о1 стоит «да») и затем
     СЛИЧАЕТСЯ: `вставить_вместо` — та же двухпроходная замена, что у Разв2,
     поэтому «( не да ) или да», а не «( не ( да ) ) или ( да )». Граница:
     посылки — только шаги Выч; кусок не совпал — отказ, а не подбор другого. */
  if (strcmp(имя, "Р3") == 0 || strcmp(имя, "Р2") == 0) {
    long i, j, гл = 0; char *в, *да, *нет;
    if (strcmp(преж[ш->из1 - 1].правило, "Выч") != 0 || strcmp(преж[ш->из2 - 1].правило, "Выч") != 0)
      return fmt("шаг %ld: %s — половины (шаги %ld и %ld) обязаны быть выведены правилом Выч",
                 ш->номер, имя, ш->из1, ш->из2);
    for (i = 0; ф[i] && ф[i] == о1[i]; i++) ;
    if (!ф[i] || strncmp(о1 + i, "да", strlen("да")) != 0)
      return fmt("шаг %ld: %s — на месте первого расхождения «%s» с половиной «%s» стоит не «да»",
                 ш->номер, имя, ф, о1);
    if (ф[i] == '(') { for (j = i; ф[j]; j++) { if (ф[j] == '(') гл++; else if (ф[j] == ')' && --гл == 0) { j++; break; } } }
    else for (j = i; ф[j]; j++)
      if (начинается(ф + j, " )") || начинается(ф + j, " то ") || начинается(ф + j, " иначе ") ||
          начинается(ф + j, " или ") || начинается(ф + j, " и притом ")) break;
    в = ужать(копия(ф + i, (size_t)(j - i)));
    да = терм(вставить_вместо(ф, в, "да")); нет = терм(вставить_вместо(ф, в, "нет"));
    if (!*в || strcmp(да, о1) != 0)
      return fmt("шаг %ld: %s — условие «%s» на «да» даёт «%s», а шаг %ld заключает «%s»",
                 ш->номер, имя, в, да, ш->из1, о1);
    if (strcmp(нет, о2) != 0)
      return fmt("шаг %ld: %s — условие «%s» на «нет» даёт «%s», а шаг %ld заключает «%s»",
                 ш->номер, имя, в, нет, ш->из2, о2);
    return (char *)"";
  }
  /* Р1 — ОХРАНА: под гипотезой У (шаг H, «ГипО ⟨У⟩ сам») выведено Ц (шаг M),
     и ни на чём, кроме H, шаг M не стоит; тогда «если У то Ц иначе да» верно
     безусловно: при истинной У — Ц, при ложной — литерал «да». Половина
     «условие ложно» не печатается: она и есть этот литерал, и ветвь «иначе»
     сличается с ним знак в знак. Граница: любая иная ветвь «иначе» — отказ. */
  if (strcmp(имя, "Р1") == 0) {
    char *у, *ц, *б; ШагВывода *г;
    г = &преж[ш->из1 - 1];
    if (strcmp(г->правило, "ГипО") != 0)
      return fmt("шаг %ld: Р1 — шаг %ld не гипотеза охраны «ГипО ⟨У⟩ сам» (порядок «из H M» фиксирован)",
                 ш->номер, ш->из1);
    if (!разрез_выбора(ф, &у, &ц, &б))
      return fmt("шаг %ld: Р1 заключает «если У то Ц иначе да», а вида выбора у «%s» нет", ш->номер, ф);
    if (strcmp(ужать(б), "да") != 0)
      return fmt("шаг %ld: Р1 — ветвь «иначе» не литерал «да», а «%s»: половина «условие ложно» не тривиальна",
                 ш->номер, ужать(б));
    if (strcmp(ужать(у), о1) != 0)
      return fmt("шаг %ld: Р1 — гипотеза шага %ld «%s» не есть охрана цели «%s»", ш->номер, ш->из1, о1, ужать(у));
    if (strcmp(ужать(ц), о2) != 0)
      return fmt("шаг %ld: Р1 — под охраной выведено «%s» (шаг %ld), а ветвь «то» есть «%s»",
                 ш->номер, о2, ш->из2, ужать(ц));
    if (преж[ш->из2 - 1].откр & ~г->откр)
      return fmt("шаг %ld: Р1 — шаг %ld стоит и на гипотезе шага %ld, а снимается только гипотеза шага %ld",
                 ш->номер, ш->из2, младшая_гипотеза(преж[ш->из2 - 1].откр & ~г->откр), ш->из1);
    ш->откр &= ~г->откр; г->снята = 1;
    return (char *)"";
  }
  /* Р4 — СЛУЧАИ ДИЗЪЮНКЦИИ: допущение строки N есть «Л или П»; шаг M1 вывел Ц
     ровно под гипотезой Л (одной), шаг M2 — ровно под П (другой); Ц верно
     безусловно, потому что одна из половин истинна. Граница: случай, стоящий
     на ОБЕИХ половинах, случаи на ОДНОЙ половине, гипотезы разных строк —
     отказ поимённо. */
  if (strcmp(имя, "Р4") == 0) {
    unsigned long long м1, м2; ШагВывода *а, *б; char *доп;
    if (strcmp(о1, ф) != 0 || strcmp(о2, ф) != 0)
      return fmt("шаг %ld: Р4 — оба случая обязаны заключать «%s», а шаги %ld и %ld заключают «%s» и «%s»",
                 ш->номер, ф, ш->из1, ш->из2, о1, о2);
    м1 = преж[ш->из1 - 1].откр; м2 = преж[ш->из2 - 1].откр;
    if (!м1 || !м2)
      return fmt("шаг %ld: Р4 — шаг %ld выведен без гипотезы случая: снимать нечего", ш->номер, м1 ? ш->из2 : ш->из1);
    if ((м1 & (м1 - 1)) || (м2 & (м2 - 1)))
      return fmt("шаг %ld: Р4 — случай (шаг %ld) опирается на обе половины дизъюнкции разом",
                 ш->номер, (м1 & (м1 - 1)) ? ш->из1 : ш->из2);
    if (м1 == м2)
      return fmt("шаг %ld: Р4 — оба случая (шаги %ld и %ld) стоят на одной половине дизъюнкции, вторая не разобрана",
                 ш->номер, ш->из1, ш->из2);
    а = &преж[младшая_гипотеза(м1) - 1]; б = &преж[младшая_гипотеза(м2) - 1];
    if (strcmp(а->правило, "ГипД") != 0 || strcmp(б->правило, "ГипД") != 0 || а->строка != б->строка)
      return fmt("шаг %ld: Р4 — гипотезы шагов %ld и %ld не два «ГипД» ОДНОЙ строки-дизъюнкции",
                 ш->номер, а->номер, б->номер);
    доп = допущение_строки(строка_функции(строки, а->строка, чья));
    if (!доп || !надвое_вывода(доп, "или", &л, &п) ||
        !((strcmp(терм(а->формула), л) == 0 && strcmp(терм(б->формула), п) == 0) ||
          (strcmp(терм(а->формула), п) == 0 && strcmp(терм(б->формула), л) == 0)))
      return fmt("шаг %ld: Р4 — гипотезы «%s» и «%s» не две разные половины дизъюнкции строки %ld",
                 ш->номер, терм(а->формула), терм(б->формула), а->строка);
    ш->откр = 0; а->снята = 1; б->снята = 1;
    return (char *)"";
  }
  /* Р5/Р6: при факте пустоты Л тело отдаёт ветвь «случай пусто» (Р5) либо
     начало свёртки (Р6), шага свёртки не делая. Граница: строка N — ПЕРВАЯ
     строка тела. Зеркала знака отдельным правилом нет: `строгий_вывода` и
     `порядок_вывода` читают обе записи сравнения как одну форму. */
  if (strcmp(имя, "Р5") == 0 || strcmp(имя, "Р6") == 0) {
    char *т, *пуст, *тело, *что = (char *)""; long a, b, ци;
    if (!надвое_вывода(ф, "равен", &л, &т) || strcmp(л, "результат") != 0)
      return fmt("шаг %ld: %s заключает «результат равен Т», а у «%s» такого вида нет", ш->номер, имя, ф);
    пуст = список_из_пустоты(о1);
    if (!пуст)
      return fmt("шаг %ld: %s — шаг %ld заключает «%s», а нужен факт пустоты: «пусто Л», «( длина Л ) равен 0»,"
                 " «Л равен пустой список» либо «Л равен \"\"»", ш->номер, имя, ш->из1, о1);
    a = блок_функции(строки, чья, &b);
    if (strcmp(имя, "Р6") == 0) {
      Разрез с;
      тело = a < 1 ? (char *)"" : терм(тело_функции_текст(строки, a, b));
      if (!начинается(тело, "свёртка ") || !начинается(тело, терм(исх)))
        return fmt("шаг %ld: Р6 — строка %ld не первая строка тела «свёртка Л начиная с Н как …» функции «%s»",
                   ш->номер, ш->строка, чья);
      с = разрез_по(разрез_по(тело, "как").лево, "начиная с");
      if (!с.есть)
        return fmt("шаг %ld: Р6 — у свёртки «%s» нет «начиная с Н как»", ш->номер, тело);
      if (strcmp(ужать(слова_после(с.лево, 1)), пуст) != 0)
        return fmt("шаг %ld: Р6 — факт пустоты о «%s», а свёртка идёт по «%s»: факт о другом списке",
                   ш->номер, пуст, ужать(слова_после(с.лево, 1)));
      if (strcmp(ужать(с.право), т) != 0)
        return fmt("шаг %ld: Р6 — начало свёртки «%s» не совпало с заключённым «%s»", ш->номер, ужать(с.право), т);
      return (char *)"";
    }
    if (a < 1 || строка_разбора(строки, a, b, &что) != ш->строка)
      return fmt("шаг %ld: Р5 — строка %ld не первая строка тела «разбор Л» функции «%s»", ш->номер, ш->строка, чья);
    if (strcmp(терм(голо(что)), пуст) != 0)
      return fmt("шаг %ld: Р5 — факт пустоты о «%s», а разбор идёт по «%s»: факт о другом списке",
                 ш->номер, пуст, терм(голо(что)));
    ци = найти_случай(строки, ш->строка, b, "пусто");
    if (ци < 0)
      return fmt("шаг %ld: Р5 — в разборе «%s» нет ветви «случай пусто»", ш->номер, пуст);
    тело = тело_случая(строки, ци, b);
    if (!*тело || strcmp(тело, т) != 0)
      return fmt("шаг %ld: Р5 — ветвь «пусто» отдаёт «%s», а заключено «результат равен %s»",
                 ш->номер, *тело ? тело : "то, что сверщик одним термом не читает", т);
    return (char *)"";
  }
  return fmt("шаг %ld: правила «%s» в приёме нет — из семейства разбора написаны Р1–Р6 (без Р7: зеркало"
             " знака читают строгий_вывода/порядок_вывода)", ш->номер, имя);
}


static char *семейство_н(ШагВывода *ш, ШагВывода *преж, Сп строки, const char *чья, const char *имя,
                         char *ф, char *о1, char *о2, char *исх) {
  char *л = (char *)""; char *п = (char *)""; double з1;
  if (!надвое_вывода(ф, "не меньше", &л, &п) || strcmp(п, "0") != 0)
    return fmt("шаг %ld: %s заключает неотрицательность, а вида «Т не меньше 0» у «%s» нет",
               ш->номер, имя, ф);
  if (strcmp(имя, "Н1") == 0) {
    if (!литерал_вывода(л, &з1))
      return fmt("шаг %ld: Н1 — слева «%s», а не целый литерал не меньше нуля", ш->номер, л);
    return (char *)"";
  }
  if (strcmp(имя, "Н2") == 0) {
    char *доп;
    доп = допущение_строки(исх);
    if (!доп)
      return fmt("шаг %ld: Н2 — строка %ld не есть допущение «требует «имя» формула»", ш->номер, ш->строка);
    if (strcmp(доп, ф) != 0)
      return fmt("шаг %ld: Н2 — допущение строки %ld есть «%s», а заключено «%s»",
                 ш->номер, ш->строка, доп, ф);
    return (char *)"";
  }
  if (strcmp(имя, "Н3") == 0) {
    if (!имя_вывода(л))
      return fmt("шаг %ld: Н3 берёт только имя, а слева стоит «%s»", ш->номер, л);
    if (!объявлен_с_дном(строки, исх, л))
      return fmt("шаг %ld: Н3 — строка %ld не объявляет «%s» типом с дном", ш->номер, ш->строка, л);
    return (char *)"";
  }
  if (strcmp(имя, "Н4") == 0) {
    char *хвост;
    if (начинается(л, "длина ")) хвост = ужать(слова_после(л, 1));
    else if (начинается(л, "код символа ")) хвост = ужать(слова_после(л, 2));
    else return fmt("шаг %ld: Н4 берёт только встроенные «длина Т» и «код символа Т», а слева «%s»",
                    ш->номер, л);
    if (!простой(хвост))
      return fmt("шаг %ld: Н4 — довод встроенной формы «%s» не прост, старшинства сверщик не знает",
                 ш->номер, хвост);
    return (char *)"";
  }
  if (strcmp(имя, "Н5") == 0) {
    char *сл, *сп;
    if (!надвое_вывода(л, "плюс", &сл, &сп))
      return fmt("шаг %ld: Н5 берёт сумму ровно двух слагаемых, а слева «%s»", ш->номер, л);
    if (strcmp(о1, fmt("%s не меньше 0", сл)) != 0)
      return fmt("шаг %ld: Н5 — шаг %ld заключает «%s», а нужно «%s не меньше 0»",
                 ш->номер, ш->из1, о1, сл);
    if (strcmp(о2, fmt("%s не меньше 0", сп)) != 0)
      return fmt("шаг %ld: Н5 — шаг %ld заключает «%s», а нужно «%s не меньше 0»",
                 ш->номер, ш->из2, о2, сп);
    return (char *)"";
  }
  /* Н9 (строка ведомости): КВАДРАТ КОНЕЧНОГО неотрицателен — обе стороны
     умножения один и тот же терм знак в знак, и терм КОНЕЧЕН (посылка
     семейства Кон). Конечность обязательна: у не-числа произведение есть
     не-число, и «не-число не меньше 0» ложно. */
  if (strcmp(имя, "Н9") == 0) {
    char *мл, *мп, *ол, *оп;
    if (ш->вид != ОСН_ИЗ1 || !надвое_вывода(л, "умножить на", &мл, &мп) || strcmp(мл, мп) != 0)
      return fmt("шаг %ld: Н9 берёт «Т умножить на Т» одним термом обеими сторонами при основании «из N»,"
                 " а слева «%s»", ш->номер, л);
    if (!надвое_вывода(о1, ":", &ол, &оп) || strcmp(ол, мл) || strcmp(оп, "кон") ||
        !начинается(преж[ш->из1 - 1].правило, "Кон"))
      return fmt("шаг %ld: Н9 — шаг %ld заключает «%s», а нужно «%s : кон» правилом семейства Кон", ш->номер, ш->из1, о1, мл);
    return (char *)"";
  }
  /* Н12 (ADR-0032, задача 1403): разность под записанным порядком. Посылки —
     дно и потолок вычитаемого (оно лежит в [0, К]); порядок «П не больше Л»
     (либо зеркало «Л не меньше П») обязан стоять строкой `требует` этой же
     функции и читается с исходника, как допущение у Н2. Без потолка П = Л = +∞
     даёт не-число, без дна — П = Л = −∞; конечность уменьшаемого не нужна. */
  if (strcmp(имя, "Н12") == 0) {
    char *сл, *сп, *к, *кк, *е, *г, *доп; long fa, fb, j; int порядок = 0;
    if (!надвое_вывода(л, "минус", &сл, &сп))
      return fmt("шаг %ld: Н12 берёт разность ровно двух частей, а слева «%s»", ш->номер, л);
    if (strcmp(о1, fmt("%s не меньше 0", сп)) != 0)
      return fmt("шаг %ld: Н12 — шаг %ld заключает «%s», а нужно «%s не меньше 0»", ш->номер, ш->из1, о1, сп);
    if (!надвое_вывода(о2, "не больше", &к, &кк) || strcmp(к, сп) != 0 || !литерал_вывода(кк, &з1))
      return fmt("шаг %ld: Н12 — шаг %ld заключает «%s», а нужно «%s не больше ⟨конечный литерал⟩»", ш->номер, ш->из2, о2, сп);
    fa = блок_функции(строки, чья, &fb);
    for (j = fa; fa >= 1 && j < fb; j++)
      if ((доп = допущение_строки(как_читает_язык(часть(строки, j)))) && порядок_вывода(доп, &е, &г) &&
          strcmp(е, сп) == 0 && strcmp(г, сл) == 0) порядок = 1;
    if (!порядок)
      return fmt("шаг %ld: Н12 — у функции «%s» нет допущения «%s не больше %s» (ни зеркала «%s не меньше %s»): "
                 "порядок не записан, и разность неотрицательной не выводится", ш->номер, чья, сп, сл, сл, сп);
    return (char *)"";
  }
  /* Н10 (ADR-0029): остаток несёт знак делимого — у конечного целого Т ≥ 0
     и ненулевого целого делителя он не меньше нуля. */
  if (strcmp(имя, "Н10") == 0) {
    char *т, *дел; double z;
    if (!надвое_вывода(л, "остаток от", &т, &дел) || !литерал_вывода(дел, &z) || z == 0)
      return fmt("шаг %ld: Н10 берёт «Т остаток от Д» при ненулевом целом литерале Д, а слева «%s»", ш->номер, л);
    if (!целое_неотрицательное(преж[ш->из1 - 1].правило, о1, о2, т))
      return fmt("шаг %ld: Н10 — шаги %ld и %ld обязаны дать «%s : цел» (Цел1 либо Цел2) и «%s не меньше 0», а дают «%s» и «%s»",
                 ш->номер, ш->из1, ш->из2, т, т, о1, о2);
    return (char *)"";
  }
  /* Н7: шаг свёртки проверяется ФОРМОЙ тела (`шаг_счёта`), без поиска. Имена
     накопителя и элемента обязаны быть различны — иначе накопитель и есть
     элемент, и знак его не держится. */
  if (strcmp(имя, "Н7") == 0) {
    Разрез до_шага, до_имён, начало, имена; char *акк, *эл;
    до_шага = разрез_по(л, "→"); до_имён = разрез_по(до_шага.лево, "как");
    начало = разрез_по(до_имён.лево, "начиная с"); имена = разрез_по(до_имён.право, "и");
    if (!начинается(л, "свёртка ") || !до_шага.есть || !до_имён.есть || !начало.есть || !имена.есть)
      return fmt("шаг %ld: Н7 берёт «свёртка Л начиная с Н как А и Э → Ш», а слева «%s»", ш->номер, л);
    акк = ужать(имена.лево); эл = ужать(имена.право);
    if (!имя_вывода(акк) || !имя_вывода(эл) || strcmp(акк, эл) == 0)
      return fmt("шаг %ld: Н7 — имена накопителя «%s» и элемента «%s» обязаны быть различными именами", ш->номер, акк, эл);
    if (!шаг_дна(о1, ужать(начало.право), "0"))
      return fmt("шаг %ld: Н7 — шаг %ld заключает «%s», а нужно «%s не меньше 0»", ш->номер, ш->из1, о1, ужать(начало.право));
    if (!шаг_счёта(до_шага.право, акк))
      return fmt("шаг %ld: Н7 — шаг свёртки «%s» не накопитель и не накопитель плюс литерал: знак не держится",
                 ш->номер, ужать(до_шага.право));
    return (char *)"";
  }
  /* Н8 (строка таблицы; второй способ): один сомножитель — положительный целый литерал
     не выше 2⁵³−1 (он лежит в (0, кон]), второй не меньше нуля (посылка). «0 умножить
     на +∞» так исключено: литерал не ноль и конечен. */
  if (strcmp(имя, "Н8") == 0) {
    char *мл, *мп, *второй = NULL; double z;
    if (!надвое_вывода(л, "умножить на", &мл, &мп))
      return fmt("шаг %ld: Н8 берёт произведение ровно двух сомножителей, а слева «%s»", ш->номер, л);
    if (литерал_вывода(мп, &z) && z > 0 && z <= К_ПРЕДСТ_ЧИСЛО) второй = мл;
    else if (литерал_вывода(мл, &z) && z > 0 && z <= К_ПРЕДСТ_ЧИСЛО) второй = мп;
    /* Тот же отрезок (0,кон] даёт и пара НАЗВАННЫХ допущений функции — «Т больше К»
       при К не ниже нуля и «Т не больше ⟨литерал⟩»: строгую положительность не даёт
       ни один объявленный тип, только названный факт (колонка 12 ведомости). */
    else if (в_строго_положительном_отрезке(строки, чья, мл)) второй = мп;
    else if (в_строго_положительном_отрезке(строки, чья, мп)) второй = мл;
    if (!второй)
      return fmt("шаг %ld: Н8 — ни «%s», ни «%s» не лежит в (0,кон] ни литералом, ни парой допущений"
                 " «больше К» и «не больше ⟨литерал⟩»: «0 умножить на +∞» не исключено",
                 ш->номер, мл, мп);
    if (!шаг_дна(о1, второй, "0"))
      return fmt("шаг %ld: Н8 — шаг %ld заключает «%s», а нужно «%s не меньше 0»", ш->номер, ш->из1, о1, второй);
    return (char *)"";
  }
  return fmt("шаг %ld: правила «%s» в приёме нет — из семейства неотрицательности написаны Н1–Н5, Н7–Н10, Н12",
             ш->номер, имя);
}


  /* Семейство Пред. Стоит РАНЬШЕ семейства П: «Пред1» начинается с той же буквы. */
static char *семейство_пред(ШагВывода *ш, Сп строки, Сп обяз, const char *имя, char *ф, char *исх) {
  char *им;
  if (!помещается_вывода(ф, &им))
    return fmt("шаг %ld: %s заключает представимость, а вида «ИМЯ помещается» у «%s» нет",
               ш->номер, имя, ф);
  if (strcmp(имя, "Пред1") == 0) {
    if (!объявлен_точным(строки, исх, им))
      return fmt("шаг %ld: Пред1 — строка %ld не объявляет «%s» типом точной сетки", ш->номер, ш->строка, им);
    /* Представимость держится не на типе, а на обязательстве зовущего: строка
       обязательства под тем же утверждением, с тем же именем, той же строкой
       объявления и формулой потолка — строка целости того же довода (Цел2) её
       не заменяет. Саму строку переигрывает `сверить_обязательства`. */
    if (!есть_обязательство(обяз, им, fmt("%s не больше %s", им, К_ПРЕДСТ), ш->строка))
      return fmt("шаг %ld: Пред1 — под утверждением нет строки «обязательство вход «%s» ⟨%s не больше %s⟩ строка %ld»: "
                 "представимость довода держится на обязательстве зовущего, а оно не названо",
                 ш->номер, им, им, К_ПРЕДСТ, ш->строка);
    return (char *)"";
  }
  return fmt("шаг %ld: правила «%s» в приёме нет — из семейства представимости написан Пред1",
             ш->номер, имя);
}


static char *семейство_п(ШагВывода *ш, ШагВывода *преж, const char *имя, char *ф,
                         char *о1, char *о2, char *исх) {
  char *л = (char *)""; char *п = (char *)""; double з1; double з2;
  if (!надвое_вывода(ф, "не больше", &л, &п))
    return fmt("шаг %ld: %s заключает потолок, а вида «Т не больше К» у «%s» нет", ш->номер, имя, ф);
  if (!литерал_вывода(п, &з1))
    return fmt("шаг %ld: %s — потолок «%s» не целый литерал", ш->номер, имя, п);
  if (strcmp(имя, "П1") == 0) {
    if (!литерал_вывода(л, &з2))
      return fmt("шаг %ld: П1 — слева «%s», а не целый литерал", ш->номер, л);
    if (з2 > з1)
      return fmt("шаг %ld: П1 — литерал «%s» больше потолка «%s»", ш->номер, л, п);
    return (char *)"";
  }
  if (strcmp(имя, "П2") == 0) {
    char *доп, *дл, *дп;
    if (ш->вид != ОСН_СТРОКА && ш->вид != ОСН_ИЗ1)
      return fmt("шаг %ld: П2 опирается на допущение — основание обязано быть «строка N» либо «из M»", ш->номер);
    доп = ш->вид == ОСН_ИЗ1 ? о1 : допущение_строки(исх);
    if (!доп)
      return fmt("шаг %ld: П2 — строка %ld не есть допущение «требует «имя» формула»", ш->номер, ш->строка);
    /* «равен» и «равно» — одно и то же слово языка в двух написаниях, и
       допущения в дереве написаны обоими (`abilities`: «требует «н равно
       десяти» н равно 10»). Приём, знавший одно, молчал на другом. */
    if (!надвое_вывода(доп, "не больше", &дл, &дп) &&
        !надвое_вывода(доп, "равен", &дл, &дп) &&
        !надвое_вывода(доп, "равно", &дл, &дп))
      return fmt("шаг %ld: П2 — допущение «%s» не вида «Т не больше К» и не «Т равен К»", ш->номер, доп);
    if (strcmp(дл, л) != 0)
      return fmt("шаг %ld: П2 — допущение говорит о «%s», а заключение о «%s»", ш->номер, дл, л);
    if (!литерал_вывода(дп, &з2))
      return fmt("шаг %ld: П2 — граница допущения «%s» не целый литерал", ш->номер, дп);
    if (з2 > з1)
      return fmt("шаг %ld: П2 — граница допущения «%s» выше потолка «%s»", ш->номер, дп, п);
    return (char *)"";
  }
  /* П3 (6202, ADR-0025): потолок от ПОСЫЛКИ «Т помещается» (Пред1), а не от
     строки объявления. Основание «строка N» — отказ с названной причиной:
     это и есть подделка задачи — граница без посылки, которую тип «даёт». */
  if (strcmp(имя, "П3") == 0) {
    char *им;
    if (ш->вид == ОСН_СТРОКА)
      return fmt("шаг %ld: П3 — посылки нет: объявление типа (строка %ld) посылкой не является, потолок — "
                 "обязательство зовущего; основание обязано быть «из M», где шаг M — Пред1 ⟨%s помещается⟩",
                 ш->номер, ш->строка, л);
    if (ш->вид != ОСН_ИЗ1)
      return fmt("шаг %ld: П3 берёт одну посылку — основание обязано быть «из M»", ш->номер);
    if (!имя_вывода(л))
      return fmt("шаг %ld: П3 берёт только имя, а слева стоит «%s»", ш->номер, л);
    if (strcmp(преж[ш->из1 - 1].правило, "Пред1") != 0)
      return fmt("шаг %ld: П3 — шаг %ld выведен правилом «%s», а посылка П3 — представимость, правило Пред1",
                 ш->номер, ш->из1, преж[ш->из1 - 1].правило);
    if (!помещается_вывода(о1, &им) || strcmp(им, л) != 0)
      return fmt("шаг %ld: П3 — шаг %ld заключает «%s», а нужно «%s помещается»", ш->номер, ш->из1, о1, л);
    if (з1 < К_ПРЕДСТ_ЧИСЛО)
      return fmt("шаг %ld: П3 — потолок «%s» ниже К_предст %s, вложения отрезков нет",
                 ш->номер, п, К_ПРЕДСТ);
    return (char *)"";
  }
  if (strcmp(имя, "П5") == 0) {
    char *сл, *сп;
    if (!надвое_вывода(л, "минус", &сл, &сп))
      return fmt("шаг %ld: П5 берёт разность ровно двух частей, а слева «%s»", ш->номер, л);
    if (strcmp(о1, fmt("%s не больше %s", сл, п)) != 0)
      return fmt("шаг %ld: П5 — шаг %ld заключает «%s», а нужно «%s не больше %s»",
                 ш->номер, ш->из1, о1, сл, п);
    if (strcmp(о2, fmt("%s не меньше 0", сп)) != 0)
      return fmt("шаг %ld: П5 — шаг %ld заключает «%s», а нужно «%s не меньше 0»",
                 ш->номер, ш->из2, о2, сп);
    return (char *)"";
  }
  /* П6 (ADR-0029): у конечного целого Т ≥ 0 и положительного целого Д остаток
     лежит в [0, Д−1]; без целости ложно («5.5 остаток от 2» есть 1.5). */
  if (strcmp(имя, "П6") == 0) {
    char *т, *дел; double z;
    if (!надвое_вывода(л, "остаток от", &т, &дел) || !литерал_вывода(дел, &z) || z < 1)
      return fmt("шаг %ld: П6 берёт «Т остаток от Д» при положительном целом литерале Д, а слева «%s»", ш->номер, л);
    if (z - 1 > з1)
      return fmt("шаг %ld: П6 — остаток от %s доходит до %.0f, а потолок «%s» ниже", ш->номер, дел, z - 1, п);
    if (!целое_неотрицательное(преж[ш->из1 - 1].правило, о1, о2, т))
      return fmt("шаг %ld: П6 — шаги %ld и %ld обязаны дать «%s : цел» (Цел1 либо Цел2) и «%s не меньше 0», а дают «%s» и «%s»",
                 ш->номер, ш->из1, ш->из2, т, т, о1, о2);
    return (char *)"";
  }
  return fmt("шаг %ld: правила «%s» в приёме нет — из семейства потолка написаны П1, П2, П3 (из Пред1), П5, П6",
             ш->номер, имя);
}


static char *семейство_д(ШагВывода *ш, const char *имя, char *ф, char *о1, char *о2, char *исх) {
  double з1;
  char *г, *д;
  if (!порядок_вывода(ф, &д, &г))   /* «Г не меньше Д» и «Д не больше Г» — одна форма (ADR-0029) */
    return fmt("шаг %ld: %s заключает дно, а вида «Г не меньше Д» (либо «Д не больше Г») у «%s» нет",
               ш->номер, имя, ф);
  if (strcmp(имя, "Д1") == 0) {
    char *доп, *дл, *дп;
    доп = допущение_строки(исх);
    if (!доп)
      return fmt("шаг %ld: Д1 — строка %ld не есть допущение «требует «имя» формула»", ш->номер, ш->строка);
    if (!надвое_вывода(доп, "не больше", &дл, &дп))
      return fmt("шаг %ld: Д1 — допущение «%s» не вида «литерал не больше Г»", ш->номер, доп);
    if (!литерал_вывода(дл, &з1))
      return fmt("шаг %ld: Д1 — дно «%s» не конечный целый литерал", ш->номер, дл);
    if (strcmp(дп, г) != 0)
      return fmt("шаг %ld: Д1 — допущение о «%s», а дно заключено у «%s»", ш->номер, дп, г);
    if (strcmp(дл, д) != 0)
      return fmt("шаг %ld: Д1 — допущение даёт дно «%s», а заключено «%s»", ш->номер, дл, д);
    return (char *)"";
  }
  if (strcmp(имя, "Д4") == 0) {
    char *а, *б; double да, дб;
    if (!выбор_вывода(г, &а, &б))
      return fmt("шаг %ld: Д4 берёт выбор «если У то А иначе Б», а слева «%s»", ш->номер, г);
    if (!литерал_вывода(д, &з1))
      return fmt("шаг %ld: Д4 — дно выбора «%s» не целый литерал", ш->номер, д);
    if (!дно_шага(о1, а, &да))
      return fmt("шаг %ld: Д4 — шаг %ld не даёт дна ветви «то» «%s»", ш->номер, ш->из1, а);
    if (!дно_шага(о2, б, &дб))
      return fmt("шаг %ld: Д4 — шаг %ld не даёт дна ветви «иначе» «%s»", ш->номер, ш->из2, б);
    /* Заявленное дно НЕ вычисляется наименьшим из двух — оно СВЕРЯЕТСЯ: обе
       ветви обязаны стоять не ниже него. Цель тут проверяется, а не строится. */
    if (да < з1 || дб < з1)
      return fmt("шаг %ld: Д4 — заявлено дно «%s», а ветви стоят ниже его", ш->номер, д);
    return (char *)"";
  }
  if (strcmp(имя, "Д6") == 0) {
    if (!литерал_вывода(г, &з1))
      return fmt("шаг %ld: Д6 — слева «%s», а не написанное число", ш->номер, г);
    if (strcmp(г, д) != 0)
      return fmt("шаг %ld: Д6 берёт одно и то же число обеими сторонами, а стоят «%s» и «%s»",
                 ш->номер, г, д);
    return (char *)"";
  }
  /* Д5 (ADR-0029): закон монотонности. Факты «Д₁ не больше Л», «Д₂ не больше П»
     при Д₁, Д₂ ≥ 1 исключают не-число, ноль и отрицательные; точное Л·П не
     меньше Д₁·Д₂, а округление к ближайшему монотонно. Написанное дно СЛИЧАЕТСЯ с
     произведением двух написанных целых (прецедент 63ab3ce77 — сумма двух
     выписанных) и только до 2⁵³−1, где произведение точно. Нулевое дно — отказ:
     «0 умножить на +∞» есть не-число. */
  if (strcmp(имя, "Д5") == 0) {
    char *мл, *мп; double д1, д2;
    if (!надвое_вывода(г, "умножить на", &мл, &мп))
      return fmt("шаг %ld: Д5 берёт произведение ровно двух сомножителей, а стоит «%s»", ш->номер, г);
    if (!дно_литералом(о1, мл, &д1))
      return fmt("шаг %ld: Д5 — шаг %ld «%s» не даёт дна «%s» целым литералом", ш->номер, ш->из1, о1, мл);
    if (!дно_литералом(о2, мп, &д2))
      return fmt("шаг %ld: Д5 — шаг %ld «%s» не даёт дна «%s» целым литералом", ш->номер, ш->из2, о2, мп);
    if (д1 < 1 || д2 < 1)
      return fmt("шаг %ld: Д5 — дно сомножителя не строго положительно: «0 умножить на +∞» есть не-число", ш->номер);
    if (!литерал_вывода(д, &з1) || д1 * д2 > К_ПРЕДСТ_ЧИСЛО || з1 != д1 * д2)
      return fmt("шаг %ld: Д5 — заявлено дно «%s», а произведение написанных дон %.0f и %.0f есть %.0f",
                 ш->номер, д, д1, д2, д1 * д2);
    return (char *)"";
  }
  /* Д3 (ADR-0029, поправка §4): дно суммы. Факты «Д₁ не больше Л», «Д₂ не больше П»
     исключают не-число и −∞; точная сумма не меньше Д₁ + Д₂, округление к ближайшему
     монотонно, и Д₁ + Д₂ до 2⁵³−1 точно. Нулевое дно законно: у суммы нет «0·∞».
     Написанное дно СЛИЧАЕТСЯ с суммой двух написанных дон (прецедент 63ab3ce77). */
  if (strcmp(имя, "Д3") == 0) {
    char *сл, *сп; double д1, д2;
    if (!надвое_вывода(г, "плюс", &сл, &сп))
      return fmt("шаг %ld: Д3 берёт сумму ровно двух слагаемых, а стоит «%s»", ш->номер, г);
    if (!дно_литералом(о1, сл, &д1))
      return fmt("шаг %ld: Д3 — шаг %ld «%s» не даёт дна «%s» целым литералом", ш->номер, ш->из1, о1, сл);
    if (!дно_литералом(о2, сп, &д2))
      return fmt("шаг %ld: Д3 — шаг %ld «%s» не даёт дна «%s» целым литералом", ш->номер, ш->из2, о2, сп);
    if (!литерал_вывода(д, &з1) || д1 + д2 > К_ПРЕДСТ_ЧИСЛО || з1 != д1 + д2)
      return fmt("шаг %ld: Д3 — заявлено дно «%s», а сумма написанных дон %.0f и %.0f есть %.0f",
                 ш->номер, д, д1, д2, д1 + д2);
    return (char *)"";
  }
  /* ЧЕГО ЗДЕСЬ НЕТ И ПОЧЕМУ. Д2 — переход «Г неотрицательно ⟹ дно 0»: в
     формулах языка обе стороны пишутся одной и той же строкой «Г не меньше 0»,
     и шага между ними нет вовсе. */
  return fmt("шаг %ld: правила «%s» в приёме нет — из семейства дна написаны Д1, Д3, Д4, Д5, Д6",
             ш->номер, имя);
}


static char *семейство_о(ШагВывода *ш, ШагВывода *преж, const char *имя, char *ф, char *о1,
                         char *о2, char *о3, char *исх) {
  double з1;
  char *е, *г;
  if (!порядок_вывода(ф, &е, &г))
    return fmt("шаг %ld: %s заключает порядок, а вида «Е не больше Г» у «%s» нет", ш->номер, имя, ф);
  if (strcmp(имя, "О1") == 0) {
    char *доп, *дл, *дп;
    доп = допущение_строки(исх);
    if (!доп)
      return fmt("шаг %ld: О1 — строка %ld не есть допущение «требует «имя» формула»", ш->номер, ш->строка);
    if (!порядок_вывода(доп, &дл, &дп))
      return fmt("шаг %ld: О1 — допущение «%s» не о порядке", ш->номер, доп);
    if (strcmp(дл, е) != 0 || strcmp(дп, г) != 0)
      return fmt("шаг %ld: О1 — допущение даёт «%s не больше %s», а заключено «%s не больше %s»",
                 ш->номер, дл, дп, е, г);
    return (char *)"";
  }
  if (strcmp(имя, "О2") == 0) {
    char *ол, *оп;
    if (strcmp(е, г) != 0)
      return fmt("шаг %ld: О2 берёт один и тот же терм обеими сторонами, а стоят «%s» и «%s»",
                 ш->номер, е, г);
    /* Посылка — неотрицательность ЛИБО конечность. Конечность у языка своей
       формулы не имеет, и берётся она той, какая есть: «Г не больше литерал»
       либо «Г : кон» — заключение Кон3 (ведро Е), и только его. */
    if (шаг_дна(о1, г, "0")) return (char *)"";
    if (надвое_вывода(о1, "не больше", &ол, &оп) && strcmp(ол, г) == 0 &&
        литерал_вывода(оп, &з1)) return (char *)"";
    if (надвое_вывода(о1, ":", &ол, &оп) && strcmp(ол, г) == 0 && strcmp(оп, "кон") == 0 &&
        strcmp(преж[ш->из1 - 1].правило, "Кон3") == 0) return (char *)"";
    return fmt("шаг %ld: О2 — шаг %ld заключает «%s», а нужно «%s не меньше 0», «%s не больше ЛИТЕРАЛ»"
               " либо «%s : кон» (Кон3)", ш->номер, ш->из1, о1, г, г, г);
  }
  if (strcmp(имя, "О3") == 0) {
    char *а, *б;
    if (!выбор_вывода(е, &а, &б))
      return fmt("шаг %ld: О3 берёт выбор «если У то А иначе Б», а слева «%s»", ш->номер, е);
    if (!шаг_порядка(о1, а, г))
      return fmt("шаг %ld: О3 — шаг %ld заключает «%s», а нужно «%s не больше %s»",
                 ш->номер, ш->из1, о1, а, г);
    if (!шаг_порядка(о2, б, г))
      return fmt("шаг %ld: О3 — шаг %ld заключает «%s», а нужно «%s не больше %s»",
                 ш->номер, ш->из2, о2, б, г);
    return (char *)"";
  }
  if (strcmp(имя, "О4") == 0) {
    double д;
    if (!литерал_вывода(е, &з1))
      return fmt("шаг %ld: О4 берёт слева литерал, а стоит «%s»", ш->номер, е);
    if (!дно_шага(о1, г, &д))
      return fmt("шаг %ld: О4 — шаг %ld не даёт дна «%s» целым литералом", ш->номер, ш->из1, г);
    if (з1 > д)
      return fmt("шаг %ld: О4 — литерал «%s» выше дна верхней стороны", ш->номер, е);
    return (char *)"";
  }
  if (strcmp(имя, "О5") == 0) {
    char *ел, *еп, *гл, *гп;
    if (ш->вид != ОСН_ИЗ1 && ш->вид != ОСН_ИЗ3)
      return fmt("шаг %ld: О5 берёт посылку порядка «из N», а при прибавке-имени — ещё её дно и потолок: «из N M K»", ш->номер);
    if (!надвое_вывода(е, "плюс", &ел, &еп) || !надвое_вывода(г, "плюс", &гл, &гп))
      return fmt("шаг %ld: О5 — обе стороны обязаны быть суммами двух слагаемых, а стоят «%s» и «%s»",
                 ш->номер, е, г);
    /* Общая прибавка ищется в ЧЕТЫРЁХ сочетаниях позиций: узел «плюс»
       коммутативен, и жёсткая форма отвергала бы верные записи. Совпадения
       знак в знак мало: прибавка обязана быть ЧИСЛОМ. Дна ей не нужно, а
       КОНЕЧНОСТЬ обязательна — при Г = +∞ и прибавке −∞ правая сторона есть
       не-число, сравнение с ним ложно, и правило вывело бы ложь из истины
       (встречный пример в Lean: Е = −5, Г = +∞, Ш = −∞). */
    if (strcmp(еп, гп) == 0 && прибавка_числом(ш->вид, еп, о2, о3) && шаг_порядка(о1, ел, гл)) return (char *)"";
    if (strcmp(еп, гл) == 0 && прибавка_числом(ш->вид, еп, о2, о3) && шаг_порядка(о1, ел, гп)) return (char *)"";
    if (strcmp(ел, гп) == 0 && прибавка_числом(ш->вид, ел, о2, о3) && шаг_порядка(о1, еп, гл)) return (char *)"";
    if (strcmp(ел, гл) == 0 && прибавка_числом(ш->вид, ел, о2, о3) && шаг_порядка(о1, еп, гп)) return (char *)"";
    return fmt("шаг %ld: О5 — общей прибавки-ЧИСЛА (целым литералом либо именем в отрезке шагов M и K) у «%s» и «%s» нет"
               " либо шаг %ld заключает не «%s»", ш->номер, е, г, ш->из1, о1);
  }
  if (strcmp(имя, "О6") == 0) {
    char *гл, *гп;
    if (ш->вид != ОСН_ИЗ1 && ш->вид != ОСН_ИЗ3)
      return fmt("шаг %ld: О6 берёт посылку порядка «из N», а при прибавке-имени — ещё её дно и потолок: «из N M K»", ш->номер);
    if (!надвое_вывода(г, "плюс", &гл, &гп))
      return fmt("шаг %ld: О6 берёт справа сумму ровно двух слагаемых, а стоит «%s»", ш->номер, г);
    /* У прибавки спрашиваются ОБЕ границы разом: голого «плюс» без них нет.
       Обе разом даёт целый литерал, а при «из N M K» — имя с дном (шаг M) и
       потолком (шаг K); см. `прибавка_числом`. */
    if (прибавка_числом(ш->вид, гл, о2, о3) && шаг_порядка(о1, е, гп)) return (char *)"";
    if (прибавка_числом(ш->вид, гп, о2, о3) && шаг_порядка(о1, е, гл)) return (char *)"";
    return fmt("шаг %ld: О6 — прибавка не целый литерал и не имя в отрезке шагов M и K, либо шаг %ld заключает «%s», а нужен порядок «%s»",
               ш->номер, ш->из1, о1, е);
  }
  /* О8 — лист: сверяется только ФОРМА обеих сторон и то, что список отбора и
     список справа — один довод знак в знак. Условие под отбором правилу
     безразлично, и считать его не нужно. */
  if (strcmp(имя, "О8") == 0) {
    char *вн, *спр;
    if (ш->вид != ОСН_ЛИСТ || !начинается(е, "длина ") || !начинается(г, "длина "))
      return fmt("шаг %ld: О8 — лист («сам») с «длина Т» обеими сторонами, а стоят «%s» и «%s»", ш->номер, е, г);
    вн = ужать(слова_после(е, 1)); спр = ужать(слова_после(г, 1));
    if (!начинается(вн, "отфильтровать ") || strcmp(ужать(слово(вн, 2)), спр) != 0)
      return fmt("шаг %ld: О8 берёт слева «длина ( отфильтровать %s … )», а стоит «длина %s»", ш->номер, спр, вн);
    return (char *)"";
  }
  if (strcmp(имя, "О10") == 0) {
    char *е1, *г1, *е2, *г2;
    if (!порядок_вывода(о1, &е1, &г1) || !порядок_вывода(о2, &е2, &г2))
      return fmt("шаг %ld: О10 — шаги %ld и %ld заключают не порядок", ш->номер, ш->из1, ш->из2);
    if (strcmp(г1, е2) != 0)
      return fmt("шаг %ld: О10 — середина не сходится: шаг %ld кончается «%s», шаг %ld начинается «%s»",
                 ш->номер, ш->из1, г1, ш->из2, е2);
    if (strcmp(е1, е) != 0 || strcmp(г2, г) != 0)
      return fmt("шаг %ld: О10 — звенья дают «%s не больше %s», а заключено «%s не больше %s»",
                 ш->номер, е1, г2, е, г);
    return (char *)"";
  }
  /* О7 (разбор) и О9 (свёртка под длиной) читают ТЕЛО и строят узел сами;
     здесь их нет, и имя даёт названный отказ. */
  return fmt("шаг %ld: правила «%s» в приёме нет — из семейства порядка написаны"
             " О1–О6, О8 и О10", ш->номер, имя);
}


  /* Семейство СС. Стоит ДО семейства С: «СС1» начинается теми же знаками, что «С1». */
static char *семейство_сс(ШагВывода *ш, const char *имя, char *ф, char *о1, char *о2, char *исх) {
  char *л;
  if (!неубыв_вывода(ф, &л))
    return fmt("шаг %ld: %s заключает порядок соседних, а вида «Л не убывает» у «%s» нет",
               ш->номер, имя, ф);
  if (strcmp(имя, "СС1") == 0) {
    int выписан; Сп ч = члены_списка_вывода(л, &выписан);
    if (!выписан)
      return fmt("шаг %ld: СС1 берёт выписанный список, а слева «%s»", ш->номер, л);
    if (ч.n > 1)
      return fmt("шаг %ld: СС1 берёт список без пар соседей, а в «%s» членов %d",
                 ш->номер, л, ч.n);
    return (char *)"";
  }
  if (strcmp(имя, "СС2") == 0) {
    char *доп;
    доп = допущение_строки(исх);
    if (!доп)
      return fmt("шаг %ld: СС2 — строка %ld не есть допущение «требует «имя» формула»", ш->номер, ш->строка);
    if (strcmp(доп, ф) != 0)
      return fmt("шаг %ld: СС2 — допущение строки %ld есть «%s», а заключено «%s»",
                 ш->номер, ш->строка, доп, ф);
    return (char *)"";
  }
  if (strcmp(имя, "СС3") == 0) {
    char *г, *х, *голова; int пуст = 0;
    if (!к_списку_вывода(л, "приписать", &г, &х))
      return fmt("шаг %ld: СС3 берёт «приписать Г к Х», а слева «%s»", ш->номер, л);
    if (!голова_списка_вывода(х, &голова, &пуст))
      return fmt("шаг %ld: СС3 — головы хвоста «%s» по построению не видно", ш->номер, х);
    if (пуст) {
      /* У пустого хвоста пары соседей не возникает вовсе, и второй посылки
         правилу не нужно — но первая обязана стоять. */
      if (ш->вид != ОСН_ИЗ1)
        return fmt("шаг %ld: СС3 при пустом хвосте берёт одну посылку — основание обязано быть «из N»",
                   ш->номер);
      if (!шаг_неубыв(о1, х))
        return fmt("шаг %ld: СС3 — шаг %ld заключает «%s», а нужно «%s не убывает»",
                   ш->номер, ш->из1, о1, х);
      return (char *)"";
    }
    if (ш->вид != ОСН_ИЗ2)
      return fmt("шаг %ld: СС3 берёт две посылки — основание обязано быть «из N M»", ш->номер);
    if (!шаг_неубыв(о1, х))
      return fmt("шаг %ld: СС3 — шаг %ld заключает «%s», а нужно «%s не убывает»",
                 ш->номер, ш->из1, о1, х);
    if (!шаг_порядка(о2, г, голова))
      return fmt("шаг %ld: СС3 — шаг %ld заключает «%s», а нужно «%s не больше %s»",
                 ш->номер, ш->из2, о2, г, голова);
    return (char *)"";
  }
  if (strcmp(имя, "СС4") == 0) {
    char *а, *б;
    /* Ветвь «иначе» не доказывается, а ЗАКРЫТА ПРОТИВОРЕЧИЕМ: охрана выбора
       стоит допущением функции знак в знак, значит при ложной охране ложно и
       допущение — ветвь недостижима, и второй посылки не нужно. */
    if (ш->вид == ОСН_ИЗ1_СТРОКА) {
      char *у, *то, *ин, *доп = допущение_строки(исх);
      if (!разрез_выбора(л, &у, &то, &ин) || !доп || strcmp(ужать(у), доп) != 0)
        return fmt("шаг %ld: СС4 — ветвь «иначе» закрыта противоречием лишь тогда, когда «%s» есть выбор,"
                   " а его охрана стоит допущением строки %ld знак в знак", ш->номер, л, ш->строка);
      if (!шаг_неубыв(о1, ужать(то)))
        return fmt("шаг %ld: СС4 — шаг %ld заключает «%s», а нужно «%s не убывает»", ш->номер, ш->из1, о1, ужать(то));
      return (char *)"";
    }
    if (ш->вид != ОСН_ИЗ2)
      return fmt("шаг %ld: СС4 берёт две посылки («из N M») либо ветвь «то» и строку"
                 " допущения-охраны («из N строка M»)", ш->номер);
    if (!выбор_вывода(л, &а, &б))
      return fmt("шаг %ld: СС4 берёт выбор «если У то А иначе Б», а слева «%s»", ш->номер, л);
    if (!шаг_неубыв(о1, а))
      return fmt("шаг %ld: СС4 — шаг %ld заключает «%s», а нужно «%s не убывает»",
                 ш->номер, ш->из1, о1, а);
    if (!шаг_неубыв(о2, б))
      return fmt("шаг %ld: СС4 — шаг %ld заключает «%s», а нужно «%s не убывает»",
                 ш->номер, ш->из2, о2, б);
    return (char *)"";
  }
  /* СС5 не заключает ничего: он КЛАДЁТ два факта в окружение из одного
     допущения о звене. Шагом вывода это не записывается. */
  return fmt("шаг %ld: правила «%s» в приёме нет — из семейства соседних написаны СС1–СС4",
             ш->номер, имя);
}


static char *семейство_с(ШагВывода *ш, const char *имя, char *ф, char *о1, char *о2, char *исх) {
  double з1; double з2;
  char *е, *г;
  if (!строгий_вывода(ф, &е, &г))
    return fmt("шаг %ld: %s заключает строгий порядок, а вида «Е меньше Г» у «%s» нет",
               ш->номер, имя, ф);
  if (strcmp(е, г) == 0)
    return fmt("шаг %ld: %s — «%s меньше %s» ложно при всяком значении: тождества сторон"
               " в строгом порядке нет (запрет С✗)", ш->номер, имя, е, г);
  if (strcmp(имя, "С1") == 0) {
    char *доп, *дл, *дп;
    доп = допущение_строки(исх);
    if (!доп)
      return fmt("шаг %ld: С1 — строка %ld не есть допущение «требует «имя» формула»", ш->номер, ш->строка);
    if (!строгий_вывода(доп, &дл, &дп))
      return fmt("шаг %ld: С1 — допущение «%s» не о СТРОГОМ порядке; из нестрогого строгость"
                 " не выводится никогда (запрет С✗4)", ш->номер, доп);
    if (strcmp(дл, е) != 0 || strcmp(дп, г) != 0)
      return fmt("шаг %ld: С1 — допущение даёт «%s меньше %s», а заключено «%s меньше %s»",
                 ш->номер, дл, дп, е, г);
    return (char *)"";
  }
  if (strcmp(имя, "С2") == 0) {
    char *а, *б;
    if (!выбор_вывода(е, &а, &б))
      return fmt("шаг %ld: С2 берёт выбор «если У то А иначе Б», а слева «%s»", ш->номер, е);
    if (!шаг_строгий(о1, а, г))
      return fmt("шаг %ld: С2 — шаг %ld заключает «%s», а нужно «%s меньше %s»",
                 ш->номер, ш->из1, о1, а, г);
    if (!шаг_строгий(о2, б, г))
      return fmt("шаг %ld: С2 — шаг %ld заключает «%s», а нужно «%s меньше %s»",
                 ш->номер, ш->из2, о2, б, г);
    return (char *)"";
  }
  if (strcmp(имя, "С3") == 0) {
    double д;
    if (!литерал_вывода(е, &з1))
      return fmt("шаг %ld: С3 берёт слева литерал, а стоит «%s»", ш->номер, е);
    if (!дно_шага(о1, г, &д))
      return fmt("шаг %ld: С3 — шаг %ld не даёт дна «%s» целым литералом", ш->номер, ш->из1, г);
    if (!(з1 < д))
      return fmt("шаг %ld: С3 — литерал «%s» не СТРОГО ниже дна верхней стороны", ш->номер, е);
    return (char *)"";
  }
  if (strcmp(имя, "С4") == 0) {
    char *доп, *дл, *дп;
    if (ш->вид != ОСН_СТРОКА && ш->вид != ОСН_ИЗ1)
      return fmt("шаг %ld: С4 опирается на названный строгий факт —"
                 " основание обязано быть «строка N» либо «из M»", ш->номер);
    if (!литерал_вывода(е, &з1))
      return fmt("шаг %ld: С4 берёт слева литерал, а стоит «%s»", ш->номер, е);
    доп = ш->вид == ОСН_ИЗ1 ? о1 : допущение_строки(исх);
    if (!доп)
      return fmt("шаг %ld: С4 — строка %ld не есть допущение «требует «имя» формула»", ш->номер, ш->строка);
    if (!строгий_вывода(доп, &дл, &дп))
      return fmt("шаг %ld: С4 — допущение «%s» не о СТРОГОМ порядке (запрет С✗4)", ш->номер, доп);
    if (strcmp(дп, г) != 0)
      return fmt("шаг %ld: С4 — допущение о верхней стороне «%s», а заключено о «%s»",
                 ш->номер, дп, г);
    if (!литерал_вывода(дл, &з2))
      return fmt("шаг %ld: С4 — строгое дно «%s» не целый литерал", ш->номер, дл);
    if (з1 > з2)
      return fmt("шаг %ld: С4 — литерал «%s» выше строгого дна «%s»", ш->номер, е, дл);
    return (char *)"";
  }
  return fmt("шаг %ld: правила «%s» в приёме нет — из семейства строгого порядка написаны С1–С4",
             ш->номер, имя);
}


static char *семейство_в(ШагВывода *ш, const char *имя, char *ф, char *о1, char *о2) {
  char *л, *э;
  if (!надвое_вывода(ф, "содержит", &л, &э))
    return fmt("шаг %ld: %s заключает вхождение, а вида «Л содержит Э» у «%s» нет",
               ш->номер, имя, ф);
  if (strcmp(имя, "В1") == 0) {
    int выписан, i; Сп ч = члены_списка_вывода(л, &выписан);
    if (!выписан)
      return fmt("шаг %ld: В1 берёт выписанный список, а слева «%s»", ш->номер, л);
    for (i = 0; i < ч.n; i++) if (strcmp(ч.e[i], э) == 0) return (char *)"";
    return fmt("шаг %ld: В1 — члена «%s» в выписанном списке «%s» нет знак в знак",
               ш->номер, э, л);
  }
  if (strcmp(имя, "В2") == 0) {
    char *д, *ост;
    if (!к_списку_вывода(л, "добавить", &д, &ост) &&
        !к_списку_вывода(л, "приписать", &д, &ост))
      return fmt("шаг %ld: В2 берёт «добавить Э к Л» и «приписать Э к Л», а слева «%s»",
                 ш->номер, л);
    if (strcmp(д, э) != 0)
      return fmt("шаг %ld: В2 — кладётся «%s», а заключено вхождение «%s»", ш->номер, д, э);
    return (char *)"";
  }
  if (strcmp(имя, "В3") == 0) {
    char *д, *ост;
    if (!к_списку_вывода(л, "добавить", &д, &ост) &&
        !к_списку_вывода(л, "приписать", &д, &ост))
      return fmt("шаг %ld: В3 берёт «добавить Х к Л» и «приписать Х к Л», а слева «%s»",
                 ш->номер, л);
    if (!шаг_вхождения(о1, ост, э))
      return fmt("шаг %ld: В3 — шаг %ld заключает «%s», а нужно «%s содержит %s»",
                 ш->номер, ш->из1, о1, ост, э);
    return (char *)"";
  }
  if (strcmp(имя, "В4") == 0) {
    char *а, *б;
    if (!выбор_вывода(л, &а, &б))
      return fmt("шаг %ld: В4 берёт выбор «если У то А иначе Б», а слева «%s»", ш->номер, л);
    if (!шаг_вхождения(о1, а, э))
      return fmt("шаг %ld: В4 — шаг %ld заключает «%s», а нужно «%s содержит %s»",
                 ш->номер, ш->из1, о1, а, э);
    if (!шаг_вхождения(о2, б, э))
      return fmt("шаг %ld: В4 — шаг %ld заключает «%s», а нужно «%s содержит %s»",
                 ш->номер, ш->из2, о2, б, э);
    return (char *)"";
  }
  return fmt("шаг %ld: правила «%s» в приёме нет — из семейства вхождения написаны В1–В4",
             ш->номер, имя);
}

static char *семейство_э(ШагВывода *ш, const char *имя, char *ф, char *о1, char *о2) {
  char *эп, *эл, *эу;
  if (!все_элементы_вывода(ф, &эп, &эл, &эу))
    return fmt("шаг %ld: %s заключает свойство всех элементов, а вида «для всех П из Л : У» у «%s» нет",
               ш->номер, имя, ф);
  if (strcmp(имя, "Э1") == 0) {
    int выписан; Сп чл = члены_списка_вывода(эл, &выписан);
    /* Пустой список: слово `пустой список` ИЛИ выписанный без членов `[]`
       (хвост выписанного списка Э5 — ADR-0037 §4.3). */
    if (strcmp(эл, "пустой список") != 0 && !(выписан && чл.n == 0))
      return fmt("шаг %ld: Э1 берёт пустой список, а список цели «%s»", ш->номер, эл);
    return (char *)"";
  }
  if (strcmp(имя, "Э2") == 0) {
    char *над, *х, *у2;
    if (!отбор_вывода(эл, &над, &х, &у2))
      return fmt("шаг %ld: Э2 берёт отбор «отфильтровать Л где х → У», а список цели «%s»", ш->номер, эл);
    /* Подстановка имени цели вместо х — без захвата, и имя цели не стоит в
       условии свободным (или то же имя): иначе «м больше м» выводилось бы из
       отбора «э больше м». Lean: «Э2-терм» спрашивает то же. */
    if (захват_в_свойстве(у2, х, эп) || (strcmp(эп, х) != 0 && есть_терм(у2, эп)))
      return fmt("шаг %ld: Э2 — условие отбора «%s» связывает имя либо несёт имя цели «%s» свободным: подстановка «%s» вместо «%s» заперта", ш->номер, у2, эп, эп, х);
    if (strcmp(терм(вставить_вместо(у2, х, эп)), эу) != 0)
      return fmt("шаг %ld: Э2 — условие отбора «%s» при «%s» вместо «%s» не есть свойство цели «%s»",
                 ш->номер, у2, эп, х, эу);
    return (char *)"";
  }
  if (strcmp(имя, "Э3") == 0) {
    char *д, *ост, *о_д;
    if (!к_списку_вывода(эл, "добавить", &д, &ост) && !к_списку_вывода(эл, "приписать", &д, &ост))
      return fmt("шаг %ld: Э3 берёт «добавить Х к Л» и «приписать Х к Л», а список цели «%s»", ш->номер, эл);
    if (захват_в_свойстве(эу, эп, д))
      return fmt("шаг %ld: Э3 — свойство «%s» связывает имя, подстановка «%s» вместо «%s» заперта", ш->номер, эу, д, эп);
    о_д = терм(вставить_вместо(эу, эп, д));
    if (strcmp(о1, о_д) != 0)
      return fmt("шаг %ld: Э3 — шаг %ld заключает «%s», а нужно свойство о прибавленном «%s»",
                 ш->номер, ш->из1, о1, о_д);
    if (!шаг_всех(о2, эп, ост, эу))
      return fmt("шаг %ld: Э3 — шаг %ld заключает «%s», а нужно «для всех %s из %s : %s»",
                 ш->номер, ш->из2, о2, эп, ост, эу);
    return (char *)"";
  }
  if (strcmp(имя, "Э4") == 0) {
    char *а, *б;
    if (!выбор_вывода(эл, &а, &б))
      return fmt("шаг %ld: Э4 берёт выбор «если У то А иначе Б», а список цели «%s»", ш->номер, эл);
    if (!шаг_всех(о1, эп, а, эу))
      return fmt("шаг %ld: Э4 — шаг %ld заключает «%s», а нужно «для всех %s из %s : %s»",
                 ш->номер, ш->из1, о1, эп, а, эу);
    if (!шаг_всех(о2, эп, б, эу))
      return fmt("шаг %ld: Э4 — шаг %ld заключает «%s», а нужно «для всех %s из %s : %s»",
                 ш->номер, ш->из2, о2, эп, б, эу);
    return (char *)"";
  }
  if (strcmp(имя, "Э5") == 0) {
    int выписан, i; Сп ч = члены_списка_вывода(эл, &выписан), хв = ПУСТО; char *хвост, *о_г;
    if (!выписан || ч.n < 1)
      return fmt("шаг %ld: Э5 берёт выписанный список с членами, а список цели «%s»", ш->номер, эл);
    for (i = 1; i < ч.n; i++) добавить(&хв, ч.e[i]);
    /* Хвост пишется выписанным списком, пустой — «[]» (см. zapis.flang: так
       строго убывает мера длины формулы; «пустой список» её сорвал бы). */
    хвост = ч.n > 1 ? fmt("[%s]", соединить(хв, ", ")) : (char *)"[]";
    if (захват_в_свойстве(эу, эп, ч.e[0]))
      return fmt("шаг %ld: Э5 — свойство «%s» связывает имя, подстановка «%s» вместо «%s» заперта", ш->номер, эу, ч.e[0], эп);
    о_г = терм(вставить_вместо(эу, эп, ч.e[0]));
    if (strcmp(о1, о_г) != 0)
      return fmt("шаг %ld: Э5 — шаг %ld заключает «%s», а нужно свойство о первом члене «%s»", ш->номер, ш->из1, о1, о_г);
    if (!шаг_всех(о2, эп, хвост, эу))
      return fmt("шаг %ld: Э5 — шаг %ld заключает «%s», а нужно «для всех %s из %s : %s»", ш->номер, ш->из2, о2, эп, хвост, эу);
    return (char *)"";
  }
  /* Э6: свойство образа из свойства прообраза под П[э:=Ф]. Запрет на свободное
     х в П — не лишний: подстановка идёт под связывателем х и захватила бы его. */
  if (strcmp(имя, "Э6") == 0) {
    char *над, *х, *ф2;
    if (!отображение_вывода(эл, &над, &х, &ф2))
      return fmt("шаг %ld: Э6 берёт отображение «отобразить Л как х → Ф», а список цели «%s»", ш->номер, эл);
    if (захват_в_свойстве(эу, эп, ф2) || захват_в_свойстве(эу, х, ф2) || (strcmp(х, эп) != 0 && есть_терм(эу, х)))
      return fmt("шаг %ld: Э6 — свойство «%s» связывает или упоминает имя «%s» либо «%s», подстановка «%s» заперта", ш->номер, эу, эп, х, ф2);
    if (!шаг_всех(о1, х, над, терм(вставить_вместо(эу, эп, ф2))))
      return fmt("шаг %ld: Э6 — шаг %ld заключает «%s», а нужно «для всех %s из %s : %s»",
                 ш->номер, ш->из1, о1, х, над, терм(вставить_вместо(эу, эп, ф2)));
    return (char *)"";
  }
  return fmt("шаг %ld: правила «%s» в приёме нет — из семейства всех элементов написаны Э1–Э6",
             ш->номер, имя);
}


static char *семейство_ч(ШагВывода *ш, const char *имя, char *ф, char *о1, char *о2) {
  char *т, *п;
  if (!надвое_вывода(ф, "начинается с", &т, &п))
    return fmt("шаг %ld: %s заключает начало, а вида «Т начинается с П» у «%s» нет",
               ш->номер, имя, ф);
  if (strcmp(имя, "Ч1") == 0) {
    if (strcmp(т, п) != 0)
      return fmt("шаг %ld: Ч1 берёт один и тот же терм обеими сторонами, а стоят «%s» и «%s»",
                 ш->номер, т, п);
    return (char *)"";
  }
  if (strcmp(имя, "Ч2") == 0) {
    if (strcmp(п, "\"\"") != 0)
      return fmt("шаг %ld: Ч2 берёт ПУСТУЮ приставку-литерал, а стоит «%s»", ш->номер, п);
    return (char *)"";
  }
  if (strcmp(имя, "Ч3") == 0) {
    char *левый, *правый;
    if (!склейка_вывода(т, &левый, &правый))
      return fmt("шаг %ld: Ч3 берёт двоичную склейку «соединить Л с Р», а слева «%s»",
                 ш->номер, т);
    if (!шаг_начала(о1, левый, п))
      return fmt("шаг %ld: Ч3 — шаг %ld заключает «%s», а нужно «%s начинается с %s»",
                 ш->номер, ш->из1, о1, левый, п);
    return (char *)"";
  }
  if (strcmp(имя, "Ч4") == 0) {
    char *а, *б;
    if (!выбор_вывода(т, &а, &б))
      return fmt("шаг %ld: Ч4 берёт выбор «если У то А иначе Б», а слева «%s»", ш->номер, т);
    if (!шаг_начала(о1, а, п))
      return fmt("шаг %ld: Ч4 — шаг %ld заключает «%s», а нужно «%s начинается с %s»",
                 ш->номер, ш->из1, о1, а, п);
    if (!шаг_начала(о2, б, п))
      return fmt("шаг %ld: Ч4 — шаг %ld заключает «%s», а нужно «%s начинается с %s»",
                 ш->номер, ш->из2, о2, б, п);
    return (char *)"";
  }
  if (strcmp(имя, "Ч6") == 0) {
    char *т1, *п1, *т2, *п2;
    if (!надвое_вывода(о1, "начинается с", &т1, &п1) ||
        !надвое_вывода(о2, "начинается с", &т2, &п2))
      return fmt("шаг %ld: Ч6 — шаги %ld и %ld заключают не начало", ш->номер, ш->из1, ш->из2);
    if (strcmp(п1, т2) != 0)
      return fmt("шаг %ld: Ч6 — середина не сходится: шаг %ld даёт приставку «%s»,"
                 " а шаг %ld говорит о «%s»", ш->номер, ш->из1, п1, ш->из2, т2);
    if (strcmp(т1, т) != 0 || strcmp(п2, п) != 0)
      return fmt("шаг %ld: Ч6 — звенья дают «%s начинается с %s», а заключено «%s начинается с %s»",
                 ш->номер, т1, п2, т, п);
    return (char *)"";
  }
  /* Ч5: одной точности обоих текстов МАЛО — начало проверяется сличением
     знак в знак. Счёт здесь тот же, каким Выч закрывает замкнутую половину;
     второго вычислителя языка не заводится — отказ поимённо. */
  if (strcmp(имя, "Ч5") == 0) {
    char *тт, *пт;
    if (!точный_текст(т, &тт))
      return fmt("шаг %ld: Ч5 берёт слева ТОЧНЫЙ текст — литерал, склейку точных, «к строке» от"
                 " литерала либо длины выписанного списка, — а стоит «%s»", ш->номер, т);
    if (!точный_текст(п, &пт))
      return fmt("шаг %ld: Ч5 берёт справа ТОЧНУЮ приставку, а стоит «%s»", ш->номер, п);
    if (!начинается(тт, пт))
      return fmt("шаг %ld: Ч5 — собранный текст «%s» не начинается с «%s»", ш->номер, тт, пт);
    return (char *)"";
  }
  return fmt("шаг %ld: правила «%s» в приёме нет — из семейства начала написаны Ч1–Ч6",
             ш->номер, имя);
}

static char *шаг_вывода(ШагВывода *ш, ШагВывода *преж, long сколько,
                        Сп строки, const char *чья, Сп обяз) {
  const char *имя = ш->правило;
  char *ф = терм(ш->формула), *о1 = (char *)"", *о2 = (char *)"", *о3 = (char *)"";
  char *исх = NULL;
  int i;

  for (i = 0; i < (int)(sizeof ЗАПРЕТЫ_ВЫВОДА / sizeof *ЗАПРЕТЫ_ВЫВОДА); i++)
    if (strcmp(имя, ЗАПРЕТЫ_ВЫВОДА[i]) == 0)
      return fmt("шаг %ld: «%s» — запрет ведомости, а не правило: им не выводится ничего",
                 ш->номер, имя);
  if (!*ф) return fmt("шаг %ld: заключение пусто", ш->номер);

  /* Основания шагов берутся ЗДЕСЬ и один раз: правило ниже видит уже
     проверенные номера, а не ищет их само. */
  if (ш->вид == ОСН_ИЗ1 || ш->вид == ОСН_ИЗ2 || ш->вид == ОСН_ИЗ3 || ш->вид == ОСН_ИЗ1_СТРОКА) {
    if (ш->из1 < 1 || ш->из1 >= ш->номер || ш->из1 > сколько)
      return fmt("шаг %ld: основание «из %ld» указывает не на прежний шаг этого блока", ш->номер, ш->из1);
    о1 = терм(преж[ш->из1 - 1].формула);
    ш->откр |= преж[ш->из1 - 1].откр;
  }
  if (ш->вид == ОСН_ИЗ2 || ш->вид == ОСН_ИЗ3) {
    if (ш->из2 < 1 || ш->из2 >= ш->номер || ш->из2 > сколько)
      return fmt("шаг %ld: основание «из %ld» указывает не на прежний шаг этого блока", ш->номер, ш->из2);
    о2 = терм(преж[ш->из2 - 1].формула);
    ш->откр |= преж[ш->из2 - 1].откр;
  }
  if (ш->вид == ОСН_ИЗ3) {
    if (ш->из3 < 1 || ш->из3 >= ш->номер || ш->из3 > сколько)
      return fmt("шаг %ld: основание «из %ld» указывает не на прежний шаг этого блока", ш->номер, ш->из3);
    о3 = терм(преж[ш->из3 - 1].формула);
    ш->откр |= преж[ш->из3 - 1].откр;
  }
  if ((ш->вид == ОСН_СТРОКА || ш->вид == ОСН_ИЗ1_СТРОКА) && strcmp(имя, "Разв3") != 0) {
    исх = строка_функции(строки, ш->строка, чья);
    if (!исх)
      return fmt("шаг %ld: строки %ld в функции «%s» нет — основание указывает мимо",
                 ш->номер, ш->строка, чья);
  }
  { char *беда = не_то_основание(ш, имя); if (беда) return беда; }

  /* ПОРЯДОК ВЕТВЕЙ — ЧАСТЬ ПРАВИЛЬНОСТИ, А НЕ ОФОРМЛЕНИЕ: имена семейств
     спрашиваются приставкой, и приставки сталкиваются. Раньше своего семейства
     обязаны стоять «Св1» (до С), «Выч» (до В), «Пр1» (до П), «Пред» (до П),
     «СС» (до С); у «Р» оговорка «не Разв». Переставь — имя уйдёт в чужое
     семейство и получит внятный, но неверный отказ. */
  if (strcmp(имя, "Т1") == 0) return правило_т1(ш, ф, исх);

  /* Т2: цель есть допущение с точностью до имени связанной. Список обязан
     совпасть знак в знак; свойство сличается после подстановки имени цели
     вместо имени допущения — сторож захвата ниже. */
  if (strcmp(имя, "Т2") == 0) return правило_т2(ш, ф, исх);

  /* Св1: свидетель Т написан в самом заключении — сверщик ничего не ищет,
     а только подставляет и сличает. */
  if (strcmp(имя, "Св1") == 0) return правило_св1(ш, ф, о1);

  /* ── Кон1 (строка ведомости): КОНЕЧНОСТЬ ИЗ ДОПУЩЕНИЯ «Т не больше ⟨литерал⟩».
     Литерал сверщика — только цифры (`литерал_вывода`), а значит конечен по
     построению: ни бесконечность, ни не-число под такое допущение не подходят
     (у не-числа сравнение ложно). Заключение — вид колонки 6, «Т : кон». */
  if (strcmp(имя, "Кон1") == 0) return правило_кон1(ш, ф, исх);

  /* ── Кон3: КОНЕЧНОСТЬ ИЗ ФАКТА «( Т минус Т ) равен 0» (ведро Е, ADR-0027) ──
     Своей формулы у конечности в языке нет; заключение пишется видом колонки 6
     ведомости — «Т : кон», — и читает его только О2. Теорема: у бесконечностей
     и не-числа «Т минус Т» есть не-число, а «равен» (Object.is) с нулём у него
     ложно. Граница: обе стороны разности — тот же Т знак в знак. */
  if (strcmp(имя, "Кон3") == 0) return правило_кон3(ш, ф, о1);

  /* Кон2 снимает гипотезу оговорки: под H выведено Ц и ни на чём кроме H,
     значит «не А или Ц» верно безусловно. Граница: левый дизъюнкт — ровно
     «не ( ( Т минус Т ) равен 0 )» с ОДНИМ Т знак в знак, иначе оговорка
     говорит о равенстве двух термов, а не о конечности. */
  if (strcmp(имя, "Кон2") == 0) return правило_кон2(ш, преж, ф, о1, о2);

  /* ── Цел1: ЦЕЛОСТЬ ИЗ ФАКТА ОСТАТКА (ADR-0029) ────────────────────────────
     «( Т остаток от 1 ) равен 0» — с прибавкой «плюс 0» справа или без, нулём
     справа или слева: ровно те записи, что читает ядро («Это целость терма»).
     Равенство это есть Number.isInteger(Т): у бесконечностей и не-числа остаток
     от единицы — не-число, у дробного — дробь. Заключение пишется «Т : цел». */
  if (strcmp(имя, "Цел1") == 0) return правило_цел1(ш, ф, о1);

  /* ── Цел2: ЦЕЛОСТЬ ДОВОДА ТОЧНОГО ТИПА — ОБЯЗАТЕЛЬСТВО ЗОВУЩЕГО (ADR-0029, вторая поправка) ──
     Тип целости во время работы не гарантирует — зовущий вправе подать 2.5, — как не
     гарантирует потолка (Пред1). Лист законен только при строке `обязательство вход «Т»
     ⟨Т : цел⟩ строка N на зовущем` того же утверждения; закрытие переигрывает
     `сверить_обязательства`. */
  if (strcmp(имя, "Цел2") == 0) return правило_цел2(ш, строки, обяз, ф, исх);

  /* Разв2: тело читается ИЗ ИСХОДНИКА, а не из записи доказательства, и номер
     строки сверяется с ним — иначе доказывающий вписал бы любое удобное тело. */
  if (strcmp(имя, "Разв2") == 0) return правило_разв2(ш, строки, чья, ф, о1, исх);

  /* Разв1 «из N строка M»: ветвь разбора выбирается числом ВЫПИСАННЫХ членов,
     тело ветви берётся как написано, голова — первый член, хвост — остальные.
     Граница: разбираемое — только выписанный список (имя, вызов, вложенный
     список — отказ); тело ветви — одним термом. */
  if (strcmp(имя, "Разв1") == 0 && ш->вид != ОСН_ИЗ1)
    return правило_разв1_список(ш, строки, чья, ф, о1);

  /* Шаг ничего не выводит: кладёт формулу в открытые гипотезы. Снимают её
     только Р1 (ГипО) и Р4 (ГипД); неснятая гипотеза и последний шаг под
     гипотезой — отказ в `проиграть_вывод`. Здесь гипотеза НАРОЧНО не сверяется
     с целью: без Р1/Р4 блок всё равно отвергнут. */
  if (strcmp(имя, "ГипО") == 0 || strcmp(имя, "ГипД") == 0) return правило_гипотезы(ш, имя, ф, исх);
  if (strcmp(имя, "Или1") == 0 || strcmp(имя, "Или2") == 0) return правило_или(ш, имя, ф, о1);
  if (strcmp(имя, "И1") == 0 || strcmp(имя, "И2") == 0) return правило_и(ш, имя, ф, о1);

  /* Выч закрывает половину уже доверенным `половина_закрыта`; второго
     упростителя нет нарочно — одна дорога вместо двух. Стоит ДО семейства В:
     имя начинается той же буквой, что «В1». */
  if (strcmp(имя, "Выч") == 0) return правило_выч(ш, строки, ф);

  /* Пр1 выводит ЛЮБУЮ формулу, поэтому пара посылок обязана быть заведомо
     несовместной: первая — СТРОГАЯ «А меньше Б», вторая — её стороны,
     переставленные, знак в знак. «А не больше Б» при «А меньше Б» совместны —
     отказ. */
  if (strcmp(имя, "Пр1") == 0) return правило_пр1(ш, о1, о2);

  /* Длина языка — целое меньше 2⁵³, и «плюс 1» к ней точен; на этом стоят обе
     меры. */
  if (strcmp(имя, "М1") == 0 || strcmp(имя, "М2") == 0) return правило_меры(ш, строки, имя, ф, о1);

  /* К↑ берёт поле ЗНАЧЕНИЯ, построенного тут же: конструктор обязан стоять
     написанным. Поле неизвестного значения — запрет. */
  if (strcmp(имя, "К↑") == 0) return правило_поля(ш, ф, о1);

  /* Разв3: тело ВЫЗВАННОЙ обязано быть без вызовов, а своё тело («результат»)
     звать может — вызовы в нём разворачиваются следующими шагами. */
  if (strcmp(имя, "Разв3") == 0) return правило_разв3(ш, строки, чья, ф, о1);

  /* То же имя «Разв1», другая ветвь: разбор выписанного КОНСТРУКТОРА идёт
     основанием «из N», разбор списка в теле — «из N строка M» (выше). */
  if (strcmp(имя, "Разв1") == 0 && ш->вид == ОСН_ИЗ1) return правило_разв1_вариант(ш, ф, о1);

  /* Семейство Р. Оговорка «не Разв» обязательна: Разв1/Разв2/Разв3 начинаются
     той же буквой и разобраны выше. */
  if (начинается(имя, "Р") && !начинается(имя, "Разв"))
    return семейство_р(ш, преж, строки, чья, имя, ф, о1, о2, исх);
  if (начинается(имя, "Н")) return семейство_н(ш, преж, строки, чья, имя, ф, о1, о2, исх);
  if (начинается(имя, "Пред")) return семейство_пред(ш, строки, обяз, имя, ф, исх);
  if (начинается(имя, "П")) return семейство_п(ш, преж, имя, ф, о1, о2, исх);
  if (начинается(имя, "Д")) return семейство_д(ш, имя, ф, о1, о2, исх);
  if (начинается(имя, "О")) return семейство_о(ш, преж, имя, ф, о1, о2, о3, исх);
  if (начинается(имя, "СС")) return семейство_сс(ш, имя, ф, о1, о2, исх);
  if (начинается(имя, "С")) return семейство_с(ш, имя, ф, о1, о2, исх);
  if (начинается(имя, "В")) return семейство_в(ш, имя, ф, о1, о2);

  /* Свойство У подставляется ТЕКСТОМ (`вставить_вместо`), поэтому связыватель
     внутри У — отказ: подстановка захватила бы имя. */
  if (начинается(имя, "Э")) return семейство_э(ш, имя, ф, о1, о2);
  if (начинается(имя, "Ч")) return семейство_ч(ш, имя, ф, о1, о2);

  return fmt("шаг %ld: имени «%s» в приёме нет — написаны семейства Н, П, Д, О, С, СС, В, Ч,"
             " Т и развёртка ведомости", ш->номер, имя);
}

static char *разобрать_шаг_вывода(const char *s, ШагВывода *ш) {
  char *хвост;
  ш->номер = (long)число_из_слова(слово(s, 2));
  ш->правило = слово(s, 3);
  ш->формула = в_уголках(s, 1);
  ш->вид = ОСН_ЛИСТ; ш->строка = 0; ш->из1 = 0; ш->из2 = 0; ш->из3 = 0; ш->откр = 0; ш->снята = 0;
  if (ш->номер < 1) return fmt("строка «%s»: номер шага не число", s);
  if (!содержит(s, "⟨") || !содержит(s, "⟩")) return fmt("строка «%s»: заключение не в уголках", s);
  хвост = обрезать(хвост_после(s, "⟩"));
  if (strcmp(хвост, "сам") == 0) { ш->вид = ОСН_ЛИСТ; return (char *)""; }
  if (начинается(хвост, "строка ")) {
    ш->вид = ОСН_СТРОКА; ш->строка = номер_после(хвост, "строка ");
    if (ш->строка < 1) return fmt("строка «%s»: номер строки исходника не число", s);
    return (char *)"";
  }
  if (начинается(хвост, "из ")) {
    Сп ч = разделить(обрезать(хвост_после(хвост, "из ")), " ");
    ш->из1 = (long)число_из_слова(часть(ч, 1));
    if (ч.n == 1) { ш->вид = ОСН_ИЗ1; }
    else if (ч.n == 3 && strcmp(часть(ч, 2), "строка") == 0) {
      ш->вид = ОСН_ИЗ1_СТРОКА; ш->строка = (long)число_из_слова(часть(ч, 3));
      if (ш->строка < 1) return fmt("строка «%s»: номер строки исходника не число", s);
    }
    else if (ч.n == 2) { ш->вид = ОСН_ИЗ2; ш->из2 = (long)число_из_слова(часть(ч, 2)); }
    else if (ч.n == 3) { ш->вид = ОСН_ИЗ3; ш->из2 = (long)число_из_слова(часть(ч, 2)); ш->из3 = (long)число_из_слова(часть(ч, 3)); }
    else return fmt("строка «%s»: основание «из» разобрано быть не может", s);
    return (char *)"";
  }
  return fmt("строка «%s»: основание не названо — их три и только три: «сам», «строка N», «из N [M [K]]»", s);
}

/* Всякий отказ назван вслух и роняет запись кодом 1: приём, который молча
   не взялся, от приёма, который согласился, не отличить. */
static int проиграть_вывод(Сверка *s, Сп свои, Сп строки, const char *имя_т,
                           const char *чья, const char *цель_сырая) {
  Сп все = все_с_началом(свои, "вывод ");
  /* Обязательства входа здесь только передаются шагу Пред1; переигрывает их
     `сверить_обязательства` — не эта функция. */
  Сп обяз = все_с_началом(свои, "обязательство ");
  ШагВывода шаги[64]; long n = 0;
  int i, конец = 0; char *цель_блока = NULL, *цель, *беда = NULL;

  if (!все.n) return 0;
  цель = терм(цель_сырая);
  for (i = 0; i < все.n && !беда; i++) {
    char *l = все.e[i];
    if (начинается(l, "вывод цель")) {
      if (цель_блока) { беда = (char *)"строка «вывод цель» стоит дважды"; break; }
      if (n) { беда = (char *)"строка «вывод цель» стоит после шага"; break; }
      цель_блока = терм(в_уголках(l, 1));
      continue;
    }
    if (strcmp(l, "вывод конец") == 0) {
      if (конец) { беда = (char *)"строка «вывод конец» стоит дважды"; break; }
      конец = 1; continue;
    }
    if (конец) { беда = (char *)"шаг стоит после «вывод конец»"; break; }
    if (!цель_блока) { беда = (char *)"шаг стоит до «вывод цель»"; break; }
    if (n >= (long)(sizeof шаги / sizeof *шаги)) {
      беда = (char *)"шагов вывода больше шестидесяти четырёх — столько сверщик не берёт"; break;
    }
    беда = разобрать_шаг_вывода(l, &шаги[n]);
    if (*беда) break;
    беда = NULL;
    if (шаги[n].номер != n + 1) {
      беда = fmt("шаг %ld стоит %ld-м: шаг пропущен или переставлен", шаги[n].номер, n + 1); break;
    }
    n++;
  }
  if (!беда && !цель_блока) беда = (char *)"блок вывода без строки «вывод цель»";
  if (!беда && !конец) беда = (char *)"блок вывода не закрыт строкой «вывод конец»";
  if (!беда && !n) беда = (char *)"в блоке вывода нет ни одного шага";
  /* ЦЕЛЬ БЛОКА СВЕРЯЕТСЯ С ИСХОДНИКОМ, а не берётся из записи на слово: иначе
     блок объявлял бы себе цель сам и выводил бы что удобно. */
  if (!беда && strcmp(цель_блока, цель) != 0)
    беда = fmt("цель блока «%s» не совпала с постусловием исходника «%s»", цель_блока, цель);
  ДОКАЗАНО_ДО_ВЫВОДА = &s->доказанные_свойства;
  for (i = 0; !беда && i < (int)n; i++) {
    char *почему = шаг_вывода(&шаги[i], шаги, n, строки, чья, обяз);
    if (*почему) беда = почему;
  }
  if (!беда && strcmp(терм(шаги[n - 1].формула), цель) != 0)
    беда = fmt("последний шаг заключает «%s», а цель блока «%s» — вывод до цели не доведён",
               терм(шаги[n - 1].формула), цель);
  /* ГИПОТЕЗЫ СНЯТЫ? Каждая гипотеза обязана быть снята Р1 либо Р4, и последний шаг
     обязан стоять без открытых гипотез: иначе цель доказана под допущением, о
     котором она сама молчит (ведро Е). Два вопроса, не один: гипотезу могли
     снять, а на неё же опереться ещё раз ниже. */
  for (i = 0; !беда && i < (int)n; i++)
    if ((strcmp(шаги[i].правило, "ГипО") == 0 || strcmp(шаги[i].правило, "ГипД") == 0) && !шаги[i].снята)
      беда = fmt("гипотеза шага %ld «%s» не снята: охрану (ГипО) снимает Р1, дизъюнкт (ГипД) — Р4",
                 шаги[i].номер, терм(шаги[i].формула));
  if (!беда && шаги[n - 1].откр)
    беда = fmt("последний шаг стоит под открытой гипотезой шага %ld — вывод не безусловен",
               младшая_гипотеза(шаги[n - 1].откр));
  если_не(s, беда == NULL, fmt("утверждение «%s», вывод: %s", имя_т, беда ? беда : ""));
  return беда == NULL;
}

/* 1 — строка квантора в записи обязательна: её отсутствие отвергается вслух.
   0 оставлено для записей, снятых ядром до того, как оно стало эту строку
   печатать: тогда отсутствие принимается, но за проверенное не выдаётся. */
#define СТРОКИ_КВАНТОРОВ_ОБЯЗАТЕЛЬНЫ 1

/* Имена за «для всех» берутся ВСЕ, списком в порядке написания (вложенное
   «для всех а для всех б» — то же самое): индукция может идти по любому из
   них, и счёт по одному первому имени отвергал бы честную запись.
   Ограничение «таких что» в список не входит. */
static Сп имена_квантора(const char *место) {
  char *л = как_читает_язык(место), *t = strstr(л, "для всех "), *об = strstr(л, "обеспечивает "), *конец;
  Сп r = ПУСТО, ч; int i;
  /* «для всех» ПОСЛЕ «обеспечивает» — квантор по элементам внутри самой цели
     (`для всех э из Л: У`, 6206), а не имена индукции: имён квантора нет. */
  if (!t || (об && об < t)) return r;
  t = заменить(t + strlen("для всех "), " для всех ", " и ");
  if ((конец = strstr(t, " обеспечивает ")) != NULL) *конец = 0;
  if ((конец = strstr(t, " таких что ")) != NULL) *конец = 0;
  ч = разделить(t, " и ");
  for (i = 0; i < ч.n; i++) добавить(&r, голо(ч.e[i]));
  return r;
}

static char *как_слово(const char *w) { return начинается(w, "«") ? (char *)w : fmt("«%s»", w); }
static char *первое_расхождение(const char *в_записи, const char *ждём) {
  Сп a = разделить(в_записи, " "), b = разделить(ждём, " "), хв; int i = 0;
  while (i < a.n && i < b.n && strcmp(a.e[i], b.e[i]) == 0) i++;
  хв = i < a.n ? a : b; хв.e += i; хв.n -= i;
  return fmt("строка записи «%s», а исходник даёт «%s» — %s", в_записи, ждём,
             i < a.n && i < b.n ? fmt("после %s: %s вместо %s", как_слово(i ? a.e[i - 1] : ""),
                                       как_слово(a.e[i]), как_слово(b.e[i]))
             : i < a.n ? fmt("в записи лишнее %s", как_слово(соединить(хв, " ")))
             : fmt("в записи недостаёт %s", как_слово(соединить(хв, " "))));
}

static void сверить_покрытие(Сверка *s, Сп свои, Сп строки, const char *имя_т,
                            const char *вердикт, const char *место, int проигран) {
  char *принцип = первая_с_началом(свои, "принцип тип ");
  Сп посылки = все_с_началом(свои, "посылка "), варианты, непокр = ПУСТО;
  Сп об_строки = все_с_началом(свои, "объявление");
  int i, j, доказано = strcmp(вердикт, "доказано") == 0, слабых = 0;
  char *тип, *носитель = слово_после(принцип, "носитель ");
  char *индукция = первая_с_началом(свои, "индукция по «");
  for (i = 0; i < посылки.n; i++)
    if (strcmp(слово_после(посылки.e[i], "вердикт "), "доказано") != 0) слабых++;
  /* Узел вердикта проигран заново — его посылки на слово ядра не идут. */
  if (!проигран) s->на_слово += посылки_на_слово_(свои, s, имя_т);
  если_не(s, !доказано || слабых == 0,
          fmt("теорема «%s»: вердикт «доказано», а посылок не доказано %d", имя_т, слабых));
  if (!*принцип) return;
  /* Носитель — только из закрытого списка: неизвестное слово молча ОТКЛЮЧАЛО бы
     проверку покрытия («не algebra — и ладно»), и подделка прошла бы. */
  если_не(s, strcmp(носитель, "algebra") == 0 || strcmp(носитель, "segment") == 0 ||
             strcmp(носитель, "fold") == 0,
          fmt("теорема «%s»: носитель принципа «%s» — сверщику известны только «algebra», «segment» и «fold»",
              имя_т, носитель));
  /* Носитель выводится из ОБЪЯВЛЕНИЯ довода индукции в исходнике, а не берётся
     словом записи: сумма (объявленная, встроенная, запись) даёт algebra и fold,
     встроенный отрезок — segment, прочее — принципа нет, и это код 1 с причиной.
     Иначе подделка «segment над числом» проходит как непроверенная, а не как ложь. */
  { char *по0 = в_ёлочках(принцип, 2);
    char *объявлено = тип_довода_у_места(строки, место, по0);
    char *имя_об = имя_типа(объявлено);
    Объявление об = объявление_типа(строки, имя_об);
    int сумма = strcmp(об.вид, "сумма") == 0 || strcmp(об.вид, "встроенная-сумма") == 0 ||
                strcmp(об.вид, "запись") == 0;
    int отрезок = strcmp(об.вид, "отрезок") == 0;
    int ладно = strcmp(носитель, "segment") == 0 ? отрезок
              : (strcmp(носитель, "algebra") == 0 || strcmp(носитель, "fold") == 0) ? сумма : 0;
    if (*объявлено) {
      если_не(s, *об.вид,
              fmt("теорема «%s»: довод «%s» объявлен типом «%s» — принципа индукции по нему нет: объявление не сумма, не запись, не отрезок",
                  имя_т, по0, имя_об));
      если_не(s, !*об.вид || ладно,
              fmt("теорема «%s»: носитель «%s», а объявление довода «%s» — %s «%s»: такой носитель из него не следует",
                  имя_т, носитель, по0, об.вид, об.основа));
      если_не(s, strcmp(в_ёлочках(принцип, 1), имя_об) == 0,
              fmt("теорема «%s»: принцип назван над типом «%s», а довод «%s» объявлен типом «%s»",
                  имя_т, в_ёлочках(принцип, 1), по0, имя_об));
    }
    /* Строка «объявление» сличается со своей читкой объявления знак в знак: вид,
       имя, строка объявления, цепочка псевдонимов, у algebra — варианты с числом
       рекурсивных частей, у segment — дно и потолок. Расхождение — код 1 с
       названным словом, а не «похоже». */
    если_не(s, об_строки.n || !СТРОКИ_КВАНТОРОВ_ОБЯЗАТЕЛЬНЫ,
            fmt("теорема «%s»: под принципом нет строки «объявление» — ядро обязано её печатать", имя_т));
    if (об_строки.n) {
      char *ждём = fmt("объявление %s%s", об.откуда,
                       strcmp(носитель, "algebra") == 0 ? fmt(" варианты %s", об.арности)
                     : strcmp(носитель, "segment") == 0 ? fmt(" дно 0 потолок %s", К_ПРЕДСТ) : "");
      если_не(s, об_строки.n == 1, fmt("теорема «%s»: строк «объявление» %d, а принцип один", имя_т, об_строки.n));
      если_не(s, *об.откуда,
              fmt("теорема «%s»: у довода «%s» объявления типа в исходнике нет — строке «%s» сверять не с чем",
                  имя_т, по0, обрезать(об_строки.e[0])));
      если_не(s, !*об.откуда || strcmp(обрезать(об_строки.e[0]), ждём) == 0,
              fmt("теорема «%s»: %s", имя_т, первое_расхождение(обрезать(об_строки.e[0]), ждём)));
    } }
  /* Имя переменной индукции названо в записи дважды — в принципе и в строке
     «индукция по»; разойдутся — запись противоречит себе. Где второй строки нет,
     имя сверяется с ИСХОДНИКОМ: без встречной проверки порча имени принимается
     молча. */
  если_не(s, !*индукция || strcmp(в_ёлочках(принцип, 2), в_ёлочках(индукция, 1)) == 0,
          fmt("теорема «%s»: принцип ведёт индукцию по «%s», а запись говорит «индукция по «%s»»",
              имя_т, в_ёлочках(принцип, 2), в_ёлочках(индукция, 1)));
  /* Имя индукции — ОДНО ИЗ названных за «для всех», не обязательно первое:
     счёт по первому отвергал бы честную индукцию по второму имени. */
  { Сп имена = ПУСТО; char *по = в_ёлочках(принцип, 2); int k = 0;
    if (строка_высказывания(строки, место))
      из_высказывания(строки, строка_высказывания(строки, место), "", &имена);
    else имена = имена_квантора(место);
    while (k < имена.n && strcmp(имена.e[k], по) != 0) k++;
    if (имена.n)
      если_не(s, k < имена.n,
              fmt("теорема «%s»: принцип ведёт индукцию по «%s», а постусловие исходника — по «%s»",
                  имя_т, по, соединить(имена, "», «")));
    else
      если_не(s, довод_функции(строки, место, по),
              fmt("теорема «%s»: принцип ведёт индукцию по «%s», а такого довода у функции нет",
                  имя_т, по)); }
  /* Имя посылки не украшение, а свойство принципа: у объявленной суммы это имя
     варианта, у отрезка и свёртки — одно из двух, что пишет само ядро. */
  for (i = 0; i < посылки.n; i++) {
    char *им = в_ёлочках(посылки.e[i], 1), *вр = в_ёлочках(посылки.e[i], 2);
    int ладно = strcmp(носитель, "algebra") == 0 ? strcmp(им, вр) == 0
              : (strcmp(носитель, "segment") == 0
                   ? (strcmp(им, "дно") == 0 || strcmp(им, "спуск") == 0)
                   : (strcmp(им, "начало свёртки") == 0 || strcmp(им, "шаг свёртки") == 0));
    если_не(s, ладно,
            fmt("теорема «%s»: посылка «%s» при носителе «%s» названа не своим именем", имя_т, им, носитель));
  }
  if (strcmp(носитель, "algebra") != 0) return;
  тип = в_ёлочках(принцип, 1);
  варианты = варианты_типа(строки, тип);
  for (i = 0; i < варианты.n; i++) {
    for (j = 0; j < посылки.n; j++) if (strcmp(в_ёлочках(посылки.e[j], 2), варианты.e[i]) == 0) break;
    if (j == посылки.n) добавить(&непокр, варианты.e[i]);
  }
  если_не(s, варианты.n == посылки.n,
          fmt("теорема «%s»: у типа «%s» вариантов %d, а посылок %d — принцип не покрывает объявленную сумму",
              имя_т, тип, варианты.n, посылки.n));
  если_не(s, непокр.n == 0,
          fmt("теорема «%s»: посылки не покрывают варианты %s", имя_т, соединить(непокр, ", ")));
}


static void сверить_круги(Сверка *s, Сп блоки) {
  Сп из = ПУСТО, v = ПУСТО, круги = ПУСТО; int i, j, k, росла = 1;
  for (i = 0; i < блоки.n; i++) {
    Сп свои = разделить(блоки.e[i], "\n"), шаги;
    char *имя = в_ёлочках(часть(свои, 1), 1);
    шаги = все_с_началом(свои, "шаг ");
    /* Слова и ёлочки считаются БЕЗ терма (`шаг_обоснование`/`шаг_словами`):
       термин несёт внутри и пробелы, и ёлочки, и без выреза круг перестал бы
       находиться ровно в записи, что несёт термин рядом с номером. */
    for (j = 0; j < шаги.n; j++)
      if (начинается(шаг_обоснование(шаги.e[j]), "по свойству "))
        { добавить(&из, имя); добавить(&v, в_ёлочках(шаг_словами(шаги.e[j]), 1)); }
    /* 4416: ребро даёт и ХОД, а не только шаг. Пока «не доказано РАНЬШЕ» было бедой,
       круг через ходы ловился ею же; теперь у объявленного доказанным это третий
       исход, и круг обязан быть назван вслух здесь. */
    шаги = все_с_началом(свои, "ход ");
    for (j = 0; j < шаги.n; j++)
      if (содержит(шаги.e[j], "факт по свойству «") || содержит(шаги.e[j], "переписать по свойству «"))
        { добавить(&из, имя); добавить(&v, в_ёлочках(шаги.e[j], 1)); }
  }
  while (росла) {
    росла = 0;
    for (i = 0; i < из.n; i++) for (j = 0; j < из.n; j++) {
      if (strcmp(v.e[i], из.e[j]) != 0) continue;
      for (k = 0; k < из.n; k++) if (!strcmp(из.e[k], из.e[i]) && !strcmp(v.e[k], v.e[j])) break;
      if (k == из.n) { добавить(&из, из.e[i]); добавить(&v, v.e[j]); росла = 1; }
    }
  }
  for (i = 0; i < из.n; i++) if (strcmp(из.e[i], v.e[i]) == 0) добавить(&круги, из.e[i]);
  если_не(s, круги.n == 0,
          fmt("утверждения обосновывают сами себя по кругу: %s", соединить(круги, ", ")));
}

/* Поля записи закрыты сличением с исходником либо с другим полем той же
   записи — объявленному в записи здесь не верят ни в одном поле. */

static void сверить_имена(Сверка *s, Сп свои, Сп строки, const char *имя_т) {
  int i;
  for (i = 0; i < свои.n; i++) {
    char *z = обрезать(свои.e[i]), *имя, *в_исх, *было;
    long где;
    const char *что;
    if (начинается(z, "дано «")) что = "дано ";
    else if (начинается(z, "индукция по «")) что = "индукция по ";
    else continue;
    имя = в_ёлочках(z, 1);
    где = номер_после(z, "строка ");
    if (где < 1) { s->без_привязки++; continue; }
    в_исх = строка_по_номеру(строки, где);
    было = хвост_после(в_исх, что);
    было = *что == 'd' || начинается(что, "дано")
             ? голо(часть(разделить(было, ":"), 1))
             : (начинается(было, "«") ? в_ёлочках(было, 1) : слово(было, 1));
    если_не(s, начинается(в_исх, что) && strcmp(было, имя) == 0,
            fmt("теорема «%s», строка %ld: запись зовёт «%s%s», а в исходнике стоит «%s»",
                имя_т, где, что, имя, в_исх));
  }
}

/* Объявленное «шагов N» сличается с числом написанных шагов: несверяемое поле
   записи — это поле, в котором можно написать что угодно. */
static void сверить_число_шагов(Сверка *s, Сп свои, const char *имя_т) {
  int i; long объявлено = -1, факт = 0, где = 0;
  for (i = 0; i <= свои.n; i++) {
    char *z = i < свои.n ? обрезать(свои.e[i]) : (char *)"";
    if (i == свои.n || начинается(z, "случай строка")) {
      if (объявлено >= 0)
        если_не(s, объявлено == факт,
                fmt("теорема «%s», случай на строке %ld: объявлено шагов %ld, а написано %ld",
                    имя_т, где, объявлено, факт));
      if (i == свои.n) break;
      объявлено = номер_после(z, "шагов "); где = номер_после(z, "строка "); факт = 0;
    } else if (начинается(z, "шаг ") && объявлено >= 0) факт++;
  }
}

static long шагов_случая(Сп свои, Сп строки, const char *вариант) {
  int i; long объявлено = -1; char *текущий = (char *)"";
  for (i = 0; i < свои.n; i++) {
    char *z = обрезать(свои.e[i]);
    if (!начинается(z, "случай строка")) continue;
    текущий = строка_по_номеру(строки, номер_после(z, "строка "));
    if (strcmp(имя_варианта(слова_после(текущий, 1)), вариант) == 0)
      объявлено = номер_после(z, "шагов ");
  }
  return объявлено;
}

/* Имена «дно»/«спуск» и «начало свёртки»/«шаг свёртки» пишет САМО ЯДРО, а не
   автор: их вид — свойство принципа, и запись, назвавшая «дно» шагом, лжёт о
   строении индукции. Носитель `algebra` сюда не входит — там имена вариантов
   авторские, о них судит `вид_по_варианту_типа` по объявлению типа. */
static const char *вид_по_имени_посылки(const char *имя_п) {
  if (strcmp(имя_п, "дно") == 0 || strcmp(имя_п, "начало свёртки") == 0) return "base";
  if (strcmp(имя_п, "спуск") == 0 || strcmp(имя_п, "шаг свёртки") == 0) return "step";
  return NULL;
}

/* Вид посылки `algebra` берётся из ОБЪЯВЛЕНИЯ ТИПА: вариант с полем своего же
   типа — «step», без него — «base». Рекурсия ищется В ХВОСТЕ ПОСЛЕ «содержит »,
   а не по всей строке: у типа, чей вариант назван именем самого типа,
   заголовок иначе сошёл бы за поле и сделал базу шагом. */
static const char *вид_по_варианту_типа(Сп строки, const char *тип, const char *вариант) {
  char *строка;
  if (strcmp(тип, "список") == 0 || strcmp(тип, "строка") == 0) {
    if (strcmp(вариант, "пусто") == 0) return "base";
    if (strcmp(вариант, "голова и хвост") == 0) return "step";
    return NULL;
  }
  строка = строка_варианта_типа(строки, тип, вариант);
  if (!*строка) return NULL;
  if (!содержит(строка, "содержит ")) return "base";
  return содержит(хвост_после(строка, "содержит "), fmt("«%s»", тип)) ? "step" : "base";
}

static char *вариант_случая(const char *хвост) {
  if (начинается(хвост, "вариант ")) return имя_варианта(хвост);
  if (начинается(хвост, "голова ")) return (char *)"голова и хвост";
  return слово(хвост, 1);
}

/* «Закрыта reduction» значит, что ядро свело цель на ТЕЛЕ ВЕТВИ: ветвь обязана
   быть написана, иначе сводить было нечего и посылка выдумана. Случай ищется
   во ВСЁМ блоке функции, а не только в разборе по переменной индукции: язык
   склоняет имя разбора, и сличать их пришлось бы морфологией. */
static int есть_ветвь_варианта(Сп строки, const char *функция, const char *вариант) {
  long a, b, i;
  a = блок_функции(строки, функция, &b);
  if (a < 1) return 1;                 /* функции в исходнике нет — скажет сверка имён */
  for (i = a; i < b; i++) {
    char *l = строка_по_номеру(строки, i);
    if (начинается(l, "случай ") &&
        strcmp(вариант_случая(слова_после(l, 1)), вариант) == 0) return 1;
  }
  return 0;
}

/* Тело-свёртка по доводу индукции: база «пусто» сводится БЕЗ ветви разбора —
   свёртка по пустому списку и есть её начало, ядру было что сводить. Узла это
   не проигрывает, а лишь не зовёт ложью честное сведение: код 3, не 1. */
static int свёртка_по_доводу(Сп строки, const char *чья, const char *по, const char *вариант) {
  Сп д = доводы_функции(строки, чья).голые; long a, b; char *т; int k;
  if (strcmp(вариант, "пусто") != 0 || (a = блок_функции(строки, чья, &b)) < 1) return 0;
  т = тело_функции_текст(строки, a, b);
  for (k = 0; k < д.n; k++)
    if ((strcmp(д.e[k], по) == 0 || д.n == 1) && начинается(т, fmt("свёртка %s начиная с ", д.e[k]))) return 1;
  return 0;
}

static void сверить_поля_посылок(Сверка *s, Сп свои, Сп строки, const char *имя_т,
                                 const char *чья) {
  Сп посылки = все_с_началом(свои, "посылка "); int i;
  char *принцип = первая_с_началом(свои, "принцип тип ");
  int по_алгебре = *принцип && strcmp(слово_после(принцип, "носитель "), "algebra") == 0;
  char *тип_принципа = по_алгебре ? в_ёлочках(принцип, 1) : (char *)"";
  for (i = 0; i < посылки.n; i++) {
    char *q = посылки.e[i];
    char *закрыта = слово_после(q, "закрыта "), *вид = слово_после(q, "вид ");
    const char *ждём = вид_по_имени_посылки(в_ёлочках(q, 1));
    /* При носителе algebra имя посылки авторское, поэтому вид спрашивается по
       ВАРИАНТУ, а не по имени — судит объявление типа, не словарь ядра. */
    if (!ждём && по_алгебре) ждём = вид_по_варианту_типа(строки, тип_принципа, в_ёлочках(q, 2));
    если_не(s, strcmp(вид, "base") == 0 || strcmp(вид, "step") == 0,
            fmt("теорема «%s»: посылка «вид %s» — сверщику известны только «base» и «step»", имя_т, вид));
    /* Переставленные местами база и шаг иначе остаются «ПРОВЕРЕНО»: узел проигран
       заново, его посылки на слово ядра не идут, и ложь в них не ловит никто. */
    если_не(s, !ждём || strcmp(вид, ждём) == 0,
            вид_по_имени_посылки(в_ёлочках(q, 1))
              ? fmt("теорема «%s», посылка «%s»: объявлена «вид %s», а имя ядра «%s» — это всегда «вид %s»",
                    имя_т, в_ёлочках(q, 1), вид, в_ёлочках(q, 1), ждём ? ждём : "")
              : fmt("теорема «%s», посылка «%s»: объявлена «вид %s», а вариант «%s» типа «%s» — %s, значит «вид %s»",
                    имя_т, в_ёлочках(q, 1), вид, в_ёлочках(q, 2), тип_принципа,
                    ждём && strcmp(ждём, "step") == 0 ? "рекурсивный" : "без поля своего типа",
                    ждём ? ждём : ""));
    char *вариант = в_ёлочках(q, 2);
    long шагов = номер_после(q, "шагов "), в_случае = шагов_случая(свои, строки, вариант);
    if (strcmp(закрыта, "reduction") == 0) {
      если_не(s, шагов == 0,
              fmt("теорема «%s», посылка «%s»: закрыта сведением, а шагов объявлено %ld — шагов автора там нет",
                  имя_т, вариант, шагов));
      если_не(s, !по_алгебре || !*вариант || есть_ветвь_варианта(строки, чья, вариант) ||
                 (strcmp(тип_принципа, "список") == 0 &&
                  свёртка_по_доводу(строки, чья, в_ёлочках(принцип, 2), вариант)),
              fmt("теорема «%s», посылка «%s»: закрыта сведением, а случая на вариант «%s» в функции «%s» исходника нет — ядру нечего было сводить",
                  имя_т, вариант, вариант, чья));
    }
    else if (strcmp(закрыта, "term") == 0)
      если_не(s, шагов >= 1 && (в_случае < 0 || шагов <= в_случае),
              fmt("теорема «%s», посылка «%s»: объявлено шагов %ld, а в случае того же варианта написано %ld",
                  имя_т, вариант, шагов, в_случае));
    else
      если_не(s, 0, fmt("теорема «%s», посылка «%s»: «закрыта %s» — сверщику известны только «term» и «reduction»",
                        имя_т, вариант, закрыта));
  }
}

static void сверить_сведение(Сверка *s, Сп свои, const char *имя_т) {
  char *строка = первая_с_началом(свои, "сведение «");
  Сп посылки; char *имя; int i, нашлось = 0;
  if (!*строка) return;
  имя = в_ёлочках(строка, 1);
  посылки = все_с_началом(свои, "посылка ");
  for (i = 0; i < посылки.n; i++)
    if (strcmp(в_ёлочках(посылки.e[i], 3), имя) == 0) нашлось = 1;
  если_не(s, нашлось,
          fmt("теорема «%s»: сведение названо «%s», а ни одна посылка этим правилом не закрыта",
              имя_т, имя));
}

/* Пути сличаются по составным частям: два полных совпадают целиком,
   относительный обязан быть хвостом полного — иначе запись о ДРУГОЙ программе
   прошла бы своим же словом. */
static Сп части_пути(const char *p) {
  Сп v = разделить(p, "/"), r = ПУСТО; int i;
  for (i = 0; i < v.n; i++) if (*v.e[i] && strcmp(v.e[i], ".") != 0) добавить(&r, v.e[i]);
  return r;
}
/* Относительный путь доводится до полного рабочим каталогом — лексически, без
   разбора ссылок: иначе «хвост совпал» пропускал бы приписанное спереди. */
static char *полный_путь(const char *p) {
  char кат[4096];
  if (p[0] == '/' || !getcwd(кат, sizeof кат)) return (char *)p;
  return fmt("%s/%s", кат, p);
}
static int путь_совпал(const char *a, const char *b) {
  Сп A, B;
  b = полный_путь(b);
  A = части_пути(a); B = части_пути(b);
  { int i, полный_а = a[0] == '/', полный_б = b[0] == '/';
  Сп кор = полный_а ? B : A, длин = полный_а ? A : B;
  if (полный_а == полный_б) {
    if (A.n != B.n) return 0;
    for (i = 0; i < A.n; i++) if (strcmp(A.e[i], B.e[i]) != 0) return 0;
    return 1;
  }
  if (кор.n > длин.n) return 0;
  for (i = 0; i < кор.n; i++)
    if (strcmp(кор.e[i], длин.e[длин.n - кор.n + i]) != 0) return 0;
  return 1; }
}

/* СКЕЛЕТ СТРОКИ: имя в ёлочках и терм в уголках — один знак, что бы внутри ни
   стояло. Иначе пословный разбор ломался бы на именах с пробелами. */
static char *скелет(const char *s) {
  char *r = дай(strlen(s) + 1), *v = r; const char *p = s;
  while (*p) {
    const char *k = NULL; const char *откр = NULL, *закр = NULL;
    if (начинается(p, "«")) { откр = "«"; закр = "»"; }
    else if (начинается(p, "⟨")) { откр = "⟨"; закр = "⟩"; }
    if (откр && (k = strstr(p + strlen(откр), закр)) != NULL) {
      memcpy(v, откр, strlen(откр)); v += strlen(откр);
      memcpy(v, закр, strlen(закр)); v += strlen(закр);
      p = k + strlen(закр); continue;
    }
    *v++ = *p++;
  }
  *v = 0; return r;
}
/* Образец: `#` — число, `.` — любое слово, `…` — любой хвост; прочее слово
   обязано стоять на своём месте. */
static int по_образцу(const char *s, const char *образец) {
  Сп a = разделить(s, " "), b = разделить(образец, " "); int i;
  for (i = 0; i < b.n; i++) {
    if (strcmp(b.e[i], "…") == 0) return 1;
    if (i >= a.n) return 0;
    if (strcmp(b.e[i], "#") == 0) { if (число_из_слова(a.e[i]) < 0) return 0; continue; }
    if (strcmp(b.e[i], ".") == 0) { if (!*a.e[i]) return 0; continue; }
    if (strcmp(b.e[i], a.e[i]) != 0) return 0;
  }
  return a.n == b.n;
}
/* Закрытый список видов строк записи: значения `вид`, `вердикт` и `ядро`
   названы поимённо — новое значение отвергается вслух, а не проходит молча. */
static const char *ОБРАЗЦЫ[] = {
  "", "запись доказательства 1", "исходник …", "строк #", "знаков #",
  "отпечаток # #", "отпечаток256 .", "ядро 2", "утверждений #",
  "утверждение «» функции «» строка #", "вид postcondition",
  "утверждение «» строка #", "вид statement",
  "вердикт доказано", "вердикт нет вердикта", "вердикт доказано при условии",
  "теорема «» строка #", "теоремы нет",
  "дано «» строка #", "цель строка #", "цель ⟨⟩", "индукция по «» строка #",
  "случай строка # шагов #", "шаг # строка # закрывающий …",
  "шаг # строка # промежуточный …", "шаг # ⟨⟩ закрывающий …",
  "шаг # ⟨⟩ промежуточный …",
  /* Термин РЯДОМ с номером строки — второй свидетель о том же месте, а не
     замена первого. */
  "цель строка # ⟨⟩", "шаг # строка # ⟨⟩ закрывающий …",
  "шаг # строка # ⟨⟩ промежуточный …",
  "следовательно доказано да", "следовательно доказано нет",
  "принцип тип «» по «» носитель . база # шаг #", "сведение «»",
  "объявление …",
  "для всех …",
  "таких что ⟨⟩ строка #", "допущение ⟨⟩ строка #",
  "свидетель «» ⟨⟩ строка #", "после подстановки ⟨⟩",
  "прогон «» шаг «» строка #",
  "план «» строка #", "разрешено «» строка #",
  "поручение «» функции «» строка #", "конец плана",
  "посылка «» вид . вариант «» вердикт доказано закрыта . шагов # правило «»",
  "посылка «» вид . вариант «» вердикт нет вердикта закрыта . шагов # правило «»",
  "конец утверждения", "конец записи", "ход …",
  "таблиц #", "таблица «» открыта # закрыта # звеньев #",
  /* Эти строки только УЗНАЮТСЯ, но по существу не читаются: без образцов честная
     запись краснела бы («строка не узнана»), а узнать — не значит проверить.
     Значение «по объявлению» при этом закрыто списком из двух слов, и третье
     отвергается вслух. */
  "правило «»", "по объявлению да", "по объявлению нет",
  /* Обязательство входа — условие на ЗОВУЩЕМ, а не свойство типа; переигрывают
     его `сверить_обязательства` и шаг Пред1. */
  "обязательство вход «» ⟨⟩ строка # на зовущем",
  /* Основание шага вывода закрыто: «сам», «строка N», «из …». Вид, которого в
     списке нет, даёт код 1, а не тихий пропуск. */
  "вывод цель ⟨⟩", "вывод конец",
  "вывод # . ⟨⟩ сам", "вывод # . ⟨⟩ строка #",
  "вывод # . ⟨⟩ из #", "вывод # . ⟨⟩ из # #", "вывод # . ⟨⟩ из # # #", "вывод # . ⟨⟩ из # строка #",
  "тотальностей #", "тотальность «» строка #", "вид composition",
  "зовёт «» строка # тотальна", "зовёт примитив «»",
  "самовызова нет", "конец тотальности",
  "снятие «» функции «» зовёт «» строка # столбец #", "вид precondition-at-call", "конец снятия",
  /* `вид measure` НАРОЧНО не в списке: строка остаётся неузнанной, и это код 1.
     Состоятельно переиграть СТРОГОЕ убывание меры нечем — такого правила в
     переигрывателе ходов нет, а дать его значит вырастить доверенную базу.
     Дописать сюда `measure`, не заведя правила, — тихо принять недоказанное. */
  "вид structure", "вид step",
  "убывает аргумент # «»", "дно тип «»",
  "виток строка # «» от …", "часть «» поле «» варианта «»",
  "мера не меньше 0 тип «»", "самовызов строка #"
};
static int знакомая_строка(const char *s) {
  char *ск = скелет(s); int i;
  for (i = 0; i < (int)(sizeof ОБРАЗЦЫ / sizeof *ОБРАЗЦЫ); i++)
    if (по_образцу(ск, ОБРАЗЦЫ[i])) return 1;
  return 0;
}
/* Строка обязана стоять ПРЯМО под названной: без неё над собой сличать её не с
   чем, а вторая подряд — уже не та, что сличена. Столбцы: начало строки,
   допустимые начала строки над ней (через «|»), имя места для отказа. */
static const char *МЕСТА_СТРОК[][3] = {
  { "объявление", "принцип тип ", "принцип" },
  { "для всех ", "вид postcondition|вид statement|для всех |таких что ",
    "вид postcondition" },
  { "таких что ", "для всех ", "для всех" },
  { "свидетель ", "вид postcondition|вид statement|для всех |таких что ",
    "вид postcondition" },
  { "после подстановки ", "свидетель ", "свидетель" },
  { "прогон «", "для всех |таких что ", "для всех" },
  /* Строка, вставшая не на своё место, сличается не с тем: разрешённое — со
     строкой `разрешает`, выданное — со списком разрешённого. Подмена места — подлог. */
  { "разрешено «", "план «|разрешено «", "план" },
  { "поручение «", "разрешено «|поручение «", "разрешено" }
};
static int под_одной_из(const char *над, const char *можно) {
  Сп ч = разделить(можно, "|"); int j;
  for (j = 0; j < ч.n; j++) if (начинается(над, ч.e[j])) return 1;
  return 0;
}
static void сверить_строки_записи(Сверка *s, const char *запись) {
  Сп v = разделить(запись, "\n"); int i, k, конец = 0;
  for (i = 0; i < v.n; i++) {
    char *l = обрезать(v.e[i]);
    если_не(s, знакомая_строка(l),
            fmt("строка записи %d не узнана: «%s» — чекер не принимает того, чего не читает", i + 1, l));
    for (k = 0; k < (int)(sizeof МЕСТА_СТРОК / sizeof *МЕСТА_СТРОК); k++)
      если_не(s, !начинается(l, МЕСТА_СТРОК[k][0]) ||
                 (i > 0 && под_одной_из(обрезать(v.e[i - 1]), МЕСТА_СТРОК[k][1])),
              fmt("строка записи %d «%s» стоит не сразу под строкой «%s» — сличать её не с чем",
                  i + 1, l, МЕСТА_СТРОК[k][2]));
    if (strcmp(l, "конец записи") == 0) конец = 1;
  }
  если_не(s, конец, (char *)"запись не кончается словами «конец записи» — она обрублена");
}

/* Утверждение обязано быть целым: у него есть вид, вердикт, слово о теореме и
   свой конец. Обрубленная запись без этого выглядела бы просто короче. */
static void сверить_целость_блока(Сверка *s, Сп свои, const char *имя) {
  int i, вид = 0, верд = 0, теор = 0, конец = 0;
  for (i = 0; i < свои.n; i++) {
    char *l = обрезать(свои.e[i]);
    if (начинается(l, "вид ")) вид++;
    else if (начинается(l, "вердикт ")) верд++;
    else if (начинается(l, "теорема «") || strcmp(l, "теоремы нет") == 0) теор++;
    else if (strcmp(l, "конец утверждения") == 0) конец++;
  }
  если_не(s, вид == 1 && верд == 1 && теор == 1 && конец == 1,
          fmt("утверждение «%s» записано не целиком: вид %d, вердикт %d, слово о теореме %d, конец %d — обязано быть по одному",
              имя, вид, верд, теор, конец));
}

/* ЗАПИСЬ НЕ ВПРАВЕ МОЛЧАТЬ О НАПИСАННОМ: теорема, которой в записи нет вовсе, —
   это не «не доказано», а НЕ СКАЗАНО. Строка объявления, а не упоминание в
   пояснении: пояснение начинается двумя косыми. */
static void сверить_полноту(Сверка *s, Сп строки, Сп блоки) {
  Сп замолчано = ПУСТО; int i, j; long постусловий = 0, высказываний = 0;
  for (i = 0; i < строки.n; i++) {
    char *l = строки.e[i], *t = как_читает_язык(l);
    if (начинается(l, "теорема") && начинается(t, "теорема «")) {
      char *имя = в_ёлочках(t, 1);
      for (j = 0; j < блоки.n; j++)
        if (strcmp(в_ёлочках(часть(разделить(блоки.e[j], "\n"), 1), 1), имя) == 0) break;
      if (j == блоки.n) добавить(&замолчано, имя);
    }
    if (содержит(t, "обеспечивает «")) постусловий++;
    if (начинается(l, "утверждение «")) высказываний++;   /* К3a: верхний уровень, от края */
  }
  если_не(s, замолчано.n == 0,
          fmt("в исходнике есть теоремы, о которых запись молчит: %s", соединить(замолчано, ", ")));
  если_не(s, постусловий + высказываний == блоки.n,
          высказываний ? fmt("в исходнике постусловий %ld и утверждений без функции %ld, а в записи блоков %d — "
                             "запись говорит не обо всей программе", постусловий, высказываний, блоки.n)
                       : fmt("в исходнике постусловий %ld, а в записи утверждений %d — запись говорит не обо всей программе",
                             постусловий, блоки.n));
}

/* 4416: места прогона, которых сверщик НЕ ВЗЯЛСЯ проверять, идут не в беды, а на
   слово ядра с причиной — общее у трёх звавших `проиграть_блок`. */
static void влить_не_взялся(Сверка *s, Прогон *p, const char *чьё) {
  int i;
  for (i = 0; i < p->не_взялся.n; i++)
    добавить(&s->не_взялся, fmt("%s, сведение: %s — место на слове ядра", чьё, p->не_взялся.e[i]));
  s->шагов_на_слово += p->не_взялся.n;
}

static void влить_прогон(Сверка *s, Прогон *p, const char *имя_т) {
  если_не(s, p->беды.n == 0, fmt("теорема «%s», сведение: %s", имя_т, соединить(p->беды, "; ")));
  влить_не_взялся(s, p, fmt("теорема «%s»", имя_т));
  s->сведений += p->проиграно; s->ходов += p->ходов; s->без_привязки += p->без_привязки;
}

static void сверить_разметку_теоремы(Сверка *s, Сп свои, Сп строки, const char *имя_т, long начало) {
  Сп ожидаемая, настоящая; int без_номеров = 0;
  char *a, *b;
  если_не(s, strcmp(строка_по_номеру(строки, начало), fmt("теорема «%s»", имя_т)) == 0,
          fmt("строка %ld исходника — не «теорема «%s»»", начало, имя_т));
  ожидаемая = разметка_записи(свои, начало, &без_номеров);
  настоящая = разметка_теоремы(строки, начало);
  if (без_номеров) { s->без_привязки++;
    a = без_номеров_в(ожидаемая); b = без_номеров_в(настоящая); }
  else { a = соединить(ожидаемая, ", "); b = соединить(настоящая, ", "); }
  если_не(s, strcmp(a, b) == 0,
          fmt("теорема «%s»: запись говорит о строках [%s], а в исходнике стоят [%s]", имя_т, a, b));
  /* Сколько допущений и на каких строках — сличила разметка выше; здесь только
     их текст, знак в знак с исходником. */
  { Сп доп = все_с_началом(свои, "допущение "); int j;
    for (j = 0; j < доп.n; j++) {
      long где_д = номер_после(доп.e[j], "строка ");
      char *л = как_читает_язык(строка_по_номеру(строки, где_д));
      char *P = содержит(л, " таких что ") ? хвост_после(л, " таких что ") : хвост_после(л, "дано ");
      если_не(s, strcmp(терм(в_уголках(доп.e[j], 1)), терм(P)) == 0,
              fmt("теорема «%s»: допущение %d — в записи ⟨%s⟩, а в исходнике на строке %ld — «%s»",
                  имя_т, j + 1, в_уголках(доп.e[j], 1), где_д, P));
    } }
}
static void сверить_теорему(Сверка *s, Сп свои, Сп строки, const char *вердикт,
                           const char *место, const char *имя, const char *чья) {
  char *строка_т = первая_с_началом(свои, "теорема «");
  long начало = номер_после(строка_т, "строка ");
  char *имя_т = в_ёлочках(строка_т, 1);
  Обст o; Прогон p;
  long не_проигрываемых_до = 0, моих_не_проигрываемых;
  long законом_до = 0;
  сверить_разметку_теоремы(s, свои, строки, имя_т, начало);
  сверить_цель(s, свои, строки, место, имя, имя_т);
  сверить_имена(s, свои, строки, имя_т);
  сверить_число_шагов(s, свои, имя_т);
  сверить_поля_посылок(s, свои, строки, имя_т, чья);
  сверить_сведение(s, свои, имя_т);
  { char *ск = первая_с_началом(свои, "цель ");
    long гц = номер_после(ск, "строка ");
    не_проигрываемых_до = s->шагов_не_проигрываемых;
    законом_до = s->шагов_законом;
    сверить_шаги(s, свои, строки, имя_т, чья,
                 гц < 1 ? в_уголках(ск, 1) : хвост_после(как_читает_язык(строка_по_номеру(строки, гц)), "утверждаем ")); }
  сверить_закрытие(s, свои, имя_т, вердикт);
  сверить_правила(s, свои, fmt("теорема «%s»", имя_т));
  /* Места снимаются РОВНО те, что начислила ветвь «по закону» (разница
     счётчика), и переносятся в `выводов_мест`: иначе тождество линейки
     «текст мест = долг + снятое» разошлось бы на честной записи. */
  if (strcmp(вердикт, "доказано") == 0 && *первая_с_началом(свои, "вывод ") &&
      s->шагов_законом > законом_до) {
    char *ск_в = первая_с_началом(свои, "цель ");
    long гц_в = номер_после(ск_в, "строка ");
    char *цель_в = гц_в < 1 ? в_уголках(ск_в, 1)
                            : хвост_после(как_читает_язык(строка_по_номеру(строки, гц_в)), "утверждаем ");
    if (проиграть_вывод(s, свои, строки, имя_т, чья, цель_в)) {
      long моих_законом = s->шагов_законом - законом_до;
      s->шагов_на_слово -= моих_законом;
      s->выводов++; s->выводов_мест += моих_законом;
      s->шаги_отложенные = ПУСТО;
    }
  }
  { char *принцип = первая_с_началом(свои, "принцип тип ");
    char *строка_цели = первая_с_началом(свои, "цель ");
    long где = номер_после(строка_цели, "строка ");
    o.строки = строки; o.свои = свои; o.функция = (char *)чья;
    o.цель = терм(где < 1 ? в_уголках(строка_цели, 1)
                         : хвост_после(как_читает_язык(строка_по_номеру(строки, где)), "утверждаем "));
    /* У индуктивной теоремы самовызов идёт по переменной принципа, у ПРЯМОЙ
       (принципа нет) — по свободной переменной `дано «имя»`: иначе `ход цель`
       строит вызов без аргумента и развёртка не находит терма. */
    o.по = *принцип ? в_ёлочках(принцип, 2)
                    : в_ёлочках(первая_с_началом(свои, "дано «"), 1);
    o.тип = в_ёлочках(принцип, 1);
    o.хвост = доводы_функции(строки, чья).хвост;
    o.обяз = (char *)имя; o.доказанные = s->доказанные_свойства;
    o.объявленные = s->объявленные_доказанными;
    o.ограничения = ограничения_высказывания(строки, место); }
  p = проиграть_блок(&o);
  влить_прогон(s, &p, имя_т);
  /* Узел вердикта проигрывается и под теоремой: `проиграть_узел` не верит записи
     — он читает ТЕЛО ФУНКЦИИ и сам сверяет дно со спуском, а тело от наличия
     теоремы не зависит. `разбором_цели` здесь НЕ зовётся нарочно: его узлов у
     теоремы в записи нет ни строкой, и он снимал бы места, которых не проигрывал. */
  { char *ск = первая_с_началом(свои, "цель ");
    long гц = номер_после(ск, "строка ");
    char *цель_узла = гц < 1 ? в_уголках(ск, 1)
                            : хвост_после(как_читает_язык(строка_по_номеру(строки, гц)),
                                          "утверждаем ");
    int проигран = strcmp(вердикт, "доказано") == 0 &&
                   проиграть_узел(s, свои, строки, имя_т, чья, цель_узла);
    сверить_покрытие(s, свои, строки, имя_т, вердикт, место, проигран);
    s->узлов += проигран ? 1 : 0;
    s->узлов_мест += проигран ? посылки_на_слово(свои) : 0;
    if (проигран && s->узел_булев) s->узлов_булево_мест += посылки_на_слово(свои);
    /* Шаг, которого сверщик не проиграл, ложится в долг — кроме узла вердикта,
       проигранного заново: он читает ТЕЛО ФУНКЦИИ и уже проверил по существу то,
       на что ссылается «по предположению»; взять плату и здесь значило бы числить
       долгом снятое. Дописанной теоремой это не обходится — тело читается настоящее. */
    моих_не_проигрываемых = s->шагов_не_проигрываемых - не_проигрываемых_до;
    if (проигран && моих_не_проигрываемых > 0) {
      s->шагов_на_слово -= моих_не_проигрываемых;
      s->узлов_мест += моих_не_проигрываемых;
      if (s->узел_булев) s->узлов_булево_мест += моих_не_проигрываемых;
    }
    /* Причины по этим шагам названы, только если места остались за ними: узел
       снял место — снимается и строка, иначе список причин был бы длиннее
       числа мест и сам вводил бы в заблуждение. */
    if (!проигран) { int k;
      for (k = 0; k < s->шаги_отложенные.n; k++)
        добавить(&s->не_взялся, s->шаги_отложенные.e[k]); }
    s->шаги_отложенные = ПУСТО; }
}

/* Цель «результат не больше (длина Л)» закрывается по ТЕЛУ функции: свёртка по
   тому же Л, начало 0, шаг прибавляет к мере не больше единицы. Структурный
   переигрыш того же рода, что узел algebra; вычислитель не зовётся. */
static int ветвь_не_больше_единицы(const char *в, const char *акк) {
  char *л, *п, *у = ужать(в); double z;
  if (strcmp(у, акк) == 0) return 1;
  return надвое_вывода(у, "плюс", &л, &п) &&
         ((strcmp(л, акк) == 0 && литерал_вывода(п, &z) && z <= 1) ||
          (strcmp(п, акк) == 0 && литерал_вывода(л, &z) && z <= 1));
}
static int свёртка_не_длиннее(Сп строки, const char *чья, const char *цель) {
  Разрез до_шага, до_имён, начало, имена; char *т, *мера, *а, *б, *акк; long a, b;
  if (!разрез_словом(ужать(терм(цель)), " не больше ", &т, &мера) || strcmp(ужать(т), "результат") != 0 ||
      !начинается(ужать(мера), "длина ") || (a = блок_функции(строки, чья, &b)) < 1) return 0;
  т = ужать(тело_функции_текст(строки, a, b));
  до_шага = разрез_по(т, "→"); до_имён = разрез_по(до_шага.лево, "как");
  начало = разрез_по(до_имён.лево, "начиная с"); имена = разрез_по(до_имён.право, "и");
  if (!начинается(т, "свёртка ") || !до_шага.есть || !до_имён.есть || !начало.есть || !имена.есть) return 0;
  акк = ужать(имена.лево);
  if (strcmp(ужать(начало.право), "0") != 0 || !имя_вывода(акк) || !имя_вывода(ужать(имена.право)) ||
      strcmp(акк, ужать(имена.право)) == 0 ||
      strcmp(ужать(хвост_после(начало.лево, "свёртка ")), ужать(хвост_после(ужать(мера), "длина "))) != 0) return 0;
  return ветвь_не_больше_единицы(до_шага.право, акк) ||
         (выбор_вывода(ужать(до_шага.право), &а, &б) && ветвь_не_больше_единицы(а, акк) && ветвь_не_больше_единицы(б, акк));
}

/* Цель «результат начинается с П» закрывается по ТЕЛУ: один вызов «F», у F нет
   «требует», и её обещание «результат начинается с Б» проверено по существу
   (реестр доказанных). «Б начинается с П» — сличение двух написанных
   литералов, а не счёт: вычислитель здесь не зовётся. */
static int начало_от_вызванной(Сверка *s, Сп строки, const char *чья, const char *цель) {
  char *т, *п, *лп, *лб, *тело, *f; long a, b, i; int k; Сп дов;
  if (!разрез_словом(ужать(терм(цель)), " начинается с ", &т, &п) || strcmp(ужать(т), "результат") != 0 ||
      !разобрать_литерал(ужать(п), &лп) || (a = блок_функции(строки, чья, &b)) < 1) return 0;
  тело = ужать(тело_функции_текст(строки, a, b)); f = в_ёлочках(тело, 1);
  if (!*f || !начинается(тело, fmt("«%s» от ", f)) || все_требования_функции(строки, f).n ||
      (a = блок_функции(строки, f, &b)) < 1) return 0;
  дов = доводы_вызова(хвост_после(тело, fmt("«%s» от ", f)));
  for (k = 0; k < дов.n; k++) if (!имя_вывода(ужать(дов.e[k]))) return 0;
  for (i = a; i < b; i++) {
    char *l = как_читает_язык(часть(строки, i)), *и = в_ёлочках(l, 1), *т2, *п2;
    if (!начинается(l, "обеспечивает «") && !(начинается(l, "для всех ") && содержит(l, " обеспечивает «"))) continue;
    for (k = 0; k < s->доказанные_свойства.n && strcmp(s->доказанные_свойства.e[k], и) != 0; k++) ;
    if (k < s->доказанные_свойства.n &&
        разрез_словом(ужать(терм(хвост_после(l, fmt("обеспечивает «%s» ", и)))), " начинается с ", &т2, &п2) &&
        strcmp(ужать(т2), "результат") == 0 && разобрать_литерал(ужать(п2), &лб) && начинается(лб, лп)) return 1;
  }
  return 0;
}

/* Терм начинается с литерала П, если он сам П, литерал с таким началом
   (сличение написанного, не счёт), склейка с таким левым или выбор, у которого
   начинаются ОБЕ ветви. Иное — не взялся, а не «ладно». */
static int начинается_по_построению(const char *т, const char *п, const char *лп, int глубина) {
  char *у = ужать(т), *л, *р, *а, *б, *лт;
  if (глубина > 12) return 0;
  if (strcmp(у, п) == 0) return 1;
  if (разобрать_литерал(у, &лт)) return начинается(лт, лп);
  if (склейка_вывода(у, &л, &р)) return начинается_по_построению(л, п, лп, глубина + 1);
  if (выбор_вывода(у, &а, &б)) return начинается_по_построению(а, п, лп, глубина + 1) && начинается_по_построению(б, п, лп, глубина + 1);
  return 0;
}
static int начало_по_телу(Сп строки, const char *чья, const char *цель) {
  char *т, *п, *лп, *тело;
  if (!разрез_словом(ужать(терм(цель)), " начинается с ", &т, &п) || strcmp(ужать(т), "результат") != 0 ||
      !разобрать_литерал(ужать(п), &лп)) return 0;
  тело = плоское_тело(строки, чья);
  return *тело && начинается_по_построению(тело, ужать(п), лп, 0);
}

/* Цель-разбор написана несколькими строками: «разбор результат» на строке
   `обеспечивает`, случаи ниже отступом глубже — они собираются в один терм. */
static char *цель_разбором(Сп строки, const char *чья, const char *место, char *цель) {
  long a, b, i;
  if (!начинается(ужать(цель), "разбор ") || (a = блок_функции(строки, чья, &b)) < 1) return цель;
  for (i = a; i < b && strcmp(строка_по_номеру(строки, i), место) != 0; i++) ;
  for (i++; i < b && начинается(часть(строки, i), "   "); i++)
    цель = fmt("%s %s", цель, как_читает_язык(строка_по_номеру(строки, i)));
  return цель;
}
/* КАКОЙ ПРИЁМ СНЯЛ МЕСТО СО СЛОВА ЯДРА. Снявший бывает ровно один: два приёма,
   снявших ОДНО место, дали бы «снято» больше, чем мест, и тождество линейки
   («текст мест = долг + снятое + проверенное по существу») рухнуло бы на ЧЕСТНОЙ
   записи. */
typedef struct { int узлом, разбором, ходами, выводом; } Снято;

/* Блок вывода заключает цель САМОГО утверждения, поэтому посылок и блока ходов
   при нём быть не может: сверщик берётся за один свод, а не за два. Блок сошёлся,
   а обязательство входа закрыть не удалось — вывод стоит на посылке, за которую
   отвечает зовущий, и место остаётся на слове ядра. */
static int вывод_проигран(Сверка *s, Сп свои, Сп строки, const char *имя,
                          const char *чья, char *цель, int есть_ходы, int обяз_нечем) {
  если_не(s, !все_с_началом(свои, "посылка ").n,
          fmt("утверждение «%s»: под блоком вывода стоят посылки — вывод заключает цель"
              " утверждения, а посылок он не проигрывает", имя));
  если_не(s, !есть_ходы,
          fmt("утверждение «%s»: под одним утверждением стоят и блок ходов, и блок вывода —"
              " сверщик берётся за один свод, а не за два", имя));
  if (все_с_началом(свои, "посылка ").n || есть_ходы) return 0;
  if (!проиграть_вывод(s, свои, строки, имя, чья, цель) || обяз_нечем) return 0;
  s->выводов++; s->выводов_мест++;
  return 1;
}

static int ходы_проиграны(Сверка *s, Сп свои, Сп строки, const char *имя,
                          const char *чья, const char *место, char *цель) {
  Обст o; Прогон p;
  o.строки = строки; o.свои = свои; o.функция = (char *)чья;
  o.цель = терм(цель); o.тип = (char *)"";
  o.по = часть(доводы_функции(строки, чья).имена, 1); o.хвост = доводы_функции(строки, чья).хвост;
  o.обяз = (char *)имя; o.доказанные = s->доказанные_свойства;
  o.объявленные = s->объявленные_доказанными;
  o.ограничения = ограничения_высказывания(строки, место);
  p = проиграть_блок(&o);
  если_не(s, p.беды.n == 0, fmt("утверждение «%s», сведение: %s", имя, соединить(p.беды, "; ")));
  влить_не_взялся(s, &p, fmt("утверждение «%s»", имя));
  s->сведений += p.проиграно; s->ходов += p.ходов; s->без_привязки += p.без_привязки;
  return p.беды.n == 0 && p.проиграно > 0;
}

/* ПЯТЬ КРЮКОВ ПО ТЕЛУ ФУНКЦИИ, И ПОРЯДОК ИХ — НЕ СТАРШИНСТВО ПРАВИЛ, А
   БЕРЕЖЛИВОСТЬ: место, снятое первым приёмом, второй раз снимать нечем, а
   снятое крюком не должно сменить породу под следующим. Сторож ложной переписки
   мест не снимает, поэтому его ответ никуда не идёт: он либо назвал беду, либо
   промолчал, — а условие вызова у него то же, что у приёмов, снимающих места,
   чтобы множество поимок не сдвинулось. */
static Снято крюки_по_телу(Сверка *s, Сп свои, Сп строки, const char *имя,
                           const char *чья, char *цель, int доказано) {
  Снято сн; int без_посылок = !все_с_началом(свои, "посылка ").n;
  сн.узлом = сн.разбором = сн.ходами = сн.выводом = 0;
  сн.узлом = доказано && проиграть_узел(s, свои, строки, имя, чья, цель);
  if (!сн.узлом && доказано) сторож_ложной_переписки(s, свои, строки, имя, чья, цель);
  сн.разбором = !сн.узлом && доказано && разбором_цели(s, свои, строки, чья, цель);
  if (сн.узлом || сн.разбором || !доказано || !без_посылок) return сн;
  if (свёртка_не_длиннее(строки, чья, цель)) { сн.узлом = 1; s->узел_булев = 0; return сн; }
  if (начало_от_вызванной(s, строки, чья, цель)) { сн.ходами = 1; s->сведений++; s->мест_по_телу++; return сн; }
  if (начало_по_телу(строки, чья, цель)) { сн.ходами = 1; s->сведений++; s->мест_по_телу++; return сн; }
  if (strcmp(ужать(терм(цель)), "результат не меньше 0") == 0 &&
      прямая_по_предположению(строки, чья)) { сн.узлом = 1; s->узел_булев = 0; }
  return сн;
}

/* Считаются и приёмы, и СНЯТЫЕ ИМИ МЕСТА: без второго числа счёт пород мест по
   тексту записи разойдётся с этим счётом на честной записи, и расхождение будет
   не находкой, а слепотой мерки. У ходов и вывода своего счётчика породы нет —
   их места уже влиты числами «сведений проиграно заново» и «ходов проверено». */
static void счёт_породы(Сверка *s, Сп свои, const char *имя, Снято сн, int доказано) {
  if (сн.узлом) { s->узлов++; s->узлов_мест += 1 + все_с_началом(свои, "посылка ").n;
                  if (s->узел_булев) s->узлов_булево_мест += 1 + все_с_началом(свои, "посылка ").n;
                  return; }
  /* Разбор снимает РОВНО ОДНО место — само утверждение: посылок он не проигрывает
     и берётся лишь там, где их нет ни одной. */
  if (сн.разбором) { s->разбор++; s->разбор_мест++; return; }
  if (сн.ходами || сн.выводом || !доказано) return;
  /* Место, которого не проиграл ни один приём выше, идёт на слово ядра тем же +1;
     повторного счёта нет — ветка берётся ровно там, где не сработал никто. Разница
     только в одном: у места названа причина, а не тишина.
     ЧИСЕЛ ЗДЕСЬ НЕТ НАРОЧНО: счётчики `узлов_мимо`, `тождеств_не_сошлось`,
     `разбор_не_закрылась` копятся по ВСЕЙ записи, и подставить их в строку про
     ОДНО утверждение значило бы подписать общим числом частный случай. */
  { char *по = первая_с_началом(свои, "по объявлению ");
    s->на_слово++;
    if (*по)
      добавить(&s->не_взялся,
              fmt("утверждение «%s»: значение «по объявлению %s» — сверщик не повторяет изъятие объявленного типа, место на слове ядра",
                  имя, слово_после(по, "по объявлению ")));
    else
      добавить(&s->не_взялся,
              fmt("утверждение «%s»: вердикт «доказано», а за узел не взялся ни один из приёмов (ни проигрыванием, ни разбором цели) — место на слове ядра",
                  имя)); }
}

static void без_теоремы(Сверка *s, Сп свои, Сп строки, const char *имя,
                        const char *вердикт, const char *место, const char *чья) {
  int i, спрятана = 0, доказано, есть_ходы, есть_принцип, обяз_нечем = 0;
  Снято сн; char *цель;
  сн.узлом = сн.разбором = сн.ходами = сн.выводом = 0;
  for (i = 0; i < строки.n; i++)
    if (strcmp(обрезать(без_примечания(строки.e[i])), fmt("теорема «%s»", имя)) == 0) спрятана = 1;
  если_не(s, !спрятана,
          fmt("в записи сказано «теоремы нет», а в исходнике теорема «%s» написана", имя));
  доказано = strcmp(вердикт, "доказано") == 0;
  /* Цель у всех подмаршрутов ОДНА и берётся из ИСХОДНИКА, хвостом постусловия:
     запись о ней не говорит ни строкой, и спрашивать её тут не у кого. */
  цель = цель_обещанная(строка_высказывания(строки, место)
                          ? из_высказывания(строки, строка_высказывания(строки, место), NULL, NULL)
                          : цель_разбором(строки, чья, место, хвост_после(как_читает_язык(место), fmt("обеспечивает «%s» ", имя))));
  есть_ходы = *первая_с_началом(свои, "ход цель") != 0;
  есть_принцип = *первая_с_началом(свои, "принцип ") != 0;
  /* Обязательства входа переигрываются у ВСЯКОГО утверждения, где они стоят, — и
     без блока вывода тоже: строка, которую узнали, но не прочли, была бы «на веру».
     Мест они не снимают и не добавляют: обязательство — не цель утверждения, а
     условие на зовущем. */
  if (все_с_началом(свои, "обязательство ").n)
    обяз_нечем = сверить_обязательства(s, свои, строки, имя, чья);
  /* Цепочка ходов проигрывается заново — и под принципом тоже, но ТОЛЬКО когда
     свод верхнеуровневый: цепочка стоит под самим постусловием, до всякой посылки.
     Ходы ПОД ПОСЫЛКАМИ сюда не идут — они доказывают не цель утверждения, и
     снимать за них место было бы ложью. */
  if (доказано && *первая_с_началом(свои, "вывод "))
    сн.выводом = вывод_проигран(s, свои, строки, имя, чья, цель, есть_ходы, обяз_нечем);
  else if (есть_ходы && (!есть_принцип || несёт_верхний_свод(свои))) {
    if (доказано) сн.ходами = ходы_проиграны(s, свои, строки, имя, чья, место, цель);
  } else сн = крюки_по_телу(s, свои, строки, имя, чья, цель, доказано);
  сверить_правила(s, свои, fmt("утверждение «%s»", имя));
  сверить_поля_посылок(s, свои, строки, имя, чья);
  сверить_сведение(s, свои, имя);
  сверить_покрытие(s, свои, строки, имя, вердикт, место,
                  сн.узлом || сн.разбором || сн.ходами || сн.выводом);
  счёт_породы(s, свои, имя, сн, доказано);
}

/* Тотальность композицией переигрывается по ПРОГРАММЕ, а не по записи: тело F
   перечитывается само, список зовомых пересобирается сам. Границей доверия
   остаётся ТОЛЬКО тотальность примитивов. Порядок блоков роли не играет —
   два прохода и отдельная проверка круга вместо реестра «кто раньше». */

/* Голое «X» без «от» считается вызовом ЛИШЬ когда X — сама F или функция с
   блоком тотальности: нульместная зовётся как значение, а прочее голое ёлочное
   имя — переменная, поле или вариант. Иначе самовызов прятался бы за значением,
   а переменная числилась бы вызовом. */
static Сп вызовы_в_теле_строке(const char *s, const char *функция, Сп известные) {
  Сп r = ПУСТО; const char *отк = "«", *зак = "»", *p = s;
  size_t lo = strlen(отк), лз = strlen(зак);
  while ((p = strstr(p, отк)) != NULL) {
    const char *k = strstr(p + lo, зак);
    char *имя; int j, вызов;
    if (!k) break;
    имя = копия(p + lo, (size_t)(k - (p + lo)));
    вызов = (strcmp(слово(обрезать(k + лз), 1), "от") == 0) || (strcmp(имя, функция) == 0);
    for (j = 0; !вызов && j < известные.n; j++)
      if (strcmp(имя, известные.e[j]) == 0) вызов = 1;
    if (вызов) добавить(&r, имя);
    p = k + лз;
  }
  return r;
}

/* В граф вызовов идут только строки ТЕЛА: подпись, «требует», «обеспечивает»,
   «убывает»/«мера» и примеры — нет. Иначе честный круг через ПОСТУСЛОВИЕ
   («Меньшее» и «Большее» ссылаются друг на друга только там) назвался бы
   взаимной рекурсией, а самовызов из постусловия — прямым. */
static int строка_тела(const char *сырая) {
  char *l = обрезать(без_примечания(сырая));
  if (!*l) return 0;
  return !(начинается(l, "принимает ") || начинается(l, "возвращает ") ||
           начинается(l, "обеспечивает ") || начинается(l, "для всех ") ||
           начинается(l, "требует ") || начинается(l, "убывает ") ||
           начинается(l, "мера ") || начинается(l, "пример ") ||
           начинается(l, "дано ") || начинается(l, "ожидается "));
}

/* Список пересобирается из ПРОГРАММЫ: запись в нём не участвует. */
static Сп вызовы_тела(Сп строки, const char *функция, Сп известные) {
  Сп r = ПУСТО; long конец, начало = блок_функции(строки, функция, &конец), i; int j;
  for (i = начало + 1; начало && i < конец; i++) {
    char *сыр = строка_по_номеру(строки, i);
    if (!строка_тела(сыр)) continue;
    { Сп v = вызовы_в_теле_строке(сыр, функция, известные);
      for (j = 0; j < v.n; j++) добавить(&r, v.e[j]); }
  }
  return r;
}

static long строка_самовызова(Сп строки, const char *функция, Сп известные) {
  long конец, начало = блок_функции(строки, функция, &конец), i; int j;
  for (i = начало + 1; начало && i < конец; i++) {
    char *сыр = строка_по_номеру(строки, i);
    if (!строка_тела(сыр)) continue;
    { Сп v = вызовы_в_теле_строке(сыр, функция, известные);
      for (j = 0; j < v.n; j++) if (strcmp(v.e[j], функция) == 0) return i; }
  }
  return 0;
}

/* У рекурсии самовызов ЕСТЬ и служит опорой — это ИНВЕРСИЯ проверки «самовызова
   нет». Завершение доказывается структурно (убывающая часть значения) либо
   числом (точный шаг вниз при дне, фундированном типом-отрезком). Доверенное
   дно НЕ растёт: новых ходов и новых законов здесь не заводится. */

/* Тип объявлен вариантами (индуктивен) — дно СТРУКТУРНОЙ рекурсии фундировано:
   цепочка частей конечного значения обрывается сама. Встроенные суммы список/строка
   индуктивны (`варианты_типа` знает их). */
static int тип_индуктивен(Сп строки, const char *тип) { return варианты_типа(строки, тип).n > 0; }

/* Дно шага — только числовой тип-отрезок с дном 0: это ЯЗЫКОВОЕ распознавание,
   а не новый доказательный примитив. «целое» и «число» тянутся в −∞, спуск по
   ним бесконечен, и дна они не дают. */

static char *случай_тела_варианта(Сп строки, const char *функция, const char *вариант) {
  long конец, начало = блок_функции(строки, функция, &конец), i;
  for (i = начало + 1; начало && i < конец; i++) {
    char *l = строка_по_номеру(строки, i);
    if (начинается(l, "случай ") && strcmp(имя_варианта(слова_после(l, 1)), вариант) == 0) return l;
  }
  return (char *)"";
}

/* Запись лишь УКАЗЫВАЕТ место витка, исходник ПОДТВЕРЖДАЕТ: аргумент берётся
   только из вызова, найденного в названной строке исходника. */
static char *аргумент_витка(Сп строки, const char *функция, long k,
                            const char *аргтекст, long n, int *есть) {
  char *вызов = обрезать(fmt("«%s» от %s", функция, аргтекст));
  char *в_исх = строка_по_номеру(строки, k);
  Сп арги;
  *есть = содержит(без_скобок(в_исх), без_скобок(вызов));
  if (!*есть) return (char *)"";
  арги = доводы_вызова(хвост_после(вызов, fmt("«%s» от ", функция)));
  if (n < 1 || n > арги.n) return (char *)"";
  return терм(арги.e[n - 1]);
}

static void сверить_рекурсию(Сверка *s, Сп свои, Сп строки, const char *имя,
                             const char *вид, long нс) {
  int i;
  если_не(s, нс != 0,
          fmt("тотальность «%s»: вид %s, а рекурсии (самовызова) в теле нет", имя, вид));

  if (strcmp(вид, "structure") == 0) {
    char *уб = первая_с_началом(свои, "убывает аргумент ");
    long н_арг = номер_после(уб, "аргумент ");
    char *дно = первая_с_началом(свои, "дно тип «");
    char *тип = в_ёлочках(дно, 1);
    int есть_виток = 0;
    если_не(s, *уб, fmt("тотальность «%s» вид structure: нет строки «убывает аргумент N «имя»»", имя));
    если_не(s, *дно, fmt("тотальность «%s» вид structure: нет строки «дно тип «T»»", имя));
    если_не(s, strcmp(голо(тип), голо(часть(доводы_функции(строки, имя).типы, н_арг))) == 0,
            fmt("тотальность «%s» вид structure: дно «%s» не совпало с типом аргумента %ld («%s»)",
                имя, тип, н_арг, голо(часть(доводы_функции(строки, имя).типы, н_арг))));
    если_не(s, тип_индуктивен(строки, тип),
            fmt("тотальность «%s» вид structure: дно не фундировано — тип «%s» не объявлен вариантами (не индуктивен)", имя, тип));
    for (i = 0; i < свои.n; i++) {
      char *l = обрезать(свои.e[i]), *часть_стр, *п_имя, *поле, *вариант, *случай, *арг_в, *аргтекст; long k; int эв;
      if (!начинается(l, "виток строка ")) continue;
      есть_виток = 1;
      k = номер_после(l, "строка ");
      аргтекст = обрезать(хвост_после(l, fmt("«%s» от ", имя)));
      часть_стр = (i + 1 < свои.n) ? обрезать(свои.e[i + 1]) : (char *)"";
      if (!начинается(часть_стр, "часть «")) {
        если_не(s, 0, fmt("тотальность «%s» вид structure: у витка (строка %ld) нет строки «часть «имя» поле «поле» варианта «В»»", имя, k));
        continue;
      }
      п_имя = в_ёлочках(часть_стр, 1); поле = в_ёлочках(часть_стр, 2); вариант = в_ёлочках(часть_стр, 3);
      если_не(s, *строка_варианта_типа(строки, тип, вариант),
              fmt("тотальность «%s» вид structure: у типа «%s» нет варианта «%s»", имя, тип, вариант));
      { Обст o; memset(&o, 0, sizeof o); o.строки = строки; o.тип = тип;
        если_не(s, поле_рекурсивно(&o, вариант, поле),
                fmt("тотальность «%s» вид structure: поле «%s» варианта «%s» не того же типа «%s» — это круг, а не убывание", имя, поле, вариант, тип)); }
      случай = случай_тела_варианта(строки, имя, вариант);
      если_не(s, *случай && strcmp(поле_образца(случай, п_имя), поле) == 0,
              fmt("тотальность «%s» вид structure: имя «%s» не связано полем «%s» варианта «%s» в разборе тела", имя, п_имя, поле, вариант));
      арг_в = аргумент_витка(строки, имя, k, аргтекст, н_арг, &эв);
      если_не(s, эв, fmt("тотальность «%s» вид structure: самовызова «%s» от … в строке %ld исходника нет", имя, имя, k));
      if (эв) если_не(s, strcmp(терм(арг_в), терм(п_имя)) == 0,
              fmt("тотальность «%s» вид structure: на убывающей позиции витка стоит «%s», а часть названа «%s»", имя, арг_в, п_имя));
    }
    если_не(s, есть_виток, fmt("тотальность «%s» вид structure: нет ни одного витка", имя));
  }

  else if (strcmp(вид, "step") == 0) {
    char *уб = первая_с_началом(свои, "убывает аргумент ");
    long н_арг = номер_после(уб, "аргумент ");
    char *arg = в_ёлочках(уб, 1);
    char *дно = первая_с_началом(свои, "дно тип «");
    char *тип = в_ёлочках(дно, 1);
    char *тип_арг = голо(часть(доводы_функции(строки, имя).типы, н_арг));
    char *m0 = первая_с_началом(свои, "мера не меньше 0");
    int есть_виток = 0;
    если_не(s, *уб, fmt("тотальность «%s» вид step: нет строки «убывает аргумент N «имя»»", имя));
    если_не(s, *дно, fmt("тотальность «%s» вид step: нет строки «дно тип «T»»", имя));
    если_не(s, strcmp(объявление_типа(строки, голо(тип)).вид, "отрезок") == 0,
            fmt("тотальность «%s» вид step: дно не фундировано — тип «%s» не числовой отрезок с дном 0", имя, тип));
    если_не(s, strcmp(голо(тип), тип_арг) == 0,
            fmt("тотальность «%s» вид step: дно «%s» не совпало с типом аргумента %ld («%s»)", имя, тип, н_арг, тип_арг));
    если_не(s, *m0, fmt("тотальность «%s» вид step: нет строки «мера не меньше 0 тип «T»»", имя));
    if (*m0 && содержит(m0, "тип «"))
      если_не(s, strcmp(в_ёлочках(m0, 1), голо(тип)) == 0,
              fmt("тотальность «%s» вид step: «мера не меньше 0» названа типом «%s», а дно — «%s»", имя, в_ёлочках(m0, 1), тип));
    for (i = 0; i < свои.n; i++) {
      char *l = обрезать(свои.e[i]), *аргтекст, *шаг; long k; int эв; Разрез r;
      if (!начинается(l, "виток строка ")) continue;
      есть_виток = 1;
      k = номер_после(l, "строка ");
      аргтекст = обрезать(хвост_после(l, fmt("«%s» от ", имя)));
      шаг = аргумент_витка(строки, имя, k, аргтекст, н_арг, &эв);
      если_не(s, эв, fmt("тотальность «%s» вид step: самовызова «%s» от … в строке %ld исходника нет", имя, имя, k));
      if (!эв) continue;
      r = разрез_по(шаг, "минус");
      если_не(s, r.есть && strcmp(ужать(r.лево), arg) == 0 && число_из_слова(ужать(r.право)) > 0,
              fmt("тотальность «%s» вид step: аргумент в самовызове (строка %ld) — «%s», не убывание точным шагом «%s минус <положительное>» (после не меньше до)", имя, k, шаг, arg));
    }
    если_не(s, есть_виток, fmt("тотальность «%s» вид step: нет ни одного витка", имя));
  }

  else
    если_не(s, 0, fmt("тотальность «%s»: вид «%s» — не structure и не step", имя, вид));
}

/* Проверка «у зовомого есть блок тотальности» спрашивает про НАЛИЧИЕ блока, а
   не про порядок: круг стережёт отдельный проход. Прямой самовызов рёбер
   «зовёт» не даёт (он записан строкой «самовызов»), поэтому честная рекурсия
   кругом не названа. */
static void сверить_тотальность(Сверка *s, const char *блок, Сп строки, Сп все_имена, Сп вне_набора) {
  Сп свои = разделить(блок, "\n");
  char *имя = в_ёлочках(часть(свои, 1), 1);
  long где = номер_после(часть(свои, 1), "строка ");
  char *в_исх, *вид_вал;
  Сп зовёт_запись = ПУСТО, зовёт_тело;
  int вид = 0, само_нет = 0, само_есть = 0, конец = 0, i, j, comp, рекур; long нс;
  s->сведений++;   /* числитель растёт на честном проигрывании — как для тождества */
  вид_вал = слово(первая_с_началом(свои, "вид "), 2);
  comp = strcmp(вид_вал, "composition") == 0;
  рекур = strcmp(вид_вал, "structure") == 0 || strcmp(вид_вал, "step") == 0;
  for (i = 0; i < свои.n; i++) {
    char *l = обрезать(свои.e[i]);
    if (начинается(l, "вид ")) вид++;
    else if (strcmp(l, "самовызова нет") == 0) само_нет++;
    else if (начинается(l, "самовызов строка ")) само_есть++;
    else if (strcmp(l, "конец тотальности") == 0) конец++;
    else if (начинается(l, "зовёт примитив «")) {
      char *пр = в_ёлочках(l, 1);
      если_не(s, примитив_языка(пр),
              fmt("тотальность «%s»: «%s» — не примитив языка и не доказанная функция", имя, пр));
    }
    else if (начинается(l, "зовёт «")) добавить(&зовёт_запись, в_ёлочках(l, 1));
  }
  если_не(s, вид == 1 && конец == 1,
          fmt("тотальность «%s» записана не целиком: вид %d, конец %d — обязано быть по одному", имя, вид, конец));
  если_не(s, comp || рекур,
          fmt("тотальность «%s»: вид «%s» вне закрытого списка composition/structure/step — отвергается вслух", имя, вид_вал));
  if (comp) если_не(s, само_нет == 1 && само_есть == 0,
          fmt("тотальность «%s» вид composition: обязана нести ровно одно «самовызова нет» (нет %d, есть %d)", имя, само_нет, само_есть));
  if (рекур) если_не(s, само_есть == 1 && само_нет == 0,
          fmt("тотальность «%s» вид %s: обязана нести ровно одно «самовызов строка N» (нет %d, есть %d)", имя, вид_вал, само_нет, само_есть));
  /* (а) ПРИВЯЗКА К ОБЪЯВЛЕНИЮ. Родовая функция несёт доводы в объявлении
     («тотальная функция «Отобразить» от «А» и «Б»»): сверяется НАЧАЛО строки и
     первое имя в ёлочках, а не строка целиком, иначе честная родовая функция
     отвергалась бы за хвост доводов. */
  в_исх = строка_по_номеру(строки, где);
  если_не(s, начинается(в_исх, "тотальная функция «") && strcmp(имя_функции(в_исх), имя) == 0,
          fmt("тотальность «%s»: строка %ld исходника — не «тотальная функция «%s»» (стоит «%s»)",
              имя, где, имя, в_исх));
  нс = строка_самовызова(строки, имя, все_имена);
  if (comp) если_не(s, нс == 0,
          fmt("тотальность «%s»: тело зовёт саму F в строке %ld — это НЕ композиция", имя, нс));
  if (рекур) сверить_рекурсию(s, свои, строки, имя, вид_вал, нс);
  зовёт_тело = вызовы_тела(строки, имя, все_имена);
  for (i = 0; i < зовёт_запись.n; i++) {
    int есть = 0;
    for (j = 0; j < зовёт_тело.n; j++) if (strcmp(зовёт_запись.e[i], зовёт_тело.e[j]) == 0) { есть = 1; break; }
    если_не(s, есть, fmt("тотальность «%s»: запись назвала вызов «%s», а в теле F его нет", имя, зовёт_запись.e[i]));
  }
  for (j = 0; j < зовёт_тело.n; j++) {
    int есть = 0;
    if (strcmp(зовёт_тело.e[j], имя) == 0) continue;   /* самовызов ловит (б) со своей строкой */
    for (i = 0; i < зовёт_запись.n; i++) if (strcmp(зовёт_тело.e[j], зовёт_запись.e[i]) == 0) { есть = 1; break; }
    если_не(s, есть, fmt("тотальность «%s»: тело F зовёт «%s», а запись о нём молчит", имя, зовёт_тело.e[j]));
  }
  /* Зовомый обязан иметь свой блок тотальности — в этой записи или в поданном
     наборе-зависимостей. Реестр набора — это ВХОД, а не аксиома: имя стоит в нём
     лишь потому, что его блок перепроигран против его же исходника. Доверенное
     ядро от набора не растёт. */
  for (i = 0; i < зовёт_запись.n; i++) {
    int есть = 0;
    for (j = 0; j < все_имена.n; j++) if (strcmp(зовёт_запись.e[i], все_имена.e[j]) == 0) { есть = 1; break; }
    for (j = 0; !есть && j < вне_набора.n; j++) if (strcmp(зовёт_запись.e[i], вне_набора.e[j]) == 0) есть = 1;
    если_не(s, есть,
            fmt("тотальность «%s»: «%s» не примитив и не имеет блока тотальности НИ в записи, НИ в поданном наборе — тотальность зовомого не доказана", имя, зовёт_запись.e[i]));
  }
}

/* Круг ищется замыканием по достижимости рёбер «F зовёт G»; примитивы рёбер не
   дают — они листья доверия. Прямой самовызов сюда не попадает: его ловит
   проверка «самовызова нет» точнее. */
static void сверить_круги_тотальности(Сверка *s, Сп блоки) {
  Сп из = ПУСТО, v = ПУСТО, круги = ПУСТО; int i, j, k, росла = 1;
  for (i = 0; i < блоки.n; i++) {
    Сп свои = разделить(блоки.e[i], "\n");
    char *имя = в_ёлочках(часть(свои, 1), 1); int m;
    for (m = 0; m < свои.n; m++)
      if (начинается(обрезать(свои.e[m]), "зовёт «"))
        { добавить(&из, имя); добавить(&v, в_ёлочках(обрезать(свои.e[m]), 1)); }
  }
  while (росла) {
    росла = 0;
    for (i = 0; i < из.n; i++) for (j = 0; j < из.n; j++) {
      if (strcmp(v.e[i], из.e[j]) != 0) continue;
      for (k = 0; k < из.n; k++) if (!strcmp(из.e[k], из.e[i]) && !strcmp(v.e[k], v.e[j])) break;
      if (k == из.n) { добавить(&из, из.e[i]); добавить(&v, v.e[j]); росла = 1; }
    }
  }
  for (i = 0; i < из.n; i++) {
    if (strcmp(из.e[i], v.e[i]) != 0) continue;
    for (k = 0; k < круги.n; k++) if (strcmp(круги.e[k], из.e[i]) == 0) break;
    if (k == круги.n) добавить(&круги, из.e[i]);
  }
  если_не(s, круги.n == 0,
          fmt("тотальность: функции зовомы по кругу — взаимная рекурсия, композицией не доказана: %s",
              соединить(круги, ", ")));
}

/* Свидетель и цель после подстановки сличаются знак в знак, подстановку
   сверщик строит САМ. Цель с существованием без этих строк — код 1: такой
   записи ядро не печатало, и «проверено» за отсутствие строки не выдаётся.
   Строки при цели без существования — тоже код 1. */
static void сверить_свидетеля(Сверка *s, Сп свои, const char *цель_текст, long где, const char *имя) {
  char *м = (char *)"", *т = (char *)"", *у = (char *)"";
  int есть = разобрать_существование(цель_текст, &м, &т, &у);
  char *св = первая_с_началом(свои, "свидетель "), *пп = первая_с_началом(свои, "после подстановки ");
  char *ждём_св = fmt("свидетель «%s» ⟨%s⟩ строка %ld", м, терм(т), где), *ждём_пп = есть ? цель_обещанная(цель_текст) : (char *)"";
  если_не(s, !есть || (*св && *пп),
          fmt("утверждение «%s»: цель — «есть такой %s, а именно %s, что …», а строк «свидетель» и «после подстановки» в записи нет",
              имя, м, т));
  если_не(s, есть || (!*св && !*пп),
          fmt("утверждение «%s»: в записи свидетель, а цель исходника не «есть такой …, а именно …, что …»", имя));
  if (!есть || !*св || !*пп) return;
  если_не(s, strcmp(в_ёлочках(св, 1), м) == 0 && strcmp(терм(в_уголках(св, 1)), терм(т)) == 0 &&
             номер_после(св, "строка ") == где,
          fmt("утверждение «%s»: %s", имя, первое_расхождение(св, ждём_св)));
  если_не(s, strcmp(терм(в_уголках(пп, 1)), ждём_пп) == 0,
          fmt("утверждение «%s»: после подстановки в записи ⟨%s⟩, а свидетель «%s» в «%s» даёт ⟨%s⟩",
              имя, в_уголках(пп, 1), т, у, ждём_пп));
}

static char *функция_цели(const char *цель, Сп имена) {
  char *т = терм(цель); int k;
  for (k = 0; k < имена.n; k++) {
    const char *образцы[2]; int j;
    образцы[0] = fmt("» от %s", имена.e[k]); образцы[1] = fmt("» от ( %s )", имена.e[k]);
    for (j = 0; j < 2; j++) {
      const char *p = т, *q;
      while ((q = strstr(p, образцы[j])) != NULL) {
        const char *за = q + strlen(образцы[j]), *л = q;
        if (!*за || *за == ' ') {
          while (л > т && !начинается(л, "«")) л--;
          if (начинается(л, "«")) return в_ёлочках(л, 1);
        }
        p = q + 1;
      }
    }
  }
  return (char *)"";
}

static void сверить_высказывание(Сверка *s, Сп свои, Сп строки, const char *имя,
                                  long где, const char *вердикт) {
  Сп кв = все_с_началом(свои, "для всех "), тч = все_с_началом(свои, "таких что ");
  char *цель = (char *)"", *вид = первая_с_началом(свои, "вид "); long i, где_ц = 0; int k = 0, т = 0, целей = 0;
  если_не(s, strcmp(как_читает_язык(часть(строки, где)), fmt("утверждение «%s»", имя)) == 0,
          fmt("строка %ld исходника не «утверждение «%s»» от края — записанное утверждение в исходнике не стоит",
              где, имя));
  если_не(s, strcmp(вид, "вид statement") == 0,
          fmt("утверждение «%s» без функции записано как «%s», а не «вид statement»", имя, вид));
  for (i = где + 1; i <= строки.n; i++) {
    char *сырая = часть(строки, i), *l = как_читает_язык(обрезать(без_примечания(сырая))), *св, *огр = (char *)"";
    if (*сырая && !начинается(сырая, " ") && !начинается(сырая, "//")) break;
    if (начинается(l, "утверждаем ")) { цель = хвост_после(l, "утверждаем "); где_ц = i; целей++; continue; }
    if (!начинается(l, "для всех ")) continue;
    св = l + strlen("для всех ");
    if (содержит(св, " таких что ")) { огр = хвост_после(св, " таких что "); св = копия(св, (size_t)(strstr(св, " таких что ") - св)); }
    /* Несколько связываний в одной строке дают по строке записи на КАЖДОЕ, в
       порядке исходника и с одним номером строки. Разделитель « и » режется на
       ВЕРХНЕМ уровне — внутри имени типа он не встречается. */
    { Сп связывания = разделить_сверху(св, "и"); int j;
      if (!связывания.n) добавить(&связывания, св);
      for (j = 0; j < связывания.n; j++) {
        char *одно = обрезать(связывания.e[j]);
        char *ждём = fmt("для всех «%s» ⟨%s⟩ строка %ld", голо(часть(разделить(одно, ":"), 1)),
                         обрезать(часть(разделить(одно, ":"), 2)), i);
        если_не(s, сколько_раз(одно, ":") == 1,
                fmt("утверждение «%s»: связывание строки %ld «%s» не вида «имя: тип»", имя, i, одно));
        если_не(s, k < кв.n && strcmp(кв.e[k], ждём) == 0,
                fmt("утверждение «%s»: %s", имя, k < кв.n ? первое_расхождение(кв.e[k], ждём)
                    : fmt("связывание строки %ld «%s» — строки «для всех» в записи нет", i, одно)));
        k++; } }
    if (*огр) {
      char *ждт = fmt("таких что ⟨%s⟩ строка %ld", терм(огр), i);
      если_не(s, т < тч.n && strcmp(терм(в_уголках(тч.e[т], 1)), терм(огр)) == 0 && номер_после(тч.e[т], "строка ") == i,
              fmt("утверждение «%s»: ограничение строки %ld «таких что %s» — %s", имя, i, огр,
                  т < тч.n ? первое_расхождение(тч.e[т], ждт) : "строки «таких что» в записи нет"));
      т++; }
  }
  если_не(s, k == кв.n, fmt("утверждение «%s»: связываний в исходнике %d, а строк «для всех» в записи %d", имя, k, кв.n));
  если_не(s, т == тч.n, fmt("утверждение «%s»: ограничений в исходнике %d, а строк «таких что» в записи %d", имя, т, тч.n));
  если_не(s, целей == 1, fmt("утверждение «%s»: строк «утверждаем» в исходнике %d — положена одна", имя, целей));
  сверить_свидетеля(s, свои, цель, где_ц, имя);
  /* Строка «прогон» сверяется с исходником: Ф объявлена на названной строке,
     тело её — свёртка, свёртка зовёт шаг «Ш», цель утверждения зовёт Ф.
     Индукция по прогону здесь НЕ переигрывается — узел ниже остаётся на слове
     ядра, и это сказано числом, а не умолчанием. */
  { char *пр = первая_с_началом(свои, "прогон «");
    if (*пр) {
      char *ф = в_ёлочках(пр, 1), *ш = в_ёлочках(пр, 2), *объ; long n = номер_после(пр, "строка "), j; int свёртка = 0, зовёт = 0;
      объ = (n >= 1 && n <= строки.n) ? как_читает_язык(часть(строки, n)) : (char *)"";
      если_не(s, strcmp(объ, fmt("тотальная функция «%s»", ф)) == 0 || strcmp(объ, fmt("функция «%s»", ф)) == 0,
              fmt("утверждение «%s»: прогон «%s» — на строке %ld исходника не объявление функции «%s», а «%s»", имя, ф, n, ф, объ));
      for (j = n + 1; j >= 2 && j <= строки.n; j++) {
        char *сырая_т = часть(строки, j);
        if (*сырая_т && !начинается(сырая_т, " ") && !начинается(сырая_т, "//")) break;
        if (!начинается(сырая_т, "  свёртка ")) continue;
        свёртка = 1;
        if (содержит(как_читает_язык(обрезать(без_примечания(сырая_т))), fmt("«%s» от", ш))) зовёт = 1;
      }
      если_не(s, свёртка, fmt("утверждение «%s»: прогон «%s» — тело функции не свёртка, прогоном по списку шагов она не является", имя, ф));
      если_не(s, !свёртка || зовёт, fmt("утверждение «%s»: прогон «%s» — свёртка не зовёт шаг «%s»", имя, ф, ш));
      если_не(s, содержит(цель, fmt("«%s» от", ф)), fmt("утверждение «%s»: прогон «%s» — цель утверждения его не зовёт", имя, ф));
    } }
  /* У утверждения без функции переигрыванию узла всё же нужна та, чьё тело
     разбирается: берётся функция, которую цель зовёт на связанном имени. Тело её
     лишь определяет вызов, каждый случай по-прежнему сличается с целью; такой
     функции нет — узел остаётся на слове ядра. */
  { char *место_в = как_читает_язык(часть(строки, где)), *чья_ц;
    Сп имена = ПУСТО;
    из_высказывания(строки, где, "", &имена);
    чья_ц = функция_цели(цель, имена);
    МЕСТО_ВЫСКАЗЫВАНИЯ = место_в;
    if (*первая_с_началом(свои, "теорема «")) сверить_теорему(s, свои, строки, вердикт, место_в, имя, чья_ц);
    else без_теоремы(s, свои, строки, имя, вердикт, место_в, чья_ц);
    МЕСТО_ВЫСКАЗЫВАНИЯ = NULL; }
}

static void сверить_утверждение(Сверка *s, const char *блок, Сп строки) {
  Сп свои = разделить(блок, "\n");
  char *заголовок = часть(свои, 1);
  char *имя = в_ёлочках(заголовок, 1), *чья = в_ёлочках(заголовок, 2);
  long где = номер_после(заголовок, "строка ");
  char *место = строка_по_номеру(строки, где);
  char *вердикт = слово_после(первая_с_началом(свои, "вердикт "), "вердикт ");
  char *хозяин = хозяин_строки(строки, где);
  int есть_теорема = *первая_с_началом(свои, "теорема «") != 0;
  s->утверждений++;
  if (strcmp(вердикт, "доказано") == 0) s->доказанных++;
  сверить_целость_блока(s, свои, имя);
  /* Зовётся ОДИН раз на утверждение, а не из каждого маршрута: строки
     объявления печать ставит в блок последними — и при теореме тоже. */
  сверить_объявление(s, свои, fmt("утверждение «%s»", имя));
  if (!содержит(заголовок, " функции «")) { сверить_высказывание(s, свои, строки, имя, где, вердикт); return; }
  если_не(s, strcmp(первая_с_началом(свои, "вид "), "вид postcondition") == 0,
          fmt("утверждение «%s» функции «%s» записано как «%s», а не «вид postcondition»",
              имя, чья, первая_с_началом(свои, "вид ")));
  /* `место` держит строку исходника КАК ЕСТЬ, а `как_читает_язык` зовётся на
     каждом чтении: иначе имя постусловия нашлось бы и в хвостовом примечании,
     которого язык не читает вовсе. */
  если_не(s, содержит(как_читает_язык(место), fmt("обеспечивает «%s»", имя)),
          fmt("строка %ld исходника не несёт «обеспечивает «%s»» — записанное утверждение в исходнике не стоит", где, имя));
  если_не(s, strcmp(хозяин, чья) == 0,
          fmt("утверждение «%s» записано за функцией «%s», а строка %ld исходника стоит в функции «%s»",
              имя, чья, где, хозяин));
  /* Строка «для всех» сличается с именами квантора исходника знак в знак.
     Постусловие называет квантор, а строки нет — код 1; строка есть, а квантора
     в исходнике нет — тоже код 1: запись не вправе ни молчать, ни выдумывать. */
  { Сп имена = имена_квантора(место), кв = все_с_началом(свои, "для всех ");
    char *ждём = fmt("для всех «%s» строка %ld", соединить(имена, "» «"), где);
    если_не(s, кв.n <= 1,
            fmt("утверждение «%s»: строк «для всех» %d, а у постусловия квантор один", имя, кв.n));
    если_не(s, кв.n || !имена.n || (имена.n == 1 && !СТРОКИ_КВАНТОРОВ_ОБЯЗАТЕЛЬНЫ),
            fmt("утверждение «%s»: постусловие называет «для всех %s», а строки «для всех» в записи нет",
                имя, соединить(имена, " и ")));
    если_не(s, !кв.n || имена.n,
            fmt("утверждение «%s»: в записи «%s», а постусловие исходника квантора не называет",
                имя, кв.n ? кв.e[0] : ""));
    если_не(s, !кв.n || !имена.n || strcmp(кв.e[0], ждём) == 0,
            fmt("утверждение «%s»: %s", имя, первое_расхождение(кв.n ? кв.e[0] : "", ждём))); }
  /* Ограничение постусловия «таких что P» обязано стоять в записи строкой:
     потерянное ограничение делает цель шире, чем обещал исходник, а «проверено»
     за отсутствие строки не выдаётся. */
  { char *л = как_читает_язык(место), *т = strstr(л, " таких что "), *к = strstr(л, " обеспечивает ");
    size_t дт = strlen(" таких что ");
    char *P = т && к && к >= т + дт ? обрезать(копия(т + дт, (size_t)(к - т) - дт)) : (char *)"";
    Сп тч = все_с_началом(свои, "таких что ");
    char *ждём = fmt("таких что ⟨%s⟩ строка %ld", терм(P), где);
    если_не(s, тч.n || !*P,
            fmt("утверждение «%s»: постусловие ограничено «таких что %s», а строки «таких что» в записи нет — ограничение потеряно",
                имя, P));
    если_не(s, !тч.n || *P,
            fmt("утверждение «%s»: в записи «%s», а постусловие исходника ограничения не называет",
                имя, тч.n ? тч.e[0] : ""));
    если_не(s, !тч.n || !*P || (strcmp(терм(в_уголках(тч.e[0], 1)), терм(P)) == 0 &&
                                номер_после(тч.e[0], "строка ") == где),
            fmt("утверждение «%s»: %s", имя, первое_расхождение(тч.n ? тч.e[0] : "", ждём))); }
  сверить_свидетеля(s, свои, хвост_после(как_читает_язык(место), fmt("обеспечивает «%s» ", имя)), где, имя);
  if (есть_теорема) сверить_теорему(s, свои, строки, вердикт, место, имя, чья);
  else без_теоремы(s, свои, строки, имя, вердикт, место, чья);
}

/* Тотальность межмодульной G берётся в доверие ТОЛЬКО если её блок проигран
   против ЕЁ исходника и каждый её зовомый уже примитив или в реестре —
   транзитивно до дна из примитивов. Реестр наполняется до неподвижной точки:
   круг между записями до примитива не доходит и в реестр не попадёт. */

static Сп блоки_тотальности(const char *запись) {
  Сп t = разделить(запись, "\nтотальность "), r = ПУСТО; int i;
  for (i = 2; i <= t.n; i++) добавить(&r, часть(t, i));
  return r;
}

static char *имя_блока_т(const char *блок) { return в_ёлочках(часть(разделить(блок, "\n"), 1), 1); }
static long строка_блока_т(const char *блок) { return номер_после(часть(разделить(блок, "\n"), 1), "строка "); }

static Сп зовёт_блока_т(const char *блок) {
  Сп свои = разделить(блок, "\n"), r = ПУСТО; int m;
  for (m = 0; m < свои.n; m++) {
    char *l = обрезать(свои.e[m]);
    if (начинается(l, "зовёт «")) добавить(&r, в_ёлочках(l, 1));
  }
  return r;
}

/* Беды сторожа коллизии имён текут в главную сверку (код 1), а беды
   перепроигрывания блоков набора — в отдельную: провал блока лишь не пускает
   имя в реестр, и зовущий тогда покраснеет сам. */
static void предпроход(Сверка *s, Сп набор_исх, Сп набор_зап, Сп *реестр, Сп *все_блоки) {
  int d, i, j, росла;
  Сп имена = ПУСТО, ключи = ПУСТО, сообщено = ПУСТО;
  *реестр = ПУСТО; *все_блоки = ПУСТО;
  /* СТОРОЖ КОЛЛИЗИИ ИМЁН (проект §4.2.6): два блока с ОДНИМ именем, но разным
     различителем (иной исходник или строка объявления) — код 1. Без него
     подделыватель отмыл бы ложную G, подложив честную одноимённую (проба П4):
     проверка (г) нашла бы тёзку и пропустила самозванца — имя не различает. */
  for (d = 0; d < набор_исх.n; d++) {
    Сп блоки = блоки_тотальности(набор_зап.e[d]);
    char *sha = sha256(набор_исх.e[d]);
    for (i = 0; i < блоки.n; i++) {
      char *имя = имя_блока_т(блоки.e[i]);
      char *раз = fmt("%s|%s|%ld", имя, sha, строка_блока_т(блоки.e[i]));
      добавить(все_блоки, блоки.e[i]);
      for (j = 0; j < имена.n; j++)
        if (strcmp(имена.e[j], имя) == 0 && strcmp(ключи.e[j], раз) != 0) {
          int уже = 0, m;
          for (m = 0; m < сообщено.n; m++) if (strcmp(сообщено.e[m], имя) == 0) { уже = 1; break; }
          if (!уже) {
            добавить(&s->беды, fmt("в наборе два разных определения «%s» — имя не различает, кому верить", имя));
            добавить(&сообщено, имя);
          }
          break;
        }
      добавить(&имена, имя); добавить(&ключи, раз);
    }
  }
  /* ЗАМЫКАНИЕ ДО НЕПОДВИЖНОЙ ТОЧКИ. Блок принимается в реестр, когда он проигран
     против ЕГО исходника с нулём бед И каждый его зовомый уже в реестре (примитивы
     ловит `сверить_тотальность` строкой «зовёт примитив»). `все_имена` записи-
     зависимости служит `сверить_тотальность` лишь распознаванием вызовов в теле
     (проверки б/в); попадание в реестр решает СТРОГО проверка «зовомые в реестре»,
     а не наличие тёзки в той же записи — иначе ложный блок отмылся бы соседом. */
  росла = 1;
  while (росла) {
    росла = 0;
    for (d = 0; d < набор_исх.n; d++) {
      Сп строки = разделить(набор_исх.e[d], "\n");
      Сп блоки = блоки_тотальности(набор_зап.e[d]);
      Сп все_имена = ПУСТО;
      for (i = 0; i < блоки.n; i++) добавить(&все_имена, имя_блока_т(блоки.e[i]));
      for (i = 0; i < блоки.n; i++) {
        char *имя = имя_блока_т(блоки.e[i]);
        Сверка tmp; Сп зовёт; int уже = 0, k, все_в_реестре = 1;
        for (k = 0; k < реестр->n; k++) if (strcmp(реестр->e[k], имя) == 0) { уже = 1; break; }
        if (уже) continue;
        memset(&tmp, 0, sizeof tmp);
        сверить_тотальность(&tmp, блоки.e[i], строки, все_имена, *реестр);
        if (tmp.беды.n != 0) continue;
        зовёт = зовёт_блока_т(блоки.e[i]);
        for (j = 0; j < зовёт.n && все_в_реестре; j++) {
          int есть = 0;
          for (k = 0; k < реестр->n; k++) if (strcmp(зовёт.e[j], реестр->e[k]) == 0) { есть = 1; break; }
          if (!есть) все_в_реестре = 0;
        }
        if (!все_в_реестре) continue;
        добавить(реестр, имя); росла = 1;
      }
    }
  }
}

/* Проверка идёт ПО ТЕКСТУ, план не исполняется: это НАД-ОЦЕНКА, законная лишь в
   одну сторону — разрешённое, но нигде не выданное, принимается молча, а
   выданное сверх списка — код 1 с именем. Обратная сторона над-оценки —
   умолчание, поэтому исходник читается и во встречную сторону. */
static int среди(Сп v, const char *имя) {
  int i;
  for (i = 0; i < v.n; i++) if (strcmp(v.e[i], имя) == 0) return 1;
  return 0;
}

static void сверить_план(Сверка *s, const char *блок, Сп строки) {
  Сп свои = разделить(блок, "\n");
  char *имя = в_ёлочках(часть(свои, 1), 1);
  long где = номер_после(часть(свои, 1), "строка "), k;
  Сп разр = все_с_началом(свои, "разрешено «"), пор = все_с_началом(свои, "поручение «");
  Сп имена = ПУСТО, зовомые = ПУСТО;
  int i, n0;
  если_не(s, strcmp(как_читает_язык(часть(строки, где)), fmt("план «%s»", имя)) == 0,
          fmt("строка %ld исходника не «план «%s»» от края — записанный план в исходнике не стоит", где, имя));
  если_не(s, все_с_началом(свои, "конец плана").n == 1,
          fmt("план «%s» записан не целиком: строка «конец плана» обязана быть одна", имя));
  for (i = 0; i < разр.n; i++) {
    char *x = в_ёлочках(разр.e[i], 1); long m = номер_после(разр.e[i], "строка ");
    char *l = (m >= 1 && m <= строки.n) ? как_читает_язык(часть(строки, m)) : (char *)"";
    добавить(&имена, x);
    если_не(s, начинается(l, "разрешает ") && содержит(l, fmt("«%s»", x)),
            fmt("план «%s»: разрешённого «%s» на строке %ld исходника нет — там «%s»", имя, x, m, l));
  }
  /* (б) КОГО ПЛАН ДОСТАЁТ: `начинает с` и `обрабатывает`, а дальше — всё, что
     зовут уже собранные, до неподвижной точки. Поручение за функцией вне этого
     множества плану не принадлежит, и приписывать его плану — подлог. */
  for (k = где + 1; k <= строки.n && начинается(часть(строки, k), " "); k++) {
    char *l = как_читает_язык(часть(строки, k));
    if (начинается(l, "обрабатывает «") || начинается(l, "начинает с «")) добавить(&зовомые, в_ёлочках(l, 1));
  }
  do {
    n0 = зовомые.n;
    for (k = 1; k <= строки.n; k++) {
      char *l = как_читает_язык(часть(строки, k)); long t, кв = сколько_раз(l, "«");
      if (!среди(зовомые, хозяин_строки(строки, k))) continue;
      for (t = 1; t <= кв; t++) {
        char *г = в_ёлочках(l, t);
        if (*г && содержит(l, fmt("«%s» от", г)) && !среди(зовомые, г)) добавить(&зовомые, г);
      }
    }
  } while (зовомые.n != n0);
  for (i = 0; i < пор.n; i++) {
    char *x = в_ёлочках(пор.e[i], 1), *ф = в_ёлочках(пор.e[i], 2);
    long m = номер_после(пор.e[i], "строка ");
    char *l = (m >= 1 && m <= строки.n) ? как_читает_язык(часть(строки, m)) : (char *)"";
    char *хоз = (m >= 1 && m <= строки.n) ? хозяин_строки(строки, m) : (char *)"";
    если_не(s, содержит(l, fmt("поручение равным (вариант «%s»", x)),
            fmt("план «%s»: на строке %ld исходника поручения «%s» нет — там «%s»", имя, m, x, l));
    если_не(s, strcmp(хоз, ф) == 0,
            fmt("план «%s»: поручение записано за функцией «%s», а строка %ld исходника стоит в функции «%s»",
                имя, ф, m, хоз));
    если_не(s, среди(зовомые, ф),
            fmt("план «%s»: поручение записано за функцией «%s», которой план не зовёт", имя, ф));
    если_не(s, среди(имена, x),
            fmt("план «%s» разрешает %s, а «%s» строка %ld выдаёт «%s»",
                имя, соединить(имена, ", "), ф, m, x));
  }
  /* (г) ЗАПИСЬ НЕ ВПРАВЕ МОЛЧАТЬ О ВЫДАННОМ — иначе над-оценка обходится
     умолчанием: подлог прячется не ложной строкой, а отсутствующей. */
  for (k = 1; k <= строки.n; k++) {
    char *l = как_читает_язык(часть(строки, k)), *хоз = хозяин_строки(строки, k), *x;
    if (!содержит(l, "поручение равным (вариант «") || !среди(зовомые, хоз)) continue;
    x = в_ёлочках(часть(разделить(l, "поручение равным (вариант "), 2), 1);
    если_не(s, среди(пор, fmt("поручение «%s» функции «%s» строка %ld", x, хоз, k)),
            fmt("план «%s»: «%s» строка %ld выдаёт «%s», а строки об этом в записи нет — запись молчит о выданном",
                имя, хоз, k, x));
  }
}

/* Цель сверщик строит САМ: со столбца C строки L обязан стоять вызов «Г»
   внутри «Ф», у «Г» — «требует «И» У», и цель — У с параметрами, заменёнными
   доводами вызова. Имя цели, связанное в теле «Ф» до этого места, значит там
   не то, что в подписи «Г»: место не берётся и остаётся на слове ядра. */
static int связано_в_теле(Сп строки, const char *ф, long до, const char *цель) {
  long k; int i;
  for (k = 1; k <= до && k <= строки.n; k++) {
    Сп сл = разделить(терм(как_читает_язык(часть(строки, k))), " ");
    for (i = strcmp(хозяин_строки(строки, k), ф) ? сл.n : 0; i + 1 < сл.n; i++)
      if ((есть_терм("пусть как где голова хвост", сл.e[i]) && есть_терм(цель, голо(сл.e[i + 1]))) ||
          (strcmp(сл.e[i + 1], "→") == 0 && есть_терм(цель, голо(сл.e[i])))) return 1;
  }
  return 0;
}
static void сверить_снятие(Сверка *s, const char *блок, Сп строки) {
  Сп свои = разделить(блок, "\n"), треб, парам, арги = ПУСТО; Обст o; Прогон p;
  char *h = часть(свои, 1), *имя = в_ёлочках(h, 1), *ф = в_ёлочках(h, 2), *г = в_ёлочках(h, 3), *с, *у = NULL, *цель;
  char *пр = в_ёлочках(первая_с_началом(свои, "правило "), 1), *факт = в_ёлочках(первая_с_началом(свои, "ход 1 факт по свойству «"), 1);
  char *беда = NULL, *почему = NULL; long L = номер_после(h, "строка "), C = номер_после(h, "столбец "), k; int i, j, проигран = 0;
  треб = все_требования_функции(строки, г); парам = доводы_функции(строки, г).голые;
  for (с = часть(строки, L), k = 1; k < C && *с; k++) { с++; while ((*с & 0xC0) == 0x80) с++; }
  for (i = 0; i < треб.n; i++) if (strcmp(в_ёлочках(треб.e[i], 1), имя) == 0) у = формула_требования(треб.e[i]);
  if (начинается(с, fmt("«%s» от ", г))) арги = доводы_вызова(с + strlen(fmt("«%s» от ", г)));
  for (i = 0; i < (int)(sizeof ПРАВИЛА / sizeof *ПРАВИЛА) && strcmp(ПРАВИЛА[i], пр) != 0; i++) ;
  if (strcmp(хозяин_строки(строки, L), ф) != 0) беда = fmt("строка %ld стоит не в функции «%s»", L, ф);
  else if (!начинается(с, fmt("«%s»", г))) беда = fmt("в строке %ld со столбца %ld вызова «%s» нет", L, C, г);
  else if (!треб.n) почему = fmt("у «%s» в этом исходнике нет «требует» — предусловие прочесть негде", г);
  else if (!у) беда = fmt("у «%s» нет требования «%s»", г, имя);
  else if (арги.n != парам.n) беда = fmt("у «%s» параметров %d, а в вызове доводов %d", г, парам.n, арги.n);
  else if (strcmp(первая_с_началом(свои, "вердикт "), "вердикт доказано") != 0) беда = (char *)"вердикт не «доказано»";
  else if (i == (int)(sizeof ПРАВИЛА / sizeof *ПРАВИЛА)) беда = fmt("правила сведения «%s» сверщик не знает", пр);
  for (i = 0; !беда && i < парам.n; i++)
    for (j = i + 1; j < парам.n; j++)
      if (есть_терм(арги.e[i], парам.e[j])) беда = fmt("подстановка захватила бы имя «%s» — инстанции нет", парам.e[j]);
  for (цель = у ? терм(у) : (char *)"", i = 0; !беда && !почему && i < парам.n; i++) цель = вставить_вместо(цель, парам.e[i], терм(арги.e[i]));
  цель = терм(цель);
  if (!беда && !почему && связано_в_теле(строки, ф, L, цель)) почему = fmt("имя цели «%s» связано в теле «%s»", цель, ф);
  if (беда || почему) ;
  else if (*первая_с_началом(свои, "вывод ")) проигран = проиграть_вывод(s, свои, строки, fmt("снятие «%s» функции «%s»", имя, ф), ф, цель);
  else if (*факт && !среди(s->доказанные_свойства, факт)) почему = fmt("обещание «%s» сверщик не проиграл по существу", факт);
  else if (*первая_с_началом(свои, "ход цель")) {
    memset(&o, 0, sizeof o); o.строки = строки; o.свои = свои; o.функция = ф; o.цель = цель;
    o.тип = o.по = o.хвост = o.обяз = (char *)""; o.доказанные = s->доказанные_свойства;
    o.объявленные = s->объявленные_доказанными; p = проиграть_блок(&o);
    если_не(s, p.беды.n == 0, fmt("снятие «%s» функции «%s», сведение: %s", имя, ф, соединить(p.беды, "; ")));
    влить_не_взялся(s, &p, fmt("снятие «%s» функции «%s»", имя, ф));
    проигран = p.беды.n == 0 && p.проиграно > 0;
  } else почему = (char *)"вывода нет";
  s->снятий++;
  if (беда) добавить(&s->беды, fmt("снятие «%s» функции «%s» строка %ld: %s", имя, ф, L, беда));
  else if (проигран) s->снятий_проиграно++;
  else if (почему) { s->снятий_на_слово++;
    добавить(&s->не_взялся, fmt("снятие «%s» функции «%s» строка %ld: %s — место на слове ядра", имя, ф, L, почему)); }
}
/* Запись не вправе молчать и о снятии: мест вызова под «требует» в телах
   исходника обязано быть столько же, сколько блоков снятия, и ни одно не
   записано дважды. Запись, не несущая ни одного блока, не краснеет — её места
   названы отдельным числом «без блока», а не приняты молча. */
static void сверить_полноту_снятий(Сверка *s, Сп строки, Сп разрез) {
  static const char *ОБЪЯВЛЕНИЯ[] = { "принимает ", "возвращает ", "обеспечивает ", "требует ",
                                      "для всех ", "пример ", "дано ", "ожидается " };
  long мест = 0, блоков = 0, k; int i, j, внутри = 0; Сп ключи = ПУСТО;
  for (k = 1; k <= строки.n; k++) {
    char *сырая = часть(строки, k), *l = обрезать(как_читает_язык(сырая)), *q = l;
    if (*имя_функции(сырая)) { внутри = 1; continue; }
    if (*l && *сырая != ' ' && *сырая != '\t') внутри = 0;
    for (i = j = 0; j < 8; j++) i |= начинается(l, ОБЪЯВЛЕНИЯ[j]);
    for (; внутри && !i && (q = strstr(q, "«")) != NULL; q += strlen("«"))
      if (начинается(хвост_после(q, "»"), "от ")) мест += все_требования_функции(строки, в_ёлочках(q, 1)).n;
  }
  for (i = 2; i <= разрез.n; i++) {
    char *h = часть(разделить(часть(разрез, i), "\n"), 1), *ключ = fmt("%ld %ld %s", номер_после(h, "строка "), номер_после(h, "столбец "), в_ёлочках(h, 1));
    если_не(s, !среди(ключи, ключ), fmt("снятие «%s» на строке %ld записано дважды", в_ёлочках(h, 1), номер_после(h, "строка ")));
    добавить(&ключи, ключ); блоков += все_требования_функции(строки, в_ёлочках(h, 3)).n > 0;
  }
  если_не(s, разрез.n < 2 || мест == блоков, fmt("в телах исходника мест вызова под «требует» %ld, а в записи снятий о них %ld — запись говорит не обо всей программе", мест, блоков));
  s->снятий_без_блока = разрез.n < 2 ? мест : 0;
}

/* Отпечаток, поданный доводом, — такая же криптопривязка, как строка шапки, и
   считается ДО сверки пути: от него зависит, привязка путь или примета. */
static void привязка_отпечатком(Сверка *s, const char *исходник, const char *ждём) {
  s->sha = sha256(исходник);
  if (!ждём) return;
  if (strcmp(ждём, s->sha) == 0) s->крипто = 1;
  else добавить(&s->беды, fmt("ждали исходник с отпечатком %s, а у поданного %s", ждём, s->sha));
}

/* Пока криптоотпечатка нет, поле «исходник» — единственное, что держит запись
   при её программе, и сверяется жёстко. Сошёлся отпечаток256 — поданный файл
   ТА ЖЕ программа побайтно: запись, снятая в другом клоне, честна, и расхождение
   пути становится приметой, а не бедой. */
static void привязка_путём(Сверка *s, Сп шапка, const char *путь) {
  char *заявлен = хвост_после(часть(шапка, 2), "исходник ");
  if (путь_совпал(заявлен, путь)) return;
  if (s->крипто)
    добавить(&s->приметы,
            fmt("поле «исходник» зовёт «%s», а сверялись с «%s»; отпечаток256 сошёлся — "
                "это та же программа, и поле здесь примета, а не привязка", заявлен, путь));
  else
    добавить(&s->беды,
            fmt("запись зовёт своим исходником «%s», а сверяется с «%s» — это другая программа",
                заявлен, путь));
}

/* Вердикт по КАЖДОМУ утверждению порознь считается ТЕМ ЖЕ счётом, что и общий, а
   не отдельной меркой: две мерки разошлись бы, и верить было бы нечему. */
static void сверить_блок_утверждения(Сверка *s, char *блок, Сп строки) {
  long b0 = s->беды.n, d0 = s->на_слово, ш0 = s->шагов_на_слово;
  Сп свои = разделить(блок, "\n");
  char *имя = в_ёлочках(часть(свои, 1), 1);
  char *вердикт = слово_после(первая_с_началом(свои, "вердикт "), "вердикт ");
  const char *итог;
  сверить_утверждение(s, блок, строки);
  /* «доказано при условии»: `вердикт` выше — лишь ПЕРВОЕ слово строки, поэтому
     структура сверяется как у доказанной, а условность видна только всей строкой.
     Место остаётся на слове ядра с причиной и в реестр доказанного не попадает. */
  if (strcmp(первая_с_началом(свои, "вердикт "), "вердикт доказано при условии") == 0) {
    добавить(&s->не_взялся, fmt("утверждение «%s»: вердикт «доказано при условии» — доказательство опирается на утверждение, доказанное лишь при условии (без своей теоремы); место на слове ядра", имя));
    if (s->на_слово == d0 && s->шагов_на_слово == ш0) s->на_слово++;
  }
  итог = s->беды.n > b0 ? "НЕ СОШЛОСЬ"
       : (strcmp(вердикт, "доказано") != 0 ? "вердикта нет — проверять нечего"
       : ((s->на_слово > d0 || s->шагов_на_слово > ш0) ? "НЕ ПРОВЕРЕНО" : "ПРОВЕРЕНО"));
  добавить(&s->по_утверждениям,
          fmt("  утверждение «%s»: %s (на слово ядра: посылок и утверждений %ld, шагов %ld)",
              имя, итог, s->на_слово - d0, s->шагов_на_слово - ш0));
  /* Реестр доказанного пополняется ПОСЛЕ утверждения — на следующем он держит
     ровно предыдущие. Входит только ПРОВЕРЕННОЕ ПО СУЩЕСТВУ (ни посылки, ни шага
     на слове ядра): взятое на слово не звено независимой перепроверки, и через
     него в «факт по свойству» протащилось бы то, чего никто не проверял. */
  /* `!среди` — 4416: предпроход уже мог внести это имя, второй раз не кладём. */
  if (strcmp(вердикт, "доказано") == 0 && s->беды.n == b0
      && s->на_слово == d0 && s->шагов_на_слово == ш0 && !среди(s->доказанные_свойства, имя))
    добавить(&s->доказанные_свойства, имя);
}

/* 4416: РЕЕСТР ДОКАЗАННОГО — ПЕРВЫМ ПРОХОДОМ ПО ВСЕМ БЛОКАМ, А НЕ ПО ПОРЯДКУ ПЕЧАТИ.
   Прежде имя ложилось в реестр ПОСЛЕ своего блока, и ход «факт по свойству» видел
   лишь напечатанное ВЫШЕ: та же честная запись с переставленными местами блоками
   получала код 1. Порядок печати вердикта решать не вправе (для тотальности это уже
   сделано двумя проходами — `все_имена` + `сверить_тотальность`).
   Проход тот же, что основной, но на ЧЕРНОВОЙ `Сверка`: всё, что он насчитает —
   беды, места, приметы, — выбрасывается, берётся только реестр. Повторяется до
   НЕПОДВИЖНОЙ ТОЧКИ: имя входит в реестр, лишь если его блок сошёлся НА УЖЕ
   ВОШЕДШИХ, — потому круг не попадает в реестр ни при каком порядке печати, и
   строгость не сдвинута ни на шаг. Зовётся только там, где в записи есть «по
   свойству»: иначе реестр никто не читает, а второй проход стоил бы корпусу даром. */
static void реестр_доказанного(Сверка *s, Сп блоки, Сп строки) {
  Сп огл_беды = ОГЛ_БЕДЫ; long было; int i;
  do {
    Сверка чер = *s; было = s->доказанные_свойства.n;
    for (i = 0; i < блоки.n; i++)
      if (!среди(чер.доказанные_свойства, в_ёлочках(часть(разделить(блоки.e[i], "\n"), 1), 1))) сверить_блок_утверждения(&чер, блоки.e[i], строки);
    s->доказанные_свойства = чер.доказанные_свойства;
  } while (s->доказанные_свойства.n > было);
  /* Черновой проход в общий список жалоб не пишет; указатель на его реестр,
     оставленный блоком вывода, переводится на настоящий — черновик умер. */
  ОГЛ_БЕДЫ = огл_беды; ДОКАЗАНО_ДО_ВЫВОДА = &s->доказанные_свойства;
}

/* Шапка сверяется с числом блоков, лишь когда секция есть: записи без секции не
   краснеют. Первый проход собирает имена ВСЕХ блоков, второй проверяет каждый —
   «у зовомого ЕСТЬ блок», а не «он стоит выше по порядку». Круг ищется на
   ОБЪЕДИНЁННОМ графе записи и набора: иначе межзаписьный круг остался бы молча
   не-подтверждённым вместо названного вслух. */
static void сверить_секцию_тотальности(Сверка *s, Сп шапка, Сп тотальности, Сп строки,
                                       Сп набор_исх, Сп набор_зап) {
  Сп все_имена = ПУСТО, вне_набора = ПУСТО, набор_блоки = ПУСТО, объед = ПУСТО;
  char *строка_т = первая_с_началом(шапка, "тотальностей ");
  int i;
  if (*строка_т || тотальности.n)
    если_не(s, номер_после(строка_т, "тотальностей ") == тотальности.n,
            fmt("шапка обещает тотальностей %ld, а в записи блоков %d — печать назвала не всё",
                номер_после(строка_т, "тотальностей "), тотальности.n));
  for (i = 0; i < тотальности.n; i++)
    добавить(&все_имена, в_ёлочках(часть(разделить(тотальности.e[i], "\n"), 1), 1));
  if (набор_исх.n) предпроход(s, набор_исх, набор_зап, &вне_набора, &набор_блоки);
  for (i = 0; i < тотальности.n; i++)
    сверить_тотальность(s, тотальности.e[i], строки, все_имена, вне_набора);
  for (i = 0; i < тотальности.n; i++) добавить(&объед, тотальности.e[i]);
  for (i = 0; i < набор_блоки.n; i++) добавить(&объед, набор_блоки.e[i]);
  сверить_круги_тотальности(s, объед);
}

static Сверка сверить(const char *исходник, const char *запись, const char *путь,
                     const char *ждём, Сп набор_исх, Сп набор_зап) {
  Сверка s;
  /* Секция тотальности отсекается ПЕРЕД разбором утверждений: иначе её строка
     «вид composition» сошла бы за второй «вид» последнего утверждения, а её блок
     уехал бы в блоки утверждений. */
  /* Секция плана отсекается ПЕРВОЙ — по той же причине. */
  Сп п_разрез = разделить(запись, "\nплан "), планы = ПУСТО;
  Сп т_разрез = разделить(часть(п_разрез, 1), "\nтотальность "), тотальности = ПУСТО;
  Сп с_разрез = разделить(часть(т_разрез, 1), "\nснятие ");
  char *запись_голова = часть(с_разрез, 1);
  Сп части = разделить(запись_голова, "\nутверждение "), блоки = ПУСТО;
  Сп шапка = разделить(часть(части, 1), "\n"), строки = разделить(исходник, "\n");
  int i;
  memset(&s, 0, sizeof s);
  for (i = 2; i <= т_разрез.n; i++) добавить(&тотальности, часть(т_разрез, i));
  for (i = 2; i <= п_разрез.n; i++) добавить(&планы, часть(п_разрез, i));
  /* Оглавление списочных литералов доверия не получает — оно только указывает,
     где сверщику читать; всё названное перечитывается. */
  ОГЛАВЛЕНИЕ = ПУСТО; ОГЛ_БЕДЫ = ПУСТО;
  for (i = 0; i < шапка.n; i++)
    if (начинается(обрезать(шапка.e[i]), "таблица «")) добавить(&ОГЛАВЛЕНИЕ, обрезать(шапка.e[i]));
  привязка_отпечатком(&s, исходник, ждём);
  for (i = 0; i < части.n; i++)
    if (!начинается(части.e[i], "запись доказательства")) добавить(&блоки, части.e[i]);
  сверить_строки_записи(&s, запись);
  сверить_шапку(&s, шапка, исходник);
  привязка_путём(&s, шапка, путь);
  если_не(&s, !ОГЛАВЛЕНИЕ.n || номер_после(первая_с_началом(шапка, "таблиц "), "таблиц ") == ОГЛАВЛЕНИЕ.n,
          (char *)"оглавление обещает не столько таблиц, сколько в нём строк");
  если_не(&s, номер_после(часть(шапка, 7), "утверждений ") == блоки.n,
          (char *)"шапка обещает не столько утверждений, сколько в записи");
  сверить_полноту(&s, строки, блоки);
  for (i = 0; i < блоки.n; i++)
    if (strcmp(слово_после(первая_с_началом(разделить(блоки.e[i], "\n"), "вердикт "), "вердикт "), "доказано") == 0) добавить(&s.объявленные_доказанными, в_ёлочках(часть(разделить(блоки.e[i], "\n"), 1), 1));
  if (содержит(запись_голова, "по свойству ")) реестр_доказанного(&s, блоки, строки);
  for (i = 0; i < блоки.n; i++) сверить_блок_утверждения(&s, блоки.e[i], строки);
  сверить_круги(&s, блоки);
  /* Снятия — ПОСЛЕ утверждений: факт обещания вызванной берётся из реестра
     проверенных по существу постусловий, а он полон только тут. */
  for (i = 2; i <= с_разрез.n; i++) сверить_снятие(&s, часть(с_разрез, i), строки);
  сверить_полноту_снятий(&s, строки, с_разрез);
  сверить_секцию_тотальности(&s, шапка, тотальности, строки, набор_исх, набор_зап);
  for (i = 0; i < планы.n; i++) сверить_план(&s, планы.e[i], строки);
  for (i = 0; i < ОГЛ_БЕДЫ.n; i++) добавить(&s.беды, ОГЛ_БЕДЫ.e[i]);
  return s;
}

/* Исходов три, и они названы словами: 0 — ПРОВЕРЕНО (на слово не взято ничего),
   3 — НЕ ПРОВЕРЕНО (противоречий нет, но непроверенное названо числом; это НЕ
   «доказано»), 1 — НЕ СОШЛОСЬ, 2 — кривой вызов. Ключ, обменивающий 3 на 0,
   об этом не молчит: иначе код 0 под ним читался бы как приёмка. */

static int добавить_пару(Сп *набор_исх, Сп *набор_зап, const char *путь_исх, const char *путь_зап) {
  char *исх = прочитать_файл(путь_исх), *зап;
  if (!исх) { fprintf(stderr, "исходник зависимости не прочитан: %s\n", путь_исх); return 2; }
  зап = прочитать_файл(путь_зап);
  if (!зап) { fprintf(stderr, "запись зависимости не прочитана: %s\n", путь_зап); return 2; }
  добавить(набор_исх, исх); добавить(набор_зап, зап);
  return 0;
}

static int добавить_каталог(Сп *набор_исх, Сп *набор_зап, const char *кат) {
  DIR *dir = opendir(кат); struct dirent *e; const char *suf = ".запись"; size_t ls = strlen(suf);
  if (!dir) { fprintf(stderr, "каталог набора не открыт: %s\n", кат); return 2; }
  while ((e = readdir(dir)) != NULL) {
    size_t ln = strlen(e->d_name);
    char *путь_зап, *зап, *путь_исх, *исх;
    if (ln < ls || strcmp(e->d_name + ln - ls, suf) != 0) continue;
    путь_зап = fmt("%s/%s", кат, e->d_name);
    зап = прочитать_файл(путь_зап);
    if (!зап) { fprintf(stderr, "запись набора не прочитана: %s\n", путь_зап); closedir(dir); return 2; }
    путь_исх = хвост_после(часть(разделить(зап, "\n"), 2), "исходник ");
    if (!*путь_исх) { fprintf(stderr, "у записи набора нет поля «исходник»: %s\n", путь_зап); closedir(dir); return 2; }
    исх = прочитать_файл(путь_исх);
    if (!исх) { fprintf(stderr, "исходник записи набора не прочитан: %s (из %s)\n", путь_исх, путь_зап); closedir(dir); return 2; }
    добавить(набор_исх, исх); добавить(набор_зап, зап);
  }
  closedir(dir);
  return 0;
}

/* ТРИ ИСХОДА, И ОНИ НАЗВАНЫ СЛОВАМИ: 0 — ПРОВЕРЕНО (привязка криптографическая
   и на слово ядра не взято ни одного места), 1 — НЕ СОШЛОСЬ, 3 — НЕ ПРОВЕРЕНО.
   Ключ, обменивающий 3 на 0, об этом не молчит: иначе код 0 под ним читался бы
   как приёмка. */
static int напечатать_вердикт(Сверка s, int старый) {
  int d;
  int на_слово_есть = (s.на_слово || s.шагов_на_слово || s.снятий_на_слово) ? 1 : 0;
  const char *голова;
  d = (на_слово_есть || !s.крипто) ? 1 : 0;
  if (!s.крипто && на_слово_есть)
    голова = "НЕ ПРОВЕРЕНО — привязка к программе не криптографическая (строки «отпечаток256»"
             " в записи нет), и записанное доказательством не является";
  else if (!s.крипто)
    голова = "НЕ ПРОВЕРЕНО — привязка к программе не криптографическая: строки «отпечаток256»"
             " в записи нет и отпечаток не подан доводом, а многочленная свёртка ломается";
  else if (на_слово_есть)
    голова = "НЕ ПРОВЕРЕНО — запись не противоречит исходнику, но доказательством это не является";
  else
    голова = s.доказанных
           ? "ПРОВЕРЕНО — запись сошлась с исходником, и всё доказанное проиграно заново"
           : "ПРОВЕРЕНО ВПУСТУЮ — запись сошлась с исходником, но доказанным в ней не числится ничего";
  printf("%s: утверждений %ld, шагов сверено с исходником %ld, сведений проиграно заново %ld"
         " (ходов проверено %ld). Числятся доказанными %ld."
         " НА СЛОВО ЯДРА: посылок и утверждений %ld, шагов %ld."
         " Узлов вердикта «разбором по случаям» проиграно заново %ld"
         " (снято со слова ядра мест %ld),"
         " из них булевой веткой снято мест %ld,"
         " вне приёма сверщика %ld."
         " Ложных переписок (замкнутая ложь под видом тождества) поймано %ld,"
         " вне приёма сторожа %ld."
         " Узлов «разбор цели по условию» проиграно заново %ld"
         " (снято со слова ядра мест %ld),"
         " вне приёма сверщика %ld, разобрано, но не закрылось %ld."
         " Шагов по примеру проверено по существу %ld."
         " Шагов по свойству проверено по существу %ld."
         " Шагов по предположению проверено по телу функции %ld."
         " Мест без теоремы проверено по телу функции %ld."
         " Строк без привязки к исходнику %ld."
         " Выводов факта о типе проиграно заново %ld (снято со слова ядра мест %ld)."
         " Мест, сверенных ОБОИМИ свидетелями (термин и номер строки), %ld."
         " Снятий предусловий %ld: проиграно заново %ld, на слове ядра %ld; мест вызова без блока снятия %ld."
         " Привязка к программе: %s."
         " sha256 исходника %s\n",
         голова, s.утверждений, s.шагов, s.сведений, s.ходов, s.доказанных,
         s.на_слово, s.шагов_на_слово, s.узлов, s.узлов_мест, s.узлов_булево_мест, s.узлов_мимо,
         s.переписок_поймано, s.переписок_мимо,
         s.разбор, s.разбор_мест, s.разбор_мимо, s.разбор_не_закрылась,
         s.шагов_примером, s.шагов_свойством, s.шагов_по_телу, s.мест_по_телу, s.без_привязки,
         s.выводов, s.выводов_мест, s.сверено_обоими, s.снятий, s.снятий_проиграно, s.снятий_на_слово, s.снятий_без_блока,
         s.крипто ? "SHA-256 сошёлся" : "только свёртка ядра — она ломается",
         s.sha);
  if (s.приметы.n) printf("ПРИМЕТЫ (на исход не влияют): %s\n", соединить(s.приметы, "; "));
  if (d && старый)
    fprintf(stderr, "ВНИМАНИЕ: ключ --старый-код-не-приёмка обменял исход 3 на код 0."
                    " Код 0 здесь ПРИЁМКОЙ НЕ ЯВЛЯЕТСЯ. Настоящий исход: %s\n", голова);
  return (d && !старый) ? 3 : 0;
}

int main(int argc, char **argv) {
  char *исходник, *запись, *ждём = NULL; Сверка s; int старый = 0, i, поимённо = 0;
  const char *доводы[3]; int n = 0;
  Сп набор_исх = ПУСТО, набор_зап = ПУСТО;
  /* Список ключей закрыт: неизвестный ключ — отказ кодом 2, а не довод и не
     «ладно». Иначе забытый ключ уехал бы третьим доводом и дал бы ложное
     «НЕ СОШЛОСЬ» вместо честного «звать не так». */
  for (i = 1; i < argc; i++) {
    if (strcmp(argv[i], "--старый-код-не-приёмка") == 0) старый = 1;
    else if (strcmp(argv[i], "--по-утверждениям") == 0) поимённо = 1;
    else if (strcmp(argv[i], "--набор") == 0) {
      if (i + 1 >= argc) { fprintf(stderr, "--набор без каталога\n"); return 2; }
      { int e = добавить_каталог(&набор_исх, &набор_зап, argv[i + 1]); if (e) return e; }
      i += 1;
    }
    else if (strcmp(argv[i], "--зависимость") == 0) {
      if (i + 2 >= argc) { fprintf(stderr, "--зависимость ждёт ИСХОДНИК и ЗАПИСЬ\n"); return 2; }
      { int e = добавить_пару(&набор_исх, &набор_зап, argv[i + 1], argv[i + 2]); if (e) return e; }
      i += 2;
    }
    else if (начинается(argv[i], "--")) {
      fprintf(stderr, "чекер не знает ключа «%s». Ключей ровно четыре: "
                      "--старый-код-не-приёмка (им заменён прежний --мягко), "
                      "--по-утверждениям, --набор КАТАЛОГ и --зависимость ИСХОДНИК ЗАПИСЬ\n", argv[i]);
      return 2;
    }
    else if (n < 3) доводы[n++] = argv[i];
    else { fprintf(stderr, "лишний довод «%s»\n", argv[i]); return 2; }
  }
  if (n < 2 || n > 3) {
    fprintf(stderr, "звать: сверщик [--старый-код-не-приёмка] [--по-утверждениям]"
                    " [--набор КАТАЛОГ] [--зависимость ИСХОДНИК ЗАПИСЬ]..."
                    " <исходник.flang> <запись> [ожидаемый sha256]\n");
    return 2;
  }
  if (n == 3) ждём = (char *)доводы[2];
  исходник = прочитать_файл(доводы[0]);
  if (!исходник) { fprintf(stderr, "исходник не прочитан: %s\n", доводы[0]); return 2; }
  запись = прочитать_файл(доводы[1]);
  if (!запись) { fprintf(stderr, "запись не прочитана: %s\n", доводы[1]); return 2; }
  s = сверить(исходник, запись, доводы[0], ждём, набор_исх, набор_зап);
  if (поимённо) for (i = 0; i < s.по_утверждениям.n; i++) printf("%s\n", s.по_утверждениям.e[i]);
  if (s.беды.n) { printf("НЕ СОШЛОСЬ: %s\n", соединить(s.беды, "; ")); return 1; }
  /* Печатаются ДВА числа порознь — строк причин и мест на слово ядра: они не
     равны. Строк бывает больше: у непроигранного узла своя строка объясняет, за
     что приём не взялся, а место называет строка посылки под ним. Меньше мест
     строк быть не должно — место без имени никто не починит. */
  if (s.не_взялся.n)
    printf("НЕ ВЗЯЛСЯ (строк причин %d; мест на слово ядра %ld): %s\n",
           s.не_взялся.n, s.на_слово + s.шагов_на_слово, соединить(s.не_взялся, "; "));
  return напечатать_вердикт(s, старый);
}
